INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94685, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "监视", "is_correct": true, "explanation": "监视：一直看着对方，不让他走开或做坏事。"}, {"text": "坚实", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是结实、可靠。"}, {"text": "检视", "is_correct": false, "explanation": "jiǎn（第三声）与 jiān（第一声）声调不同，意思是仔细检查、审视。"}, {"text": "将士", "is_correct": false, "explanation": "jiàng 与 jiān 韵母不同（ang 与 an），意思是将领和士兵。"}], "explanations": {"监视": "监视：一直看着对方，不让他走开或做坏事。", "坚实": "shí（第二声）与 shì（第四声）声调不同，意思是结实、可靠。", "检视": "jiǎn（第三声）与 jiān（第一声）声调不同，意思是仔细检查、审视。", "将士": "jiàng 与 jiān 韵母不同（ang 与 an），意思是将领和士兵。"}, "sentence_index": null, "correct_answer": "监视"}, "level_3": {"options": [{"text": "监视", "is_correct": true, "explanation": "监视：一直看着，不让对方走开或进入，与“不让陌生人进来”的语境相合。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”针对损坏的东西，与“不让陌生人进来”的语境不合。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”表示喜爱地看，与防止陌生人进入的语境不合。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是可以移动的物品，“门口”是地点，不能被搬运。"}], "explanations": {"监视": "监视：一直看着，不让对方走开或进入，与“不让陌生人进来”的语境相合。", "修理": "语义：“修理”针对损坏的东西，与“不让陌生人进来”的语境不合。", "欣赏": "语义：“欣赏”表示喜爱地看，与防止陌生人进入的语境不合。", "搬运": "搭配：“搬运”的对象是可以移动的物品，“门口”是地点，不能被搬运。"}, "sentence_index": 6, "correct_answer": "监视"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们在门口监视新同学的到来。", "explanation": "这里应该用〈欢迎〉。监视是防范性的注意观察，不能表示热情的迎接。"}, {"text": "我们在山顶监视日出。", "explanation": "这里应该用〈欣赏〉。日出不会走开或作恶，看日出要用欣赏。"}, {"text": "他细细监视这杯茶的味道。", "explanation": "这里应该用〈品尝〉。监视针对需要防范的人或情况，尝味道要用品尝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94685, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察把那个小偷监视很紧，他跑不了。", "corrected_sentence": "警察把那个小偷监视得很紧，他跑不了。", "error_description": "错误：“监视很紧”。动词后带程度补语时，中间要加“得”：“监视得很紧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94685, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "保安正在监视了后门，不让陌生人进来。", "corrected_sentence": "保安正在监视着后门，不让陌生人进来。", "error_description": "错误：“正在监视了”。“正在”表示动作进行，要与“着”搭配，不能与“了”同用：应为“正在监视着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
