INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94689, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "称号是大家给一个人起的好名字。", "primary_collocate": null, "pronunciation": "chēng hào", "ipa": "ʈʂʰɤŋ⁵⁵ xɑʊ⁵¹", "syllable_count": 2, "sentences": [{"text": "大家给他起了一个好听的称号。", "target_word": "称号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们送给她“小天使”的称号。", "target_word": "称号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个称号是邻居们起的。", "target_word": "称号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他热心帮助别人，得到了“好人”这个称号。", "target_word": "称号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都喜欢这个称号。", "target_word": "称号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷有个称号叫“老好人”。", "target_word": "称号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱歌好听，朋友们给了她“小百灵”的称号。", "target_word": "称号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个称号让他很不好意思。", "target_word": "称号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人都用这个称号叫他。", "target_word": "称号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想要一个什么称号？", "target_word": "称号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个称号", "label": "量词"}, {"form": "稱號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "旁人根据某人的特点送给他的好听的名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd175452-6fce-49e7-ac8e-f0834ea62e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94689, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "称号", "is_correct": true, "explanation": "正确：指大家给他取的好听名称，与“起了一个好听的”相符。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“起”接的是名字、称呼，不能接“礼物”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指体型外形，是身体特征，不能像名称那样“起”。"}, {"text": "名声", "is_correct": false, "explanation": "搭配：“起”不接“名声”，应说“树立名声”或“有名声”。"}], "explanations": {"称号": "正确：指大家给他取的好听名称，与“起了一个好听的”相符。", "礼物": "搭配：“起”接的是名字、称呼，不能接“礼物”。", "身材": "体貌：“身材”指体型外形，是身体特征，不能像名称那样“起”。", "名声": "搭配：“起”不接“名声”，应说“树立名声”或“有名声”。"}, "sentence_index": 0, "correct_answer": "称号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这个称号放进了口袋里。", "explanation": "语义错误：称号是别人给的好名字，不是实物，不能放进口袋。"}, {"text": "这块石头有个称号，叫“小白”。", "explanation": "这里应该用〈名字〉。“称号”指给人或集体起的好名字，不用于石头等物品。"}, {"text": "他从小就有一块好听的称号。", "explanation": "量词用错：〈块〉用于块状的东西，不用于称号。“称号”应配〈个〉，即“一个好听的称号”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94689, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "称号", "is_correct": true, "explanation": "正确：指朋友们因她唱歌好听而给的名称，与句意相符。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是身体的温度，是生理状态，朋友不能“给”它一个名称。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：“年纪”指年龄，是客观状况，不是可以“给”的名称。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指身体的高矮，是客观特征，不能作为朋友“给”的名称。"}], "explanations": {"称号": "正确：指朋友们因她唱歌好听而给的名称，与句意相符。", "体温": "语义：“体温”是身体的温度，是生理状态，朋友不能“给”它一个名称。", "年纪": "语义：“年纪”指年龄，是客观状况，不是可以“给”的名称。", "身高": "体貌：“身高”指身体的高矮，是客观特征，不能作为朋友“给”的名称。"}, "sentence_index": 6, "correct_answer": "称号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个称号太重了，他拿不动。", "explanation": "语义错误：称号是一个名字，没有重量，不能“拿”。"}, {"text": "他的称号叫“小明”。", "explanation": "这里应该用〈名字〉。“称号”指给人起的好名字或授予的荣誉，不指人的正式姓名。"}, {"text": "他身上多了一支好听的称号。", "explanation": "量词用错：〈支〉用于笔、枪等细长物，不用于称号。“称号”应配〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94689, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师给这个学生起了一台很好的称号。", "corrected_sentence": "老师给这个学生起了一个很好的称号。", "error_description": "量词错误：「称号」应配〈个〉，〈台〉用于机器等物品，不能用于称号。正确说法是“起了一个很好的称号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94689, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她每天练习，希望能得到这首称号。", "corrected_sentence": "她每天练习，希望能得到这个称号。", "error_description": "量词错误：「称号」应配〈个〉，〈首〉用于诗词、歌曲，不能用于称号。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
