INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94690, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "授予某人或集体的表示地位、功绩或荣誉的名称。", "primary_collocate": null, "pronunciation": "chēng hào", "ipa": "ʈʂʰɤŋ⁵⁵ xɑʊ⁵¹", "syllable_count": 2, "sentences": [{"text": "她获得了“冠军”的称号。", "target_word": "称号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师得到了“优秀教师”称号。", "target_word": "称号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有“花城”的称号。", "target_word": "称号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为国家争光，得到了英雄称号。", "target_word": "称号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司拿到了“先进集体”的称号。", "target_word": "称号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给他“三好学生”这个称号。", "target_word": "称号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她三次拿到世界冠军，这个称号很光荣。", "target_word": "称号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "获得这个称号不容易，要努力很多年。", "target_word": "称号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家给这位科学家一个很高的荣誉称号。", "target_word": "称号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的班得了“文明班级”的称号。", "target_word": "称号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个称号", "label": "量词"}, {"form": "荣誉称号", "label": "复合"}, {"form": "稱號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "授予个人或集体、表示地位功绩或荣誉的正式名称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd175452-6fce-49e7-ac8e-f0834ea62e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94690, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "称号", "is_correct": true, "explanation": "正确：指授予的正式名称，与“获得”搭配，符合句意。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“获得”接的是称号、奖项，不接“名字”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是身体的高矮，不是可以获得的东西，不能说“获得了……的身高”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指出生以来的年数，不能“获得”，与“冠军”的称号无关。"}], "explanations": {"称号": "正确：指授予的正式名称，与“获得”搭配，符合句意。", "名字": "搭配：“获得”接的是称号、奖项，不接“名字”。", "身高": "体貌：“身高”是身体的高矮，不是可以获得的东西，不能说“获得了……的身高”。", "年龄": "语义：“年龄”指出生以来的年数，不能“获得”，与“冠军”的称号无关。"}, "sentence_index": 0, "correct_answer": "称号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同学们都叫他“小不点”，这个称号他用了很多年。", "explanation": "这里应该用〈绰号〉。“称号”指正式授予的荣誉名称，不用于“小不点”这类外号。"}, {"text": "这只猫的称号叫“小白”。", "explanation": "这里应该用〈名字〉。“称号”指授予人或集体的荣誉名称，不用于猫等动物。"}, {"text": "他为国家争光，得到了一顶英雄称号。", "explanation": "量词用错：〈顶〉用于帽子、帐篷等，不用于称号。“称号”应配〈个〉，即“一个英雄称号”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94690, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以“光荣”的对象，与句意相悖。"}, {"text": "称号", "is_correct": true, "explanation": "正确：指因获得冠军而得来的荣誉名称，与“很光荣”相符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指身体的高矮，是客观特征，不能用“光荣”来评价。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”是身体的重量特征，与“光荣”没有关系。"}], "explanations": {"天气": "语义：天气不是可以“光荣”的对象，与句意相悖。", "称号": "正确：指因获得冠军而得来的荣誉名称，与“很光荣”相符。", "身高": "体貌：“身高”指身体的高矮，是客观特征，不能用“光荣”来评价。", "体重": "体貌：“体重”是身体的重量特征，与“光荣”没有关系。"}, "sentence_index": 6, "correct_answer": "称号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个称号是他昨天买的，放在书桌上。", "explanation": "语义错误：称号是授予的名称，不是商品，不能“买”，也不能放在书桌上。"}, {"text": "学校给了她一块“优秀学生”的称号。", "explanation": "量词用错：〈块〉用于块状物，不用于称号。“称号”应配〈个〉。"}, {"text": "他把这个称号装进了书包。", "explanation": "这里应该用〈奖杯〉之类的实物词。“称号”是授予的名称，不是实物，不能装进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他获得了一条“优秀员工”的称号。", "corrected_sentence": "他获得了一个“优秀员工”的称号。", "error_description": "量词错误：「称号」应配〈个〉，〈条〉用于细长的东西，不能用于称号。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市政府授予了他一套“优秀市民”的称号。", "corrected_sentence": "市政府授予了他一个“优秀市民”的称号。", "error_description": "量词错误：「称号」应配〈个〉，〈套〉用于成组的物品，不能用于称号。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
