INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94691, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "等一下是请别人先不要走，慢一点。", "primary_collocate": null, "pronunciation": "děng yí xià", "ipa": "təŋ˨˩ i˧˥ ɕja˥˩", "syllable_count": 3, "sentences": [{"text": "等一下，我还没吃完。", "target_word": "等一下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请等一下，他马上来。", "target_word": "等一下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "等一下，你的书忘拿了。", "target_word": "等一下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等一下，别走，我跟你一起去。", "target_word": "等一下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等一下，路上车太多了，慢点开。", "target_word": "等一下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说：“等一下，大家先别写。”", "target_word": "等一下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等一下，门还开着呢。", "target_word": "等一下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等一下，你走得太快，我跟不上。", "target_word": "等一下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈叫住我说：“等一下，外面下雨。”", "target_word": "等一下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等一下，我的鞋带松了。", "target_word": "等一下", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "等一会儿", "label": "复合"}, {"form": "等了一下", "label": "体标"}], "register": "口语", "sense_fingerprint": "等一下：动词，请对方先不要走、慢一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9844ebf-71c6-485b-8194-50a304b0844d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94691, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "等一下", "is_correct": true, "explanation": "正确：“等一下”表示请对方先稍候，与“我还没吃完”的语境相合。"}, {"text": "吃完", "is_correct": false, "explanation": "语义：“吃完”与后半句“我还没吃完”矛盾，句子不通。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指完成学业，与“我还没吃完”的语境无关，句子不通。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”与“等一下”的请求语境无关，句子不通。"}], "explanations": {"等一下": "正确：“等一下”表示请对方先稍候，与“我还没吃完”的语境相合。", "吃完": "语义：“吃完”与后半句“我还没吃完”矛盾，句子不通。", "毕业": "语义：“毕业”指完成学业，与“我还没吃完”的语境无关，句子不通。", "睡": "语义：“睡”与“等一下”的请求语境无关，句子不通。"}, "sentence_index": 0, "correct_answer": "等一下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我先去趟洗手间，等一下就出发。", "explanation": "这里的“等一下”表示很短时间之后再做某事，是另一个义项，不是请别人先不要走、慢一点。"}, {"text": "我先把饭做好，等一下就去叫你。", "explanation": "这里的“等一下”表示很短时间之后，是另一个义项，不是请对方先不要走、慢一点。"}, {"text": "雨停了，等一下我们就出门。", "explanation": "这里的“等一下”表示很短时间之后再做某事，是另一个义项，不是请对方先不要走、慢一点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94691, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "等一下", "is_correct": true, "explanation": "正确：“等一下”请对方稍候，与“门还开着呢”的语境不冲突。"}, {"text": "打扫", "is_correct": false, "explanation": "配价：“打扫”需要宾语，如“打扫房间”，单独使用不完整。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”与“门还开着呢”的语境无关，句子不通。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指降生，与请人稍候的语境不合，句子不通。"}], "explanations": {"等一下": "正确：“等一下”请对方稍候，与“门还开着呢”的语境不冲突。", "打扫": "配价：“打扫”需要宾语，如“打扫房间”，单独使用不完整。", "发烧": "语义：“发烧”与“门还开着呢”的语境无关，句子不通。", "出生": "语义：“出生”指降生，与请人稍候的语境不合，句子不通。"}, "sentence_index": 6, "correct_answer": "等一下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他先去拿个东西，等一下就回来。", "explanation": "这里的“等一下”表示很短时间之后再回来，是另一个义项，不是请对方先不要走、慢一点。"}, {"text": "会议等一下，大家走出会议室。", "explanation": "这里应该用〈结束〉。等一下是请人稍候，不能用来描述“会议”的完结。"}, {"text": "大家先别吵，等一下老师就来。", "explanation": "这里的“等一下”表示很短时间之后，是另一个义项，不是请对方先不要走、慢一点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94691, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你等一下着，我马上回来。", "corrected_sentence": "请你等一下，我马上回来。", "error_description": "错误：“等一下着”。“一下”表示短时间，其后不接动态助词“着”，正确说法是“等一下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94691, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说：‘等一下了，我穿好衣服就走。’", "corrected_sentence": "他说：‘等一下，我穿好衣服就走。’", "error_description": "错误：“等一下了”。“一下”表示短时间，后面不接“了”，正确说法是“等一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
