INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94695, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "约定是两个人说好一件事，一定做到。", "primary_collocate": null, "pronunciation": "yuē dìng", "ipa": "ɥe˥ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我和妹妹有一个约定，谁也不能说出去。", "target_word": "约定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们约定，以后每年都回老家过年。", "target_word": "约定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "既然是约定，就一定要做到。", "target_word": "约定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跟爸爸约定好了，不再玩手机游戏。", "target_word": "约定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明和小红的约定是一起考上大学。", "target_word": "约定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们约定了，下次谁迟到谁请客。", "target_word": "约定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直记着和奶奶的约定。", "target_word": "约定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你和朋友约定过什么事吗？", "target_word": "约定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了守住约定，他今天早早回家了。", "target_word": "约定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个孩子约定，明天一起早起跑步。", "target_word": "约定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "约定了", "label": "完成体"}, {"form": "约定过", "label": "经历体"}, {"form": "约定好", "label": "结果补语形式"}, {"form": "一个约定", "label": "量词搭配"}], "register": "中性", "sense_fingerprint": "两人说好一件事，一定做到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df093371-859c-466c-bce4-6c56d378b3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94695, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约定", "is_correct": true, "explanation": "「约定」指两人说好一件事并一定做到，与“谁也不能说出去”的语境相符。"}, {"text": "作业", "is_correct": false, "explanation": "语义：「作业」是要完成的任务，不是需要保密的内容，“谁也不能说出去”说不通。"}, {"text": "房间", "is_correct": false, "explanation": "语义：「房间」是空间，不是两人之间需要保密的事情。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：「说出去」一般搭配消息、秘密、事情，不搭配“声音”。"}], "explanations": {"约定": "「约定」指两人说好一件事并一定做到，与“谁也不能说出去”的语境相符。", "作业": "语义：「作业」是要完成的任务，不是需要保密的内容，“谁也不能说出去”说不通。", "房间": "语义：「房间」是空间，不是两人之间需要保密的事情。", "声音": "搭配：「说出去」一般搭配消息、秘密、事情，不搭配“声音”。"}, "sentence_index": 0, "correct_answer": "约定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在饭馆约定了一碗面条。", "explanation": "这里应该用〈点〉。在饭馆是点菜，“约定”指双方商量好的事，不能用于点菜。"}, {"text": "他约定了下周五的天气。", "explanation": "这里应该用〈预报〉。天气由气象部门预报，不是双方商定的事，“约定”不能用于此。"}, {"text": "老师约定我们每天背十个单词。", "explanation": "这里应该用〈要求〉。老师对学生单方面提出的要求不用“约定”，约定是双方商量好的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94695, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约定", "is_correct": true, "explanation": "「约定」指两人说好一件事并一定做到，符合“一直记着”的语境。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：「鞋子」是穿的东西，不是需要一直记着的约定。"}, {"text": "账单", "is_correct": false, "explanation": "搭配：「账单」是付款凭证，与“和奶奶的”搭配不通。"}, {"text": "考试", "is_correct": false, "explanation": "语义：「考试」是测验，不是两人说好并要遵守的事。"}], "explanations": {"约定": "「约定」指两人说好一件事并一定做到，符合“一直记着”的语境。", "鞋子": "语义：「鞋子」是穿的东西，不是需要一直记着的约定。", "账单": "搭配：「账单」是付款凭证，与“和奶奶的”搭配不通。", "考试": "语义：「考试」是测验，不是两人说好并要遵守的事。"}, "sentence_index": 6, "correct_answer": "约定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校约定每天下午三点放学。", "explanation": "这里应该用〈规定〉。学校单方面的制度要用“规定”，“约定”指双方商量好的事。"}, {"text": "他约定了我的请求，马上去帮忙。", "explanation": "这里应该用〈答应〉。“答应”表示接受对方的请求，约定是双方商定的事，不能这样用。"}, {"text": "妈妈约定我今天必须写完作业。", "explanation": "这里应该用〈要求〉。妈妈对孩子单方面提出的要求不用“约定”，约定是双方商量好的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94695, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和同桌有一只约定，每天互相监督。", "corrected_sentence": "我和同桌有一个约定，每天互相监督。", "error_description": "“约定”作名词表示商定的事，量词应说“一个约定”；“只”一般用于动物等，这里应改为“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94695, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们约定了好明天一起去图书馆。", "corrected_sentence": "我们约定好了明天一起去图书馆。", "error_description": "结果补语“好”应紧跟动词，说“约定好了”，不能说“约定了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
