INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94696, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事先商量好并确定下来；也指商定好的事。", "primary_collocate": null, "pronunciation": "yuē dìng", "ipa": "ɥe˥ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我们约定明天上午九点在学校门口见面。", "target_word": "约定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们约定每个周末一起去爬山。", "target_word": "约定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和朋友约定好了，下个月一起去旅行。", "target_word": "约定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别忘了我们的约定，晚上七点到。", "target_word": "约定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有遵守约定，让大家等了很久。", "target_word": "约定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我们两个人的约定，不能告诉别人。", "target_word": "约定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和我们约定，每天都要读半小时书。", "target_word": "约定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照约定的时间，他准时到了公司。", "target_word": "约定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和爸爸约定，考好了就去看电影。", "target_word": "约定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们约定过，毕业以后还要常常联系。", "target_word": "约定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "约定了", "label": "完成体"}, {"form": "约定过", "label": "经历体"}, {"form": "约定好", "label": "结果补语形式"}, {"form": "一个约定", "label": "量词搭配"}], "register": "中性", "sense_fingerprint": "事先商量并确定；商定好的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df093371-859c-466c-bce4-6c56d378b3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94696, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约定", "is_correct": true, "explanation": "「约定」表示事先商量好并确定下来，与“明天上午九点在学校门口见面”的句意相符。"}, {"text": "请教", "is_correct": false, "explanation": "语义：「请教」指向别人求教，不能表示双方事先确定见面的时间和地点。"}, {"text": "散步", "is_correct": false, "explanation": "配价：「散步」是不及物动词，后面不能带“明天上午九点在学校门口见面”这样的内容。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：「增加」说数量或程度，不能跟“见面”这种行为搭配。"}], "explanations": {"约定": "「约定」表示事先商量好并确定下来，与“明天上午九点在学校门口见面”的句意相符。", "请教": "语义：「请教」指向别人求教，不能表示双方事先确定见面的时间和地点。", "散步": "配价：「散步」是不及物动词，后面不能带“明天上午九点在学校门口见面”这样的内容。", "增加": "搭配：「增加」说数量或程度，不能跟“见面”这种行为搭配。"}, "sentence_index": 0, "correct_answer": "约定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法官约定了被告三年的刑期。", "explanation": "这里应该用〈判处〉。法官对被告的刑罚是单方面判定的，约定指双方商定的事，不能用于判罚。"}, {"text": "我约定了下周三的气温。", "explanation": "这里应该用〈预报〉。气温由气象部门预报，不是双方商定的事，“约定”不能用于此。"}, {"text": "我约定这次考试能考满分。", "explanation": "这里应该用〈保证〉。“保证”指对自己能做到的结果作出担保，约定指双方商定的事，不能用来预测考试成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94696, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约定", "is_correct": true, "explanation": "「约定」表示双方事先商量好并确定下来，符合“每天都要读半小时书”的内容。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：「吵架」表示争执，与双方商定每天读书的内容不符。"}, {"text": "搬家", "is_correct": false, "explanation": "语义：「搬家」指搬迁住所，不能用来确定每天读书的安排。"}, {"text": "表扬", "is_correct": false, "explanation": "配价：「表扬」需要被表扬的对象和内容，句中“老师和我们”之后没有合适的宾语。"}], "explanations": {"约定": "「约定」表示双方事先商量好并确定下来，符合“每天都要读半小时书”的内容。", "吵架": "语义：「吵架」表示争执，与双方商定每天读书的内容不符。", "搬家": "语义：「搬家」指搬迁住所，不能用来确定每天读书的安排。", "表扬": "配价：「表扬」需要被表扬的对象和内容，句中“老师和我们”之后没有合适的宾语。"}, "sentence_index": 6, "correct_answer": "约定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师约定我们每天早起。", "explanation": "这里应该用〈要求〉。约定是双方商量好的事，老师对学生单方面提出的要求不用“约定”。"}, {"text": "学校约定每天早上七点开始上课。", "explanation": "这里应该用〈规定〉。学校单方面制定的作息安排要用“规定”，不能说“约定”。"}, {"text": "他约定了我的请求，并且马上帮忙。", "explanation": "这里应该用〈答应〉。“答应”表示接受对方的请求，约定是双方商定的事，不能直接用来接受别人的请求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94696, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们之间有一只约定：每周末一起打球。", "corrected_sentence": "我们之间有一个约定：每周末一起打球。", "error_description": "“约定”作名词表示商定的事，量词应说“一个约定”；“只”一般用于动物等，这里应改为“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94696, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们约定了好周末一起去爬山。", "corrected_sentence": "我们约定好了周末一起去爬山。", "error_description": "结果补语“好”要紧跟动词，应说“约定好了”，不能说“约定了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
