INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94697, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "约请是请别人来一起做一件事。", "primary_collocate": null, "pronunciation": "yuē qǐng", "ipa": "ɥɛ⁵⁵ tɕʰiŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "研究所约请三位专家一起修订标准。", "target_word": "约请", "complexity_tier": "T3", "furigana": "yánjiūsuǒ yuēqǐng sān wèi zhuānjiā yìqǐ xiūdìng biāozhǔn", "sentence_source": "generated"}, {"text": "编辑部约请几位作者一起撰写年度报告。", "target_word": "约请", "complexity_tier": "T3", "furigana": "biānjíbù yuēqǐng jǐ wèi zuòzhě yìqǐ zhuànxiě niándù bàogào", "sentence_source": "generated"}, {"text": "基金会约请多位学者一起研讨课题。", "target_word": "约请", "complexity_tier": "T3", "furigana": "jījīnhuì yuēqǐng duō wèi xuézhě yìqǐ yántǎo kètí", "sentence_source": "generated"}, {"text": "社团约请校友一起编写校史。", "target_word": "约请", "complexity_tier": "T3", "furigana": "shètuán yuēqǐng xiàoyǒu yìqǐ biānxiě xiàoshǐ", "sentence_source": "generated"}, {"text": "协会约请各地代表一起讨论章程。", "target_word": "约请", "complexity_tier": "T3", "furigana": "xiéhuì yuēqǐng gèdì dàibiǎo yìqǐ tǎolùn zhāngchéng", "sentence_source": "generated"}, {"text": "学院约请几位教授一起审阅论文。", "target_word": "约请", "complexity_tier": "T3", "furigana": "xuéyuàn yuēqǐng jǐ wèi jiàoshòu yìqǐ shěnyuè lùnwén", "sentence_source": "generated"}, {"text": "公司约请几位同事一起起草方案。", "target_word": "约请", "complexity_tier": "T3", "furigana": "gōngsī yuēqǐng jǐ wèi tóngshì yìqǐ qǐcǎo fāng''àn", "sentence_source": "generated"}, {"text": "研究组约请外校同行一起开展调查。", "target_word": "约请", "complexity_tier": "T3", "furigana": "yánjiūzǔ yuēqǐng wàixiào tóngháng yìqǐ kāizhǎn diàochá", "sentence_source": "generated"}, {"text": "博物馆约请志愿者一起整理馆藏文物。", "target_word": "约请", "complexity_tier": "T3", "furigana": "bówùguǎn yuēqǐng zhìyuànzhě yìqǐ zhěnglǐ guǎncáng wénwù", "sentence_source": "generated"}, {"text": "出版社约请译者一起校对译稿。", "target_word": "约请", "complexity_tier": "T3", "furigana": "chūbǎnshè yuēqǐng yìzhě yìqǐ jiàoduì yìgǎo", "sentence_source": "generated"}], "morphological_forms": [{"form": "约请了", "label": "完成体（了）"}, {"form": "约请过", "label": "经历体（过）"}], "register": "书面", "sense_fingerprint": "约请：请别人一起做某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '048b119b-ad33-43f5-bdcb-1cf74fb1a422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94697, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约请", "is_correct": true, "explanation": "正确。约请表示邀请专家一起做事，与“一起修订标准”相合。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的宾语是场所或物品，不能指专家。"}, {"text": "驱逐", "is_correct": false, "explanation": "语义：“驱逐”是赶走，与“一起修订标准”的合作意思不合。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”的宾语是建筑或物件，不能指专家。"}], "explanations": {"约请": "正确。约请表示邀请专家一起做事，与“一起修订标准”相合。", "打扫": "搭配：“打扫”的宾语是场所或物品，不能指专家。", "驱逐": "语义：“驱逐”是赶走，与“一起修订标准”的合作意思不合。", "拆": "搭配：“拆”的宾语是建筑或物件，不能指专家。"}, "sentence_index": 0, "correct_answer": "约请"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我约请他送我一本书。", "explanation": "这里应该用〈送〉。约请是请别人一起做一件事，送书只是一方给予，不需要共同做事，应说“他送我一本书”。"}, {"text": "我约请了一台电脑一起写论文。", "explanation": "这里应该用〈用〉。电脑是写论文的工具，应说“用电脑写论文”；约请的对象必须是能受邀一起做事的人。"}, {"text": "公司约请三名员工去外地出差。", "explanation": "这里应该用〈派〉。派遣员工出差是安排任务，约请强调对方自愿受邀参加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94697, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约请", "is_correct": true, "explanation": "正确。约请表示邀请同事一起做事，与“一起起草方案”相合。"}, {"text": "清洗", "is_correct": false, "explanation": "搭配：“清洗”的宾语是物品或身体部位，不能指同事。"}, {"text": "辞退", "is_correct": false, "explanation": "语义：“辞退”是解雇，与“一起起草方案”的合作意思相反。"}, {"text": "打击", "is_correct": false, "explanation": "语义：“打击”是攻击，与“一起起草方案”的合作意思不合。"}], "explanations": {"约请": "正确。约请表示邀请同事一起做事，与“一起起草方案”相合。", "清洗": "搭配：“清洗”的宾语是物品或身体部位，不能指同事。", "辞退": "语义：“辞退”是解雇，与“一起起草方案”的合作意思相反。", "打击": "语义：“打击”是攻击，与“一起起草方案”的合作意思不合。"}, "sentence_index": 6, "correct_answer": "约请"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我约请我自己一起校对译稿。", "explanation": "这里应该用〈独自〉。约请的对象必须是别人，自己校对译稿不能用约请，应说“我独自校对译稿”。"}, {"text": "这份合同约请双方一起签字。", "explanation": "这里应该用〈要求〉。合同只能规定或要求双方签字，不能主动约请双方；约请的主语必须是能邀请他人的人。"}, {"text": "出版社约请译者离开编辑部。", "explanation": "这里应该用〈让〉。约请只表示邀请对方一起做事，不能用于请人离开；应说“出版社让译者离开编辑部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94697, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市政府约请了三份文件一起制定方案。", "corrected_sentence": "市政府约请了三位专家一起制定方案。", "error_description": "宾语错误：“约请”的对象须是能受邀参与的人，“文件”不能被约请，应改为“三位专家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94697, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社区被约请了几位居民一起制定规则。", "corrected_sentence": "社区约请了几位居民一起制定规则。", "error_description": "语态错误：“约请”是主动动词，前面加“被”后不能带宾语，应去掉“被”，改为“约请了几位居民”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
