INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94698, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "邀请某人前来参加某项活动或会面。", "primary_collocate": null, "pronunciation": "yuē qǐng", "ipa": "ɥɛ⁵⁵ tɕʰiŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "学校约请了一位作家来开会。", "target_word": "约请", "complexity_tier": "T3", "furigana": "xuéxiào yuēqǐng le yí wèi zuòjiā lái kāihuì", "sentence_source": "generated"}, {"text": "经理约请王先生明天来公司见面。", "target_word": "约请", "complexity_tier": "T3", "furigana": "jīnglǐ yuēqǐng Wáng xiānsheng míngtiān lái gōngsī jiànmiàn", "sentence_source": "generated"}, {"text": "我们约请了很多老师参加晚会。", "target_word": "约请", "complexity_tier": "T3", "furigana": "wǒmen yuēqǐng le hěn duō lǎoshī cānjiā wǎnhuì", "sentence_source": "generated"}, {"text": "市长约请大家下周来看展览。", "target_word": "约请", "complexity_tier": "T3", "furigana": "shìzhǎng yuēqǐng dàjiā xià zhōu lái kàn zhǎnlǎn", "sentence_source": "generated"}, {"text": "他约请我下周六来市政厅参加座谈会。", "target_word": "约请", "complexity_tier": "T3", "furigana": "tā yuēqǐng wǒ xiàzhōuliù lái shìzhèngtīng cānjiā zuòtánhuì", "sentence_source": "generated"}, {"text": "公司约请过一位医生给大家上课。", "target_word": "约请", "complexity_tier": "T3", "furigana": "gōngsī yuēqǐng guo yí wèi yīshēng gěi dàjiā shàngkè", "sentence_source": "generated"}, {"text": "老师约请家长星期五来学校开会。", "target_word": "约请", "complexity_tier": "T3", "furigana": "lǎoshī yuēqǐng jiāzhǎng xīngqīwǔ lái xuéxiào kāihuì", "sentence_source": "generated"}, {"text": "他们约请了一位老朋友来参加婚礼。", "target_word": "约请", "complexity_tier": "T3", "furigana": "tāmen yuēqǐng le yí wèi lǎo péngyou lái cānjiā hūnlǐ", "sentence_source": "generated"}, {"text": "图书馆约请作家来给学生们讲课。", "target_word": "约请", "complexity_tier": "T3", "furigana": "túshūguǎn yuēqǐng zuòjiā lái gěi xuéshengmen jiǎngkè", "sentence_source": "generated"}, {"text": "我想约请李教授来参加我们的活动。", "target_word": "约请", "complexity_tier": "T3", "furigana": "wǒ xiǎng yuēqǐng Lǐ jiàoshòu lái cānjiā wǒmen de huódòng", "sentence_source": "generated"}], "morphological_forms": [{"form": "约请了", "label": "完成体（了）"}, {"form": "约请过", "label": "经历体（过）"}], "register": "书面", "sense_fingerprint": "约请：邀请某人来参加会议、活动或会面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '048b119b-ad33-43f5-bdcb-1cf74fb1a422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94698, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约请", "is_correct": true, "explanation": "正确。约请表示邀请某人前来参加活动，与“来开会”相合。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”是指责，不表示邀请作家前来开会。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的宾语是场所或物品，不能是人。"}, {"text": "辞退", "is_correct": false, "explanation": "语义：“辞退”是解雇，与“来开会”的邀请意思相反。"}], "explanations": {"约请": "正确。约请表示邀请某人前来参加活动，与“来开会”相合。", "批评": "语义：“批评”是指责，不表示邀请作家前来开会。", "打扫": "搭配：“打扫”的宾语是场所或物品，不能是人。", "辞退": "语义：“辞退”是解雇，与“来开会”的邀请意思相反。"}, "sentence_index": 0, "correct_answer": "约请"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我约请妈妈帮我洗碗。", "explanation": "这里应该用〈让〉。约请只用于邀请对方前来参加活动或会面，请妈妈帮忙做家务不是邀请，应说“让妈妈帮我洗碗”。"}, {"text": "他约请了一台新电脑来帮忙。", "explanation": "这里应该用〈借〉。电脑是物品，可以借来使用；约请的对象必须是能受邀前来的人，电脑不能被约请。"}, {"text": "我约请了一个好主意来解决问题。", "explanation": "这里应该用〈想出〉。约请的对象必须是能受邀前来的人，主意不能被约请；想出一个好主意来解决问题才是自然的说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约请", "is_correct": true, "explanation": "正确。约请表示邀请家长前来学校，与“星期五来学校开会”相合。"}, {"text": "清洗", "is_correct": false, "explanation": "搭配：“清洗”的宾语是物品或身体部位，不能指家长。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”的宾语是建筑或物件，不能指家长。"}, {"text": "驱逐", "is_correct": false, "explanation": "语义：“驱逐”是赶走，与“来学校开会”的邀请意思相反。"}], "explanations": {"约请": "正确。约请表示邀请家长前来学校，与“星期五来学校开会”相合。", "清洗": "搭配：“清洗”的宾语是物品或身体部位，不能指家长。", "拆": "搭配：“拆”的宾语是建筑或物件，不能指家长。", "驱逐": "语义：“驱逐”是赶走，与“来学校开会”的邀请意思相反。"}, "sentence_index": 6, "correct_answer": "约请"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我约请了那本书来参加读书会。", "explanation": "这里应该用〈带〉。约请的对象必须是能受邀前来的人，书不能被约请；应说“我带那本书来参加读书会”。"}, {"text": "我约请我自己来参加晚会。", "explanation": "这里应该用〈报名〉。要参加活动是自己去，应说“我报名参加晚会”；约请只能用来邀请别人。"}, {"text": "老师约请我离开教室。", "explanation": "这里应该用〈让〉。约请只表示邀请对方前来，不能用于请人离开；应说“老师让我离开教室”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司约请了两台机器来谈合同。", "corrected_sentence": "公司约请了两位律师来谈合同。", "error_description": "宾语错误：“约请”的对象须是能受邀前来的人，“机器”不能被约请，应改为“两位律师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上周我们被约请了一位摄影师来拍照。", "corrected_sentence": "上周我们约请了一位摄影师来拍照。", "error_description": "语态错误：“约请”是主动动词，前面加“被”后不能带宾语，应去掉“被”，改为“约请了一位摄影师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
