INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94704, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按照顺序给事物排定号码；也指所排的号码。", "primary_collocate": null, "pronunciation": "biān hào", "ipa": "pjɛn˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "老师给每张桌子编号。", "target_word": "编号", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你把这些书都编号。", "target_word": "编号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的编号是三五八。", "target_word": "编号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先编号，再按顺序排队。", "target_word": "编号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在表格上写下你的编号。", "target_word": "编号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人给仓库里的箱子编号。", "target_word": "编号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个座位都有编号，别坐错了。", "target_word": "编号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你查一下这个包裹的编号。", "target_word": "编号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆要给新书编号，再放上书架。", "target_word": "编号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛前，老师给每位选手编号。", "target_word": "编号", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "编号了", "label": "体标"}, {"form": "编号过", "label": "体标"}], "register": "中性", "sense_fingerprint": "按顺序给事物排号码，也指所排的号码", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca225a9-f261-4012-915b-1e8f99594883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.va