INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94704, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "编号", "is_correct": true, "explanation": "编号：给每个座位排上号码，与“别坐错了”的语境相合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：座位没有年龄，这个说法不成立，也与“别坐错了”无关。"}, {"text": "重量", "is_correct": false, "explanation": "语义：座位的重量与会不会坐错没有关系，语境不合。"}, {"text": "作者", "is_correct": false, "explanation": "语义：座位不会有作者，这个说法不成立，也与“别坐错了”无关。"}], "explanations": {"编号": "编号：给每个座位排上号码，与“别坐错了”的语境相合。", "年龄": "语义：座位没有年龄，这个说法不成立，也与“别坐错了”无关。", "重量": "语义：座位的重量与会不会坐错没有关系，语境不合。", "作者": "语义：座位不会有作者，这个说法不成立，也与“别坐错了”无关。"}, "sentence_index": 6, "correct_answer": "编号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给蛋糕编号了一圈花边。", "explanation": "这里应该用〈装饰〉。编号是排上数字，给蛋糕加花边要用装饰。"}, {"text": "他用绳子编号了一个中国结。", "explanation": "这里应该用〈编结〉。编号指排上数字，用绳子打结做装饰要用编结。"}, {"text": "他在窗边编号了一缕阳光。", "explanation": "这里应该用〈捕捉〉。编号指排上数字，阳光无法排号，抓住光线要用捕捉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个盒子上有一只编号。", "corrected_sentence": "这个盒子上有一个编号。", "error_description": "错误：“一只编号”。“编号”作名词时用量词“个”，不用“只”：应为“一个编号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师已经给每个选手编号着。", "corrected_sentence": "老师已经给每个选手编号了。", "error_description": "错误：“编号着”。“已经”表示动作已完成，应用“了”：应为“编号了”，“着”表示动作持续，不能用于已完成的动作。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94705, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "常见", "is_correct": true, "explanation": "正确。“常见”与“罕见”是反义词，指经常看到。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足，与“罕见”不构成反义。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”形容场面喧闹，与“罕见”不构成反义。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”形容速度快，与“罕见”不构成反义。"}], "correct_answer": "常见", "explanations": {"常见": "正确。“常见”与“罕见”是反义词，指经常看到。", "明亮": "“明亮”形容光线充足，与“罕见”不构成反义。", "热闹": "“热闹”形容场面喧闹，与“罕见”不构成反义。", "迅速": "“迅速”形容速度快，与“罕见”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94705, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "常见", "is_correct": true, "explanation": "正确。“常见”与“罕见”是反义词，指经常看到。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、分明，与“罕见”不构成反义。"}, {"text": "结实", "is_correct": false, "explanation": "“结实”形容坚固，与“罕见”不构成反义。"}, {"text": "响亮", "is_correct": false, "explanation": "“响亮”形容声音大而清楚，与“罕见”不构成反义。"}], "correct_answer": "常见", "explanations": {"常见": "正确。“常见”与“罕见”是反义词，指经常看到。", "清楚": "“清楚”形容明白、分明，与“罕见”不构成反义。", "结实": "“结实”形容坚固，与“罕见”不构成反义。", "响亮": "“响亮”形容声音大而清楚，与“罕见”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94705, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "罕见是很少很少能看到。", "primary_collocate": null, "pronunciation": "hǎn jiàn", "ipa": "xan˨˩˦ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这种动物在城市里十分罕见。", "target_word": "罕见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "六月下雪是罕见的事。", "target_word": "罕见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的大鱼在河里很罕见。", "target_word": "罕见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的才能在年轻人中很罕见。", "target_word": "罕见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二十年前，村里的汽车很罕见。", "target_word": "罕见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没见过这么罕见的颜色。", "target_word": "罕见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种红色的鸟罕见得很，我只看过一次。", "target_word": "罕见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我们学校，迟到的学生很罕见。", "target_word": "罕见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑容很罕见，大家都很吃惊。", "target_word": "罕见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里罕见的小动物，今天我看到了。", "target_word": "罕见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "很少很少能看到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3101b179-ea35-4787-b575-d3c8af1182ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94705, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "罕见", "is_correct": true, "explanation": "正确。“罕见”指很少能看到，“十分罕见”说这种动物在城市里很少见。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”是味道，不能用来形容动物。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”形容质地，不能用来说动物在城市里的情况。"}, {"text": "重大", "is_correct": false, "explanation": "搭配：“重大”多形容事件或决定，不说动物“十分重大”。"}], "explanations": {"罕见": "正确。“罕见”指很少能看到，“十分罕见”说这种动物在城市里很少见。", "辣": "语义：“辣”是味道，不能用来形容动物。", "硬": "语义：“硬”形容质地，不能用来说动物在城市里的情况。", "重大": "搭配：“重大”多形容事件或决定，不说动物“十分重大”。"}, "sentence_index": 0, "correct_answer": "罕见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都看到的电线杆很罕见。", "explanation": "这里应该用〈常见〉。“罕见”指很难见到，与“每天都看到”矛盾。"}, {"text": "学校门口每天都有的小卖部很罕见。", "explanation": "这里应该用〈常见〉。“罕见”指很难见到，不能形容每天都有的小卖部。"}, {"text": "我每天都能在食堂看到的老师很罕见。", "explanation": "这里应该用〈常见〉。“罕见”指很难见到，不能形容每天都能看到的老师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94705, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "罕见", "is_correct": true, "explanation": "正确。“罕见得很”与后面的“我只看过一次”相符。"}, {"text": "常见", "is_correct": false, "explanation": "语义：“常见”与后面的“我只看过一次”矛盾。"}, {"text": "热门", "is_correct": false, "explanation": "搭配：“热门”多形容话题或商品，不用来形容鸟。"}, {"text": "时髦", "is_correct": false, "explanation": "搭配：“时髦”多形容衣着或潮流，不用来形容鸟。"}], "explanations": {"罕见": "正确。“罕见得很”与后面的“我只看过一次”相符。", "常见": "语义：“常见”与后面的“我只看过一次”矛盾。", "热门": "搭配：“热门”多形容话题或商品，不用来形容鸟。", "时髦": "搭配：“时髦”多形容衣着或潮流，不用来形容鸟。"}, "sentence_index": 6, "correct_answer": "罕见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天都用的手机很罕见。", "explanation": "这里应该用〈常见〉。“罕见”指很难见到，与“每天都用”矛盾。"}, {"text": "随处可见的垃圾桶很罕见。", "explanation": "这里应该用〈常见〉。“罕见”指很难见到，不能形容随处可见的东西。"}, {"text": "公园里到处都能看到的鸽子很罕见。", "explanation": "这里应该用〈常见〉。“罕见”指很难见到，与“到处都能看到”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94705, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在山上见过很罕见鸟。", "corrected_sentence": "我在山上见过很罕见的鸟。", "error_description": "漏了“的”：“很罕见”作定语修饰名词时要加“的”，应说“很罕见的鸟”，不能说“很罕见鸟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
