INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94706, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很少见到，难得出现。", "primary_collocate": null, "pronunciation": "hǎn jiàn", "ipa": "xan˨˩˦ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这种鸟在我们这里很罕见。", "target_word": "罕见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的大雪在南方很罕见。", "target_word": "罕见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么高的分数在班里很罕见。", "target_word": "罕见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一种罕见的花，一年只开一次。", "target_word": "罕见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他得了一种罕见的病。", "target_word": "罕见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个城市，这样的好天气很罕见。", "target_word": "罕见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么安静的夜晚在大城市里很罕见。", "target_word": "罕见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个小镇上，这么热心的人很罕见。", "target_word": "罕见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书现在已经罕见了，书店里买不到。", "target_word": "罕见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪在海南非常罕见。", "target_word": "罕见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "很少见到、难得出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3101b179-ea35-4787-b575-d3c8af1182ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94706, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "罕见", "is_correct": true, "explanation": "正确。“罕见”指很少见到，“在我们这里很罕见”说这种鸟很少见。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”是味道，不能用来形容鸟。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”是味道，不能用来形容鸟。"}, {"text": "重大", "is_correct": false, "explanation": "搭配：“重大”多形容事件或决定，不说鸟“很重大”。"}], "explanations": {"罕见": "正确。“罕见”指很少见到，“在我们这里很罕见”说这种鸟很少见。", "咸": "语义：“咸”是味道，不能用来形容鸟。", "甜": "语义：“甜”是味道，不能用来形容鸟。", "重大": "搭配：“重大”多形容事件或决定，不说鸟“很重大”。"}, "sentence_index": 0, "correct_answer": "罕见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个村子的人口很罕见。", "explanation": "这里应该用〈稀少〉。“罕见”指事物很少见到，说人口或数量少要用“稀少”。"}, {"text": "超市里天天都卖的苹果很罕见。", "explanation": "这里应该用〈常见〉。“罕见”指很难见到，不能形容天天都有的东西。"}, {"text": "我天天见到的老朋友很罕见。", "explanation": "这里应该用〈常见〉。“罕见”指很难见到，不能形容天天都能见到的朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "罕见", "is_correct": true, "explanation": "正确。“很罕见”与“这么安静的夜晚”相符，说明这样的夜晚很少见。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”与前面的“安静”矛盾。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容空间，不用来形容夜晚。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”与前面的“安静”矛盾。"}], "explanations": {"罕见": "正确。“很罕见”与“这么安静的夜晚”相符，说明这样的夜晚很少见。", "吵闹": "语义：“吵闹”与前面的“安静”矛盾。", "宽敞": "搭配：“宽敞”形容空间，不用来形容夜晚。", "热闹": "语义：“热闹”与前面的“安静”矛盾。"}, "sentence_index": 6, "correct_answer": "罕见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "街上随处可见的饭店很罕见。", "explanation": "这里应该用〈常见〉。“罕见”指很难见到，不能形容随处可见的饭店。"}, {"text": "我每天吃的早饭很罕见。", "explanation": "这里应该用〈常见〉。“罕见”指很难见到，与“每天吃”矛盾。"}, {"text": "我家门口的大树每天都能看到，很罕见。", "explanation": "这里应该用〈常见〉。“罕见”指很难见到，与“每天都能看到”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他罕见的笑了一下。", "corrected_sentence": "他罕见地笑了一下。", "error_description": "用词错误：“罕见”修饰动词时是状语，要用“地”，不用“的”，应说“罕见地笑了一下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这样的好天气在这里很罕见地。", "corrected_sentence": "这样的好天气在这里很罕见。", "error_description": "多了“地”：“罕见”作谓语时后面不能加“地”，应去掉“地”，说“这样的好天气在这里很罕见”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
