INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94707, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "耶是开心时叫出来的声音。", "primary_collocate": null, "pronunciation": "yē", "ipa": "je˥", "syllable_count": 1, "sentences": [{"text": "耶！我考了第一名！", "target_word": "耶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "耶，今天不用上班了！", "target_word": "耶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到放假的消息，孩子们大声喊：“耶！”", "target_word": "耶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "耶！我们赢了这场比赛！", "target_word": "耶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说可以去公园玩，弟弟高兴地叫了一声“耶”。", "target_word": "耶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "耶，终于吃到我最爱的蛋糕了！", "target_word": "耶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "拍照的时候，大家一起喊“耶”！", "target_word": "耶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "耶！明天是周末，我们去海边吧！", "target_word": "耶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她接到好消息，开心地跳起来说：“耶！”", "target_word": "耶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "耶，我的新手机到了！", "target_word": "耶", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "耶：高兴时喊出的欢呼声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b6ab932-ffa3-44f3-be69-23e97a6cbed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94707, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "耶", "is_correct": true, "explanation": "正确。耶（yē）是高兴时喊出的欢呼声。"}, {"text": "也", "is_correct": false, "explanation": "yě（第三声）与 yē（第一声）声调不同，也是副词，意思是「也」。"}, {"text": "夜", "is_correct": false, "explanation": "yè（第四声）与 yē（第一声）声调不同，夜指夜晚。"}, {"text": "爷", "is_correct": false, "explanation": "yé（第二声）与 yē（第一声）声调不同，爷指祖父。"}, {"text": "叶", "is_correct": false, "explanation": "yè（第四声）与 yē（第一声）声调不同，叶指树叶。"}], "explanations": {"耶": "正确。耶（yē）是高兴时喊出的欢呼声。", "也": "yě（第三声）与 yē（第一声）声调不同，也是副词，意思是「也」。", "夜": "yè（第四声）与 yē（第一声）声调不同，夜指夜晚。", "爷": "yé（第二声）与 yē（第一声）声调不同，爷指祖父。", "叶": "yè（第四声）与 yē（第一声）声调不同，叶指树叶。"}, "sentence_index": null, "correct_answer": "耶"}, "level_3": {"options": [{"text": "耶", "is_correct": true, "explanation": "正确：耶是高兴时喊出的欢呼声，与「我考了第一名」相合。"}, {"text": "唉", "is_correct": false, "explanation": "语义：唉表示叹气，与「我考了第一名」的高兴相反。"}, {"text": "呸", "is_correct": false, "explanation": "语义：呸表示厌恶或唾弃，与高兴的语气不合。"}, {"text": "嘘", "is_correct": false, "explanation": "搭配：「嘘」用于叫人安静，不用于宣布成绩。"}], "explanations": {"耶": "正确：耶是高兴时喊出的欢呼声，与「我考了第一名」相合。", "唉": "语义：唉表示叹气，与「我考了第一名」的高兴相反。", "呸": "语义：呸表示厌恶或唾弃，与高兴的语气不合。", "嘘": "搭配：「嘘」用于叫人安静，不用于宣布成绩。"}, "sentence_index": 0, "correct_answer": "耶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "耶，不好意思，我迟到了。", "explanation": "这里应该用〈对不起〉。「耶」表示欢呼或高兴，道歉的场合要用〈对不起〉。"}, {"text": "耶，别说话，老师在睡觉。", "explanation": "这里应该用〈嘘〉。「耶」表示欢呼，不能用来提醒别人安静，让人安静要用〈嘘〉。"}, {"text": "耶，我的脚好疼！", "explanation": "这里应该用〈哎哟〉。「耶」是欢呼，不用于疼痛时的叫声，疼痛要用〈哎哟〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94707, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "耶", "is_correct": true, "explanation": "正确。耶（yē）是高兴时喊出的欢呼声。"}, {"text": "业", "is_correct": false, "explanation": "yè（第四声）与 yē（第一声）声调不同，业指事业、职业。"}, {"text": "野", "is_correct": false, "explanation": "yě（第三声）与 yē（第一声）声调不同，野指原野、野外。"}, {"text": "页", "is_correct": false, "explanation": "yè（第四声）与 yē（第一声）声调不同，页指书页、页面。"}], "explanations": {"耶": "正确。耶（yē）是高兴时喊出的欢呼声。", "业": "yè（第四声）与 yē（第一声）声调不同，业指事业、职业。", "野": "yě（第三声）与 yē（第一声）声调不同，野指原野、野外。", "页": "yè（第四声）与 yē（第一声）声调不同，页指书页、页面。"}, "sentence_index": null, "correct_answer": "耶"}, "level_3": {"options": [{"text": "耶", "is_correct": true, "explanation": "正确：耶是欢呼声，与「大家一起喊」的拍照场景相合。"}, {"text": "哼", "is_correct": false, "explanation": "语义：哼表示不满或轻蔑，与拍照时的欢快不合。"}, {"text": "嗷", "is_correct": false, "explanation": "搭配：「嗷」多用于野兽的叫声或痛叫，不用于拍照时的喊声。"}, {"text": "咳", "is_correct": false, "explanation": "语义：「咳」是咳嗽声，与拍照时的欢呼不合。"}], "explanations": {"耶": "正确：耶是欢呼声，与「大家一起喊」的拍照场景相合。", "哼": "语义：哼表示不满或轻蔑，与拍照时的欢快不合。", "嗷": "搭配：「嗷」多用于野兽的叫声或痛叫，不用于拍照时的喊声。", "咳": "语义：「咳」是咳嗽声，与拍照时的欢呼不合。"}, "sentence_index": 6, "correct_answer": "耶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "耶，您是哪位？", "explanation": "这里应该用〈喂〉。「耶」表示欢呼，不用于打电话时招呼对方，招呼要用〈喂〉。"}, {"text": "耶，请把门关上。", "explanation": "这里应该用〈麻烦〉。「耶」表示欢呼或高兴，请人做事要用〈麻烦〉。"}, {"text": "耶，你等等我！", "explanation": "这里应该用〈哎〉。「耶」是欢呼，不用于叫住别人，叫住别人要用〈哎〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94707, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他中了彩票，忍不住喊了一个“耶”！", "corrected_sentence": "他中了彩票，忍不住喊了一声“耶”！", "error_description": "「一个“耶”」错在量词。喊出的声音要用量词「声」，应说「一声“耶”」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94707, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "耶了，这个周末我们终于可以出去玩了！", "corrected_sentence": "耶，这个周末我们终于可以出去玩了！", "error_description": "「耶」后面多加了「了」。叹词「耶」不带体标，应直接用逗号连接，说「耶，这个周末我们终于可以出去玩了！」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94709, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自卑", "is_correct": true, "explanation": "「自卑」与「自信」意思相反，是反义词。"}, {"text": "懒惰", "is_correct": false, "explanation": "「懒惰」指不愿劳动或做事，与「自信」没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "「热情」指待人友好或做事积极，与「自信」没有反义关系。"}, {"text": "平静", "is_correct": false, "explanation": "「平静」指心情安定，与「自信」不构成反义。"}], "correct_answer": "自卑", "explanations": {"自卑": "「自卑」与「自信」意思相反，是反义词。", "懒惰": "「懒惰」指不愿劳动或做事，与「自信」没有反义关系。", "热情": "「热情」指待人友好或做事积极，与「自信」没有反义关系。", "平静": "「平静」指心情安定，与「自信」不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94709, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自卑", "is_correct": true, "explanation": "「自卑」与「自信」意思相反，是反义词。"}, {"text": "迟钝", "is_correct": false, "explanation": "「迟钝」指反应慢，与「自信」没有反义关系。"}, {"text": "粗心", "is_correct": false, "explanation": "「粗心」指做事不细致，与「自信」没有反义关系。"}, {"text": "冷淡", "is_correct": false, "explanation": "「冷淡」指态度不热情，与「自信」没有反义关系。"}], "correct_answer": "自卑", "explanations": {"自卑": "「自卑」与「自信」意思相反，是反义词。", "迟钝": "「迟钝」指反应慢，与「自信」没有反义关系。", "粗心": "「粗心」指做事不细致，与「自信」没有反义关系。", "冷淡": "「冷淡」指态度不热情，与「自信」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94709, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "自信是相信自己能做好。", "primary_collocate": null, "pronunciation": "zì xìn", "ipa": "tsɨ˥˩ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "他很自信，觉得这次比赛一定能赢。", "target_word": "自信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很自信，相信能把工作做好。", "target_word": "自信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛以前，教练让大家自信一点。", "target_word": "自信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对唱歌很自信，所以报名了。", "target_word": "自信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一点也不自信，总是怕做不好。", "target_word": "自信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子做对了事，就会变得更自信。", "target_word": "自信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说到做饭，妈妈总是特别自信。", "target_word": "自信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画画让他慢慢变得自信。", "target_word": "自信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做事要自信，别总想着会失败。", "target_word": "自信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她自信地说：“这件事我能做好。”", "target_word": "自信", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自信心", "label": "复合"}, {"form": "自信地", "label": "状语形式"}, {"form": "不自信", "label": "否定"}, {"form": "自信满满", "label": "复合"}], "register": "中性", "sense_fingerprint": "相信自己能把事情做好的心理状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b189c5-928f-4b14-9e03-b75e919a5733') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94709, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自信", "is_correct": true, "explanation": "「自信」指相信自己能把事做好，与「觉得这次比赛一定能赢」吻合。"}, {"text": "自卑", "is_correct": false, "explanation": "语义：「自卑」指看轻自己，与「觉得这次比赛一定能赢」的判断相反。"}, {"text": "悲观", "is_correct": false, "explanation": "语义：「悲观」指对前途失望，与「一定能赢」的想法矛盾。"}, {"text": "胆小", "is_correct": false, "explanation": "搭配：「胆小」形容性格怯懦，不用来描写对比赛结果的判断。"}], "explanations": {"自信": "「自信」指相信自己能把事做好，与「觉得这次比赛一定能赢」吻合。", "自卑": "语义：「自卑」指看轻自己，与「觉得这次比赛一定能赢」的判断相反。", "悲观": "语义：「悲观」指对前途失望，与「一定能赢」的想法矛盾。", "胆小": "搭配：「胆小」形容性格怯懦，不用来描写对比赛结果的判断。"}, "sentence_index": 0, "correct_answer": "自信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她为班里拿了第一名而自信。", "explanation": "这里应该用〈自豪〉。「自豪」可用于为集体或他人的成就感到骄傲；「自信」只指对自己有把握。"}, {"text": "他为儿子拿到奖牌很自信。", "explanation": "这里应该用〈骄傲〉。「骄傲」表示因成就而光荣；「自信」不能用来说为别人的成绩而有把握。"}, {"text": "我为弟弟的进步而自信。", "explanation": "这里应该用〈高兴〉。「高兴」可以表示为别人的好事感到快乐；「自信」只指相信自己能做好，不用于别人的进步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94709, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自信", "is_correct": true, "explanation": "「自信」指对自己的本事有把握，与「总是特别」的熟练形象吻合。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：「陌生」指不熟悉，与「说到做饭，妈妈总是特别……」中熟练的形象相反。"}, {"text": "胆怯", "is_correct": false, "explanation": "语义：「胆怯」指害怕，与做饭时的熟练形象冲突。"}, {"text": "悲伤", "is_correct": false, "explanation": "搭配：「悲伤」说情绪，不用来描写妈妈做饭时的态度。"}], "explanations": {"自信": "「自信」指对自己的本事有把握，与「总是特别」的熟练形象吻合。", "陌生": "语义：「陌生」指不熟悉，与「说到做饭，妈妈总是特别……」中熟练的形象相反。", "胆怯": "语义：「胆怯」指害怕，与做饭时的熟练形象冲突。", "悲伤": "搭配：「悲伤」说情绪，不用来描写妈妈做饭时的态度。"}, "sentence_index": 6, "correct_answer": "自信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很自信这次考试肯定会考砸。", "explanation": "这里应该用〈担心〉。「担心」表示为不好的结果忧虑；「自信」表示相信自己能做好，不能用来预计失败。"}, {"text": "她很自信，遇到难题就哭着跑开。", "explanation": "这里应该用〈胆怯〉。「胆怯」形容遇事害怕、退缩；「自信」表示相信自己能做好，与「哭着跑开」的状态不符。"}, {"text": "她很自信，一上台就吓得说不出话。", "explanation": "这里应该用〈紧张〉。「紧张」形容心里发慌；「自信」表示相信自己能做好，与「吓得说不出话」矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94709, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们变得更自信的。", "corrected_sentence": "孩子们变得更自信了。", "error_description": "错误：句末表示变化已经发生，要用语气词「了」，不能用「的」。正确形式是「更自信了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94709, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子自信的站上了台。", "corrected_sentence": "孩子自信地站上了台。", "error_description": "错误：「自信」修饰动词时要用「地」。「自信的」是定语标记，应改为「自信地站上了台」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94710, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自卑", "is_correct": true, "explanation": "「自卑」与「自信」意思相反，是反义词。"}, {"text": "懒惰", "is_correct": false, "explanation": "「懒惰」指不愿劳动或做事，与「自信」没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "「热情」指待人友好或做事积极，与「自信」没有反义关系。"}, {"text": "平静", "is_correct": false, "explanation": "「平静」指心情安定，与「自信」不构成反义。"}], "correct_answer": "自卑", "explanations": {"自卑": "「自卑」与「自信」意思相反，是反义词。", "懒惰": "「懒惰」指不愿劳动或做事，与「自信」没有反义关系。", "热情": "「热情」指待人友好或做事积极，与「自信」没有反义关系。", "平静": "「平静」指心情安定，与「自信」不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94710, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自卑", "is_correct": true, "explanation": "「自卑」与「自信」意思相反，是反义词。"}, {"text": "迟钝", "is_correct": false, "explanation": "「迟钝」指反应慢，与「自信」没有反义关系。"}, {"text": "粗心", "is_correct": false, "explanation": "「粗心」指做事不细致，与「自信」没有反义关系。"}, {"text": "冷淡", "is_correct": false, "explanation": "「冷淡」指态度不热情，与「自信」没有反义关系。"}], "correct_answer": "自卑", "explanations": {"自卑": "「自卑」与「自信」意思相反，是反义词。", "迟钝": "「迟钝」指反应慢，与「自信」没有反义关系。", "粗心": "「粗心」指做事不细致，与「自信」没有反义关系。", "冷淡": "「冷淡」指态度不热情，与「自信」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94710, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "相信自己的能力或判断，不怀疑自己。", "primary_collocate": null, "pronunciation": "zì xìn", "ipa": "tsɨ˥˩ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "她对自己的判断很自信。", "target_word": "自信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话的时候，样子非常自信。", "target_word": "自信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这次考试不太自信。", "target_word": "自信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要自信一点，别怕说错。", "target_word": "自信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走上台，脸上带着自信的笑。", "target_word": "自信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对自己的能力，她一直很自信。", "target_word": "自信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王走路抬着头，看起来十分自信。", "target_word": "自信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不自信，所以不敢举手。", "target_word": "自信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，我们应该对自己的想法更自信。", "target_word": "自信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他自信地回答了所有问题。", "target_word": "自信", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自信心", "label": "复合"}, {"form": "自信地", "label": "状语形式"}, {"form": "不自信", "label": "否定"}, {"form": "自信满满", "label": "复合"}], "register": "中性", "sense_fingerprint": "对自己的能力或判断有把握，不怀疑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b189c5-928f-4b14-9e03-b75e919a5733') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94710, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自信", "is_correct": true, "explanation": "「自信」指对自己的判断有把握，与「对自己的判断」搭配。"}, {"text": "自卑", "is_correct": false, "explanation": "语义：「自卑」指看轻自己，与「对自己的判断很……」的把握相反。"}, {"text": "胆小", "is_correct": false, "explanation": "搭配：「胆小」形容性格怯懦，不能用来修饰「判断」。"}, {"text": "慌张", "is_correct": false, "explanation": "语义：「慌张」指一时心神不定，与对判断有把握的意思不相容。"}], "explanations": {"自信": "「自信」指对自己的判断有把握，与「对自己的判断」搭配。", "自卑": "语义：「自卑」指看轻自己，与「对自己的判断很……」的把握相反。", "胆小": "搭配：「胆小」形容性格怯懦，不能用来修饰「判断」。", "慌张": "语义：「慌张」指一时心神不定，与对判断有把握的意思不相容。"}, "sentence_index": 0, "correct_answer": "自信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他为女儿考上大学而自信。", "explanation": "这里应该用〈自豪〉。「自豪」可用于为别人或自己的成就感到骄傲；「自信」只指对自己的能力有把握，不能这样用。"}, {"text": "她为自己的母校感到自信。", "explanation": "这里应该用〈骄傲〉。「骄傲」表示因集体或他人的成就而光荣；「自信」不用于为母校感到光荣。"}, {"text": "我为朋友的成功而自信。", "explanation": "这里应该用〈高兴〉。「高兴」可以表示为别人的成功感到快乐；「自信」指对自己有把握，不用于别人的成功。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94710, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自信", "is_correct": true, "explanation": "「自信」形容有把握、不怀疑自己的样子，与「抬着头」吻合。"}, {"text": "萎靡", "is_correct": false, "explanation": "语义：「萎靡」指精神不振，与句中「抬着头」的样子相反。"}, {"text": "狼狈", "is_correct": false, "explanation": "语义：「狼狈」指窘迫不堪的样子，与「抬着头」不相符。"}, {"text": "怯懦", "is_correct": false, "explanation": "语义：「怯懦」指胆小退缩，与句中「抬着头」的自信姿态相反。"}], "explanations": {"自信": "「自信」形容有把握、不怀疑自己的样子，与「抬着头」吻合。", "萎靡": "语义：「萎靡」指精神不振，与句中「抬着头」的样子相反。", "狼狈": "语义：「狼狈」指窘迫不堪的样子，与「抬着头」不相符。", "怯懦": "语义：「怯懦」指胆小退缩，与句中「抬着头」的自信姿态相反。"}, "sentence_index": 6, "correct_answer": "自信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一上台就很自信，两腿直发抖。", "explanation": "这里应该用〈紧张〉。「紧张」形容心里发慌；「自信」指对自己有把握，与「两腿直发抖」的状态矛盾。"}, {"text": "他很自信，做决定时总是拿不定主意。", "explanation": "这里应该用〈犹豫〉。「犹豫」形容拿不定主意；「自信」指对自己有把握，不能描述做决定时的迟疑。"}, {"text": "小王很自信，见到老板却不敢说话。", "explanation": "这里应该用〈胆怯〉。「胆怯」形容害怕、不敢；「自信」指有把握，不表示不敢开口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她变得越来越自信的。", "corrected_sentence": "她变得越来越自信了。", "error_description": "错误：句末表示变化已经发生，要用语气词「了」，不能用「的」。正确形式是「越来越自信了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他自信的走进教室。", "corrected_sentence": "他自信地走进教室。", "error_description": "错误：「自信」修饰动词时要用「地」。「自信的」是定语标记，应改为「自信地走进教室」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
