INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94711, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "自由活动是自己想玩什么就玩什么的时间。", "primary_collocate": null, "pronunciation": "zì yóu huó dòng", "ipa": "tsɨ˥˩ joʊ˧˥ xwo˧˥ tʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "下课以后是自由活动，孩子们跑去玩游戏。", "target_word": "自由活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幼儿园每天下午都有一段自由活动。", "target_word": "自由活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自由活动的时候，我喜欢画画。", "target_word": "自由活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“现在自由活动，想玩什么都可以。”", "target_word": "自由活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们最喜欢自由活动，因为可以随便玩。", "target_word": "自由活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自由活动时间到了，小明马上拿出球。", "target_word": "自由活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的自由活动，我们决定去踢足球。", "target_word": "自由活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "营地里晚上有自由活动，大家一起唱歌。", "target_word": "自由活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在自由活动的时候一直玩着积木。", "target_word": "自由活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下得很大，自由活动只能在教室里玩。", "target_word": "自由活动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "想玩什么就玩什么的自己支配的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbde994-dc07-4f05-b67a-7432fadb09bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94711, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上课", "is_correct": false, "explanation": "语义：前句说“下课以后”，后面又说“上课”，与前句矛盾。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”与后半句“跑去玩游戏”矛盾。"}, {"text": "自由活动", "is_correct": true, "explanation": "“自由活动”指想玩什么就玩什么的时间，与“下课以后”和“跑去玩游戏”相符，是正确答案。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”不是活动或时间段，不能说“下课以后是体温”。"}], "explanations": {"上课": "语义：前句说“下课以后”，后面又说“上课”，与前句矛盾。", "考试": "语义：“考试”与后半句“跑去玩游戏”矛盾。", "自由活动": "“自由活动”指想玩什么就玩什么的时间，与“下课以后”和“跑去玩游戏”相符，是正确答案。", "体温": "搭配：“体温”不是活动或时间段，不能说“下课以后是体温”。"}, "sentence_index": 0, "correct_answer": "自由活动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的自由活动很好听，我很喜欢。", "explanation": "“自由活动”指一段时间，不能用来形容歌曲；形容歌曲好听要用〈悦耳〉。"}, {"text": "他今天的自由活动很聪明。", "explanation": "“自由活动”指一段时间，不能用来形容人的聪明；形容人聪明要用〈机灵〉。"}, {"text": "老师给我们一只自由活动。", "explanation": "“只”用于动物、物件等，不能修饰“自由活动”，这里应该用〈段〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94711, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨", "is_correct": false, "explanation": "语义：“雨”是天气，不能作为可安排的活动，与“决定去踢足球”矛盾。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“感冒”是疾病，不能说“今天的感冒”作为踢足球活动的安排。"}, {"text": "自由活动", "is_correct": true, "explanation": "“自由活动”指可以自己安排的时间，与“决定去踢足球”相符，是正确答案。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”与“决定去踢足球”的安排矛盾。"}], "explanations": {"雨": "语义：“雨”是天气，不能作为可安排的活动，与“决定去踢足球”矛盾。", "感冒": "搭配：“感冒”是疾病，不能说“今天的感冒”作为踢足球活动的安排。", "自由活动": "“自由活动”指可以自己安排的时间，与“决定去踢足球”相符，是正确答案。", "作业": "语义：“作业”与“决定去踢足球”的安排矛盾。"}, "sentence_index": 6, "correct_answer": "自由活动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这批玩具的自由活动很便宜，我们买了两套。", "explanation": "“自由活动”指一段时间，不能用来说商品的价格；这里应直接说“这批玩具很便宜”。"}, {"text": "妈妈把这一天的自由活动洗干净了。", "explanation": "这里“自由活动”指一段时间，不是可以洗的东西；说一天的时长要说〈时间〉。"}, {"text": "老师给我们一条自由活动，大家都很高兴。", "explanation": "“条”用于细长的东西，不能修饰“自由活动”，这里应该用〈段〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94711, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班每天下午都有一只自由活动。", "corrected_sentence": "我们班每天下午都有一段自由活动。", "error_description": "量词用错。错误形式是“一只自由活动”，正确形式是“一段自由活动”，“只”用于动物、物件，“自由活动”指一段时间，应用“段”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94711, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "营地里晚上有一只自由活动，大家一起唱歌。", "corrected_sentence": "营地里晚上有一段自由活动，大家一起唱歌。", "error_description": "量词用错。错误形式是“一只自由活动”，正确形式是“一段自由活动”，“只”用于动物、物件，活动应用“段”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
