INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94712, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "在规定的时间里，可以按自己的意愿安排的活动。", "primary_collocate": null, "pronunciation": "zì yóu huó dòng", "ipa": "tsɨ˥˩ joʊ˧˥ xwo˧˥ tʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "下午两点到四点是自由活动时间。", "target_word": "自由活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚饭后有一个小时自由活动。", "target_word": "自由活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行第二天下午是自由活动，你可以去买东西。", "target_word": "自由活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自由活动时，请不要离开学校。", "target_word": "自由活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游给了我们两个小时自由活动。", "target_word": "自由活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课间的自由活动，我一般去操场。", "target_word": "自由活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的自由活动，你想去哪儿？", "target_word": "自由活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议中间有半小时自由活动，大家可以喝咖啡。", "target_word": "自由活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自由活动结束了，请回到车上来。", "target_word": "自由活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校每周三下午都有自由活动。", "target_word": "自由活动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "规定时间内可按自己意愿安排的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbde994-dc07-4f05-b67a-7432fadb09bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94712, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教室", "is_correct": false, "explanation": "语义：“教室”是地点，不是时间段，不能作“时间”的定语。"}, {"text": "自由活动", "is_correct": true, "explanation": "“自由活动”指规定时间内自己安排的活动，与“时间”搭配，是正确答案。"}, {"text": "苹果", "is_correct": false, "explanation": "搭配：“苹果”是水果，不能说“苹果时间”。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是地点，与“下午两点到四点”这一时间段不符。"}], "explanations": {"教室": "语义：“教室”是地点，不是时间段，不能作“时间”的定语。", "自由活动": "“自由活动”指规定时间内自己安排的活动，与“时间”搭配，是正确答案。", "苹果": "搭配：“苹果”是水果，不能说“苹果时间”。", "厨房": "语义：“厨房”是地点，与“下午两点到四点”这一时间段不符。"}, "sentence_index": 0, "correct_answer": "自由活动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师规定，这段自由活动每个人都要做一样的事。", "explanation": "“自由活动”指可以按自己意愿安排的时间，不能说人人做一样的事；统一安排的活动要说〈集体活动〉。"}, {"text": "这把椅子是自由活动的，想怎么放就怎么放。", "explanation": "“自由活动”指人在规定时间里按意愿安排的活动，不能用来形容物品；说椅子能移动要说〈可移动〉。"}, {"text": "我们有一只自由活动，很好玩。", "explanation": "“只”用于动物、物件等，不能修饰“自由活动”，这里应该用〈段〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94712, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：“作业”不能去哪儿，与“你想去哪儿”不协调。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是可以安排的活动，与“你想去哪儿”不协调。"}, {"text": "自由活动", "is_correct": true, "explanation": "“自由活动”指可以自己安排的活动，能够作为“你想去哪儿”的话题，是正确答案。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“感冒”是疾病，不能说“今天的感冒”作为可以安排去哪里的事。"}], "explanations": {"作业": "语义：“作业”不能去哪儿，与“你想去哪儿”不协调。", "天气": "语义：“天气”不是可以安排的活动，与“你想去哪儿”不协调。", "自由活动": "“自由活动”指可以自己安排的活动，能够作为“你想去哪儿”的话题，是正确答案。", "感冒": "搭配：“感冒”是疾病，不能说“今天的感冒”作为可以安排去哪里的事。"}, "sentence_index": 6, "correct_answer": "自由活动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的自由活动很好吃，大家都抢着吃。", "explanation": "“自由活动”指规定时间里的活动，不能用来形容食物；说食物好吃要用〈美味〉。"}, {"text": "这家店卖各种自由活动，价格很便宜。", "explanation": "“自由活动”指规定时间里自己安排的活动，不是商品，不能说店里卖；这里要说〈商品〉。"}, {"text": "学校每周三给我们一条自由活动。", "explanation": "“条”用于细长的东西，不能修饰“自由活动”，这里应该用〈段〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晚饭后有一只自由活动。", "corrected_sentence": "晚饭后有一段自由活动。", "error_description": "量词用错。错误形式是“一只自由活动”，正确形式是“一段自由活动”，“只”用于动物、物件，活动一般用“段”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末地自由活动，你想去哪儿？", "corrected_sentence": "周末的自由活动，你想去哪儿？", "error_description": "结构助词用错。错误形式是“周末地自由活动”，正确形式是“周末的自由活动”，时间词作定语时用“的”，“地”用来修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
