INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94713, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "街上是有很多人和车走的路上。", "primary_collocate": null, "pronunciation": "jiē shang", "ipa": "tɕje⁵⁵ ʂaŋ", "syllable_count": 2, "sentences": [{"text": "周末的街上人很多，车也很多。", "target_word": "街上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下班以后，街上到处都是回家的人和车。", "target_word": "街上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "街上的车太多了，我们走了很久才过马路。", "target_word": "街上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年前，街上挤满了买东西的人。", "target_word": "街上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天，街上的车走得很慢。", "target_word": "街上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在街上看到很多汽车和自行车。", "target_word": "街上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上八点，街上还有很多人在走路。", "target_word": "街上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "节日的时候，街上的人多得走不动。", "target_word": "街上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站在路边，看着街上来来往往的车。", "target_word": "街上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上六点，街上的人和车渐渐多起来了。", "target_word": "街上", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人来车往的街道上，强调人多车多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b189c5-928f-4b14-9e03-b75e919a5733') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94713, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "街上", "is_correct": true, "explanation": "「街上」指有人车往来的道路，与「人很多，车也很多」吻合。"}, {"text": "教室里", "is_correct": false, "explanation": "语义：教室里没有车来往，与句中「车也很多」冲突。"}, {"text": "房间里", "is_correct": false, "explanation": "语义：房间是室内，不能说车也很多。"}, {"text": "图书馆里", "is_correct": false, "explanation": "搭配：图书馆通常安静，不与「车也很多」搭配。"}], "explanations": {"街上": "「街上」指有人车往来的道路，与「人很多，车也很多」吻合。", "教室里": "语义：教室里没有车来往，与句中「车也很多」冲突。", "房间里": "语义：房间是室内，不能说车也很多。", "图书馆里": "搭配：图书馆通常安静，不与「车也很多」搭配。"}, "sentence_index": 0, "correct_answer": "街上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "飞机在街上起飞了。", "explanation": "这里应该用〈机场〉。「街上」指城镇里供人车通行的道路，飞机不在街上起降。"}, {"text": "农民在街上插秧。", "explanation": "这里应该用〈田里〉。「街上」指城镇里的道路，插秧的地方不能说在街上。"}, {"text": "鱼在街上游来游去。", "explanation": "这里应该用〈水里〉。「街上」指人车往来的道路，鱼只能在水里游。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94713, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "街上", "is_correct": true, "explanation": "「街上」指道路上的人车活动，与「晚上八点，还有很多人在走路」吻合。"}, {"text": "银行里", "is_correct": false, "explanation": "语义：晚上八点银行已关门，不会有很多人在里面走路。"}, {"text": "水里", "is_correct": false, "explanation": "语义：人不会在水里走路，与句意冲突。"}, {"text": "卧室里", "is_correct": false, "explanation": "语义：卧室是私人房间，晚上八点不会有很多人在里面走路，与句意冲突。"}], "explanations": {"街上": "「街上」指道路上的人车活动，与「晚上八点，还有很多人在走路」吻合。", "银行里": "语义：晚上八点银行已关门，不会有很多人在里面走路。", "水里": "语义：人不会在水里走路，与句意冲突。", "卧室里": "语义：卧室是私人房间，晚上八点不会有很多人在里面走路，与句意冲突。"}, "sentence_index": 6, "correct_answer": "街上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚上我在街上睡觉。", "explanation": "这里应该用〈床上〉。「街上」指人车往来的道路，不是睡觉的地方。"}, {"text": "船在街上慢慢开着。", "explanation": "这里应该用〈河上〉。「街上」是人和车走的路，船在水上行驶。"}, {"text": "学生们在街上上数学课。", "explanation": "这里应该用〈教室里〉。「街上」指人车往来的道路，上课在教室里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94713, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们的街上玩耍。", "corrected_sentence": "孩子们在街上玩耍。", "error_description": "错误：「街上」表示地点，前面要用「在」，不能用「的」把它变成所属词。应为「孩子们在街上玩耍」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94713, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晚上八点，还有很多人街上走路。", "corrected_sentence": "晚上八点，还有很多人在街上走路。", "error_description": "错误：「街上走路」。正确：「在街上走路」。「街上」表示地点，前面要加介词「在」，漏掉「在」则地点成分不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
