INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94715, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "辩论是两边的人各说各的想法，看谁说得对。", "primary_collocate": null, "pronunciation": "biàn lùn", "ipa": "pjɛn˥˩ lwən˥˩", "syllable_count": 2, "sentences": [{"text": "学校请两队同学辩论，看哪一队说得对。", "target_word": "辩论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班和三班明天要辩论环保问题。", "target_word": "辩论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正方和反方在台上辩论了一个小时。", "target_word": "辩论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让同学们分成两组，辩论“手机有没有用”。", "target_word": "辩论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两队学生站在台上辩论，裁判坐在下面听。", "target_word": "辩论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天辩论过一次，可是输了。", "target_word": "辩论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始了，双方先辩论，最后裁判打分。", "target_word": "辩论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在电视上辩论，观众看谁说得对。", "target_word": "辩论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们辩论着：学生要不要穿校服？", "target_word": "辩论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，两队要辩论三轮，最后裁判打分。", "target_word": "辩论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辩论了", "label": "完成体"}, {"form": "辩论过", "label": "经历体"}, {"form": "辩论着", "label": "持续体"}, {"form": "辯論", "label": "繁体"}], "register": "中性", "sense_fingerprint": "双方按规则各说各的想法，比谁说得对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccaa5f06-74fd-450d-9e5c-c87f845eb06a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94715, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "辩论", "is_correct": true, "explanation": "正确：“辩论”指双方各说各的想法、看谁说得对，与“看哪一队说得对”一致。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”没有对错，与“看哪一队说得对”不相干。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”不分对错，不能由“看哪一队说得对”来评判。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“洗澡”是个人的私事，不能用来组织两队同学参加的活动。"}], "explanations": {"辩论": "正确：“辩论”指双方各说各的想法、看谁说得对，与“看哪一队说得对”一致。", "唱歌": "语义：“唱歌”没有对错，与“看哪一队说得对”不相干。", "散步": "语义：“散步”不分对错，不能由“看哪一队说得对”来评判。", "洗澡": "搭配：“洗澡”是个人的私事，不能用来组织两队同学参加的活动。"}, "sentence_index": 0, "correct_answer": "辩论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两队在操场上辩论，最后一分钟进了一球。", "explanation": "这里应该用〈比赛〉。辩论 是双方讲道理、看谁说得对，不能用于踢球进球。"}, {"text": "两个小孩在路上辩论，一边吃冰淇淋一边笑。", "explanation": "这里应该用〈玩〉。辩论 指双方讲理争论，不能用于玩耍、吃东西的场面。"}, {"text": "他每天早上辩论，身体很健康。", "explanation": "这里应该用〈跑步〉。辩论 不能用于锻炼身体，锻炼身体要说跑步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94715, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辩论", "is_correct": true, "explanation": "正确：“辩论”是比赛的一个环节，双方先讲理由，裁判再打分，与句意一致。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“比赛开始”“裁判打分”的比赛环节不符。"}, {"text": "点菜", "is_correct": false, "explanation": "搭配：“点菜”的对象是菜品，不能作为比赛中双方的环节。"}, {"text": "交朋友", "is_correct": false, "explanation": "语义：“交朋友”不是比赛环节，与“裁判打分”矛盾。"}], "explanations": {"辩论": "正确：“辩论”是比赛的一个环节，双方先讲理由，裁判再打分，与句意一致。", "睡觉": "语义：“睡觉”与“比赛开始”“裁判打分”的比赛环节不符。", "点菜": "搭配：“点菜”的对象是菜品，不能作为比赛中双方的环节。", "交朋友": "语义：“交朋友”不是比赛环节，与“裁判打分”矛盾。"}, "sentence_index": 6, "correct_answer": "辩论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房辩论，做了很多好吃的菜。", "explanation": "这里应该用〈做饭〉。辩论 指双方讲理争论，不能用于做饭。"}, {"text": "老师耐心地辩论了这道题的解法，大家都听懂了。", "explanation": "这里应该用〈讲解〉。辩论 指双方各持己见、互相争论，不能用于老师单方面讲解。"}, {"text": "老师花了一个下午辩论作文，终于改完了。", "explanation": "这里应该用〈批改〉。辩论 是双方讲理争论，不能用来形容老师批阅作文。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94715, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今天没辩论了，只是在旁边听。", "corrected_sentence": "他今天没辩论，只是在旁边听。", "error_description": "错误：“没”与“了”同用。正确：“没辩论”后不加“了”，说“他今天没辩论”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94715, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在台上辩论地很激烈，观众一直在鼓掌。", "corrected_sentence": "他们在台上辩论得很激烈，观众一直在鼓掌。", "error_description": "错误：补语前用了“地”。正确：应用“得”，说“辩论得很激烈”。“地”用于修饰动词，“得”用于引出补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94716, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94716, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94716, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "持不同意见的双方用理由说服对方，互相争论。", "primary_collocate": null, "pronunciation": "biàn lùn", "ipa": "pjɛn˥˩ lwən˥˩", "syllable_count": 2, "sentences": [{"text": "他们为了房子的事辩论了很久，谁也没说服谁。", "target_word": "辩论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位专家辩论着，各用理由说服对方。", "target_word": "辩论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会上大家为新计划辩论起来，意见不一样。", "target_word": "辩论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩常常为小事辩论，可是关系还很好。", "target_word": "辩论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想和你辩论，你有你的看法。", "target_word": "辩论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议员们在会议上辩论税收问题，一直到晚上。", "target_word": "辩论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方各讲理由，辩论了三个小时才结束。", "target_word": "辩论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢和朋友辩论，用理由让别人同意他。", "target_word": "辩论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家辩论过这个问题，可是没有结果。", "target_word": "辩论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个律师在法庭上辩论，都想说服法官。", "target_word": "辩论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辩论了", "label": "完成体"}, {"form": "辩论过", "label": "经历体"}, {"form": "辩论着", "label": "持续体"}, {"form": "辯論", "label": "繁体"}], "register": "中性", "sense_fingerprint": "意见不同的双方讲理由，想说服对方，互相争论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccaa5f06-74fd-450d-9e5c-c87f845eb06a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94716, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "辩论", "is_correct": true, "explanation": "正确：“辩论”指双方用理由争论，与“谁也没说服谁”相符。"}, {"text": "种菜", "is_correct": false, "explanation": "语义：“种菜”与争论的事情无关，句子说不通。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”与“谁也没说服谁”不相干，句子意思不通。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”不能与“为了……的事”组合来表示争论，句子不通。"}], "explanations": {"辩论": "正确：“辩论”指双方用理由争论，与“谁也没说服谁”相符。", "种菜": "语义：“种菜”与争论的事情无关，句子说不通。", "跳舞": "语义：“跳舞”与“谁也没说服谁”不相干，句子意思不通。", "游泳": "搭配：“游泳”不能与“为了……的事”组合来表示争论，句子不通。"}, "sentence_index": 0, "correct_answer": "辩论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用道理辩论了老板，老板同意了他的计划。", "explanation": "这里应该用〈说服〉。辩论 的对象是问题或观点，不能直接带人作宾语。"}, {"text": "妈妈每天晚上给我辩论故事，我很喜欢。", "explanation": "这里应该用〈讲〉。辩论 不能与“故事”搭配。"}, {"text": "他每天晚上认真辩论书，读得很快。", "explanation": "这里应该用〈看〉。辩论 指双方讲理争论，不能带“书”作宾语，看书要说“看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辩论", "is_correct": true, "explanation": "正确：“辩论”指双方各讲理由，与“各讲理由”相符。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：“跑步”与“各讲理由”不相关，句子说不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与“各讲理由”无关，不能表示讲理的过程。"}, {"text": "参加", "is_correct": false, "explanation": "语义：“参加”指加入某项活动，与“双方各讲理由”的争论过程不符。"}], "explanations": {"辩论": "正确：“辩论”指双方各讲理由，与“各讲理由”相符。", "跑步": "语义：“跑步”与“各讲理由”不相关，句子说不通。", "吃饭": "语义：“吃饭”与“各讲理由”无关，不能表示讲理的过程。", "参加": "语义：“参加”指加入某项活动，与“双方各讲理由”的争论过程不符。"}, "sentence_index": 6, "correct_answer": "辩论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在舞台上辩论，唱得很好听。", "explanation": "这里应该用〈演出〉。辩论 指双方讲理争论，不能用于舞台上的歌曲表演等演出。"}, {"text": "妈妈每个周末都辩论，洗得很干净。", "explanation": "这里应该用〈做家务〉。辩论 指双方讲理争论，不能用于打扫屋子、整理衣物等家务。"}, {"text": "奶奶在院子里辩论，花开得很漂亮。", "explanation": "这里应该用〈种〉。辩论 不能用于种花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们辩论了着一个小时，还是没有结果。", "corrected_sentence": "他们辩论了一个小时，还是没有结果。", "error_description": "错误：“了”与“着”不能同用于同一动词。正确：应说“辩论了一个小时”，只用“了”表示完成并计时。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们很辩论这个问题。", "corrected_sentence": "他们很爱辩论这个问题。", "error_description": "错误：“辩论”是动作动词，不能直接受“很”修饰。正确：加上“爱”，说“很爱辩论”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
