INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94717, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "这时是说话的这一小会儿，或者刚才说的那个时候。", "primary_collocate": null, "pronunciation": "zhè shí", "ipa": "ʈʂɤ˥˩ ʂʅ˧˥", "syllable_count": 2, "sentences": [{"text": "我刚走到门口，这时电话响了。", "target_word": "这时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天快黑了，这时他才想起没带伞。", "target_word": "这时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家正在吃饭，这时门开了。", "target_word": "这时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她打开信，这时眼泪流了下来。", "target_word": "这时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正在看书，这时妈妈走了进来。", "target_word": "这时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车慢慢停下，这时下起了大雨。", "target_word": "这时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛快结束了，这时他进了一个球。", "target_word": "这时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走到山顶，这时太阳正好出来。", "target_word": "这时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师刚讲完课，这时下课铃响了。", "target_word": "这时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子睡着了，这时屋里很安静。", "target_word": "这时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "這時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "这时：刚说到的那个时刻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b6ab932-ffa3-44f3-be69-23e97a6cbed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94717, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "这时", "is_correct": true, "explanation": "正确：这时指刚说到的那个时刻，即刚走到门口的这一刻，与电话响起的时间相接。"}, {"text": "半夜", "is_correct": false, "explanation": "语义：半夜指深夜的一段时间，与“刚走到门口”的那一刻对不上，句意不通。"}, {"text": "明天", "is_correct": false, "explanation": "语义：明天指将来，与“刚走到门口”这一已经发生的情况冲突。"}, {"text": "平时", "is_correct": false, "explanation": "体貌：平时表示惯常的时段，与“电话响了”这种一次性的事件不相符。"}], "explanations": {"这时": "正确：这时指刚说到的那个时刻，即刚走到门口的这一刻，与电话响起的时间相接。", "半夜": "语义：半夜指深夜的一段时间，与“刚走到门口”的那一刻对不上，句意不通。", "明天": "语义：明天指将来，与“刚走到门口”这一已经发生的情况冲突。", "平时": "体貌：平时表示惯常的时段，与“电话响了”这种一次性的事件不相符。"}, "sentence_index": 0, "correct_answer": "这时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这时我上小学的时候，全家搬到了北京。", "explanation": "这里应该用〈那时〉。这时只指说话当下或上文提到的时刻，不能指“上小学的时候”这样已过去的时段。"}, {"text": "这时我们昨天就到了北京。", "explanation": "这里应该去掉〈这时〉，直接说“我们昨天就到了北京”。这时指说话当下或上文提到的时刻，不能与“昨天”这样的具体日期并用。"}, {"text": "这时我三岁的时候，还不会说话。", "explanation": "这里应该去掉〈这时〉，说“我三岁的时候，还不会说话”。这时只指说话当下或上文的时刻，不能指“三岁的时候”这样已过去的时段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94717, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这时", "is_correct": true, "explanation": "正确：这时指刚说到的那个时刻，即比赛快结束时他进球的这一刻。"}, {"text": "开场时", "is_correct": false, "explanation": "语义：开场时指比赛刚开始的阶段，与“快结束了”的时间背景相反。"}, {"text": "赛前", "is_correct": false, "explanation": "语义：赛前指比赛开始以前，与“快结束了”矛盾，且进球不可能发生在赛前。"}, {"text": "中场休息时", "is_correct": false, "explanation": "语义：中场休息时是比赛过半的时候，与“快结束了”的时间背景矛盾。"}], "explanations": {"这时": "正确：这时指刚说到的那个时刻，即比赛快结束时他进球的这一刻。", "开场时": "语义：开场时指比赛刚开始的阶段，与“快结束了”的时间背景相反。", "赛前": "语义：赛前指比赛开始以前，与“快结束了”矛盾，且进球不可能发生在赛前。", "中场休息时": "语义：中场休息时是比赛过半的时候，与“快结束了”的时间背景矛盾。"}, "sentence_index": 6, "correct_answer": "这时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这时我上个月搬了家。", "explanation": "这里应该去掉〈这时〉，直接说“我上个月搬了家”。这时指说话当下或上文的时刻，不能与“上个月”这样的具体过去时段并用。"}, {"text": "这时昨天下了雨。", "explanation": "这里应该去掉〈这时〉，直接说“昨天下了雨”。这时只指说话当下或上文的时刻，不能与“昨天”这样的具体日期并用。"}, {"text": "我这时每天都早起跑步。", "explanation": "这里应该用〈平时〉。这时指一个具体时刻，与表示惯常的“每天”矛盾；说惯常要用平时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94717, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我刚进屋，这时了手机响了。", "corrected_sentence": "我刚进屋，这时手机响了。", "error_description": "错误：“这时”是时间名词，后面不能直接加“了”。去掉“了”即正确：“这时手机响了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94717, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我刚坐下，这时的有人敲门了。", "corrected_sentence": "我刚坐下，这时有人敲门了。", "error_description": "错误：“的”不能加在“这时”后面、直接接“有人”。去掉“的”即正确：“这时有人敲门了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
