INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94720, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "没有事先约定而碰到、见到某人或某物。", "primary_collocate": null, "pronunciation": "yù jiàn", "ipa": "y˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我昨天在超市遇见了老同学。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在路上，他遇见一位老朋友。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你在国外遇见过中国人吗？", "target_word": "遇见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没想到会在这儿遇见你。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在大学里遇见了她的丈夫。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行时，我们遇见了一只小狗。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他上班路上遇见了王老师，就打了招呼。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在机场遇见了一个很有名的歌手。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末去公园，我遇见了好多邻居。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在火车上遇见了一位老医生。", "target_word": "遇见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遇见了", "label": "体标"}, {"form": "遇见过", "label": "体标"}], "register": "中性", "sense_fingerprint": "事先没有约定而碰到、见到某人或某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca225a9-f261-4012-915b-1e8f99594883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors 