INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94720, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "遇见", "is_correct": true, "explanation": "遇见：没有事先约定而碰到某人或某物。"}, {"text": "愚见", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是谦称自己的见解，与“遇见”不同。"}, {"text": "玉简", "is_correct": false, "explanation": "yù jiǎn 与 yù jiàn 第二音节声调不同（第三声），意思是古代刻字的玉片。"}, {"text": "预检", "is_correct": false, "explanation": "yù jiǎn 与 yù jiàn 第二音节声调不同（第三声），意思是事先检查。"}], "explanations": {"遇见": "遇见：没有事先约定而碰到某人或某物。", "愚见": "yú（第二声）与 yù（第四声）声调不同，意思是谦称自己的见解，与“遇见”不同。", "玉简": "yù jiǎn 与 yù jiàn 第二音节声调不同（第三声），意思是古代刻字的玉片。", "预检": "yù jiǎn 与 yù jiàn 第二音节声调不同（第三声），意思是事先检查。"}, "sentence_index": null, "correct_answer": "遇见"}, "level_3": {"options": [{"text": "遇见", "is_correct": true, "explanation": "正确：“遇见”表示偶然碰到，与在超市里偶然碰到老同学相符。"}, {"text": "摆放", "is_correct": false, "explanation": "搭配：“摆放”的对象是物品，不能用于人，与“老同学”不合。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”用于展馆、场所，不能带“老同学”这样的人作宾语。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”的宾语是商品，不能说“买老同学”。"}], "explanations": {"遇见": "正确：“遇见”表示偶然碰到，与在超市里偶然碰到老同学相符。", "摆放": "搭配：“摆放”的对象是物品，不能用于人，与“老同学”不合。", "参观": "搭配：“参观”用于展馆、场所，不能带“老同学”这样的人作宾语。", "买": "搭配：“买”的宾语是商品，不能说“买老同学”。"}, "sentence_index": 0, "correct_answer": "遇见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我提前三天和他约好，要在火车站遇见他。", "explanation": "这里应该用〈约见〉。遇见指没有事先约定而碰到，已经约好时间的见面要用约见。"}, {"text": "我特意去医院遇见奶奶。", "explanation": "这里应该用〈看望〉。遇见是偶然碰到，“特意去”说明是有目的的探访，要用看望。"}, {"text": "我们早就约好在车站遇见远方的朋友。", "explanation": "这里应该用〈迎接〉。遇见不能用于有计划地去接人，约好的接站要用迎接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid =