INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94720, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遇见", "is_correct": true, "explanation": "正确：“遇见”表示偶然碰到，与路上碰到王老师并打招呼相符。"}, {"text": "请教", "is_correct": false, "explanation": "语义：“请教”指有目的地向人求教，与路上偶然碰到的情景不符。"}, {"text": "想起", "is_correct": false, "explanation": "语义：“想起”是心里想到，不是当面见到，与后面“就打了招呼”矛盾。"}, {"text": "报告", "is_correct": false, "explanation": "配价：“报告”的宾语是情况或信息，不能直接带“王老师”这样的人作宾语。"}], "explanations": {"遇见": "正确：“遇见”表示偶然碰到，与路上碰到王老师并打招呼相符。", "请教": "语义：“请教”指有目的地向人求教，与路上偶然碰到的情景不符。", "想起": "语义：“想起”是心里想到，不是当面见到，与后面“就打了招呼”矛盾。", "报告": "配价：“报告”的宾语是情况或信息，不能直接带“王老师”这样的人作宾语。"}, "sentence_index": 6, "correct_answer": "遇见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "外长按日程安排，将在大使馆遇见外国代表。", "explanation": "这里应该用〈会见〉。遇见是偶然碰到，按日程安排的正式见面要用会见。"}, {"text": "他按约定遇见了王教授。", "explanation": "这里应该用〈拜访〉。遇见不能用于按约定进行的造访，约好登门见面要用拜访。"}, {"text": "学生下课后专门去办公室遇见老师，问了一道数学题。", "explanation": "这里应该用〈请教〉。专门去办公室问问题是有目的的求教，遇见是偶然碰到，要用请教。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天会在路上遇见了老师。", "corrected_sentence": "我明天会在路上遇见老师。", "error_description": "错误：“遇见”后面多了“了”。“会”表示将来，将来的动作不能加“了”，应改为“会在路上遇见老师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在路上遇见到了王老师。", "corrected_sentence": "我在路上遇见了王老师。", "error_description": "错误：“遇见”后面多了补语“到”。“遇见”本身已表示碰到，不能再加“到”组成“遇见到”，应改为“遇见了王老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
