INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94721, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "道出是把心里的话说出来。", "primary_collocate": null, "pronunciation": "dào chū", "ipa": "tɑʊ̯⁵¹ ʈʂʰu⁵⁵", "syllable_count": 2, "sentences": [{"text": "她第一次向妈妈道出了心里话。", "target_word": "道出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "喝了酒以后，他道出了心里的不满。", "target_word": "道出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议上，他大胆道出了自己的看法。", "target_word": "道出", "complexity_tier": "T3", "furigana": "huì yì shàng, tā dà dǎn dào chū le zì jǐ de kàn fǎ", "sentence_source": "generated"}, {"text": "他在信里道出了对家人的想念。", "target_word": "道出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "女儿终于道出了不想去学校的原因。", "target_word": "道出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在会上道出了自己的担心。", "target_word": "道出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她等了很久，才道出自己的感受。", "target_word": "道出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看着朋友，道出了心中的话。", "target_word": "道出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在日记里，她道出了所有的秘密。", "target_word": "道出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师，我想向您道出我的心里话。", "target_word": "道出", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "道出了", "label": "体标"}, {"form": "道出过", "label": "体标"}], "register": "书面", "sense_fingerprint": "把心里的想法和感受说出口", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b189c5-928f-4b14-9e03-b75e919a5733') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94721, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "道出", "is_correct": true, "explanation": "正确：道出，意思是把心里的话说出口。"}, {"text": "导出", "is_correct": false, "explanation": "导出的第一个音节为第三声，与道出的第四声不同，意思是把数据或文件输出。"}, {"text": "到处", "is_correct": false, "explanation": "到处的第二个音节为第四声，与道出的第一声不同，意思是各个地方。"}, {"text": "套出", "is_correct": false, "explanation": "套出的声母是 t，与道出的 d 不同，意思是用计谋让人说出实情。"}], "explanations": {"道出": "正确：道出，意思是把心里的话说出口。", "导出": "导出的第一个音节为第三声，与道出的第四声不同，意思是把数据或文件输出。", "到处": "到处的第二个音节为第四声，与道出的第一声不同，意思是各个地方。", "套出": "套出的声母是 t，与道出的 d 不同，意思是用计谋让人说出实情。"}, "sentence_index": null, "correct_answer": "道出"}, "level_3": {"options": [{"text": "道出", "is_correct": true, "explanation": "正确：“道出”表示把心里话说给别人听，与“第一次向妈妈”的语境相合。"}, {"text": "搬出", "is_correct": false, "explanation": "搭配：“搬出”指把较大的物体从某处移走，心里话不能被搬出。"}, {"text": "发表", "is_correct": false, "explanation": "语义：“发表”指正式公开言论或作品，与私下向妈妈倾诉的语境不符。"}, {"text": "讲解", "is_correct": false, "explanation": "语义：“讲解”是解释说明知识或道理，不用于表达心里话。"}], "explanations": {"道出": "正确：“道出”表示把心里话说给别人听，与“第一次向妈妈”的语境相合。", "搬出": "搭配：“搬出”指把较大的物体从某处移走，心里话不能被搬出。", "发表": "语义：“发表”指正式公开言论或作品，与私下向妈妈倾诉的语境不符。", "讲解": "语义：“讲解”是解释说明知识或道理，不用于表达心里话。"}, "sentence_index": 0, "correct_answer": "道出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向大家道出了这款新产品。", "explanation": "这里应该用〈介绍〉。道出多指吐露原来不愿说的心里话，一般介绍产品不这么用。"}, {"text": "他从包里道出了一本书。", "explanation": "这里应该用〈拿出〉。道出只用于把话语或想法说出来，从包里取出实物要用拿出。"}, {"text": "妈妈每天早上都道出一句“起床了”。", "explanation": "这里应该用〈喊〉。道出表示把心里的想法和感受说出来，早上叫醒家人只是随口喊，不用道出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94721, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道出", "is_correct": true, "explanation": "正确：“道出”表示把感受说出来，与“等了很久，才”的语境相合。"}, {"text": "摔碎", "is_correct": false, "explanation": "搭配：“摔碎”指使物体破成碎片，感受不能被摔碎。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”指美化物体的外表，与表达感受无关。"}, {"text": "拆开", "is_correct": false, "explanation": "搭配：“拆开”指把封闭的东西分开或打开，感受不能被拆开。"}], "explanations": {"道出": "正确：“道出”表示把感受说出来，与“等了很久，才”的语境相合。", "摔碎": "搭配：“摔碎”指使物体破成碎片，感受不能被摔碎。", "装饰": "语义：“装饰”指美化物体的外表，与表达感受无关。", "拆开": "搭配：“拆开”指把封闭的东西分开或打开，感受不能被拆开。"}, "sentence_index": 6, "correct_answer": "道出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向老板道出了工作进展。", "explanation": "这里应该用〈报告〉。道出指说出自己心里的想法和感受，正式汇报工作进展不这么用。"}, {"text": "他一进门就道出了一阵大笑。", "explanation": "这里应该用〈发出〉。道出只用于说出话语或想法，笑声这类非语言的声音要用发出。"}, {"text": "我每天上课前都道出一句“大家好”。", "explanation": "这里应该用〈说〉。道出表示把心里的想法和感受说出来，上课前的问候只是寻常招呼，不用道出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94721, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于道出着心底的那句话。", "corrected_sentence": "他终于道出了心底的那句话。", "error_description": "错误：“道出着”。正确：“道出了”。“道出”表示动作完成并有结果，完成要用“了”；“着”表示持续状态，与“道出”搭配不当。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94721, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把心里的话慢慢道出着。", "corrected_sentence": "他把心里的话慢慢道出了。", "error_description": "错误：“道出着”。正确：“道出了”。“道出”表示已完成的言语动作，要用“了”；“着”表示持续状态，与这一完成的动作不合。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
