INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94723, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "配备是把需要用的东西准备好放在那里。", "primary_collocate": null, "pronunciation": "pèi bèi", "ipa": "pʰei˥˩ pei˥˩", "syllable_count": 2, "sentences": [{"text": "每间教室都配备了一台电脑。", "target_word": "配备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆汽车配备了儿童安全座椅。", "target_word": "配备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里配备着各种急救药品。", "target_word": "配备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给每位员工配备了一部手机。", "target_word": "配备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店为每个房间配备了热水壶。", "target_word": "配备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校已经配备好了新桌子和椅子。", "target_word": "配备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个厨房配备了很多新式用具。", "target_word": "配备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防车上配备着长梯子和水管。", "target_word": "配备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了安全，每艘船都要配备救生衣。", "target_word": "配备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把应急用品配备好了，可以出发了。", "target_word": "配备", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "配备了", "label": "完成体"}, {"form": "配备着", "label": "持续体"}, {"form": "配备好", "label": "结果补语形式"}], "register": "中性", "sense_fingerprint": "把需要用的东西准备好放在那里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df093371-859c-466c-bce4-6c56d378b3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94723, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "配备", "is_correct": true, "explanation": "“配备”指按需要准备并配给设备，符合“每间教室配一台电脑”的句意。"}, {"text": "出售", "is_correct": false, "explanation": "语义：“出售”是卖给别人，教室不会出售电脑，句意不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能与“电脑”这类设备搭配，句子说的是提供设备。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指吞咽食物，电脑不能吃。"}], "explanations": {"配备": "“配备”指按需要准备并配给设备，符合“每间教室配一台电脑”的句意。", "出售": "语义：“出售”是卖给别人，教室不会出售电脑，句意不通。", "洗": "搭配：“洗”不能与“电脑”这类设备搭配，句子说的是提供设备。", "吃": "语义：“吃”指吞咽食物，电脑不能吃。"}, "sentence_index": 0, "correct_answer": "配备"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "年底，公司配备了一笔奖金。", "explanation": "这里应该用〈发放〉。配备指按需要配给人员或设备，奖金是发给员工的钱，要说发放，不能说配备。"}, {"text": "我们配备了这个项目。", "explanation": "这里应该用〈完成〉。配备指把需要用的东西准备好放在那里，项目要说完成，不能说配备。"}, {"text": "这篇报告配备了三个结论。", "explanation": "这里应该用〈得出〉。配备指准备好需要的东西，结论要说得出，不能说配备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94723, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "配备", "is_correct": true, "explanation": "“配备”指按需要配置用具，符合“这个厨房配备了很多新式用具”的句意。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”用于饮料，用具不能喝。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”指咽下，用具不能吞下。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿咬住，用具不能咬。"}], "explanations": {"配备": "“配备”指按需要配置用具，符合“这个厨房配备了很多新式用具”的句意。", "喝": "语义：“喝”用于饮料，用具不能喝。", "吞": "语义：“吞”指咽下，用具不能吞下。", "咬": "语义：“咬”指用牙齿咬住，用具不能咬。"}, "sentence_index": 6, "correct_answer": "配备"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校配备了一次春游。", "explanation": "这里应该用〈组织〉。配备指准备好需要的东西或分配人员，春游要说组织，不能说配备。"}, {"text": "学校配备了一份通知。", "explanation": "这里应该用〈发布〉。配备指配置设备或人员，通知要说发布，不能说配备。"}, {"text": "他一直配备着很好的心情。", "explanation": "这里应该用〈保持〉。配备指配置设备或人员，心情要说保持，不能说配备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94723, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂已经把安全设备配备了好，明天开工。", "corrected_sentence": "工厂已经把安全设备配备好了，明天开工。", "error_description": "错误：“配备了好”。正确：“配备好了”。结果补语“好”必须紧跟动词，“了”放在补语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94723, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "司机已经把急救包配备，可以上路了。", "corrected_sentence": "司机已经把急救包配备好了，可以上路了。", "error_description": "错误：“把急救包配备”。正确：“把急救包配备好了”。“把”字句中动词不能单独结尾，“配备”后要加结果补语“好”和“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
