INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94724, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按照需要分配并安排人员或设备。", "primary_collocate": null, "pronunciation": "pèi bèi", "ipa": "pʰei˥˩ pei˥˩", "syllable_count": 2, "sentences": [{"text": "公司为新项目配备了五名工程师。", "target_word": "配备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给每个班配备了两位老师。", "target_word": "配备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院会配备足够的护士。", "target_word": "配备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要为每个组配备一名负责人。", "target_word": "配备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店按顾客人数配备服务员。", "target_word": "配备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂给新车间配备了二十台机器。", "target_word": "配备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察局给每个社区配备了两名警察。", "target_word": "配备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司已经配备好了人员，下周开工。", "target_word": "配备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们会按需要配备人手和设备。", "target_word": "配备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校为图书馆配备了专门的管理员。", "target_word": "配备", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "配备了", "label": "完成体"}, {"form": "配备着", "label": "持续体"}, {"form": "配备好", "label": "结果补语形式"}], "register": "中性", "sense_fingerprint": "按需要分配并安排人员或设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df093371-859c-466c-bce4-6c56d378b3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94724, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "配备", "is_correct": true, "explanation": "“配备”指按需要分配人员，符合“为新项目配备五名工程师”的句意。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”指印刷发行，工程师不能被出版。"}, {"text": "饲养", "is_correct": false, "explanation": "语义：“饲养”用于动物，不能用于工程师。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”指乘坐或跨坐，不能用于分配人员。"}], "explanations": {"配备": "“配备”指按需要分配人员，符合“为新项目配备五名工程师”的句意。", "出版": "语义：“出版”指印刷发行，工程师不能被出版。", "饲养": "语义：“饲养”用于动物，不能用于工程师。", "骑": "搭配：“骑”指乘坐或跨坐，不能用于分配人员。"}, "sentence_index": 0, "correct_answer": "配备"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司配备了新的计划。", "explanation": "这里应该用〈制定〉。配备的对象是人员或设备，计划要说制定，不能说配备。"}, {"text": "公司把任务配备给了每个组。", "explanation": "这里应该用〈分配〉。配备的对象是人员或设备，任务要说分配，不能说配备。"}, {"text": "我们为每个会议配备了半小时。", "explanation": "这里应该用〈安排〉。配备的对象是人员或设备，时间的安排要说安排，不能说配备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94724, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "配备", "is_correct": true, "explanation": "“配备”指按需要分配人员，符合“警察局给每个社区配备两名警察”的句意。"}, {"text": "收养", "is_correct": false, "explanation": "语义：“收养”指把人领来抚养，警察局不能收养警察。"}, {"text": "赐予", "is_correct": false, "explanation": "语域：“赐予”是书面、带等级色彩的用词，不适用于日常的人员配置。"}, {"text": "讲授", "is_correct": false, "explanation": "语义：“讲授”指讲课传授知识，警察不是课程，不能讲授。"}], "explanations": {"配备": "“配备”指按需要分配人员，符合“警察局给每个社区配备两名警察”的句意。", "收养": "语义：“收养”指把人领来抚养，警察局不能收养警察。", "赐予": "语域：“赐予”是书面、带等级色彩的用词，不适用于日常的人员配置。", "讲授": "语义：“讲授”指讲课传授知识，警察不是课程，不能讲授。"}, "sentence_index": 6, "correct_answer": "配备"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校配备了一笔善款。", "explanation": "这里应该用〈筹集〉。配备指配置人员或设备，善款是要筹集来的钱，不能说配备。"}, {"text": "他配备了一个好听的名字。", "explanation": "这里应该用〈取〉。配备指分配人员或设备，名字要说取，不能说配备。"}, {"text": "妈妈给我配备了一碗面条。", "explanation": "这里应该用〈煮〉。配备指按需要配置人员或设备，做饭要说煮，不能说配备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94724, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所医院按照病人数量配备在护士。", "corrected_sentence": "这所医院按照病人数量配备了护士。", "error_description": "错误：“配备在护士”。正确：“配备了护士”。“护士”是人员，应直接作宾语，“在”会把它误作处所；表示已完成要用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94724, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经理被每个组配备了一名负责人。", "corrected_sentence": "经理为每个组配备了一名负责人。", "error_description": "错误：“被每个组配备”。正确：“为每个组配备”。引出受益对象要用“为”，“被”的主语应是受动者，这里“经理”是施动者，不能用“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
