INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94725, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "酒吧是大人喝酒聊天的地方。", "primary_collocate": null, "pronunciation": "jiǔ bā", "ipa": "tɕi̯ou̯˨˩ pa˥", "syllable_count": 2, "sentences": [{"text": "周末晚上，他们去酒吧喝啤酒聊天。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒吧晚上八点才开门。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒吧里的音乐太大声，我听不清你说话。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩不能进酒吧，里面有很多人喝酒。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友在酒吧里认识了他的妻子。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒吧老板给每位客人送了一杯啤酒。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班以后，同事们常去酒吧坐坐。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个酒吧在河边，晚上很热闹。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在酒吧工作了三年。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒吧里有很多人在喝酒、唱歌。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "间", "label": "量词"}], "register": "中性", "sense_fingerprint": "酒吧|名词|大人喝酒聊天的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60b8685b-8c93-4781-a5d8-5d5358d689c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94725, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "酒吧", "is_correct": true, "explanation": "正确：「酒吧」是大人喝酒聊天的地方，与「去……喝啤酒聊天」相符。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：「图书馆」是看书借书的地方，不是喝啤酒聊天的地方。"}, {"text": "医院", "is_correct": false, "explanation": "语义：「医院」是看病治病的地方，与喝啤酒聊天无关。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：「教室」不供应啤酒，「去教室喝啤酒」不搭配。"}], "explanations": {"酒吧": "正确：「酒吧」是大人喝酒聊天的地方，与「去……喝啤酒聊天」相符。", "图书馆": "语义：「图书馆」是看书借书的地方，不是喝啤酒聊天的地方。", "医院": "语义：「医院」是看病治病的地方，与喝啤酒聊天无关。", "教室": "搭配：「教室」不供应啤酒，「去教室喝啤酒」不搭配。"}, "sentence_index": 0, "correct_answer": "酒吧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们在一家酒吧里住了三晚。", "explanation": "这里应该用〈酒店〉。「酒吧」是大人喝酒聊天的地方，不提供住宿，不能用来说住了几晚。"}, {"text": "这家酒吧每年生产几百万瓶啤酒。", "explanation": "这里应该用〈酒厂〉。「酒吧」是大人喝酒聊天的地方，不生产酒，这里误用了它。"}, {"text": "酒吧里的电脑都是新的，很多学生在这里上网。", "explanation": "这里应该用〈网吧〉。「酒吧」是大人喝酒聊天的地方，不是上网的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94725, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "酒吧", "is_correct": true, "explanation": "正确：「酒吧」是供人喝酒休闲的地方，符合下班后同事常去坐坐的情境。"}, {"text": "银行", "is_correct": false, "explanation": "语义：「银行」是办理业务的地方，不是下班后休闲坐坐的地方。"}, {"text": "诊所", "is_correct": false, "explanation": "语义：「诊所」是看病的地方，不适合下班后去坐坐。"}, {"text": "仓库", "is_correct": false, "explanation": "搭配：「坐坐」搭配的应是休闲场所，「仓库」不能这样搭配。"}], "explanations": {"酒吧": "正确：「酒吧」是供人喝酒休闲的地方，符合下班后同事常去坐坐的情境。", "银行": "语义：「银行」是办理业务的地方，不是下班后休闲坐坐的地方。", "诊所": "语义：「诊所」是看病的地方，不适合下班后去坐坐。", "仓库": "搭配：「坐坐」搭配的应是休闲场所，「仓库」不能这样搭配。"}, "sentence_index": 6, "correct_answer": "酒吧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们昨天去了一条酒吧，里面很热闹。", "explanation": "量词错误。「条」用于细长的东西，「酒吧」应该用量词「家」或「间」。"}, {"text": "这块酒吧刚开业，人很多。", "explanation": "量词错误。「块」用于块状的东西，「酒吧」应该用量词「家」或「间」。"}, {"text": "那台酒吧装修得很漂亮。", "explanation": "量词错误。「台」多用于机器、设备，「酒吧」应该用量词「家」或「间」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94725, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在一只酒吧里认识了一个朋友。", "corrected_sentence": "我昨天在一家酒吧里认识了一个朋友。", "error_description": "错误：「酒吧」前应用量词「家」，这里误用了「只」。「只」用于动物或某些小物件，正确的是「一家酒吧」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94725, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一本很有名的酒吧。", "corrected_sentence": "这是一家很有名的酒吧。", "error_description": "错误：「酒吧」前应用量词「家」，这里误用了「本」。「本」用于书籍，正确的是「一家很有名的酒吧」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
