INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94726, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供应酒类饮料，供人饮酒、休闲的场所。", "primary_collocate": null, "pronunciation": "jiǔ bā", "ipa": "tɕi̯ou̯˨˩ pa˥", "syllable_count": 2, "sentences": [{"text": "这家酒吧卖各种啤酒和红酒。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们约在街角的酒吧见面。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒吧晚上营业到凌晨两点。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在一家酒吧里当服务员。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒吧里灯光很暗，大家边喝酒边聊天。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喝酒，所以很少去酒吧。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个酒吧有现场音乐，客人很多。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我们走进旁边的酒吧躲雨。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那间酒吧装修得很有特色。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒吧老板正在给客人倒酒。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "间", "label": "量词"}], "register": "中性", "sense_fingerprint": "酒吧|名词|供应酒类饮料供人休闲的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60b8685b-8c93-4781-a5d8-5d5358d689c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94726, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "酒吧", "is_correct": true, "explanation": "正确：「酒吧」供应酒类饮料，符合「卖各种啤酒和红酒」的说法。"}, {"text": "书店", "is_correct": false, "explanation": "语义：「书店」卖的是书，不卖啤酒和红酒。"}, {"text": "花店", "is_correct": false, "explanation": "搭配：「花店」卖的是花，与「卖啤酒和红酒」不搭配。"}, {"text": "药店", "is_correct": false, "explanation": "语义：「药店」卖的是药品，不卖啤酒和红酒。"}], "explanations": {"酒吧": "正确：「酒吧」供应酒类饮料，符合「卖各种啤酒和红酒」的说法。", "书店": "语义：「书店」卖的是书，不卖啤酒和红酒。", "花店": "搭配：「花店」卖的是花，与「卖啤酒和红酒」不搭配。", "药店": "语义：「药店」卖的是药品，不卖啤酒和红酒。"}, "sentence_index": 0, "correct_answer": "酒吧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家酒吧每天生产一万瓶白酒。", "explanation": "这里应该用〈酒厂〉。「酒吧」是供应酒类饮料、供人饮酒休闲的场所，不生产酒。"}, {"text": "这家酒吧有一百间客房，每天都住满人。", "explanation": "这里应该用〈酒店〉。「酒吧」供应饮料、供人饮酒休闲，不提供客房住宿，这里误用了它。"}, {"text": "这家酒吧的电脑很多，学生们都来这里上网。", "explanation": "这里应该用〈网吧〉。「酒吧」是供人饮酒休闲的场所，不是上网的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94726, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "酒吧", "is_correct": true, "explanation": "正确：「酒吧」供人饮酒休闲，符合「有现场音乐，客人很多」的描述。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：「工厂」是生产产品的地方，不以现场音乐和接待客人为特点。"}, {"text": "医院", "is_correct": false, "explanation": "语义：「医院」是看病治病的地方，不适合有现场音乐和很多客人。"}, {"text": "仓库", "is_correct": false, "explanation": "搭配：「仓库」是存放货物的地方，与「有现场音乐，客人很多」不搭配。"}], "explanations": {"酒吧": "正确：「酒吧」供人饮酒休闲，符合「有现场音乐，客人很多」的描述。", "工厂": "语义：「工厂」是生产产品的地方，不以现场音乐和接待客人为特点。", "医院": "语义：「医院」是看病治病的地方，不适合有现场音乐和很多客人。", "仓库": "搭配：「仓库」是存放货物的地方，与「有现场音乐，客人很多」不搭配。"}, "sentence_index": 6, "correct_answer": "酒吧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们昨天去了一本酒吧，里面很热闹。", "explanation": "量词错误。「本」用于书籍，「酒吧」应该用量词「家」。"}, {"text": "我们昨晚在一张酒吧里聚会，很开心。", "explanation": "量词错误。「张」用于平面的东西，「酒吧」应该用量词「家」。"}, {"text": "那支酒吧的装修很有特色。", "explanation": "量词错误。「支」用于笔、队伍等，「酒吧」应该用量词「家」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我们常去一只安静的酒吧聊天。", "corrected_sentence": "周末我们常去一家安静的酒吧聊天。", "error_description": "错误：「酒吧」前应用量词「家」，这里误用了「只」。「只」用于动物或某些小物件，正确的是「一家安静的酒吧」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下雨了，我们走进旁边一块酒吧躲雨。", "corrected_sentence": "下雨了，我们走进旁边一家酒吧躲雨。", "error_description": "错误：「酒吧」前应用量词「家」，这里误用了「块」。「块」用于块状的东西，正确的是「一家酒吧」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94727, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "睡", "is_correct": true, "explanation": "睡与醒构成反义：醒指睡觉结束，睡指闭眼入睡。"}, {"text": "吃", "is_correct": false, "explanation": "吃与醒不构成反义关系，指进食。"}, {"text": "站", "is_correct": false, "explanation": "站与醒不构成反义关系，指直立。"}, {"text": "笑", "is_correct": false, "explanation": "笑与醒不构成反义关系，指面部表情。"}], "correct_answer": "睡", "explanations": {"睡": "睡与醒构成反义：醒指睡觉结束，睡指闭眼入睡。", "吃": "吃与醒不构成反义关系，指进食。", "站": "站与醒不构成反义关系，指直立。", "笑": "笑与醒不构成反义关系，指面部表情。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94727, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "睡", "is_correct": true, "explanation": "睡与醒构成反义：醒指睡觉结束，睡指闭眼入睡。"}, {"text": "走", "is_correct": false, "explanation": "走与醒不构成反义关系，指移动。"}, {"text": "跳", "is_correct": false, "explanation": "跳与醒不构成反义关系，指离地运动。"}, {"text": "唱", "is_correct": false, "explanation": "唱与醒不构成反义关系，指发声歌唱。"}], "correct_answer": "睡", "explanations": {"睡": "睡与醒构成反义：醒指睡觉结束，睡指闭眼入睡。", "走": "走与醒不构成反义关系，指移动。", "跳": "跳与醒不构成反义关系，指离地运动。", "唱": "唱与醒不构成反义关系，指发声歌唱。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94727, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "醒是睡觉结束，眼睛睁开了。", "primary_collocate": null, "pronunciation": "xǐng", "ipa": "ɕiŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "今天早上六点我就醒了。", "target_word": "醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子还没醒，你小声一点。", "target_word": "醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚我半夜醒了两次。", "target_word": "醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天醒得很早。", "target_word": "醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面很吵，我醒了。", "target_word": "醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你醒了吗？饭已经好了。", "target_word": "醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈醒的时候，天还没亮。", "target_word": "醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常常十点才醒。", "target_word": "醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫醒了，在床上叫。", "target_word": "醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机一响，他就醒了。", "target_word": "醒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "醒了", "label": "体标"}, {"form": "醒着", "label": "体标"}, {"form": "醒过", "label": "体标"}, {"form": "醒醒", "label": "重叠"}], "register": "中性", "sense_fingerprint": "睡觉结束，眼睛睁开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df093371-859c-466c-bce4-6c56d378b3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94727, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "醒", "is_correct": true, "explanation": "醒指睡觉结束、眼睛睁开，读作 xǐng（第三声）。"}, {"text": "星", "is_correct": false, "explanation": "xīng（第一声）与 xǐng（第三声）声调不同，意思是星星。"}, {"text": "请", "is_correct": false, "explanation": "qǐng 与 xǐng 声母不同（q 与 x），意思是请求。"}, {"text": "姓", "is_correct": false, "explanation": "xìng（第四声）与 xǐng（第三声）声调不同，意思是姓氏。"}, {"text": "行", "is_correct": false, "explanation": "xíng（第二声）与 xǐng（第三声）声调不同，意思是行走。"}], "explanations": {"醒": "醒指睡觉结束、眼睛睁开，读作 xǐng（第三声）。", "星": "xīng（第一声）与 xǐng（第三声）声调不同，意思是星星。", "请": "qǐng 与 xǐng 声母不同（q 与 x），意思是请求。", "姓": "xìng（第四声）与 xǐng（第三声）声调不同，意思是姓氏。", "行": "xíng（第二声）与 xǐng（第三声）声调不同，意思是行走。"}, "sentence_index": null, "correct_answer": "醒"}, "level_3": {"options": [{"text": "醒", "is_correct": true, "explanation": "“醒”指睡觉结束、眼睛睁开，符合“早上六点我就醒了”的句意。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指完成学业，与“早上六点醒来”的句意不符。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指离开工作岗位，早上六点醒来不能说退休。"}, {"text": "生锈", "is_correct": false, "explanation": "搭配：“生锈”用于金属等物体，不能用于人的醒来。"}], "explanations": {"醒": "“醒”指睡觉结束、眼睛睁开，符合“早上六点我就醒了”的句意。", "毕业": "语义：“毕业”指完成学业，与“早上六点醒来”的句意不符。", "退休": "语义：“退休”指离开工作岗位，早上六点醒来不能说退休。", "生锈": "搭配：“生锈”用于金属等物体，不能用于人的醒来。"}, "sentence_index": 0, "correct_answer": "醒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这扇窗户醒了，阳光照了进来。", "explanation": "这里应该用〈打开〉。醒只用于人或动物睡醒后睁开眼睛，窗户不能醒，要说打开。"}, {"text": "那盏台灯醒了一下，又暗了。", "explanation": "这里应该用〈亮起〉。醒只用于人或动物睡醒睁眼，台灯不能醒，要说亮起。"}, {"text": "这只碗醒了，一下子碎成了几块。", "explanation": "这里应该用〈碎〉。醒只用于人或动物睡醒睁眼，碗不能醒，要说碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94727, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "醒", "is_correct": true, "explanation": "醒指睡觉结束、眼睛睁开，读作 xǐng（第三声）。"}, {"text": "景", "is_correct": false, "explanation": "jǐng 与 xǐng 声母不同（j 与 x），声调相同，意思是风景。"}, {"text": "幸", "is_correct": false, "explanation": "xìng（第四声）与 xǐng（第三声）声调不同，意思是幸运。"}, {"text": "形", "is_correct": false, "explanation": "xíng（第二声）与 xǐng（第三声）声调不同，意思是形状。"}], "explanations": {"醒": "醒指睡觉结束、眼睛睁开，读作 xǐng（第三声）。", "景": "jǐng 与 xǐng 声母不同（j 与 x），声调相同，意思是风景。", "幸": "xìng（第四声）与 xǐng（第三声）声调不同，意思是幸运。", "形": "xíng（第二声）与 xǐng（第三声）声调不同，意思是形状。"}, "sentence_index": null, "correct_answer": "醒"}, "level_3": {"options": [{"text": "醒", "is_correct": true, "explanation": "“醒”指睡觉结束，符合“妈妈醒的时候，天还没亮”的句意。"}, {"text": "落", "is_correct": false, "explanation": "语义：“落”指下落或日落，人的睡醒不能说落。"}, {"text": "升", "is_correct": false, "explanation": "语义：“升”指上升，人的睡醒不能说升。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：“发芽”用于植物，不能用于人的醒来。"}], "explanations": {"醒": "“醒”指睡觉结束，符合“妈妈醒的时候，天还没亮”的句意。", "落": "语义：“落”指下落或日落，人的睡醒不能说落。", "升": "语义：“升”指上升，人的睡醒不能说升。", "发芽": "搭配：“发芽”用于植物，不能用于人的醒来。"}, "sentence_index": 6, "correct_answer": "醒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子醒了一下，吱嘎响了一声。", "explanation": "这里应该用〈发出〉。醒只用于人或动物，椅子不能醒，要说发出声响。"}, {"text": "这扇窗户终于醒过来，打开了一条缝。", "explanation": "这里应该用〈打开〉。醒只用于人或动物，窗户不能醒，要说打开。"}, {"text": "这台冰箱醒了一夜，还在嗡嗡地响。", "explanation": "这里应该用〈运转〉。醒只用于人或动物，冰箱不能醒，要说运转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94727, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她昨晚十二点才醒了来，吓了一跳。", "corrected_sentence": "她昨晚十二点才醒过来，吓了一跳。", "error_description": "错误：“醒了来”。正确：“醒过来”。“醒”后接趋向补语“来”时，中间要用“过”，不用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94727, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天下午三点才醒过了来，发现家里没人。", "corrected_sentence": "我昨天下午三点才醒过来，发现家里没人。", "error_description": "错误：“醒过了来”。正确：“醒过来”。“过”与“来”共同构成趋向补语，中间不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94728, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "睡", "is_correct": true, "explanation": "睡与醒构成反义：醒指从睡眠中恢复清醒，睡指闭眼入睡。"}, {"text": "吃", "is_correct": false, "explanation": "吃与醒不构成反义关系，指进食。"}, {"text": "站", "is_correct": false, "explanation": "站与醒不构成反义关系，指直立。"}, {"text": "笑", "is_correct": false, "explanation": "笑与醒不构成反义关系，指面部表情。"}], "correct_answer": "睡", "explanations": {"睡": "睡与醒构成反义：醒指从睡眠中恢复清醒，睡指闭眼入睡。", "吃": "吃与醒不构成反义关系，指进食。", "站": "站与醒不构成反义关系，指直立。", "笑": "笑与醒不构成反义关系，指面部表情。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94728, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "睡", "is_correct": true, "explanation": "睡与醒构成反义：醒指从睡眠中恢复清醒，睡指闭眼入睡。"}, {"text": "走", "is_correct": false, "explanation": "走与醒不构成反义关系，指移动。"}, {"text": "跳", "is_correct": false, "explanation": "跳与醒不构成反义关系，指离地运动。"}, {"text": "唱", "is_correct": false, "explanation": "唱与醒不构成反义关系，指发声歌唱。"}], "correct_answer": "睡", "explanations": {"睡": "睡与醒构成反义：醒指从睡眠中恢复清醒，睡指闭眼入睡。", "走": "走与醒不构成反义关系，指移动。", "跳": "跳与醒不构成反义关系，指离地运动。", "唱": "唱与醒不构成反义关系，指发声歌唱。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94728, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从睡眠、麻醉或昏迷中恢复到清醒状态。", "primary_collocate": null, "pronunciation": "xǐng", "ipa": "ɕiŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "手术后，爸爸三个小时才醒。", "target_word": "醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说病人明天会醒。", "target_word": "醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他睡得很沉，叫了半天都不醒。", "target_word": "醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她昏了一天，终于醒过来了。", "target_word": "醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚醒，头还有点晕。", "target_word": "醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡了八个小时，我才醒。", "target_word": "醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗还在睡，没有醒。", "target_word": "醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到我的名字，他一下子醒了。", "target_word": "醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你醒醒，已经七点了！", "target_word": "醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她刚醒，还不想说话。", "target_word": "醒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "醒了", "label": "体标"}, {"form": "醒着", "label": "体标"}, {"form": "醒过", "label": "体标"}, {"form": "醒醒", "label": "重叠"}], "register": "中性", "sense_fingerprint": "从睡眠、麻醉或昏迷中恢复清醒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df093371-859c-466c-bce4-6c56d378b3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94728, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "醒", "is_correct": true, "explanation": "醒指从睡眠或昏迷中恢复清醒，读作 xǐng（第三声）。"}, {"text": "星", "is_correct": false, "explanation": "xīng（第一声）与 xǐng（第三声）声调不同，意思是星星。"}, {"text": "请", "is_correct": false, "explanation": "qǐng 与 xǐng 声母不同（q 与 x），意思是请求。"}, {"text": "幸", "is_correct": false, "explanation": "xìng（第四声）与 xǐng（第三声）声调不同，意思是幸运。"}, {"text": "景", "is_correct": false, "explanation": "jǐng 与 xǐng 声母不同（j 与 x），声调相同，意思是风景。"}], "explanations": {"醒": "醒指从睡眠或昏迷中恢复清醒，读作 xǐng（第三声）。", "星": "xīng（第一声）与 xǐng（第三声）声调不同，意思是星星。", "请": "qǐng 与 xǐng 声母不同（q 与 x），意思是请求。", "幸": "xìng（第四声）与 xǐng（第三声）声调不同，意思是幸运。", "景": "jǐng 与 xǐng 声母不同（j 与 x），声调相同，意思是风景。"}, "sentence_index": null, "correct_answer": "醒"}, "level_3": {"options": [{"text": "醒", "is_correct": true, "explanation": "“醒”指从昏迷或睡眠中恢复清醒，符合手术后苏醒的句意。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与手术后的语境不符，句子说的是苏醒。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：“发芽”用于植物，不能用于人的苏醒。"}, {"text": "长大", "is_correct": false, "explanation": "语义：“长大”指身体成长，与“三个小时才”的语境不符。"}], "explanations": {"醒": "“醒”指从昏迷或睡眠中恢复清醒，符合手术后苏醒的句意。", "结婚": "语义：“结婚”与手术后的语境不符，句子说的是苏醒。", "发芽": "搭配：“发芽”用于植物，不能用于人的苏醒。", "长大": "语义：“长大”指身体成长，与“三个小时才”的语境不符。"}, "sentence_index": 0, "correct_answer": "醒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这扇门醒了，自己慢慢打开了。", "explanation": "这里应该用〈打开〉。醒只用于人或动物从睡眠中恢复清醒，门不能醒，要说打开。"}, {"text": "这盏路灯醒了一晚上，把街道照得很亮。", "explanation": "这里应该用〈亮着〉。醒只用于人或动物，路灯不能醒，要说亮着。"}, {"text": "这辆卡车醒了，发动机轰隆隆地响起来。", "explanation": "这里应该用〈发动〉。醒只用于人或动物，卡车不能醒，要说发动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94728, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "醒", "is_correct": true, "explanation": "醒指从睡眠中恢复清醒，读作 xǐng（第三声）。"}, {"text": "姓", "is_correct": false, "explanation": "xìng（第四声）与 xǐng（第三声）声调不同，意思是姓氏。"}, {"text": "行", "is_correct": false, "explanation": "xíng（第二声）与 xǐng（第三声）声调不同，意思是行走。"}, {"text": "井", "is_correct": false, "explanation": "jǐng 与 xǐng 声母不同（j 与 x），声调相同，意思是水井。"}], "explanations": {"醒": "醒指从睡眠中恢复清醒，读作 xǐng（第三声）。", "姓": "xìng（第四声）与 xǐng（第三声）声调不同，意思是姓氏。", "行": "xíng（第二声）与 xǐng（第三声）声调不同，意思是行走。", "井": "jǐng 与 xǐng 声母不同（j 与 x），声调相同，意思是水井。"}, "sentence_index": null, "correct_answer": "醒"}, "level_3": {"options": [{"text": "醒", "is_correct": true, "explanation": "“醒”指从睡眠中恢复清醒，符合“还在睡，没有醒”的对比。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指完成学业，小狗不能毕业。"}, {"text": "生锈", "is_correct": false, "explanation": "搭配：“生锈”用于金属，不能用于小狗。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指离开工作岗位，小狗不能退休。"}], "explanations": {"醒": "“醒”指从睡眠中恢复清醒，符合“还在睡，没有醒”的对比。", "毕业": "语义：“毕业”指完成学业，小狗不能毕业。", "生锈": "搭配：“生锈”用于金属，不能用于小狗。", "退休": "语义：“退休”指离开工作岗位，小狗不能退休。"}, "sentence_index": 6, "correct_answer": "醒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座房子醒得很早，灯全亮了。", "explanation": "这里应该用〈亮起〉。醒只用于人或动物，房子不能醒，要说亮起。"}, {"text": "这本账本醒了，自己翻到了那一页。", "explanation": "这里应该用〈翻开〉。醒只用于人或动物，账本不能醒，要说翻开。"}, {"text": "这块石头醒了半天，突然滚了下来。", "explanation": "这里应该用〈滚落〉。醒只用于人或动物，石头不能醒，要说滚落。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "病人醒很慢，医生很担心。", "corrected_sentence": "病人醒得很慢，医生很担心。", "error_description": "错误：“醒很慢”。正确：“醒得很慢”。动词后接程度补语时要用“得”连接，不能省去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她今天醒地很晚，错过了早饭。", "corrected_sentence": "她今天醒得很晚，错过了早饭。", "error_description": "错误：“醒地很晚”。正确：“醒得很晚”。补语标志要用“得”，“地”只用于修饰动词作状语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94729, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94729, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94729, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "限是规定数量、时间或范围的上限，不许超过；也指只允许某类人或某段时间参加、使用。", "primary_collocate": null, "pronunciation": "xiàn", "ipa": "ɕjɛn⁵¹", "syllable_count": 1, "sentences": [{"text": "每人限买两瓶牛奶。", "target_word": "限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间限四人入住。", "target_word": "限", "complexity_tier": "T3", "furigana": "zhè ge fáng jiān xiàn sì rén rù zhù", "sentence_source": "generated"}, {"text": "报名限今天下午五点前。", "target_word": "限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的蛋糕每天限卖五十个。", "target_word": "限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯限坐八个人，请不要再进来了。", "target_word": "限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳池限十岁以下的孩子使用。", "target_word": "限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次课限二十个学生参加。", "target_word": "限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张优惠券限周末使用。", "target_word": "限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活动限女生参加，男生不能来。", "target_word": "限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的会议限一个小时，请快一点。", "target_word": "限", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "限制", "label": "复合"}, {"form": "限于", "label": "复合"}], "register": "中性", "sense_fingerprint": "限：把数量、时间、范围限定在某个界线之内", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c88eb55d-87b9-4467-ab1d-de538215c096') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94729, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "限", "is_correct": true, "explanation": "正确答案。限（xiàn，第四声）表示限定数量、时间或范围。"}, {"text": "先", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，意思是先，不是限。"}, {"text": "咸", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是咸，不是限。"}, {"text": "险", "is_correct": false, "explanation": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是危险，不是限。"}, {"text": "显", "is_correct": false, "explanation": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是明显，不是限。"}], "explanations": {"限": "正确答案。限（xiàn，第四声）表示限定数量、时间或范围。", "先": "xiān（第一声）与 xiàn（第四声）声调不同，意思是先，不是限。", "咸": "xián（第二声）与 xiàn（第四声）声调不同，意思是咸，不是限。", "险": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是危险，不是限。", "显": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是明显，不是限。"}, "sentence_index": null, "correct_answer": "限"}, "level_3": {"options": [{"text": "限", "is_correct": true, "explanation": "正确。“限”表示限定，“每人限买两瓶牛奶”即每人最多买两瓶。"}, {"text": "禁止", "is_correct": false, "explanation": "语义：禁止是完全不许，句子会变成不许买，与“买两瓶”的限量意思不符。"}, {"text": "陪", "is_correct": false, "explanation": "语义：陪是陪同，“陪买两瓶”不表示数量限制，与“每人”的范围不相符。"}, {"text": "劝", "is_correct": false, "explanation": "配价：劝需要带人称宾语（劝某人买），“每人劝买两瓶”缺少对象，结构不成立。"}], "explanations": {"限": "正确。“限”表示限定，“每人限买两瓶牛奶”即每人最多买两瓶。", "禁止": "语义：禁止是完全不许，句子会变成不许买，与“买两瓶”的限量意思不符。", "陪": "语义：陪是陪同，“陪买两瓶”不表示数量限制，与“每人”的范围不相符。", "劝": "配价：劝需要带人称宾语（劝某人买），“每人劝买两瓶”缺少对象，结构不成立。"}, "sentence_index": 0, "correct_answer": "限"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛限我们得第一。", "explanation": "这里应该用〈让〉。限表示限定数量、时间或范围，不能表示使人获得某种结果，应说“让我们得第一”。"}, {"text": "这家店的蛋糕每天限不少于五十个。", "explanation": "这里应该用〈至少〉。限只表示数量的上限，表示最低数量要用“至少”，不能用“限”。"}, {"text": "凡事都要有个限。", "explanation": "这里的“限”是名词“限度”的意思，指界限。本词作动词时表示限定数量或地方，这里不是这个用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94729, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "限", "is_correct": true, "explanation": "正确答案。限（xiàn，第四声）表示限定数量、时间或范围。"}, {"text": "鲜", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，意思是新鲜，不是限。"}, {"text": "贤", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是贤良，不是限。"}, {"text": "信", "is_correct": false, "explanation": "xìn 比 xiàn 少了韵母中的 a（ian 变为 in），意思是信件，不是限。"}], "explanations": {"限": "正确答案。限（xiàn，第四声）表示限定数量、时间或范围。", "鲜": "xiān（第一声）与 xiàn（第四声）声调不同，意思是新鲜，不是限。", "贤": "xián（第二声）与 xiàn（第四声）声调不同，意思是贤良，不是限。", "信": "xìn 比 xiàn 少了韵母中的 a（ian 变为 in），意思是信件，不是限。"}, "sentence_index": null, "correct_answer": "限"}, "level_3": {"options": [{"text": "限", "is_correct": true, "explanation": "正确。“限”表示限定人数，“这次课限二十个学生参加”即只允许二十人参加。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：拒绝表示不接受，句子会变成不接收这些学生，与限定名额的意思相反。"}, {"text": "派", "is_correct": false, "explanation": "语义：派是指派、派遣，“派二十个学生参加”说的是安排，不表示限定人数。"}, {"text": "推迟", "is_correct": false, "explanation": "搭配：推迟的对象通常是时间或活动，不能直接带“二十个学生”作宾语。"}], "explanations": {"限": "正确。“限”表示限定人数，“这次课限二十个学生参加”即只允许二十人参加。", "拒绝": "语义：拒绝表示不接受，句子会变成不接收这些学生，与限定名额的意思相反。", "派": "语义：派是指派、派遣，“派二十个学生参加”说的是安排，不表示限定人数。", "推迟": "搭配：推迟的对象通常是时间或活动，不能直接带“二十个学生”作宾语。"}, "sentence_index": 6, "correct_answer": "限"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的会议限大家喜欢。", "explanation": "这里应该用〈让〉。限表示限定数量或范围，不能表示使人产生喜欢的心理；使别人喜欢要用“让”。"}, {"text": "我们的会议限在一个小时以上。", "explanation": "这里应该用〈至少〉。限只表示上限，不能和“以上”一起表示最低时间，应说“会议至少一个小时”。"}, {"text": "我们的会议很限五十人。", "explanation": "限是动词，不能被程度副词“很”修饰；限定人数应说“我们的会议限五十人”，去掉“很”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94729, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校很限学生每天用电脑一小时。", "corrected_sentence": "学校限学生每天用电脑一小时。", "error_description": "“很”是程度副词，不能修饰动词“限”；“限”后直接带宾语即可，应说“学校限学生每天用电脑一小时”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94729, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个景点每天很限两千名游客进入。", "corrected_sentence": "这个景点每天限两千名游客进入。", "error_description": "“很”是程度副词，不能修饰动词“限”，应去掉“很”，说“每天限两千名游客进入”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
