INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94730, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "规定范围或数量的界线，不许超出。", "primary_collocate": null, "pronunciation": "xiàn", "ipa": "ɕjɛn⁵¹", "syllable_count": 1, "sentences": [{"text": "参加人数以二十人为限。", "target_word": "限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个班的学生以三十人为限。", "target_word": "限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "借书时间以一个月为限。", "target_word": "限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报名以今天为限，明天不收了。", "target_word": "限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动以学生为限，别人不能参加。", "target_word": "限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人带的行李以两件为限。", "target_word": "限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停车时间以两小时为限。", "target_word": "限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛报名以十个队为限。", "target_word": "限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时间以九十分钟为限。", "target_word": "限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参观的人数以五十人为限。", "target_word": "限", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "期限", "label": "复合"}, {"form": "界限", "label": "复合"}, {"form": "有限", "label": "复合"}], "register": "中性", "sense_fingerprint": "限：规定的范围或数量的界线，常用于“以……为限”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c88eb55d-87b9-4467-ab1d-de538215c096') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94730, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "限", "is_correct": true, "explanation": "正确答案。限（xiàn，第四声）作名词时指界线，如“以……为限”。"}, {"text": "先", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，意思是先，不是限。"}, {"text": "咸", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是咸，不是限。"}, {"text": "险", "is_correct": false, "explanation": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是危险，不是限。"}, {"text": "显", "is_correct": false, "explanation": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是明显，不是限。"}], "explanations": {"限": "正确答案。限（xiàn，第四声）作名词时指界线，如“以……为限”。", "先": "xiān（第一声）与 xiàn（第四声）声调不同，意思是先，不是限。", "咸": "xián（第二声）与 xiàn（第四声）声调不同，意思是咸，不是限。", "险": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是危险，不是限。", "显": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是明显，不是限。"}, "sentence_index": null, "correct_answer": "限"}, "level_3": {"options": [{"text": "限", "is_correct": true, "explanation": "正确。“以二十人为限”指以二十人为界线，符合句子的语境。"}, {"text": "尽头", "is_correct": false, "explanation": "语义：尽头指道路或事物的终点，不表示人数的界线。"}, {"text": "期", "is_correct": false, "explanation": "搭配：“以……为期”搭配的是时间，不能接“二十人”这样的人数。"}, {"text": "底", "is_correct": false, "explanation": "语义：底指底部，与人数上的界线无关，句子意思不通。"}], "explanations": {"限": "正确。“以二十人为限”指以二十人为界线，符合句子的语境。", "尽头": "语义：尽头指道路或事物的终点，不表示人数的界线。", "期": "搭配：“以……为期”搭配的是时间，不能接“二十人”这样的人数。", "底": "语义：底指底部，与人数上的界线无关，句子意思不通。"}, "sentence_index": 0, "correct_answer": "限"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "报名的限是今天。", "explanation": "这里应该用〈期限〉。限单独作名词用得少，要说“报名的期限是今天”。"}, {"text": "报名以我的心情为限，明天不收了。", "explanation": "这里不能用〈限〉。“以……为限”的界线要能计算，如时间、数量或范围，“心情”不能作界线；凭心情决定应说“看心情”。"}, {"text": "报名以今天为限，后天也还可以报。", "explanation": "语义冲突：“以今天为限”表示今天是最后界线，后面却说后天还能报，与“限”的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94730, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "限", "is_correct": true, "explanation": "正确答案。限（xiàn，第四声）作名词时指界线，如“以……为限”。"}, {"text": "鲜", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，意思是新鲜，不是限。"}, {"text": "贤", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是贤良，不是限。"}, {"text": "信", "is_correct": false, "explanation": "xìn 比 xiàn 少了韵母中的 a（ian 变为 in），意思是信件，不是限。"}], "explanations": {"限": "正确答案。限（xiàn，第四声）作名词时指界线，如“以……为限”。", "鲜": "xiān（第一声）与 xiàn（第四声）声调不同，意思是新鲜，不是限。", "贤": "xián（第二声）与 xiàn（第四声）声调不同，意思是贤良，不是限。", "信": "xìn 比 xiàn 少了韵母中的 a（ian 变为 in），意思是信件，不是限。"}, "sentence_index": null, "correct_answer": "限"}, "level_3": {"options": [{"text": "限", "is_correct": true, "explanation": "正确。“以两小时为限”指以两小时为界线，符合停车时间的语境。"}, {"text": "顶", "is_correct": false, "explanation": "语义：顶指顶端，不表示时间上的界线，句子意思不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是动作，不能表示时间界线，“以两小时为吃”不成立。"}, {"text": "尾", "is_correct": false, "explanation": "语义：尾指末尾，与时间界线的意思不符，不能说“以两小时为尾”。"}], "explanations": {"限": "正确。“以两小时为限”指以两小时为界线，符合停车时间的语境。", "顶": "语义：顶指顶端，不表示时间上的界线，句子意思不通。", "吃": "语义：吃是动作，不能表示时间界线，“以两小时为吃”不成立。", "尾": "语义：尾指末尾，与时间界线的意思不符，不能说“以两小时为尾”。"}, "sentence_index": 6, "correct_answer": "限"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "参观的人数以提高水平为限。", "explanation": "这里不能用〈限〉。“以……为限”的界线要是时间、数量或范围，“提高水平”不能作界线；表示目标应说“以……为目标”。"}, {"text": "参观的人数以笑声为限。", "explanation": "这里不能用〈限〉。“以……为限”只能用于可计算的时间、数量或范围，“笑声”不能作界线。"}, {"text": "参观的人数以五十人为限，多的人也都能进。", "explanation": "语义冲突：限表示界线不能超出，这里却说多的人也能进，与“限”的意思相反，应说“不限”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "报名人数以五十人限。", "corrected_sentence": "报名人数以五十人为限。", "error_description": "“以……为限”结构中间的“为”不能省略：正确说法是“以五十人为限”，不能说“以五十人限”，应补上“为”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "停车数量以两百辆为限，超过了也可以停。", "corrected_sentence": "停车数量以两百辆为限，超过了就不能停。", "error_description": "“以……为限”规定的界线不能超出，后句说“超过了也可以停”与“限”矛盾；应说“超过了就不能停”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
