INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94731, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "院校是大学和学院这样的学校。", "primary_collocate": null, "pronunciation": "yuàn xiào", "ipa": "ɥɛn˥˩ ɕjaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "院校的学生都很年轻。", "target_word": "院校", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在一所院校工作。", "target_word": "院校", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是一所很大的院校。", "target_word": "院校", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好的院校不一定很贵。", "target_word": "院校", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她想去南方的院校读书。", "target_word": "院校", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些院校都有自己的图书馆。", "target_word": "院校", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末，院校里的学生常常去打球。", "target_word": "院校", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟参观了两所著名的院校。", "target_word": "院校", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "院校放假的时候，校园里特别安静。", "target_word": "院校", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多院校都在门口挂着欢迎新生的牌子。", "target_word": "院校", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "高等院校", "label": "复合"}], "register": "中性", "sense_fingerprint": "大学和学院这类学校", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60b8685b-8c93-4781-a5d8-5d5358d689c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94731, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "院校", "is_correct": true, "explanation": "院校：大学和学院这样的学校，“院校的学生”指高等学校的学生，符合句意。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是烹饪的场所，不是学习的地方，“厨房的学生”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人或机构，不会有“学生”，句子说不通。"}, {"text": "汽车", "is_correct": false, "explanation": "配价：“学生”需要人或学校作为领属者，汽车不能有学生。"}], "explanations": {"院校": "院校：大学和学院这样的学校，“院校的学生”指高等学校的学生，符合句意。", "厨房": "语义：厨房是烹饪的场所，不是学习的地方，“厨房的学生”说不通。", "天气": "语义：天气不是人或机构，不会有“学生”，句子说不通。", "汽车": "配价：“学生”需要人或学校作为领属者，汽车不能有学生。"}, "sentence_index": 0, "correct_answer": "院校"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的女儿才三岁，每天在院校玩得很开心。", "explanation": "这里应该用〈幼儿园〉。院校只指大学和学院，三岁的孩子应该去幼儿园。"}, {"text": "我感冒发烧了，下午要去院校看医生。", "explanation": "这里应该用〈医院〉。院校是大学和学院这样的学校，看病应该去医院。"}, {"text": "我的儿子才十岁，每周去院校两次，每次两小时。", "explanation": "这里应该用〈补习班〉。院校是高等学校，十岁的孩子应该去补习班，不能去院校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94731, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "院校", "is_correct": true, "explanation": "院校：大学和学院这样的学校，“院校里的学生”指大学生，周末常去打球，符合句意。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是金融机构，不是学习的地方，“银行里的学生”说不通。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：饭馆是餐饮场所，学生在饭馆里常常去打球说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "配价：“里”前的场所应能容纳学生活动，冰箱不能容纳学生。"}], "explanations": {"院校": "院校：大学和学院这样的学校，“院校里的学生”指大学生，周末常去打球，符合句意。", "银行": "语义：银行是金融机构，不是学习的地方，“银行里的学生”说不通。", "饭馆": "语义：饭馆是餐饮场所，学生在饭馆里常常去打球说不通。", "冰箱": "配价：“里”前的场所应能容纳学生活动，冰箱不能容纳学生。"}, "sentence_index": 6, "correct_answer": "院校"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院校的阿姨每天给一岁的宝宝喂饭。", "explanation": "这里应该用〈托儿所〉。院校是高等学校，给一岁宝宝喂饭的应该是托儿所的阿姨。"}, {"text": "弟弟上小学二年级，每天在院校读书。", "explanation": "这里应该用〈小学〉。院校只指大学和学院，上小学二年级的弟弟应该在小学读书。"}, {"text": "初一的学生每天都在院校上课，很辛苦。", "explanation": "这里应该用〈中学〉。院校是高等学校，初一的学生应该在中学上课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94731, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在一只院校学习音乐。", "corrected_sentence": "她在一所院校学习音乐。", "error_description": "量词错误：“院校”应该用量词“所”，“只”用于动物，不能用来计量院校。正确说法是“一所院校”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94731, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所院校们很有名，学生都很努力。", "corrected_sentence": "这所院校很有名，学生都很努力。", "error_description": "词缀错误：“们”只用于指人，不能加在“院校”后面，应说“这所院校”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
