INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94732, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "学院和大学等高等学校的合称。", "primary_collocate": null, "pronunciation": "yuàn xiào", "ipa": "ɥɛn˥˩ ɕjaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这所院校在北京。", "target_word": "院校", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想报考外地的院校。", "target_word": "院校", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个城市有很多院校。", "target_word": "院校", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她在选择院校的时候很认真。", "target_word": "院校", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些院校的老师都很有名。", "target_word": "院校", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国内的院校每年都会招很多新生。", "target_word": "院校", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥毕业的那所院校很有名。", "target_word": "院校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校附近有几所院校。", "target_word": "院校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报考院校以前，你要先看看招生条件。", "target_word": "院校", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位同学把好几所院校的介绍都看过了。", "target_word": "院校", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "高等院校", "label": "复合"}], "register": "中性", "sense_fingerprint": "学院和大学等高等学校的合称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60b8685b-8c93-4781-a5d8-5d5358d689c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94732, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "院校", "is_correct": true, "explanation": "院校：学院和大学等高等学校的合称，“这所院校”指一所高校，在北京，符合句意。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“所”用于学校、医院等机构，河流应用“条”，不能说“这所河流”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是建筑或机构，不能用“这所”计量，句子说不通。"}, {"text": "树", "is_correct": false, "explanation": "搭配：“树”的量词是“棵”，不能用“所”，“这所树”不成立。"}], "explanations": {"院校": "院校：学院和大学等高等学校的合称，“这所院校”指一所高校，在北京，符合句意。", "河流": "搭配：“所”用于学校、医院等机构，河流应用“条”，不能说“这所河流”。", "天气": "语义：天气不是建筑或机构，不能用“这所”计量，句子说不通。", "树": "搭配：“树”的量词是“棵”，不能用“所”，“这所树”不成立。"}, "sentence_index": 0, "correct_answer": "院校"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所院校的学生都只有十二岁。", "explanation": "这里应该用〈学校〉。院校专指学院和大学等高等学校，十二岁的学生在中小学读书，不能说“院校”。"}, {"text": "爷爷生病了，在院校住了一个星期。", "explanation": "这里应该用〈医院〉。院校是学院和大学等高等学校，生病住院应该在医院。"}, {"text": "我的女儿才三岁，每天早上七点去院校。", "explanation": "这里应该用〈幼儿园〉。院校只指学院和大学，三岁的孩子应该去幼儿园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94732, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "院校", "is_correct": true, "explanation": "院校：学院和大学等高等学校的合称，“那所院校”指哥哥毕业的那所高校，符合句意。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“所”用于学校、医院等机构，面包应用“个”或“块”，不能说“那所面包”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是机构，不能“毕业”，也不能“很有名”，句子说不通。"}, {"text": "鱼", "is_correct": false, "explanation": "搭配：“鱼”的量词是“条”，不能用“所”，“那所鱼”不成立。"}], "explanations": {"院校": "院校：学院和大学等高等学校的合称，“那所院校”指哥哥毕业的那所高校，符合句意。", "面包": "搭配：“所”用于学校、医院等机构，面包应用“个”或“块”，不能说“那所面包”。", "作业": "语义：作业不是机构，不能“毕业”，也不能“很有名”，句子说不通。", "鱼": "搭配：“鱼”的量词是“条”，不能用“所”，“那所鱼”不成立。"}, "sentence_index": 6, "correct_answer": "院校"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "初一的表弟在院校读书，每天要做很多作业。", "explanation": "这里应该用〈中学〉。院校指高等学校，初一的学生应该在中学读书。"}, {"text": "院校里的孩子们每天中午都要睡午觉。", "explanation": "这里应该用〈托儿所〉。院校是高等学校，需要午睡的孩子应该在托儿所。"}, {"text": "我的侄子今年七岁，在院校读书。", "explanation": "这里应该用〈小学〉。院校只指高等学校，七岁的孩子应该在小学读书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94732, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只院校有很多外国学生。", "corrected_sentence": "这所院校有很多外国学生。", "error_description": "量词错误：“院校”应该用量词“所”，“只”用于动物，不能用来计量院校。正确说法是“这所院校”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94732, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个区有两院校。", "corrected_sentence": "这个区有两所院校。", "error_description": "量词漏掉：数词“两”后面的“院校”需要量词“所”，应说“两所院校”，不能说“两院校”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
