INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94733, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "隔是在两个东西中间放一个东西，让它们分开。", "primary_collocate": null, "pronunciation": "gé", "ipa": "kɤ˧˥", "syllable_count": 1, "sentences": [{"text": "我们用一块布把房间隔成两半。", "target_word": "隔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中间隔一块板子，就不吵了。", "target_word": "隔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家里用书架隔出一个小书房。", "target_word": "隔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水把村子隔成两个部分。", "target_word": "隔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在两张床中间隔了一道屏风。", "target_word": "隔", "complexity_tier": "T3", "furigana": "wǒ zài liǎng zhāng chuáng zhōngjiān gé le yí dào píngfēng", "sentence_source": "generated"}, {"text": "老板用玻璃把办公室隔开。", "target_word": "隔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这堵墙把两家人隔开。", "target_word": "隔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个孩子打架，老师把他们隔开。", "target_word": "隔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用屏风把床隔起来。", "target_word": "隔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木板把大房间隔成了三个小间。", "target_word": "隔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隔着", "label": "体标"}, {"form": "隔开", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，在中间放东西使两边分开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccaa5f06-74fd-450d-9e5c-c87f845eb06a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94733, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "隔", "is_correct": true, "explanation": "正确答案：隔（gé，第二声），意思是在中间放东西使两边分开。"}, {"text": "哥", "is_correct": false, "explanation": "gē（第一声）与 gé（第二声）声调不同，“哥”意思是哥哥。"}, {"text": "割", "is_correct": false, "explanation": "gē（第一声）与 gé（第二声）声调不同，“割”意思是切断、划开。"}, {"text": "个", "is_correct": false, "explanation": "gè（第四声）与 gé（第二声）声调不同，“个”是量词，意思是单个。"}], "explanations": {"隔": "正确答案：隔（gé，第二声），意思是在中间放东西使两边分开。", "哥": "gē（第一声）与 gé（第二声）声调不同，“哥”意思是哥哥。", "割": "gē（第一声）与 gé（第二声）声调不同，“割”意思是切断、划开。", "个": "gè（第四声）与 gé（第二声）声调不同，“个”是量词，意思是单个。"}, "sentence_index": null, "correct_answer": "隔"}, "level_3": {"options": [{"text": "隔", "is_correct": true, "explanation": "正确答案。隔是在中间放东西使房间分成两半，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能用来分隔房间，“把房间吃成两半”句意不通。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”不与“把房间……成两半”搭配，擦不能使房间分开。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”指移动物品，不能使房间分成两半。"}], "explanations": {"隔": "正确答案。隔是在中间放东西使房间分成两半，符合句意。", "吃": "语义：“吃”不能用来分隔房间，“把房间吃成两半”句意不通。", "擦": "搭配：“擦”不与“把房间……成两半”搭配，擦不能使房间分开。", "搬": "语义：“搬”指移动物品，不能使房间分成两半。"}, "sentence_index": 0, "correct_answer": "隔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用刀把蛋糕隔成八块。", "explanation": "这里应该用〈切〉。用刀把东西分开是“切”；“隔”是在两者中间放阻挡物，不能用刀切。"}, {"text": "医生用刀隔开了伤口。", "explanation": "这里应该用〈割〉。用刀划开伤口是“割”；“隔”指在中间放东西使分开，不能用来指划开。"}, {"text": "老师把两个班隔成了三组。", "explanation": "这里应该用〈分〉。分组用“分”；“隔”指用墙、板等阻挡物把空间隔开，不能用来指分组。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94733, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "隔", "is_correct": true, "explanation": "正确答案：隔（gé，第二声），意思是在中间放东西使两边分开。"}, {"text": "歌", "is_correct": false, "explanation": "gē（第一声）与 gé（第二声）声调不同，“歌”意思是歌曲。"}, {"text": "鸽", "is_correct": false, "explanation": "gē（第一声）与 gé（第二声）声调不同，“鸽”意思是鸽子。"}, {"text": "各", "is_correct": false, "explanation": "gè（第四声）与 gé（第二声）声调不同，“各”意思是各自。"}, {"text": "搁", "is_correct": false, "explanation": "gē（第一声）与 gé（第二声）声调不同，“搁”意思是放置。"}], "explanations": {"隔": "正确答案：隔（gé，第二声），意思是在中间放东西使两边分开。", "歌": "gē（第一声）与 gé（第二声）声调不同，“歌”意思是歌曲。", "鸽": "gē（第一声）与 gé（第二声）声调不同，“鸽”意思是鸽子。", "各": "gè（第四声）与 gé（第二声）声调不同，“各”意思是各自。", "搁": "gē（第一声）与 gé（第二声）声调不同，“搁”意思是放置。"}, "sentence_index": null, "correct_answer": "隔"}, "level_3": {"options": [{"text": "隔", "is_correct": true, "explanation": "正确答案。这堵墙放在两家中间，使两家分开，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能使两家人分开，“这堵墙把两家人唱开”句意不通。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”不能表示墙把人分开，句意不通。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”不与“把两家人……开”搭配，写不能使人分开。"}], "explanations": {"隔": "正确答案。这堵墙放在两家中间，使两家分开，符合句意。", "唱": "语义：“唱”不能使两家人分开，“这堵墙把两家人唱开”句意不通。", "喝": "语义：“喝”不能表示墙把人分开，句意不通。", "写": "搭配：“写”不与“把两家人……开”搭配，写不能使人分开。"}, "sentence_index": 6, "correct_answer": "隔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用斧子把木头隔成两半。", "explanation": "这里应该用〈劈〉。用斧子把木头劈开是“劈”；“隔”不指用斧子劈开。"}, {"text": "他用剪刀把布隔成三段。", "explanation": "这里应该用〈剪〉。用剪刀把布剪开是“剪”；“隔”不指剪开。"}, {"text": "他用手隔开了信封的封口。", "explanation": "这里应该用〈拆开〉。拆信封要“拆开”；“隔开”是在两者中间放东西使分开，不能用来指打开封口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94733, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们用布帘卧室隔开了。", "corrected_sentence": "他们用布帘把卧室隔开了。", "error_description": "错误：宾语“卧室”直接放在动词前，语序不对。正确：应说“他们用布帘把卧室隔开了”，把“卧室”提到“把”字之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94733, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书架把客厅隔了成两部分。", "corrected_sentence": "书架把客厅隔成了两部分。", "error_description": "体标位置错误：“了”应放在补语“成”之后，说“隔成了两部分”，不能插在“隔”与“成”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
