INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94734, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指两地或两个时间之间相距、有间隔。", "primary_collocate": null, "pronunciation": "gé", "ipa": "kɤ˧˥", "syllable_count": 1, "sentences": [{"text": "我家和学校隔着一条河。", "target_word": "隔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们隔着一条街喊话。", "target_word": "隔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隔着一座山，我们很难见面。", "target_word": "隔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市和我家隔着三百公里。", "target_word": "隔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和他隔一天见一次面。", "target_word": "隔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家和奶奶家隔着三条街。", "target_word": "隔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家隔着大海。", "target_word": "隔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们两家只隔一条马路。", "target_word": "隔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每隔三天给奶奶打一次电话。", "target_word": "隔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里和那里隔得太远，走路要两个小时。", "target_word": "隔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隔着", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词，指空间或时间上相距、有间隔", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccaa5f06-74fd-450d-9e5c-c87f845eb06a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94734, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "隔", "is_correct": true, "explanation": "正确答案：隔（gé，第二声），意思是中间有阻挡或相距。"}, {"text": "哥", "is_correct": false, "explanation": "gē（第一声）与 gé（第二声）声调不同，“哥”意思是哥哥。"}, {"text": "割", "is_correct": false, "explanation": "gē（第一声）与 gé（第二声）声调不同，“割”意思是切断、划开。"}, {"text": "个", "is_correct": false, "explanation": "gè（第四声）与 gé（第二声）声调不同，“个”是量词，意思是单个。"}], "explanations": {"隔": "正确答案：隔（gé，第二声），意思是中间有阻挡或相距。", "哥": "gē（第一声）与 gé（第二声）声调不同，“哥”意思是哥哥。", "割": "gē（第一声）与 gé（第二声）声调不同，“割”意思是切断、划开。", "个": "gè（第四声）与 gé（第二声）声调不同，“个”是量词，意思是单个。"}, "sentence_index": null, "correct_answer": "隔"}, "level_3": {"options": [{"text": "隔", "is_correct": true, "explanation": "正确答案。隔着一条河表示两地之间有河相隔，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能与“着一条河”构成表示相隔的句子，句意不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”不能表示河在两地之间相隔，句意不通。"}, {"text": "拿", "is_correct": false, "explanation": "搭配：“拿着”不与“一条河”搭配，河不能被拿着。"}], "explanations": {"隔": "正确答案。隔着一条河表示两地之间有河相隔，符合句意。", "吃": "语义：“吃”不能与“着一条河”构成表示相隔的句子，句意不通。", "洗": "语义：“洗”不能表示河在两地之间相隔，句意不通。", "拿": "搭配：“拿着”不与“一条河”搭配，河不能被拿着。"}, "sentence_index": 0, "correct_answer": "隔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他隔开了家乡。", "explanation": "这里应该用〈离开〉。人离开某地用“离开”；“隔开”指在中间放东西使分开，不能用于人离开家乡。"}, {"text": "他隔开了窗户。", "explanation": "这里应该用〈打开〉。窗户要“打开”，“隔开”是在两者中间放东西，不能用于开窗。"}, {"text": "医生用刀隔开了伤口。", "explanation": "这里应该用〈割〉。用刀划开伤口是“割”，“隔”不能用刀划开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94734, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "隔", "is_correct": true, "explanation": "正确答案：隔（gé，第二声），意思是中间有阻挡或相距。"}, {"text": "歌", "is_correct": false, "explanation": "gē（第一声）与 gé（第二声）声调不同，“歌”意思是歌曲。"}, {"text": "鸽", "is_correct": false, "explanation": "gē（第一声）与 gé（第二声）声调不同，“鸽”意思是鸽子。"}, {"text": "各", "is_correct": false, "explanation": "gè（第四声）与 gé（第二声）声调不同，“各”意思是各自。"}, {"text": "搁", "is_correct": false, "explanation": "gē（第一声）与 gé（第二声）声调不同，“搁”意思是放置。"}], "explanations": {"隔": "正确答案：隔（gé，第二声），意思是中间有阻挡或相距。", "歌": "gē（第一声）与 gé（第二声）声调不同，“歌”意思是歌曲。", "鸽": "gē（第一声）与 gé（第二声）声调不同，“鸽”意思是鸽子。", "各": "gè（第四声）与 gé（第二声）声调不同，“各”意思是各自。", "搁": "gē（第一声）与 gé（第二声）声调不同，“搁”意思是放置。"}, "sentence_index": null, "correct_answer": "隔"}, "level_3": {"options": [{"text": "隔", "is_correct": true, "explanation": "正确答案。隔着大海表示两个国家被海洋相隔，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”不能表示两个国家之间有海相隔，句意不通。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”不与“着大海”搭配，大海不能被咬。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”不能表示大海把两国隔开，句意不通。"}], "explanations": {"隔": "正确答案。隔着大海表示两个国家被海洋相隔，符合句意。", "扔": "语义：“扔”不能表示两个国家之间有海相隔，句意不通。", "咬": "搭配：“咬”不与“着大海”搭配，大海不能被咬。", "擦": "语义：“擦”不能表示大海把两国隔开，句意不通。"}, "sentence_index": 6, "correct_answer": "隔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那辆车隔在门口。", "explanation": "这里应该用〈停〉。车停在某处用“停”；“隔”表示在两者之间设置阻挡物使不相通，不能说车隔在某处。"}, {"text": "他把书隔在桌上。", "explanation": "这里应该用〈放〉。把东西放在桌上用“放”；“隔”需要有阻隔两者的作用，不能用于一般放置。"}, {"text": "警察隔住了那辆车。", "explanation": "这里应该用〈拦住〉。拦车用“拦住”；“隔住”指在两者之间放东西使不相通，不能用于人或车的阻拦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这栋楼和学校隔了着一条马路。", "corrected_sentence": "这栋楼和学校隔着一条马路。", "error_description": "体标重复：“隔”后只用一个体标“着”，不能同时加“了”，应说“隔着一条马路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家和超市隔了很近。", "corrected_sentence": "我家和超市隔得很近。", "error_description": "补语标记错误：表示程度的补语前应用“得”，说“隔得很近”，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
