INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94735, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94735, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "雷是下雨时天上发出的很大的响声。", "primary_collocate": null, "pronunciation": "léi", "ipa": "lei˧˥", "syllable_count": 1, "sentences": [{"text": "下雨时，天上的雷很响。", "target_word": "雷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗怕雷，躲在床下不出来。", "target_word": "雷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雷很大，我昨晚没睡好。", "target_word": "雷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗外响起一声雷，孩子哭了。", "target_word": "雷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到雷，我们就赶快回家。", "target_word": "雷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨下得很大，雷也一直在响。", "target_word": "雷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天的雨常常带着雷。", "target_word": "雷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹不怕雨，只怕雷。", "target_word": "雷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑了，远处又传来一声雷。", "target_word": "雷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雷一响，雨就下来了。", "target_word": "雷", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一声雷", "label": "量词"}, {"form": "打雷", "label": "复合"}], "register": "中性", "sense_fingerprint": "雷|名词|下雨时天上发出的很大的响声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81aba494-6514-4052-93d8-2027c397c7d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94735, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "雷", "is_correct": true, "explanation": "雷（léi，第二声）指下雨时天上发出的很大响声，是正确答案。"}, {"text": "肋", "is_correct": false, "explanation": "lèi（第四声）与 léi（第二声）声调不同，「肋」意思是肋骨。"}, {"text": "泪", "is_correct": false, "explanation": "lèi（第四声）与 léi（第二声）声调不同，「泪」意思是眼泪。"}, {"text": "类", "is_correct": false, "explanation": "lèi（第四声）与 léi（第二声）声调不同，「类」意思是种类。"}, {"text": "垒", "is_correct": false, "explanation": "lěi（第三声）与 léi（第二声）声调不同，「垒」意思是堡垒、棒球的垒。"}, {"text": "蕾", "is_correct": false, "explanation": "lěi（第三声）与 léi（第二声）声调不同，「蕾」意思是花蕾。"}], "explanations": {"雷": "雷（léi，第二声）指下雨时天上发出的很大响声，是正确答案。", "肋": "lèi（第四声）与 léi（第二声）声调不同，「肋」意思是肋骨。", "泪": "lèi（第四声）与 léi（第二声）声调不同，「泪」意思是眼泪。", "类": "lèi（第四声）与 léi（第二声）声调不同，「类」意思是种类。", "垒": "lěi（第三声）与 léi（第二声）声调不同，「垒」意思是堡垒、棒球的垒。", "蕾": "lěi（第三声）与 léi（第二声）声调不同，「蕾」意思是花蕾。"}, "sentence_index": null, "correct_answer": "雷"}, "level_3": {"options": [{"text": "雷", "is_correct": true, "explanation": "正确：雷是下雨时天上发出的响声，与“很响”相合。"}, {"text": "闪电", "is_correct": false, "explanation": "语义：闪电是光，不发出声音，与“很响”矛盾。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不会发出声响，与“很响”矛盾。"}, {"text": "光", "is_correct": false, "explanation": "搭配：“响”说声音，不能说光很响。"}], "explanations": {"雷": "正确：雷是下雨时天上发出的响声，与“很响”相合。", "闪电": "语义：闪电是光，不发出声音，与“很响”矛盾。", "太阳": "语义：太阳不会发出声响，与“很响”矛盾。", "光": "搭配：“响”说声音，不能说光很响。"}, "sentence_index": 0, "correct_answer": "雷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窗外闪过一道雷，孩子哭了。", "explanation": "这里应该用〈闪电〉。雷是声音，闪电是光，“闪过一道”要用闪电。"}, {"text": "船长靠雷发现了前面的暗礁。", "explanation": "这里应该用〈雷达〉。雷是雷声，不能用来探测，“靠……发现”要用雷达。"}, {"text": "窗外响起一块雷，孩子哭了。", "explanation": "这里应该用〈声〉。雷是声音，量词要用“声”，“块”用于块状物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94735, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "雷", "is_correct": true, "explanation": "雷（léi，第二声）指下雨时天上发出的很大响声，是正确答案。"}, {"text": "肋", "is_correct": false, "explanation": "lèi（第四声）与 léi（第二声）声调不同，「肋」意思是肋骨。"}, {"text": "磊", "is_correct": false, "explanation": "lěi（第三声）与 léi（第二声）声调不同，「磊」意思是石头堆叠（磊落）。"}, {"text": "儡", "is_correct": false, "explanation": "lěi（第三声）与 léi（第二声）声调不同，「儡」用于傀儡。"}, {"text": "类", "is_correct": false, "explanation": "lèi（第四声）与 léi（第二声）声调不同，「类」意思是种类。"}], "explanations": {"雷": "雷（léi，第二声）指下雨时天上发出的很大响声，是正确答案。", "肋": "lèi（第四声）与 léi（第二声）声调不同，「肋」意思是肋骨。", "磊": "lěi（第三声）与 léi（第二声）声调不同，「磊」意思是石头堆叠（磊落）。", "儡": "lěi（第三声）与 léi（第二声）声调不同，「儡」用于傀儡。", "类": "lèi（第四声）与 léi（第二声）声调不同，「类」意思是种类。"}, "sentence_index": null, "correct_answer": "雷"}, "level_3": {"options": [{"text": "雷", "is_correct": true, "explanation": "正确：夏天的雨常带雷，雷是雨天的响声，与句意相合。"}, {"text": "雪", "is_correct": false, "explanation": "语义：夏天不下雪，与“夏天”矛盾。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：“冬天”与句中“夏天”冲突，且不是可以被“带着”的东西。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“带着”后接可随身携带的东西，雨不能带桌子。"}], "explanations": {"雷": "正确：夏天的雨常带雷，雷是雨天的响声，与句意相合。", "雪": "语义：夏天不下雪，与“夏天”矛盾。", "冬天": "语义：“冬天”与句中“夏天”冲突，且不是可以被“带着”的东西。", "桌子": "搭配：“带着”后接可随身携带的东西，雨不能带桌子。"}, "sentence_index": 6, "correct_answer": "雷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窗外刮起了大雷，孩子哭了。", "explanation": "这里应该用〈风〉。雷是声音，不会“刮”，“刮”用于风。"}, {"text": "这把伞能挡住雷，衣服就不会湿。", "explanation": "这里应该用〈雨〉。伞挡的是雨，雷是响声，挡不住。"}, {"text": "天边飘来一朵雷，很快下雨了。", "explanation": "这里应该用〈声〉。“朵”多用于云、花，雷是声音，应说“一声雷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94735, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里打了两只雷，我被吵醒了。", "corrected_sentence": "夜里打了两声雷，我被吵醒了。", "error_description": "量词错误：雷是声音，应用量词“声”，不能用“只”（“只”多用于动物）。错误形式：两只雷；正确形式：两声雷。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94735, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "刚才打了一雷声，雨就下大了。", "corrected_sentence": "刚才打了一声雷，雨就下大了。", "error_description": "语序错误：量词「声」应紧接数词、放在名词「雷」前，应说「一声雷」，不能说「一雷声」。错误形式：打了一雷声；正确形式：打了一声雷。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
