INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94736, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "云层放电时发出的巨大响声。", "primary_collocate": null, "pronunciation": "léi", "ipa": "lei˧˥", "syllable_count": 1, "sentences": [{"text": "先看到闪电，过几秒才听到雷。", "target_word": "雷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，雷是云里的电发出的。", "target_word": "雷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天云很厚，晚上可能有雷。", "target_word": "雷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的雷特别大。", "target_word": "雷", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "闪电过后，一声雷响了。", "target_word": "雷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雷把小鸟吓飞了。", "target_word": "雷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在家里听着雷，看着闪电。", "target_word": "雷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云越来越黑，雷越来越近。", "target_word": "雷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雷比闪电来得慢一些。", "target_word": "雷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "云层里放出电，就会有雷。", "target_word": "雷", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一声雷", "label": "量词"}, {"form": "打雷", "label": "复合"}], "register": "中性", "sense_fingerprint": "雷|名词|云层放电时发出的巨大响声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81aba494-6514-4052-93d8-2027c397c7d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94736, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "雷", "is_correct": true, "explanation": "雷（léi，第二声）指云层放电时发出的巨大响声，是正确答案。"}, {"text": "肋", "is_correct": false, "explanation": "lèi（第四声）与 léi（第二声）声调不同，「肋」意思是肋骨。"}, {"text": "泪", "is_correct": false, "explanation": "lèi（第四声）与 léi（第二声）声调不同，「泪」意思是眼泪。"}, {"text": "类", "is_correct": false, "explanation": "lèi（第四声）与 léi（第二声）声调不同，「类」意思是种类。"}, {"text": "垒", "is_correct": false, "explanation": "lěi（第三声）与 léi（第二声）声调不同，「垒」意思是堡垒、棒球的垒。"}, {"text": "蕾", "is_correct": false, "explanation": "lěi（第三声）与 léi（第二声）声调不同，「蕾」意思是花蕾。"}], "explanations": {"雷": "雷（léi，第二声）指云层放电时发出的巨大响声，是正确答案。", "肋": "lèi（第四声）与 léi（第二声）声调不同，「肋」意思是肋骨。", "泪": "lèi（第四声）与 léi（第二声）声调不同，「泪」意思是眼泪。", "类": "lèi（第四声）与 léi（第二声）声调不同，「类」意思是种类。", "垒": "lěi（第三声）与 léi（第二声）声调不同，「垒」意思是堡垒、棒球的垒。", "蕾": "lěi（第三声）与 léi（第二声）声调不同，「蕾」意思是花蕾。"}, "sentence_index": null, "correct_answer": "雷"}, "level_3": {"options": [{"text": "雷", "is_correct": true, "explanation": "正确：“听到”后接声音，雷是打雷的响声，与句意相合。"}, {"text": "光", "is_correct": false, "explanation": "搭配：“听到”后接声音，不能说听到光。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“听到”的对象应是声音，颜色不能被听到。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是视觉的、无声的，与“听到”矛盾。"}], "explanations": {"雷": "正确：“听到”后接声音，雷是打雷的响声，与句意相合。", "光": "搭配：“听到”后接声音，不能说听到光。", "颜色": "搭配：“听到”的对象应是声音，颜色不能被听到。", "影子": "语义：影子是视觉的、无声的，与“听到”矛盾。"}, "sentence_index": 0, "correct_answer": "雷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山里的雷特别亮。", "explanation": "这里应该用〈闪电〉。雷是声音，“亮”形容光，要用闪电。"}, {"text": "渔民靠雷找到了一群鱼。", "explanation": "这里应该用〈雷达〉。雷是云层放电的响声，不能用来探测，“靠……找到”要用雷达。"}, {"text": "山里来了一条雷。", "explanation": "这里应该用〈声〉。雷用量词“声”，“条”多用于河、蛇等长物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94736, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "雷", "is_correct": true, "explanation": "雷（léi，第二声）指云层放电时发出的巨大响声，是正确答案。"}, {"text": "肋", "is_correct": false, "explanation": "lèi（第四声）与 léi（第二声）声调不同，「肋」意思是肋骨。"}, {"text": "磊", "is_correct": false, "explanation": "lěi（第三声）与 léi（第二声）声调不同，「磊」意思是石头堆叠（磊落）。"}, {"text": "儡", "is_correct": false, "explanation": "lěi（第三声）与 léi（第二声）声调不同，「儡」用于傀儡。"}, {"text": "类", "is_correct": false, "explanation": "lèi（第四声）与 léi（第二声）声调不同，「类」意思是种类。"}], "explanations": {"雷": "雷（léi，第二声）指云层放电时发出的巨大响声，是正确答案。", "肋": "lèi（第四声）与 léi（第二声）声调不同，「肋」意思是肋骨。", "磊": "lěi（第三声）与 léi（第二声）声调不同，「磊」意思是石头堆叠（磊落）。", "儡": "lěi（第三声）与 léi（第二声）声调不同，「儡」用于傀儡。", "类": "lèi（第四声）与 léi（第二声）声调不同，「类」意思是种类。"}, "sentence_index": null, "correct_answer": "雷"}, "level_3": {"options": [{"text": "雷", "is_correct": true, "explanation": "正确：“听着”后接可以听到的响声，雷与句意相合。"}, {"text": "墙", "is_correct": false, "explanation": "搭配：“听着”的对象应是声音，墙不能被听。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是可见的物体，不发出声音，与“听着”矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“听着”需要声音的来源，桌子不能说听着。"}], "explanations": {"雷": "正确：“听着”后接可以听到的响声，雷与句意相合。", "墙": "搭配：“听着”的对象应是声音，墙不能被听。", "窗户": "语义：窗户是可见的物体，不发出声音，与“听着”矛盾。", "桌子": "搭配：“听着”需要声音的来源，桌子不能说听着。"}, "sentence_index": 6, "correct_answer": "雷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天一黑，雷就下来了。", "explanation": "这里应该用〈雨〉。雷是响声，不会“下来”，要说“雷就响了”。"}, {"text": "这阵雷把窗户吹得直响。", "explanation": "这里应该用〈风〉。吹窗户的是风，雷是响声，不会“吹”。"}, {"text": "云层里放出电，就会有一座雷。", "explanation": "这里应该用〈声〉。“座”用于山、房屋等，雷是响声，要用“声”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94736, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雷突然响下来了。", "corrected_sentence": "雷突然响起来了。", "error_description": "补语错误：“响”表示开始发声，应接补语“起来”，不说“响下来”。错误形式：响下来；正确形式：响起来。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94736, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天晚上雷打了。", "corrected_sentence": "今天晚上打雷了。", "error_description": "离合词错误：“打雷”是离合词，“雷”应放在“打”之后，不能提到“打”前面。错误形式：雷打了；正确形式：打雷了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
