INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94737, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "电话会是大家在不同地方，用电话一起说话开会。", "primary_collocate": null, "pronunciation": "diàn huà huì", "ipa": "tjɛn˥˩ xwa˥˩ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "我们明天上午开电话会。", "target_word": "电话会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在出差，只能参加电话会。", "target_word": "电话会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话会一点开始，别迟到。", "target_word": "电话会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电话会有五个人参加。", "target_word": "电话会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的电话会开了一个小时。", "target_word": "电话会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板在电话会上说了新计划。", "target_word": "电话会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在车上开了一个电话会。", "target_word": "电话会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能参加下午的电话会吗？", "target_word": "电话会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话会结束后，我给他发了邮件。", "target_word": "电话会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个城市的同事一起开电话会。", "target_word": "电话会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "场", "label": "量词"}, {"form": "次", "label": "量词"}, {"form": "電話會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不同地方的人用电话一起开会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df093371-859c-466c-bce4-6c56d378b3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94737, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电话会", "is_correct": true, "explanation": "正确：电话会指通过电话开的会，符合“明天上午开”的语境。"}, {"text": "晚会", "is_correct": false, "explanation": "语义：晚会指晚上举行的聚会，与“上午”矛盾。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：说“放电影”，不说“开电影”。"}, {"text": "午餐", "is_correct": false, "explanation": "搭配：说“吃午餐”，“开午餐”不成立。"}], "explanations": {"电话会": "正确：电话会指通过电话开的会，符合“明天上午开”的语境。", "晚会": "语义：晚会指晚上举行的聚会，与“上午”矛盾。", "电影": "搭配：说“放电影”，不说“开电影”。", "午餐": "搭配：说“吃午餐”，“开午餐”不成立。"}, "sentence_index": 0, "correct_answer": "电话会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我参加了一只电话会。", "explanation": "这里应该用〈场〉。会议用“场”“次”“个”，“只”用于动物等，不用于会议。"}, {"text": "我们吃了一个电话会，讨论了新方案。", "explanation": "搭配错误：“吃”不搭配会议，应说“开”。"}, {"text": "请你留一下电话会，方便我联系你。", "explanation": "语义错误：这里要说的是电话号码，“电话会”指会议，不能指号码。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94737, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电话会", "is_correct": true, "explanation": "正确：在车上用电话参加会议，符合语境。"}, {"text": "苹果", "is_correct": false, "explanation": "搭配：说“吃一个苹果”，不说“开一个苹果”。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：说“吃面包”，“开了一个面包”不成立。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "搭配：说“吃鸡蛋”，不说“开了一个鸡蛋”。"}], "explanations": {"电话会": "正确：在车上用电话参加会议，符合语境。", "苹果": "搭配：说“吃一个苹果”，不说“开一个苹果”。", "面包": "搭配：说“吃面包”，“开了一个面包”不成立。", "鸡蛋": "搭配：说“吃鸡蛋”，不说“开了一个鸡蛋”。"}, "sentence_index": 6, "correct_answer": "电话会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三个城市的同事面对面地开电话会。", "explanation": "语义矛盾：电话会靠电话交谈，不能“面对面”进行。"}, {"text": "我和妈妈每天吃电话会，聊聊家常。", "explanation": "搭配错误：“吃”不搭配会议，应说“开”。"}, {"text": "三个城市的同事买了一个电话会。", "explanation": "语义错误：电话会是一次会议，不是可以购买的东西，应说“参加”或“开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94737, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天上午开一只电话会。", "corrected_sentence": "我们明天上午开一场电话会。", "error_description": "量词错误：会议应用“场”（或“次”“个”），“只”用于动物等，不能说“一只电话会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94737, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们每周五都开一张电话会。", "corrected_sentence": "他们每周五都开一次电话会。", "error_description": "量词错误：“张”用于纸张、桌子等，不用于会议；会议应说“开一次电话会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94739, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '607e29e9-b1d6-4274-a4c2-ecaae7dee8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
