INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94741, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "巩固是让东西变得更结实，不容易坏。", "primary_collocate": null, "pronunciation": "gǒng gù", "ipa": "kʊŋ˨˩˦ ku˥˩", "syllable_count": 2, "sentences": [{"text": "工人正在巩固这座桥。", "target_word": "巩固", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们要巩固堤坝。", "target_word": "巩固", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些石头能巩固房子的地基。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雨以前，村民巩固了河边的土墙。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要巩固这道墙，得多加几根柱子。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用木板巩固了旧门。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了让桥更结实，工人巩固了桥墩。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震后，政府巩固了很多旧房子。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把窗户用铁条巩固了一下。", "target_word": "巩固", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们用水泥巩固着塔的底部。", "target_word": "巩固", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "巩固了", "label": "体标"}, {"form": "巩固过", "label": "体标"}, {"form": "巩固着", "label": "体标"}, {"form": "巩固巩固", "label": "重叠"}], "register": "中性", "sense_fingerprint": "让东西更结实不易坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60b8685b-8c93-4781-a5d8-5d5358d689c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94741, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巩固", "is_correct": true, "explanation": "巩固：使桥更结实，“正在巩固这座桥”符合句意。"}, {"text": "游览", "is_correct": false, "explanation": "语义：游览指参观景点，工人在桥上工作不是去游览，句子说不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能用于桥。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能用于桥。"}], "explanations": {"巩固": "巩固：使桥更结实，“正在巩固这座桥”符合句意。", "游览": "语义：游览指参观景点，工人在桥上工作不是去游览，句子说不通。", "吃": "搭配：“吃”的对象是食物，不能用于桥。", "唱": "搭配：“唱”的对象是歌曲，不能用于桥。"}, "sentence_index": 0, "correct_answer": "巩固"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次施工巩固了大楼的高度。", "explanation": "这里应该用〈增加〉。巩固是使东西更结实，不表示高度增加，要用“增加”。"}, {"text": "我们用彩灯巩固了整个大厅。", "explanation": "这里应该用〈装饰〉。巩固是使东西更结实，用彩灯美化大厅要用“装饰”。"}, {"text": "地震巩固了几座旧房子。", "explanation": "这里应该用〈摧毁〉。巩固是使东西更结实，地震使房屋倒塌要用“摧毁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94741, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巩固", "is_correct": true, "explanation": "巩固：使桥墩更结实，“为了让桥更结实”表明目的，符合句意。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“为了让桥更结实”却“破坏”桥墩，前后矛盾，句子说不通。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：装饰是美化，不能使桥墩更结实，与“为了让桥更结实”不符。"}, {"text": "锯", "is_correct": false, "explanation": "搭配：“锯”多用于木材等，不能用于桥墩。"}], "explanations": {"巩固": "巩固：使桥墩更结实，“为了让桥更结实”表明目的，符合句意。", "破坏": "语义：“为了让桥更结实”却“破坏”桥墩，前后矛盾，句子说不通。", "装饰": "语义：装饰是美化，不能使桥墩更结实，与“为了让桥更结实”不符。", "锯": "搭配：“锯”多用于木材等，不能用于桥墩。"}, "sentence_index": 6, "correct_answer": "巩固"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次改革让大楼的重量巩固了一半。", "explanation": "这里应该用〈减少〉。巩固表示使稳固，不表示重量减少一半，要用“减少”。"}, {"text": "台风巩固了村里的电线。", "explanation": "这里应该用〈破坏〉。巩固是使东西更结实，台风使电线受损要用“破坏”。"}, {"text": "这块膏药能巩固腰痛。", "explanation": "这里应该用〈减轻〉。巩固是使东西更结实，缓解腰痛要用“减轻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94741, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把桥巩固很结实。", "corrected_sentence": "工人把桥巩固得很结实。", "error_description": "补语错误：“巩固”后接程度补语“很结实”时需要用“得”连接，应说“巩固得很结实”，不能直接说“巩固很结实”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94741, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每天都巩固过堤坝。", "corrected_sentence": "我们每天都巩固堤坝。", "error_description": "时态助词错误：“过”表示曾经有过的经历，与“每天都”表示的习惯相矛盾，应说“我们每天都巩固堤坝”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
