INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94742, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94742, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使事物、友谊或关系更加稳固、坚实；也指反复练习使学到的知识牢固。", "primary_collocate": null, "pronunciation": "gǒng gù", "ipa": "kʊŋ˨˩˦ ku˥˩", "syllable_count": 2, "sentences": [{"text": "我们要巩固新学的词。", "target_word": "巩固", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每天复习可以巩固知识。", "target_word": "巩固", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这样做能巩固友谊。", "target_word": "巩固", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天晚上都巩固当天学的内容。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国的合作巩固了双方的关系。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做完练习以后，我想巩固一下语法。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了巩固成绩，她没有放松学习。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这堵墙需要巩固，不然会倒。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把学过的汉字又巩固了一遍。", "target_word": "巩固", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们用钢筋巩固着河边的堤坝。", "target_word": "巩固", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "巩固了", "label": "体标"}, {"form": "巩固过", "label": "体标"}, {"form": "巩固着", "label": "体标"}, {"form": "巩固巩固", "label": "重叠"}], "register": "中性", "sense_fingerprint": "使事物、关系或所学知识更稳固", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60b8685b-8c93-4781-a5d8-5d5358d689c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94742, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巩固", "is_correct": true, "explanation": "巩固：使学到的知识更牢固，“巩固新学的词”即让新词记得更牢，符合句意。"}, {"text": "修建", "is_correct": false, "explanation": "语义：修建指建造房屋或设施，“词”不能被修建，句子说不通。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”多用于房间、地面等场所，不能用于“词”。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”的对象是植物或作物，“词”不能被种植，句子说不通。"}], "explanations": {"巩固": "巩固：使学到的知识更牢固，“巩固新学的词”即让新词记得更牢，符合句意。", "修建": "语义：修建指建造房屋或设施，“词”不能被修建，句子说不通。", "打扫": "搭配：“打扫”多用于房间、地面等场所，不能用于“词”。", "种植": "语义：“种植”的对象是植物或作物，“词”不能被种植，句子说不通。"}, "sentence_index": 0, "correct_answer": "巩固"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次跑步时，心跳巩固了很多。", "explanation": "这里应该用〈加快〉。巩固表示使稳固，不表示心跳加快，“心跳加快了很多”才符合句意。"}, {"text": "他每天晚上都巩固第二天要学的内容。", "explanation": "这里应该用〈预习〉。巩固是把学过的内容变牢固，第二天要学的内容还没学过，应该用“预习”。"}, {"text": "他的体重巩固了五公斤。", "explanation": "这里应该用〈增加〉。巩固不表示数量增加，体重增加了要用“增加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巩固", "is_correct": true, "explanation": "巩固：使成绩稳定、不下滑，“为了巩固成绩”表示目的，符合句意。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“为了破坏成绩”与后文“没有放松学习”的目的相矛盾，句子说不通。"}, {"text": "挥霍", "is_correct": false, "explanation": "搭配：“挥霍”多用于金钱、时间，不搭配“成绩”。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“为了忘记成绩”与“没有放松学习”的目的相矛盾，句子说不通。"}], "explanations": {"巩固": "巩固：使成绩稳定、不下滑，“为了巩固成绩”表示目的，符合句意。", "破坏": "语义：“为了破坏成绩”与后文“没有放松学习”的目的相矛盾，句子说不通。", "挥霍": "搭配：“挥霍”多用于金钱、时间，不搭配“成绩”。", "忘记": "语义：“为了忘记成绩”与“没有放松学习”的目的相矛盾，句子说不通。"}, "sentence_index": 6, "correct_answer": "巩固"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种新方法让学生的运动量巩固了许多。", "explanation": "这里应该用〈增加〉。巩固表示使稳固，不表示数量增加，运动量增加要用“增加”。"}, {"text": "工人们正在巩固坏掉的电视机。", "explanation": "这里应该用〈修复〉。巩固是使东西更结实，把坏掉的东西修好要用“修复”。"}, {"text": "这种药能巩固头痛。", "explanation": "这里应该用〈减轻〉。巩固不表示减轻疼痛，缓解头痛要用“减轻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "复习可以巩固了学到的语法。", "corrected_sentence": "复习可以巩固学到的语法。", "error_description": "时态助词错误：“可以”表示可能，后面不能加“了”，“巩固”后不用“了”，应说“复习可以巩固学到的语法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次施工把墙巩固很牢。", "corrected_sentence": "这次施工把墙巩固得很牢。", "error_description": "补语错误：“巩固”后接程度补语“很牢”时需要用“得”连接，应说“巩固得很牢”，不能直接说“巩固很牢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
