INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94743, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "预定是事先说好要留一个东西给某人。", "primary_collocate": null, "pronunciation": "yù dìng", "ipa": "y⁵¹ tiŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "我想预定明天晚上的位子。", "target_word": "预定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上预定了两张电影票。", "target_word": "预定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们已经预定好了房间。", "target_word": "预定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，你预定的是哪天的票？", "target_word": "预定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给爸爸预定了一个生日蛋糕。", "target_word": "预定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末人多，最好先预定座位。", "target_word": "预定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她预定了去北京的火车票。", "target_word": "预定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆要提前预定吗？", "target_word": "预定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打电话预定了一张四人桌。", "target_word": "预定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你预定过这家酒店吗？", "target_word": "预定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预定了", "label": "体标"}, {"form": "预定过", "label": "体标"}], "register": "中性", "sense_fingerprint": "预定：事先订好座位、房间、票等，留给某人使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c88eb55d-87b9-4467-ab1d-de538215c096') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94743, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "预定", "is_correct": true, "explanation": "正确：预定指事先订下，与“我想……明天晚上的位子”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：吃的宾语应是食物，不能说吃位子。"}, {"text": "修", "is_correct": false, "explanation": "搭配：修多用于损坏的东西，不能用于订座位。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：回忆指想起过去，与“明天晚上”的未来时间矛盾。"}], "explanations": {"预定": "正确：预定指事先订下，与“我想……明天晚上的位子”相符。", "吃": "搭配：吃的宾语应是食物，不能说吃位子。", "修": "搭配：修多用于损坏的东西，不能用于订座位。", "回忆": "语义：回忆指想起过去，与“明天晚上”的未来时间矛盾。"}, "sentence_index": 0, "correct_answer": "预定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我周六下午预定了好心情。", "explanation": "这里应该用〈保持〉。预定只用于订座、订房、订票等可以事先订下的东西，心情不能预定。"}, {"text": "我预定今天会有好事发生。", "explanation": "这里应该用〈预感〉。预感指凭直觉觉得将要发生某事，“预定”只表示订下或事先规定，不能表示个人的感觉。"}, {"text": "我想跟朋友预定周末见面。", "explanation": "这里应该用〈约定〉。约定指双方商量好，“预定”指事先订下座位、票等，不用于双方商定见面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94743, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预定", "is_correct": true, "explanation": "正确：预定指事先订下，与“去北京的火车票”相符。"}, {"text": "听", "is_correct": false, "explanation": "搭配：听的宾语是声音、话语，不能说听车票。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：洗多用于衣物、器具，不能用于车票。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：欢迎需要人作宾语，不能说欢迎车票。"}], "explanations": {"预定": "正确：预定指事先订下，与“去北京的火车票”相符。", "听": "搭配：听的宾语是声音、话语，不能说听车票。", "洗": "搭配：洗多用于衣物、器具，不能用于车票。", "欢迎": "配价：欢迎需要人作宾语，不能说欢迎车票。"}, "sentence_index": 6, "correct_answer": "预定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套家具是他请木匠预定的。", "explanation": "这里应该用〈定做〉。定做指按要求制作，预定只能用于事先订下现成的座位、房间、票等。"}, {"text": "他预定朋友办理签证。", "explanation": "这里应该用〈委托〉。委托指请别人代办事情，“预定”只用于订座、订票，不能用来让别人去办理事务。"}, {"text": "我在学校预定了一个好朋友。", "explanation": "这里应该用〈交〉。预定只用于事先订下座位、房间、票等，朋友不能预定，应说“交了一个好朋友”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94743, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经在网上预定了好下周的火车票。", "corrected_sentence": "他已经在网上预定好了下周的火车票。", "error_description": "“好”作结果补语要紧跟动词，应说“预定好了”，不能说“预定了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94743, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来没有预定了这么贵的酒店。", "corrected_sentence": "我从来没有预定过这么贵的酒店。", "error_description": "表示“从未有过这种经历”要用体标“过”，不能用“了”，应说“没有预定过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
