INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94744, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "预先规定或安排好的（时间、计划、目标等）。", "primary_collocate": null, "pronunciation": "yù dìng", "ipa": "y⁵¹ tiŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "会议按预定时间开始了。", "target_word": "预定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机没有按预定时间到达。", "target_word": "预定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活动预定下个月开始。", "target_word": "预定", "complexity_tier": "T3", "furigana": "huódòng yùdìng xià ge yuè kāishǐ.", "sentence_source": "generated"}, {"text": "这个项目预定明年完成。", "target_word": "预定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览预定在周五开幕。", "target_word": "预定", "complexity_tier": "T3", "furigana": "zhǎnlǎn yùdìng zài zhōu wǔ kāimù.", "sentence_source": "generated"}, {"text": "工作已经提前完成了预定的目标。", "target_word": "预定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛预定三点开始，但是下雨了。", "target_word": "预定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂预定明年春天投产。", "target_word": "预定", "complexity_tier": "T3", "furigana": "gōngchǎng yùdìng míngnián chūntiān tóuchǎn.", "sentence_source": "generated"}, {"text": "一切都按预定的办法进行。", "target_word": "预定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议预定三天后召开。", "target_word": "预定", "complexity_tier": "T3", "furigana": "huìyì yùdìng sān tiān hòu zhàokāi.", "sentence_source": "generated"}], "morphological_forms": [{"form": "预定了", "label": "体标"}, {"form": "预定过", "label": "体标"}], "register": "中性", "sense_fingerprint": "预定：事先约定或规定时间、计划、目标", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c88eb55d-87b9-4467-ab1d-de538215c096') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94744, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "预定", "is_correct": true, "explanation": "正确：预定指事先规定好的，与“按……时间开始”相符。"}, {"text": "开心", "is_correct": false, "explanation": "搭配：“开心”是心情，不能用来修饰“时间”。"}, {"text": "匆忙", "is_correct": false, "explanation": "搭配：“时间”不能用“匆忙”来修饰。"}, {"text": "红色", "is_correct": false, "explanation": "搭配：“红色”是颜色，不能用来修饰“时间”。"}], "explanations": {"预定": "正确：预定指事先规定好的，与“按……时间开始”相符。", "开心": "搭配：“开心”是心情，不能用来修饰“时间”。", "匆忙": "搭配：“时间”不能用“匆忙”来修饰。", "红色": "搭配：“红色”是颜色，不能用来修饰“时间”。"}, "sentence_index": 0, "correct_answer": "预定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司预定明年利润会增长。", "explanation": "这里应该用〈预计〉。预计指估计、推测，“预定”只表示事先规定或约定，不能用来推测利润。"}, {"text": "专家预定明年经济会好转。", "explanation": "这里应该用〈预测〉。预测指根据已有情况推断未来，“预定”只表示事先规定或安排，不能用来推断经济走势。"}, {"text": "天气预定说明天会下雨。", "explanation": "这里应该用〈预报〉。预报指事先说明天气情况，“预定”不能用来说天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94744, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预定", "is_correct": true, "explanation": "正确：预定指事先安排好的时间，与“比赛预定三点开始”相符。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“结束”与“三点开始”矛盾，比赛不能在开始前结束。"}, {"text": "考虑", "is_correct": false, "explanation": "搭配：“考虑”的主语须是人，比赛不能考虑什么时候开始。"}, {"text": "批评", "is_correct": false, "explanation": "配价：“批评”需要人作宾语，不能说批评三点开始。"}], "explanations": {"预定": "正确：预定指事先安排好的时间，与“比赛预定三点开始”相符。", "结束": "语义：“结束”与“三点开始”矛盾，比赛不能在开始前结束。", "考虑": "搭配：“考虑”的主语须是人，比赛不能考虑什么时候开始。", "批评": "配价：“批评”需要人作宾语，不能说批评三点开始。"}, "sentence_index": 6, "correct_answer": "预定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他预定这次考试会很难。", "explanation": "这里应该用〈估计〉。估计指推测，“预定”只表示事先规定或约定，不能用来推测考试难度。"}, {"text": "这场大雪预定来年是丰收年。", "explanation": "这里应该用〈预示〉。预示指事先显出某种迹象，“预定”不能用来说明兆头或前景。"}, {"text": "老人预定这个国家会发生变化。", "explanation": "这里应该用〈预言〉。预言指预先说出未来会发生的事，“预定”不能用来说未来的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "出差的行程已经预定了好。", "corrected_sentence": "出差的行程已经预定好了。", "error_description": "“好”作结果补语要紧跟动词，应说“预定好了”，不能说“预定了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
