INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94745, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "颁发是把奖状或证书交给得到的人。", "primary_collocate": null, "pronunciation": "bān fā", "ipa": "pan˥ fa˥", "syllable_count": 2, "sentences": [{"text": "校长给获奖的同学颁发了奖状。", "target_word": "颁发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天要颁发毕业证书。", "target_word": "颁发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长在会上给他颁发荣誉证书。", "target_word": "颁发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，大家等着领导颁发奖状。", "target_word": "颁发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校每年六月给学生颁发毕业证。", "target_word": "颁发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理给优秀员工颁发了奖状。", "target_word": "颁发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来给冠军颁发证书？", "target_word": "颁发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，校长为三个同学颁发奖状。", "target_word": "颁发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司向完成培训的人颁发证书。", "target_word": "颁发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下午，学院给学生颁发奖状。", "target_word": "颁发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "頒發", "label": "繁体"}, {"form": "颁发了", "label": "体标"}, {"form": "颁发过", "label": "体标"}], "register": "书面", "sense_fingerprint": "颁发：正式地把奖状、证书交给获得的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab3b97-f3d7-4c95-a0b9-3d6f706e958c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94745, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颁发", "is_correct": true, "explanation": "颁发：正式把奖状交给获奖的人，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物送进嘴里，不能用于奖状。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱奖状”。"}, {"text": "举行", "is_correct": false, "explanation": "配价：“举行”只带一个宾语（如仪式、会议），不能同时接“给同学”和“奖状”。"}], "explanations": {"颁发": "颁发：正式把奖状交给获奖的人，符合句意。", "吃": "语义：“吃”指把食物送进嘴里，不能用于奖状。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱奖状”。", "举行": "配价：“举行”只带一个宾语（如仪式、会议），不能同时接“给同学”和“奖状”。"}, "sentence_index": 0, "correct_answer": "颁发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司每个月都给员工颁发工资。", "explanation": "这里应该用〈发放〉。颁发指正式授予奖状、证书等荣誉，发工资要用发放。"}, {"text": "他把自己的旧书颁发给了弟弟。", "explanation": "这里应该用〈赠送〉。颁发是由机关或组织正式授予，私人之间送书要用赠送。"}, {"text": "老师每天颁发作业给同学。", "explanation": "这里应该用〈发〉。颁发是正式授予，分发作业用发即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94745, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颁发", "is_correct": true, "explanation": "颁发：正式把证书交给获得者，符合句意。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”是用火毁坏东西，不能用来给冠军证书。"}, {"text": "配", "is_correct": false, "explanation": "搭配：“配”多用于钥匙、眼镜等，不说“配证书”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与“给冠军”的赠予意思相反。"}], "explanations": {"颁发": "颁发：正式把证书交给获得者，符合句意。", "烧": "语义：“烧”是用火毁坏东西，不能用来给冠军证书。", "配": "搭配：“配”多用于钥匙、眼镜等，不说“配证书”。", "扔": "语义：“扔”表示丢弃，与“给冠军”的赠予意思相反。"}, "sentence_index": 6, "correct_answer": "颁发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钥匙颁发给了我。", "explanation": "这里应该用〈交〉。颁发指正式授予荣誉、证书，把钥匙递给别人要用交。"}, {"text": "学院每年颁发一次运动会。", "explanation": "这里应该用〈举办〉。颁发指授予证书奖状，运动会要用举办。"}, {"text": "他颁发了一篇论文。", "explanation": "这里应该用〈发表〉。颁发指授予证书奖状，论文要用发表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94745, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校长在会上他颁发了一张奖状。", "corrected_sentence": "校长在会上给他颁发了一张奖状。", "error_description": "配价错误：“颁发”的受奖人要用介词“给”引出，应说“给他颁发”，不能缺少“给”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校把毕业证书颁发了给每位同学。", "corrected_sentence": "学校把毕业证书颁发给了每位同学。", "error_description": "“颁发给”之后的“了”应放在“给”后面，应说“颁发给了”，不能说“颁发了给”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94747, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模糊", "is_correct": true, "explanation": "正确：模糊与高清相反，指图像不清晰、细节看不见。"}, {"text": "悠久", "is_correct": false, "explanation": "悠久形容历史长，与图像清晰程度没有反义关系。"}, {"text": "友好", "is_correct": false, "explanation": "友好形容态度亲切，与高清没有反义关系。"}, {"text": "辛苦", "is_correct": false, "explanation": "辛苦形容劳累，与高清没有反义关系。"}], "correct_answer": "模糊", "explanations": {"模糊": "正确：模糊与高清相反，指图像不清晰、细节看不见。", "悠久": "悠久形容历史长，与图像清晰程度没有反义关系。", "友好": "友好形容态度亲切，与高清没有反义关系。", "辛苦": "辛苦形容劳累，与高清没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
