INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94747, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "高清是图像特别清楚，看得很细。", "primary_collocate": null, "pronunciation": "gāo qīng", "ipa": "kɑʊ̯⁵⁵ tɕʰiŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "高清照片可以看到每一根头发。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张图是高清的，连小字都看得见。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥买了一台高清相机。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏的画面是高清的，特别细。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在网上看了高清的月亮照片。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高清图片放大以后，还是很清楚。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生用高清图像检查他的眼睛。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影的高清画面看得很细。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请给我发一张高清的地图。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台电脑的屏幕是高清的，字很清楚。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "高清图片", "label": "复合"}, {"form": "高清画面", "label": "复合"}], "register": "中性", "sense_fingerprint": "图像特别清楚，细节看得见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b189c5-928f-4b14-9e03-b75e919a5733') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94747, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高清", "is_correct": true, "explanation": "正确：“高清”形容图像清晰、细节可见，与“看到每一根头发”相合。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容物体的质地，照片不能用来形容。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，与照片的清晰程度无关。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容温度，照片不能是寒冷的。"}], "explanations": {"高清": "正确：“高清”形容图像清晰、细节可见，与“看到每一根头发”相合。", "柔软": "搭配：“柔软”形容物体的质地，照片不能用来形容。", "甜": "语义：“甜”形容味道，与照片的清晰程度无关。", "寒冷": "语义：“寒冷”形容温度，照片不能是寒冷的。"}, "sentence_index": 0, "correct_answer": "高清"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位厨师的刀工很高清。", "explanation": "这里应该用〈精细〉。高清只用于图像或屏幕的分辨率，不用于形容刀工。"}, {"text": "这家店的服务很高清。", "explanation": "这里应该用〈周到〉。高清只描述影像或屏幕的清晰度，不用于形容服务。"}, {"text": "他的思路很高清。", "explanation": "这里应该用〈清晰〉。高清只描述影像或屏幕的清晰度，不用于形容思路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94747, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高清", "is_correct": true, "explanation": "正确：“高清”形容图像分辨率高，与“检查眼睛”的语境相合。"}, {"text": "高尚", "is_correct": false, "explanation": "语义：“高尚”形容品德，不能用来形容检查用的图像。"}, {"text": "肥胖", "is_correct": false, "explanation": "体貌：“肥胖”形容人的体形，与图像无关。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”形容态度，不能用来形容图像。"}], "explanations": {"高清": "正确：“高清”形容图像分辨率高，与“检查眼睛”的语境相合。", "高尚": "语义：“高尚”形容品德，不能用来形容检查用的图像。", "肥胖": "体貌：“肥胖”形容人的体形，与图像无关。", "冷淡": "语义：“冷淡”形容态度，不能用来形容图像。"}, "sentence_index": 6, "correct_answer": "高清"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个道理讲得很高清。", "explanation": "这里应该用〈清楚〉。高清只描述画面的分辨率，不用于讲解道理。"}, {"text": "这件衣服的颜色很高清。", "explanation": "这里应该用〈鲜艳〉。高清只用于影像的清晰度，不能用来形容颜色。"}, {"text": "他的性格很高清，大家都喜欢他。", "explanation": "这里应该用〈开朗〉。高清只描述影像或屏幕的清晰度，不用于形容人的性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94747, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台相机拍出的照片得高清。", "corrected_sentence": "这台相机拍出的照片很高清。", "error_description": "错误：“照片得高清”。正确：“照片很高清”。“得”是补语标记，不能用来修饰形容词“高清”，程度副词应用“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94747, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台显微镜把细胞图片拍很得高清。", "corrected_sentence": "这台显微镜把细胞图片拍得很高清。", "error_description": "错误：“拍很得高清”。正确：“拍得很高清”。“得”后面接补语，“很”要放在补语的形容词前，不能放在“得”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94748, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模糊", "is_correct": true, "explanation": "正确：模糊与高清相反，指画面不清楚、细节看不清。"}, {"text": "悠久", "is_correct": false, "explanation": "悠久形容历史长，与画面清晰程度没有反义关系。"}, {"text": "友好", "is_correct": false, "explanation": "友好形容态度亲切，与高清没有反义关系。"}, {"text": "轻松", "is_correct": false, "explanation": "轻松形容不费力，与画面分辨率没有关系。"}], "correct_answer": "模糊", "explanations": {"模糊": "正确：模糊与高清相反，指画面不清楚、细节看不清。", "悠久": "悠久形容历史长，与画面清晰程度没有反义关系。", "友好": "友好形容态度亲切，与高清没有反义关系。", "轻松": "轻松形容不费力，与画面分辨率没有关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94748, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模糊", "is_correct": true, "explanation": "正确：模糊与高清相反，指画面不清楚、细节看不清。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙形容表面不平滑，与高清没有反义关系。"}, {"text": "寂静", "is_correct": false, "explanation": "寂静形容没有声音，与画面清晰程度无关。"}, {"text": "迟钝", "is_correct": false, "explanation": "迟钝形容反应慢，与高清没有反义关系。"}], "correct_answer": "模糊", "explanations": {"模糊": "正确：模糊与高清相反，指画面不清楚、细节看不清。", "粗糙": "粗糙形容表面不平滑，与高清没有反义关系。", "寂静": "寂静形容没有声音，与画面清晰程度无关。", "迟钝": "迟钝形容反应慢，与高清没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94748, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "分辨率很高、画面非常清晰的。", "primary_collocate": null, "pronunciation": "gāo qīng", "ipa": "kɑʊ̯⁵⁵ tɕʰiŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "这台电视是高清的，画面很清楚。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想买一台高清电视。", "target_word": "高清", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这部电影有高清版本，可以在网上看。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的新手机能拍高清视频。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个高清屏幕看起来特别漂亮。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家里的电视不是高清的，画面不太清楚。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个视频太模糊了，有高清的吗？", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用高清摄像机拍出来的照片很好看。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家电影院的屏幕是高清的，很大。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把旧电视换成了高清的。", "target_word": "高清", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高清电视", "label": "复合"}, {"form": "高清视频", "label": "复合"}], "register": "中性", "sense_fingerprint": "分辨率高、画面清晰的影像或设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b189c5-928f-4b14-9e03-b75e919a5733') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94748, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高清", "is_correct": true, "explanation": "正确：“高清”形容画面分辨率高，与“画面很清楚”相合。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容物体的质地，不能用来形容电视。"}, {"text": "老实", "is_correct": false, "explanation": "语义：“老实”形容人的品性，不能用来形容电视。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容温度，与画面清楚的语境无关。"}], "explanations": {"高清": "正确：“高清”形容画面分辨率高，与“画面很清楚”相合。", "柔软": "搭配：“柔软”形容物体的质地，不能用来形容电视。", "老实": "语义：“老实”形容人的品性，不能用来形容电视。", "寒冷": "语义：“寒冷”形容温度，与画面清楚的语境无关。"}, "sentence_index": 0, "correct_answer": "高清"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个答案很高清，大家都听懂了。", "explanation": "这里应该用〈清楚〉。高清只用于图像或屏幕的分辨率，不用于说明或道理。"}, {"text": "他的心地很高清，大家都喜欢他。", "explanation": "这里应该用〈善良〉。高清只描述影像或屏幕的清晰度，不用于形容人的心地。"}, {"text": "这杯茶的味道很高清。", "explanation": "这里应该用〈醇厚〉。高清只描述影像或屏幕的清晰度，不用于形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94748, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高清", "is_correct": true, "explanation": "正确：“高清”与“模糊”相对，询问是否有画面更清晰的版本。"}, {"text": "辛辣", "is_correct": false, "explanation": "语义：“辛辣”形容食物的味道，不能用来形容视频。"}, {"text": "腼腆", "is_correct": false, "explanation": "语义：“腼腆”形容人的性格，与视频无关。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：“沉重”形容分量或心情，不能说视频沉重。"}], "explanations": {"高清": "正确：“高清”与“模糊”相对，询问是否有画面更清晰的版本。", "辛辣": "语义：“辛辣”形容食物的味道，不能用来形容视频。", "腼腆": "语义：“腼腆”形容人的性格，与视频无关。", "沉重": "搭配：“沉重”形容分量或心情，不能说视频沉重。"}, "sentence_index": 6, "correct_answer": "高清"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套家具的做工很高清。", "explanation": "这里应该用〈精致〉。高清只描述画面或屏幕的分辨率，不用于形容做工。"}, {"text": "他听到消息后，心里很高清。", "explanation": "这里应该用〈激动〉。高清只描述影像或屏幕的清晰度，不用于形容人的心情。"}, {"text": "他这次数学考试的成绩很高清。", "explanation": "这里应该用〈好〉。高清只描述影像的清晰程度，不用于形容成绩，成绩好要说“好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94748, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一台很高清电视。", "corrected_sentence": "这是一台很高清的电视。", "error_description": "错误：“很高清电视”。正确：“很高清的电视”。“高清”前面有程度副词“很”修饰时，再修饰名词必须加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94748, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一台高清地电视。", "corrected_sentence": "我买了一台高清的电视。", "error_description": "错误：“高清地电视”。正确：“高清的电视”。“地”用于修饰动词，修饰名词的定语要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
