INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94749, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "abstract", "definition": "一声是叫一下或响一下。", "primary_collocate": null, "pronunciation": "yì shēng", "ipa": "i˥˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "他大叫了一声。", "target_word": "一声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门外响了一声。", "target_word": "一声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗叫了一声就跑了。", "target_word": "一声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机响了一声，又不响了。", "target_word": "一声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听到楼下“砰”地响了一声。", "target_word": "一声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈叫了我一声。", "target_word": "一声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师喊了一声，大家都停下了。", "target_word": "一声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钟响了一声，现在是一点。", "target_word": "一声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫轻轻叫了一声。", "target_word": "一声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他叫了一声，没有回头。", "target_word": "一声", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "叫一下或响一下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df093371-859c-466c-bce4-6c56d378b3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94749, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一声", "is_correct": true, "explanation": "正确：一声指发出一次声音，即叫一下或响一下。"}, {"text": "医生", "is_correct": false, "explanation": "声调不同：yī（第一声）与 yì（第四声）声调不同，意思是医生，不是一声。"}, {"text": "应声", "is_correct": false, "explanation": "韵尾不同：yìng 比 yì 多一个 ng，意思是应答，不是一声。"}, {"text": "一身", "is_correct": false, "explanation": "韵尾不同：shēn 与 shēng 的韵尾分别是 n 与 ng，意思是全身或一套衣服。"}], "explanations": {"一声": "正确：一声指发出一次声音，即叫一下或响一下。", "医生": "声调不同：yī（第一声）与 yì（第四声）声调不同，意思是医生，不是一声。", "应声": "韵尾不同：yìng 比 yì 多一个 ng，意思是应答，不是一声。", "一身": "韵尾不同：shēn 与 shēng 的韵尾分别是 n 与 ng，意思是全身或一套衣服。"}, "sentence_index": null, "correct_answer": "一声"}, "level_3": {"options": [{"text": "一声", "is_correct": true, "explanation": "正确：“大叫了一声”指叫一下，符合语境。"}, {"text": "一支", "is_correct": false, "explanation": "搭配：“支”用于队伍、歌曲等，不计量叫声。"}, {"text": "一片", "is_correct": false, "explanation": "搭配：“片”指成片的景象或区域，不能计量叫声。"}, {"text": "一圈", "is_correct": false, "explanation": "语义：“圈”指环绕一周，与一下叫声不符。"}], "explanations": {"一声": "正确：“大叫了一声”指叫一下，符合语境。", "一支": "搭配：“支”用于队伍、歌曲等，不计量叫声。", "一片": "搭配：“片”指成片的景象或区域，不能计量叫声。", "一圈": "语义：“圈”指环绕一周，与一下叫声不符。"}, "sentence_index": 0, "correct_answer": "一声"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一声都在农村工作。", "explanation": "这里应该用〈一生〉。“一生”指一辈子，“一声”只指发出的一次声音。"}, {"text": "这件事我一声都不知道。", "explanation": "这里应该用〈一点〉。“一点都不知道”表示程度，“一声”不能表示程度。"}, {"text": "我们一声就把问题解决了。", "explanation": "这里应该用〈一下子〉。“一下子”表示很快，“一声”不表示快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94749, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一声", "is_correct": true, "explanation": "正确：“喊了一声”指一次喊叫，符合语境。"}, {"text": "一趟", "is_correct": false, "explanation": "语义：“趟”指一次往返，与一次喊叫不符。"}, {"text": "一盘", "is_correct": false, "explanation": "搭配：“盘”用于棋局、磁带等，不计量喊声。"}, {"text": "一摞", "is_correct": false, "explanation": "搭配：“摞”指堆叠的物品，不计量喊声。"}], "explanations": {"一声": "正确：“喊了一声”指一次喊叫，符合语境。", "一趟": "语义：“趟”指一次往返，与一次喊叫不符。", "一盘": "搭配：“盘”用于棋局、磁带等，不计量喊声。", "一摞": "搭配：“摞”指堆叠的物品，不计量喊声。"}, "sentence_index": 6, "correct_answer": "一声"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我等了一声就走了。", "explanation": "这里应该用〈一会儿〉。“一会儿”表示短时间，“一声”指一次声音，不能计时间。"}, {"text": "这首歌一声很动人。", "explanation": "语义错误：“一声”指一次声音，不能形容歌曲动人；应说“这首歌很动人”。"}, {"text": "这盆花开了一声就谢了。", "explanation": "语义错误：“一声”指发出的一次声音，花开不发出声音，不能用“一声”计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94749, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他轻轻地喊了一个声。", "corrected_sentence": "他轻轻地喊了一声。", "error_description": "量词错误：“声”本身就是量词，直接说“喊了一声”，不能说“一个声”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94749, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "猫叫了一下一声，又跑了。", "corrected_sentence": "猫叫了一声，又跑了。", "error_description": "量词重复：“一下”与“一声”都是计量叫声的量词，只能用其一；应说“叫了一声”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
