INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94751, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "一遍是从头到尾做一次。", "primary_collocate": null, "pronunciation": "yí biàn", "ipa": "i pjɛn", "syllable_count": 2, "sentences": [{"text": "这篇课文太难了，请你再读一遍。", "target_word": "一遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把生词从头到尾抄一遍。", "target_word": "一遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌我只听了一遍，还没学会。", "target_word": "一遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉以前，妈妈把故事讲了一遍。", "target_word": "一遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把今天的作业从头到尾检查一遍。", "target_word": "一遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没看懂，又把信读了一遍。", "target_word": "一遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前，我再看一遍地图。", "target_word": "一遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很短，一个晚上就能读一遍。", "target_word": "一遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先自己试一遍，再给我看。", "target_word": "一遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试以前，我把笔记从头复习了一遍。", "target_word": "一遍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一遍遍", "label": "重叠"}], "register": "中性", "sense_fingerprint": "量词：一件事从头到尾做一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3fe24b8-ed9b-4c4c-b194-80ca274be0f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94751, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一遍", "is_correct": true, "explanation": "正确答案：一遍（yí biàn，“一”变调），表示从头到尾做一次。"}, {"text": "一片", "is_correct": false, "explanation": "piàn 与 biàn 声母不同（p 与 b），声调相同，意思是一片。"}, {"text": "一边", "is_correct": false, "explanation": "biān（第一声）与 biàn（第四声）声调不同，意思是一边。"}, {"text": "一面", "is_correct": false, "explanation": "miàn 与 biàn 声母不同（m 与 b），声调相同，意思是一面。"}, {"text": "一半", "is_correct": false, "explanation": "bàn 比 biàn 少了介音 i，声调相同，意思是一半。"}], "explanations": {"一遍": "正确答案：一遍（yí biàn，“一”变调），表示从头到尾做一次。", "一片": "piàn 与 biàn 声母不同（p 与 b），声调相同，意思是一片。", "一边": "biān（第一声）与 biàn（第四声）声调不同，意思是一边。", "一面": "miàn 与 biàn 声母不同（m 与 b），声调相同，意思是一面。", "一半": "bàn 比 biàn 少了介音 i，声调相同，意思是一半。"}, "sentence_index": null, "correct_answer": "一遍"}, "level_3": {"options": [{"text": "一遍", "is_correct": true, "explanation": "“遍”表示从头到尾做一次，与“再读”搭配，符合句意。"}, {"text": "一张", "is_correct": false, "explanation": "搭配：“张”用于纸张、桌子等平面物，不能计量“读”的动作。"}, {"text": "一首", "is_correct": false, "explanation": "搭配：“首”用于诗歌、歌曲，“课文”不能用“首”计量。"}, {"text": "一把", "is_correct": false, "explanation": "语义：“把”指有柄的东西或一握，与“读”的动作无关。"}], "explanations": {"一遍": "“遍”表示从头到尾做一次，与“再读”搭配，符合句意。", "一张": "搭配：“张”用于纸张、桌子等平面物，不能计量“读”的动作。", "一首": "搭配：“首”用于诗歌、歌曲，“课文”不能用“首”计量。", "一把": "语义：“把”指有柄的东西或一握，与“读”的动作无关。"}, "sentence_index": 0, "correct_answer": "一遍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一共去过三遍医院。", "explanation": "这里应该用〈次〉。去医院这类反复发生的行为用“次”，“遍”强调从头到尾完整做一次。"}, {"text": "我昨天打了一遍喷嚏。", "explanation": "这里应该用〈个〉。打喷嚏是一下子完成的动作，没有“从头到尾”的过程，不能用“一遍”。"}, {"text": "上个月我去了一遍北京。", "explanation": "这里应该用〈趟〉或〈次〉。去某地来回一次用“趟/次”，“遍”强调从头到尾完整做一次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94751, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一遍", "is_correct": true, "explanation": "“遍”表示从头到尾做一次，与“看”搭配，符合句意。"}, {"text": "一把", "is_correct": false, "explanation": "语义：“把”指有柄的东西或一握，不能用来计量“地图”。"}, {"text": "一座", "is_correct": false, "explanation": "搭配：“座”用于山、桥、建筑等，“地图”不能用“座”计量。"}, {"text": "一颗", "is_correct": false, "explanation": "搭配：“颗”用于粒状或球状的东西，“地图”不能用“颗”计量。"}], "explanations": {"一遍": "“遍”表示从头到尾做一次，与“看”搭配，符合句意。", "一把": "语义：“把”指有柄的东西或一握，不能用来计量“地图”。", "一座": "搭配：“座”用于山、桥、建筑等，“地图”不能用“座”计量。", "一颗": "搭配：“颗”用于粒状或球状的东西，“地图”不能用“颗”计量。"}, "sentence_index": 6, "correct_answer": "一遍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天见了他一遍。", "explanation": "这里应该用〈次〉或〈面〉。见人没有“从头到尾”的过程，不能用“一遍”。"}, {"text": "他敲了一遍门，没人开。", "explanation": "这里应该用〈下〉。敲门是短促的动作，用“一下”，不用“一遍”。"}, {"text": "我们一年去一遍医院体检。", "explanation": "这里应该用〈次〉。表示事情发生的次数用“次”，“遍”强调从头到尾完整做一次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94751, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师让我们把笔记抄了一遍遍。", "corrected_sentence": "老师让我们把笔记抄了一遍。", "error_description": "数量词错误：“一遍遍”是表示反复的重叠形式，不能作“抄了”的数量补语，应说“抄了一遍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94751, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把房间又打扫了一遍遍。", "corrected_sentence": "我把房间又打扫了一遍。", "error_description": "数量词错误：“一遍遍”是表示反复的重叠词，不能用在“了”后作数量补语，应只用“一遍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552e5b7a-b4eb-4b55-be64-712c72ccd081') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
