INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94753, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "上次是前一回，不是这一回。", "primary_collocate": null, "pronunciation": "shàng cì", "ipa": "ʂɑŋ˥˩ tsʰɨ˥˩", "syllable_count": 2, "sentences": [{"text": "上次的作业我还没做完。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上次比这次容易多了。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次的菜比上次好吃。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上次是谁请客？", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上次我们去的那家店关门了。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起上次，他这次进步很大。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试比上次难。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上次是他赢，这次是我赢。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上次的错误，这次不要再犯。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上次开会，大家都迟到了。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "上次：前一回，与这一回相对比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b6ab932-ffa3-44f3-be69-23e97a6cbed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94753, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上次", "is_correct": true, "explanation": "正确答案。上次指这一回之前的那一次，与句中“前一回”的意思相符。"}, {"text": "上菜", "is_correct": false, "explanation": "shàng cài 与 shàng cì 只有韵母不同（ai 与 i），意思是端上菜，不是前一回。"}, {"text": "上市", "is_correct": false, "explanation": "shì 与 cì 声母不同（sh 与 c），意思是产品投放市场，不是前一回。"}, {"text": "上策", "is_correct": false, "explanation": "cè 与 cì 韵母不同（e 与 i），意思是高明的办法，不是前一回。"}, {"text": "上册", "is_correct": false, "explanation": "cè 与 cì 韵母不同（e 与 i），意思是书的上一册，不是前一回。"}], "explanations": {"上次": "正确答案。上次指这一回之前的那一次，与句中“前一回”的意思相符。", "上菜": "shàng cài 与 shàng cì 只有韵母不同（ai 与 i），意思是端上菜，不是前一回。", "上市": "shì 与 cì 声母不同（sh 与 c），意思是产品投放市场，不是前一回。", "上策": "cè 与 cì 韵母不同（e 与 i），意思是高明的办法，不是前一回。", "上册": "cè 与 cì 韵母不同（e 与 i），意思是书的上一册，不是前一回。"}, "sentence_index": null, "correct_answer": "上次"}, "level_3": {"options": [{"text": "上次", "is_correct": true, "explanation": "正确答案。「上次的作业」指前一回布置的作业，与“还没做完”相合。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“礼物的作业”说不通，作业不能由礼物修饰。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭与作业没有领属关系，句子不成立。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不能布置或完成作业，句子不通。"}], "explanations": {"上次": "正确答案。「上次的作业」指前一回布置的作业，与“还没做完”相合。", "礼物": "搭配：“礼物的作业”说不通，作业不能由礼物修饰。", "午饭": "语义：午饭与作业没有领属关系，句子不成立。", "花园": "语义：花园不能布置或完成作业，句子不通。"}, "sentence_index": 0, "correct_answer": "上次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事我们上次再谈吧。", "explanation": "这里应该用〈以后〉。上次指已经过去的那一回，不能用于将来的安排；将来的事要用〈以后〉。"}, {"text": "我们上次经常一起吃饭。", "explanation": "这里应该用〈以前〉。上次只指前一回，不能表示经常性的过去；经常性的过去要用〈以前〉。"}, {"text": "我们上次一起去爬山吧。", "explanation": "这里应该用〈下次〉。上次指过去，提议一起去做某事要用〈下次〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94753, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上次", "is_correct": true, "explanation": "正确答案。“比上次难”与前一次考试比较，符合句意。"}, {"text": "食堂", "is_correct": false, "explanation": "搭配：比较的双方应是可以比难度的对象，“考试”不能与地点比较。"}, {"text": "电影", "is_correct": false, "explanation": "语义：考试和电影不能比难度，句子不通。"}, {"text": "草地", "is_correct": false, "explanation": "语义：草地没有难易之分，不能与考试比较。"}], "explanations": {"上次": "正确答案。“比上次难”与前一次考试比较，符合句意。", "食堂": "搭配：比较的双方应是可以比难度的对象，“考试”不能与地点比较。", "电影": "语义：考试和电影不能比难度，句子不通。", "草地": "语义：草地没有难易之分，不能与考试比较。"}, "sentence_index": 6, "correct_answer": "上次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上次我们每周都见面。", "explanation": "这里应该用〈以前〉。上次只指前一回，不能与“每周都”表示多次的情况连用；表示过去经常的情况要用〈以前〉。"}, {"text": "上次我们再一起去旅行吧。", "explanation": "这里应该用〈将来〉。上次指已经过去的那一回，提议将来要做的事不能用“上次”。"}, {"text": "上次我们经常打电话。", "explanation": "这里应该用〈最近〉。上次只指一回，不能表示经常性的动作；经常性的动作要用〈最近〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94753, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们上次的见面了。", "corrected_sentence": "我们上次见面了。", "error_description": "错误：“上次的”把“见面”变成名词性短语，句中“见面了”失去谓语位置，句子不通。正确形式是“我们上次见面了”，“上次”直接作状语，不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94753, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次我没迟到，上次我迟到着。", "corrected_sentence": "这次我没迟到，上次我迟到了。", "error_description": "错误：“上次”指过去已完成的一次，动词后应用“了”表示完成；用“着”表示持续状态，与“迟到”这一次性事件不符。正确形式是“上次我迟到了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
