INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94754, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "紧挨着这一次之前的那一次。", "primary_collocate": null, "pronunciation": "shàng cì", "ipa": "ʂɑŋ˥˩ tsʰɨ˥˩", "syllable_count": 2, "sentences": [{"text": "上次见面，你还是短头发。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上次你说的那本书，我买到了。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上次来这儿，还是去年冬天。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我上次来的时候，这里没有地铁。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上次的会议在三楼开的。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上次给我打电话，是上周五。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上次你生病，现在好了吗？", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上次我忘了带伞，这次带了。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师上次说过，明天要考试。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上次吃火锅，我们一起去了那家店。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "上次：紧靠现在之前的那一次，用来回忆过去的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b6ab932-ffa3-44f3-be69-23e97a6cbed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94754, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上次", "is_correct": true, "explanation": "正确答案。上次指紧挨着这一次之前的那一次。"}, {"text": "上菜", "is_correct": false, "explanation": "shàng cài 与 shàng cì 只有韵母不同（ai 与 i），意思是端上菜，不是前一次。"}, {"text": "上市", "is_correct": false, "explanation": "shì 与 cì 声母不同（sh 与 c），意思是产品投放市场，不是前一次。"}, {"text": "上策", "is_correct": false, "explanation": "cè 与 cì 韵母不同（e 与 i），意思是高明的办法，不是前一次。"}, {"text": "上册", "is_correct": false, "explanation": "cè 与 cì 韵母不同（e 与 i），意思是书的上一册，不是前一次。"}], "explanations": {"上次": "正确答案。上次指紧挨着这一次之前的那一次。", "上菜": "shàng cài 与 shàng cì 只有韵母不同（ai 与 i），意思是端上菜，不是前一次。", "上市": "shì 与 cì 声母不同（sh 与 c），意思是产品投放市场，不是前一次。", "上策": "cè 与 cì 韵母不同（e 与 i），意思是高明的办法，不是前一次。", "上册": "cè 与 cì 韵母不同（e 与 i），意思是书的上一册，不是前一次。"}, "sentence_index": null, "correct_answer": "上次"}, "level_3": {"options": [{"text": "上次", "is_correct": true, "explanation": "正确答案。“上次见面”指前一次见面，与“还是短头发”的过去到现在对比相合。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“礼物”不是时间词，不能作“见面”的时间状语，句子不通。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“书包”不是时间词，不能作“见面”的时间状语，句子不通。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：电影不能作为见面的时间状语，“电影见面”句子不通。"}], "explanations": {"上次": "正确答案。“上次见面”指前一次见面，与“还是短头发”的过去到现在对比相合。", "礼物": "搭配：“礼物”不是时间词，不能作“见面”的时间状语，句子不通。", "书包": "搭配：“书包”不是时间词，不能作“见面”的时间状语，句子不通。", "电影": "搭配：电影不能作为见面的时间状语，“电影见面”句子不通。"}, "sentence_index": 0, "correct_answer": "上次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们上次经常来这里吃饭。", "explanation": "这里应该用〈以前〉。上次只指一次，不能表示经常性的过去。"}, {"text": "你上次想来就来吧。", "explanation": "这里应该用〈随时〉。上次指紧挨着这一次之前的那一次，不能表示任何一次都可以；表示随便哪次都行要用〈随时〉。"}, {"text": "上次再来这里的时候，要记得带伞。", "explanation": "这里应该用〈以后〉。上次指过去，提醒将来要做的事应该用〈以后〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上次", "is_correct": true, "explanation": "正确答案。“上次你生病，现在好了吗”指过去的一次生病，与“现在好了吗”相合。"}, {"text": "下次", "is_correct": false, "explanation": "语义：“下次”指将来，与“现在好了吗”的现在时矛盾。"}, {"text": "将来", "is_correct": false, "explanation": "语义：“将来”指未来，与“现在好了”的现在状态矛盾。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“午饭你生病”不成立，餐时不能作为生病的时间状语。"}], "explanations": {"上次": "正确答案。“上次你生病，现在好了吗”指过去的一次生病，与“现在好了吗”相合。", "下次": "语义：“下次”指将来，与“现在好了吗”的现在时矛盾。", "将来": "语义：“将来”指未来，与“现在好了”的现在状态矛盾。", "午饭": "搭配：“午饭你生病”不成立，餐时不能作为生病的时间状语。"}, "sentence_index": 6, "correct_answer": "上次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上次吃火锅，我们每次都去那家店。", "explanation": "这里应该用〈以前〉。上次只指一次，不能用于表示多次的情况；表示多次要用〈以前〉。"}, {"text": "上次吃火锅，我们一起去那家店吧。", "explanation": "这里应该用〈明天〉。上次指过去，提议要去做的事应该用〈明天〉。"}, {"text": "上次吃火锅，我们下个月去那家店。", "explanation": "这里应该用〈下次〉。上次指已经过去的那一次，不能与“下个月”这样的将来时间连用；将来的时间要用〈下次〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我上次给你发着消息。", "corrected_sentence": "我上次给你发了消息。", "error_description": "错误：“发消息”是一次完成的动作，应用“了”表示完成；用“着”表示持续，与“上次”指过去的一次不合。正确形式是“我上次给你发了消息”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们上次的一起吃了饭。", "corrected_sentence": "我们上次一起吃了饭。", "error_description": "错误：在时间词“上次”后加“的”，使它变成定语修饰后面的“一起”，句子结构不通。正确形式是“我们上次一起吃了饭”，“上次”直接作状语，不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94755, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "愿意", "is_correct": true, "explanation": "反义：“愿意”表示心里愿意去做，与“不愿”正相反。"}, {"text": "吃", "is_correct": false, "explanation": "无关：“吃”是进食动作，与“不愿”的心愿义不构成反义。"}, {"text": "跑", "is_correct": false, "explanation": "无关：“跑”是移动动作，与“不愿”的心愿义不构成反义。"}, {"text": "唱", "is_correct": false, "explanation": "无关：“唱”是发声动作，与“不愿”的心愿义不构成反义。"}], "correct_answer": "愿意", "explanations": {"愿意": "反义：“愿意”表示心里愿意去做，与“不愿”正相反。", "吃": "无关：“吃”是进食动作，与“不愿”的心愿义不构成反义。", "跑": "无关：“跑”是移动动作，与“不愿”的心愿义不构成反义。", "唱": "无关：“唱”是发声动作，与“不愿”的心愿义不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94755, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "愿意", "is_correct": true, "explanation": "反义：“愿意”表示心里愿意去做，与“不愿”正相反。"}, {"text": "读", "is_correct": false, "explanation": "无关：“读”是阅读动作，与“不愿”的心愿义不构成反义。"}, {"text": "走", "is_correct": false, "explanation": "无关：“走”是移动动作，与“不愿”的心愿义不构成反义。"}, {"text": "写", "is_correct": false, "explanation": "无关：“写”是书写动作，与“不愿”的心愿义不构成反义。"}], "correct_answer": "愿意", "explanations": {"愿意": "反义：“愿意”表示心里愿意去做，与“不愿”正相反。", "读": "无关：“读”是阅读动作，与“不愿”的心愿义不构成反义。", "走": "无关：“走”是移动动作，与“不愿”的心愿义不构成反义。", "写": "无关：“写”是书写动作，与“不愿”的心愿义不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94755, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不愿是心里不想去做。", "primary_collocate": null, "pronunciation": "bú yuàn", "ipa": "pu˧˥ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他不愿去医院看病。", "target_word": "不愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不愿起床，因为外面很冷。", "target_word": "不愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不愿说话，只想一个人坐着。", "target_word": "不愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不愿吃药，觉得药太苦。", "target_word": "不愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟不愿跟我们一起去公园。", "target_word": "不愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不愿再提那件难过的事。", "target_word": "不愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人不愿离开住了五十年的老房子。", "target_word": "不愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不愿让妈妈担心，所以没告诉她。", "target_word": "不愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太热，大家都不愿出门。", "target_word": "不愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不愿把秘密告诉别人。", "target_word": "不愿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不願", "label": "繁体"}], "register": "中性", "sense_fingerprint": "心里不想去做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4d8750f-33e3-4d0a-afc2-fdce50ccbd55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94755, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不愿", "is_correct": true, "explanation": "正确：“不愿”表示心里不想去做某事，符合“他……去医院看病”的语境。"}, {"text": "甘", "is_correct": false, "explanation": "语域：“甘”单独作动词多见于文言，不符合现代口语的表达习惯。"}, {"text": "乐", "is_correct": false, "explanation": "语域：“乐”作动词多见于文言或固定搭配，直接带动词短语不自然。"}, {"text": "饿", "is_correct": false, "explanation": "语法：“饿”是形容词，不能直接带“去医院看病”这样的动词短语，句子不成立。"}], "explanations": {"不愿": "正确：“不愿”表示心里不想去做某事，符合“他……去医院看病”的语境。", "甘": "语域：“甘”单独作动词多见于文言，不符合现代口语的表达习惯。", "乐": "语域：“乐”作动词多见于文言或固定搭配，直接带动词短语不自然。", "饿": "语法：“饿”是形容词，不能直接带“去医院看病”这样的动词短语，句子不成立。"}, "sentence_index": 0, "correct_answer": "不愿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不愿会游泳，所以没去海边。", "explanation": "这里应该用〈不会〉。“不愿”表示心里不想做某事，不能修饰“会”这种能力，说不会游泳要用“不会”。"}, {"text": "他不愿打雷。", "explanation": "这里应该用〈害怕〉。“不愿”只用于人能主动决定的意愿，“打雷”不是人能决定的，怕打雷要说“害怕”。"}, {"text": "外面下雨了，天不愿晴。", "explanation": "这里应该用〈没有〉。“不愿”只用于有意愿的人，天气不能“不愿”，应说“天没有晴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94755, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不愿", "is_correct": true, "explanation": "正确：“不愿”表示心里不想离开住了很久的老房子，符合句意。"}, {"text": "冷", "is_correct": false, "explanation": "语法：“冷”是形容词，不能直接带“离开……老房子”这样的动词短语，句子不成立。"}, {"text": "赶", "is_correct": false, "explanation": "语法：“赶”不能直接带“离开住了五十年的老房子”这样的动词短语，句子不成立。"}, {"text": "忍", "is_correct": false, "explanation": "语义：“忍”表示克制，与“离开住了五十年的老房子”的情感语境不合。"}], "explanations": {"不愿": "正确：“不愿”表示心里不想离开住了很久的老房子，符合句意。", "冷": "语法：“冷”是形容词，不能直接带“离开……老房子”这样的动词短语，句子不成立。", "赶": "语法：“赶”不能直接带“离开住了五十年的老房子”这样的动词短语，句子不成立。", "忍": "语义：“忍”表示克制，与“离开住了五十年的老房子”的情感语境不合。"}, "sentence_index": 6, "correct_answer": "不愿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她有不愿，所以不去。", "explanation": "这里应该用〈不想去〉。“不愿”是动词，表示心里不想做某事，不能作名词“有”的宾语。"}, {"text": "他很不愿聪明。", "explanation": "这里应该用〈不想〉。“不愿”只能表示心里不想去做某件事，不能用来修饰“聪明”这类性质。"}, {"text": "他的不愿是音乐。", "explanation": "这里应该用〈爱好〉。“不愿”是动词，不能作名词，不能用“的不愿是……”来说明事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94755, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她不愿钥匙交给我。", "corrected_sentence": "她不愿把钥匙交给我。", "error_description": "语法错误：“不愿”后直接接名词“钥匙”，缺少“把”字，应说“她不愿把钥匙交给我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94755, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把不愿借书给别人。", "corrected_sentence": "他不愿借书给别人。", "error_description": "把字错误：“把”字后面要接名词性宾语，“不愿”是动词，不能放在“把”后面。应去掉“把”，说“他不愿借书给别人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
