INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94757, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94757, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "任意是想怎么样就怎么样，没有人管。", "primary_collocate": null, "pronunciation": "rèn yì", "ipa": "ɻən˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们在草地上任意玩耍。", "target_word": "任意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别任意扔垃圾。", "target_word": "任意", "complexity_tier": "T3", "furigana": "bié rèn yì rēng lā jī", "sentence_source": "generated"}, {"text": "他任意花钱，从来不管家里。", "target_word": "任意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不能任意改别人的东西。", "target_word": "任意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不在，学生们任意说话。", "target_word": "任意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他任意把书扔在地上。", "target_word": "任意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里不能任意摘花。", "target_word": "任意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫在家里任意跑来跑去。", "target_word": "任意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她任意发脾气，没有人敢说话。", "target_word": "任意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有规定，大家就任意停车。", "target_word": "任意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "任意：不管规矩，想怎么做就怎么做（随意妄为）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b6ab932-ffa3-44f3-be69-23e97a6cbed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94757, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "任意", "is_correct": true, "explanation": "正确答案。“任意玩耍”指不受约束地玩，与句意相合。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”是介词，后面须接处置对象和动作，“把玩耍”不成立。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”要与否定词连用，“根本玩耍”不成立。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”表被动，需有施事或受事的完整结构，“被玩耍”不成立。"}], "explanations": {"任意": "正确答案。“任意玩耍”指不受约束地玩，与句意相合。", "把": "语法：“把”是介词，后面须接处置对象和动作，“把玩耍”不成立。", "根本": "搭配：“根本”要与否定词连用，“根本玩耍”不成立。", "被": "语法：“被”表被动，需有施事或受事的完整结构，“被玩耍”不成立。"}, "sentence_index": 0, "correct_answer": "任意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他任意就解出了这道难题。", "explanation": "这里应该用〈轻易〉。任意表示想怎样就怎样、不受约束，不表示做事不费力；“不费力”要用〈轻易〉。"}, {"text": "他任意考上了大学，大家都很惊讶。", "explanation": "这里应该用〈居然〉。任意表示想怎样就怎样，不表示出乎意料；“出乎意料”要用〈居然〉。"}, {"text": "她任意地努力，成绩越来越好。", "explanation": "这里应该用〈拼命〉。任意表示不受约束，不表示程度很高；“程度很高”要用〈拼命〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94757, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "任意", "is_correct": true, "explanation": "正确答案。“不能任意摘花”指不能随意摘花，符合句意。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：“已经”表示已经完成，与“不能”的禁止语境不符。"}, {"text": "必定", "is_correct": false, "explanation": "语义：“必定”表示一定，与“不能摘花”的禁止语境相矛盾。"}, {"text": "大概", "is_correct": false, "explanation": "语义：“大概”表示估计，不能用于禁止句，句子不通。"}], "explanations": {"任意": "正确答案。“不能任意摘花”指不能随意摘花，符合句意。", "已经": "搭配：“已经”表示已经完成，与“不能”的禁止语境不符。", "必定": "语义：“必定”表示一定，与“不能摘花”的禁止语境相矛盾。", "大概": "语义：“大概”表示估计，不能用于禁止句，句子不通。"}, "sentence_index": 6, "correct_answer": "任意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们必须任意遵守纪律。", "explanation": "这里应该用〈认真〉。任意表示想怎样就怎样、不受约束，与“必须遵守”的要求矛盾；表示按要求去做要用〈认真〉。"}, {"text": "大家应该按照规定，任意排队。", "explanation": "这里应该用〈依次〉。任意表示不受约束，与“按照规定”的要求矛盾；表示有秩序地一个接一个要用〈依次〉。"}, {"text": "这次考试要求大家任意保持安静。", "explanation": "这里应该用〈始终〉。任意表示不受约束，与“要求”的限制矛盾；表示持续不变要用〈始终〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94757, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很任意说了几句，就走了。", "corrected_sentence": "他任意说了几句，就走了。", "error_description": "错误：“任意”表示不受约束、想怎样就怎样，本身不能再受程度副词“很”修饰。正确形式是“他任意说了几句”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94757, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生们不能任意的离开教室。", "corrected_sentence": "学生们不能任意离开教室。", "error_description": "错误：“任意”是副词，后面加“的”会变成定语，无法直接修饰动词“离开”，句子不通。正确形式是“不能任意离开教室”，“任意”直接作状语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
