INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94758, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不受限制，随着自己的意愿。", "primary_collocate": null, "pronunciation": "rèn yì", "ipa": "ɻən˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "你可以任意选一本书。", "target_word": "任意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在这些颜色中任意选择一种。", "target_word": "任意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间很大，你可以任意选座位。", "target_word": "任意", "complexity_tier": "T3", "furigana": "fáng jiān hěn dà nǐ kě yǐ rèn yì xuǎn zuò wèi", "sentence_source": "generated"}, {"text": "这些水果，你可以任意挑选。", "target_word": "任意", "complexity_tier": "T3", "furigana": "zhè xiē shuǐ guǒ nǐ kě yǐ rèn yì tiāo xuǎn", "sentence_source": "generated"}, {"text": "我们可以任意安排时间。", "target_word": "任意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门票免费，大家任意进出。", "target_word": "任意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从一到十，任意写一个数字。", "target_word": "任意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜单上的套餐，你可以任意搭配。", "target_word": "任意", "complexity_tier": "T3", "furigana": "cài dān shàng de tào cān nǐ kě yǐ rèn yì dā pèi", "sentence_source": "generated"}, {"text": "你想住哪间房，就任意选一间吧。", "target_word": "任意", "complexity_tier": "T3", "furigana": "nǐ xiǎng zhù nǎ jiān fáng jiù rèn yì xuǎn yī jiān ba", "sentence_source": "generated"}, {"text": "在这里，你可以任意提出问题。", "target_word": "任意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "任意：没有限制，按自己的想法选择、行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b6ab932-ffa3-44f3-be69-23e97a6cbed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94758, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "任意", "is_correct": true, "explanation": "正确答案。“任意选一本书”指按自己的想法挑选，符合句意。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”要与否定词连用，“根本选一本书”不成立。"}, {"text": "只好", "is_correct": false, "explanation": "语义：“只好”表示别无选择，与“可以”所表达的自由选择矛盾，句子不通。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”需先接处置对象再接动词，“把选一本书”语序不成立。"}], "explanations": {"任意": "正确答案。“任意选一本书”指按自己的想法挑选，符合句意。", "根本": "搭配：“根本”要与否定词连用，“根本选一本书”不成立。", "只好": "语义：“只好”表示别无选择，与“可以”所表达的自由选择矛盾，句子不通。", "把": "语法：“把”需先接处置对象再接动词，“把选一本书”语序不成立。"}, "sentence_index": 0, "correct_answer": "任意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他任意地看见了一只小鸟。", "explanation": "这里应该用〈意外地〉。任意表示随着自己的意愿挑选，“看见”不是自己能选择的事；无意中遇到要用〈意外地〉。"}, {"text": "这份考卷的答案是统一的，你可以任意挑选。", "explanation": "这里应该用〈只能〉。任意表示可以按自己的意愿挑选，与“答案是统一的”的限制矛盾；只有一种选择时要用〈只能〉。"}, {"text": "他任意地读完了这本厚书，只用了十分钟。", "explanation": "这里应该用〈飞快地〉。任意表示随着自己的意愿挑选，不表示速度快；速度快要用〈飞快地〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "任意", "is_correct": true, "explanation": "正确答案。“从一到十，任意写一个数字”指随意选择一个数字，符合句意。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：“已经”表示已经完成，与“从一到十，写一个数字”的要求不符。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”表被动，需有受事或施事的完整结构，“被写一个数字”在此句不成立。"}, {"text": "的", "is_correct": false, "explanation": "语法：结构助词“的”不能独立充当状语，“的写一个数字”不成立。"}], "explanations": {"任意": "正确答案。“从一到十，任意写一个数字”指随意选择一个数字，符合句意。", "已经": "搭配：“已经”表示已经完成，与“从一到十，写一个数字”的要求不符。", "被": "语法：“被”表被动，需有受事或施事的完整结构，“被写一个数字”在此句不成立。", "的": "语法：结构助词“的”不能独立充当状语，“的写一个数字”不成立。"}, "sentence_index": 6, "correct_answer": "任意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要按照规定，任意提出问题。", "explanation": "这里应该用〈有序地〉。任意表示不受限制，与“按照规定”的要求矛盾；表示按秩序进行要用〈有序地〉。"}, {"text": "这是老师的命令，学生们必须任意遵守。", "explanation": "这里应该用〈认真〉。任意表示不受限制，与“必须遵守”的要求矛盾；表示按要求去做要用〈认真〉。"}, {"text": "他任意地摔倒了，爬起来继续走。", "explanation": "这里应该用〈不小心〉。任意表示随着自己的意愿挑选，“摔倒”不是自己选择的事；无意发生要用〈不小心〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94758, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里不可以很任意拍照。", "corrected_sentence": "这里不可以任意拍照。", "error_description": "错误：“任意”表示想怎样就怎样，不能受程度副词“很”修饰，“很任意”不成立。正确形式是“这里不可以任意拍照”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94758, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们可以任意的搭配这些衣服。", "corrected_sentence": "我们可以任意搭配这些衣服。", "error_description": "错误：“任意”是副词，后加“的”会变成定语，无法直接修饰动词“搭配”，句子不通。正确形式是“可以任意搭配这些衣服”，“任意”作状语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
