INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94759, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "来路是人或东西从哪里来的路。", "primary_collocate": null, "pronunciation": "lái lù", "ipa": "lai̯˧˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "来路上有一棵很大的树。", "target_word": "来路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们顺着来路慢慢走回村子。", "target_word": "来路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了一夜雨，来路变得很难走。", "target_word": "来路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在路口，望着来路等朋友。", "target_word": "来路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来路和去路都是这条河边的小路。", "target_word": "来路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我记得来路，不会迷路的。", "target_word": "来路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走了很远，他又回头看来路。", "target_word": "来路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太黑，我们找不到来路了。", "target_word": "来路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥正好在我们的来路上。", "target_word": "来路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪把来路盖住了，他们只好等天亮。", "target_word": "来路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "來路", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人或东西来时走的那条路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c832532e-8599-453c-a65b-bf3d6cc2a2e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94759, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "来路", "is_correct": true, "explanation": "正确：“来路上”指来时的那条路上，有一棵树是合理的。"}, {"text": "信心", "is_correct": false, "explanation": "语义：信心不是一个地方，上面不可能长着一棵树。"}, {"text": "笑声", "is_correct": false, "explanation": "语义：笑声不是位置，“笑声上有一棵树”说不通。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不是位置，“心情上有一棵树”没有意义。"}], "explanations": {"来路": "正确：“来路上”指来时的那条路上，有一棵树是合理的。", "信心": "语义：信心不是一个地方，上面不可能长着一棵树。", "笑声": "语义：笑声不是位置，“笑声上有一棵树”说不通。", "心情": "语义：心情不是位置，“心情上有一棵树”没有意义。"}, "sentence_index": 0, "correct_answer": "来路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他已经规划好了去山顶的来路。", "explanation": "这里应该用〈路线〉。“来路”指已经走过的路，不能用来规划将要走的路线。"}, {"text": "一只狗突然跳出来，咬伤了他的来路。", "explanation": "这里应该用〈腿〉。“来路”指道路，不是身体部位，不能被咬伤。"}, {"text": "他把来路摆在了客厅里。", "explanation": "这里应该用〈物品〉。“来路”指道路，不是物品，不能摆在客厅里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cd7f24c-5159-466b-8e24-be195f5be339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94759, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "来路", "is_correct": true, "explanation": "正确：“回头看”的对象是他走过的路，来路正合适。"}, {"text": "味道", "is_correct": false, "explanation": "语义：走了很远，“回头看味道”说不通。"}, {"text": "饥饿", "is_correct": false, "explanation": "语义：饥饿是感觉，不是可以回头去看的东西。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是走过的路，“回头看年龄”在这里说不通。"}], "explanations": {"来路": "正确：“回头看”的对象是他走过的路，来路正合适。", "味道": "语义：走了很远，“回头看味道”说不通。", "饥饿": "语义：饥饿是感觉，不是可以回头去看的东西。", "年龄": "语义：年龄不是走过的路，“回头看年龄”在这里说不通。"}, "sentence_index": 6, "correct_answer": "来路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一个来路在前面等着他。", "explanation": "这里应该用〈来人〉。“来路”指道路或来源，不指人，不能用来指站在前面等他的人。"}, {"text": "他推开来路，走进了房间。", "explanation": "这里应该用〈门〉。“来路”指道路，不能被推开，推开的应是门。"}, {"text": "他把来路装进了行李箱。", "explanation": "这里应该用〈东西〉。“来路”是道路，不是可以装进行李箱的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cd7f24c-5159-466b-8e24-be195f5be339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94759, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他顺着那位来路找到了那只狗。", "corrected_sentence": "他顺着那条来路找到了那只狗。", "error_description": "量词错误：“来路”指道路，应该用“条”计量；“位”用于人，这里用“位”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cd7f24c-5159-466b-8e24-be195f5be339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94759, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大雨冲坏了我们来路。", "corrected_sentence": "大雨冲坏了我们的来路。", "error_description": "漏用“的”：“我们”修饰“来路”时要用“的”，应说“我们的来路”，不能省去“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cd7f24c-5159-466b-8e24-be195f5be339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94761, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平庸", "is_correct": true, "explanation": "正确：“平庸”指一般、没有特别出色，与“杰出”（比别人都好很多）相反。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、不模糊，与“杰出”的出众程度无关，不是反义词。"}, {"text": "温暖", "is_correct": false, "explanation": "“温暖”形容温度或感情，与“杰出”的水平高低不构成反义。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”与“吵闹”相对，不是“杰出”的反义词。"}], "correct_answer": "平庸", "explanations": {"平庸": "正确：“平庸”指一般、没有特别出色，与“杰出”（比别人都好很多）相反。", "清楚": "“清楚”形容明白、不模糊，与“杰出”的出众程度无关，不是反义词。", "温暖": "“温暖”形容温度或感情，与“杰出”的水平高低不构成反义。", "安静": "“安静”与“吵闹”相对，不是“杰出”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94761, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平庸", "is_correct": true, "explanation": "正确：“平庸”指没有特别出色的表现，与“杰出”相反。"}, {"text": "寒冷", "is_correct": false, "explanation": "“寒冷”形容温度，与“杰出”无反义关系。"}, {"text": "丰富", "is_correct": false, "explanation": "“丰富”指种类多、数量大，与“杰出”的出众程度不构成反义。"}, {"text": "狭窄", "is_correct": false, "explanation": "“狭窄”形容空间小，与“杰出”无关，不是反义词。"}], "correct_answer": "平庸", "explanations": {"平庸": "正确：“平庸”指没有特别出色的表现，与“杰出”相反。", "寒冷": "“寒冷”形容温度，与“杰出”无反义关系。", "丰富": "“丰富”指种类多、数量大，与“杰出”的出众程度不构成反义。", "狭窄": "“狭窄”形容空间小，与“杰出”无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94761, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "杰出是比别人都好很多，很了不起。", "primary_collocate": null, "pronunciation": "jié chū", "ipa": "tɕjɛ˧˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "这次比赛，他的表现非常杰出，大家都鼓掌。", "target_word": "杰出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的成绩杰出，每门课都是第一名。", "target_word": "杰出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司去年的业绩很杰出，赚了很多钱。", "target_word": "杰出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位画家的作品十分杰出，令人赞叹。", "target_word": "杰出", "complexity_tier": "T3", "furigana": "zhè wèi huà jiā de zuò pǐn shí fēn jié chū, lìng rén zàn tàn.", "sentence_source": "generated"}, {"text": "他在比赛中的水平很杰出，超过了所有对手。", "target_word": "杰出", "complexity_tier": "T3", "furigana": "tā zài bǐ sài zhōng de shuǐ píng hěn jié chū, chāo guò le suǒ yǒu duì shǒu.", "sentence_source": "generated"}, {"text": "这部电影的音乐非常杰出，让人难忘。", "target_word": "杰出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说你的作文结构很杰出，是全班最好的。", "target_word": "杰出", "complexity_tier": "T3", "furigana": "lǎo shī shuō nǐ de zuò wén jié gòu hěn jié chū, shì quán bān zuì hǎo de.", "sentence_source": "generated"}, {"text": "这个队的防守很杰出，对手一个球也没进。", "target_word": "杰出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的设计杰出，评委们都觉得了不起。", "target_word": "杰出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为表现杰出，这个学生得了大奖。", "target_word": "杰出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "傑出", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "表现、成绩、作品等比别人好很多，很了不起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccaa5f06-74fd-450d-9e5c-c87f845eb06a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94761, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "杰出", "is_correct": true, "explanation": "正确：杰出（jié chū），比别人都好很多，很了不起。"}, {"text": "决出", "is_correct": false, "explanation": "jué（第二声）与 jié（第二声）韵母不同（üe 与 ie），意思是“经过比较定出结果”，如“决出冠军”。"}, {"text": "解出", "is_correct": false, "explanation": "jiě（第三声）与 jié（第二声）声调不同，意思是“解答得出”，如“解出题目”。"}, {"text": "借出", "is_correct": false, "explanation": "jiè（第四声）与 jié（第二声）声调不同，意思是“把东西借给别人”，如“借出图书”。"}], "explanations": {"杰出": "正确：杰出（jié chū），比别人都好很多，很了不起。", "决出": "jué（第二声）与 jié（第二声）韵母不同（üe 与 ie），意思是“经过比较定出结果”，如“决出冠军”。", "解出": "jiě（第三声）与 jié（第二声）声调不同，意思是“解答得出”，如“解出题目”。", "借出": "jiè（第四声）与 jié（第二声）声调不同，意思是“把东西借给别人”，如“借出图书”。"}, "sentence_index": null, "correct_answer": "杰出"}, "level_3": {"options": [{"text": "杰出", "is_correct": true, "explanation": "正确：“杰出”形容表现特别出众，与“大家都鼓掌”的赞扬相符。"}, {"text": "平庸", "is_correct": false, "explanation": "语义：“平庸”指一般、没有特色，表现平庸就不会有人鼓掌，与后句矛盾。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容质地或性情，不用来形容比赛中的表现。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”描述人的身材，不能用来形容表现。"}], "explanations": {"杰出": "正确：“杰出”形容表现特别出众，与“大家都鼓掌”的赞扬相符。", "平庸": "语义：“平庸”指一般、没有特色，表现平庸就不会有人鼓掌，与后句矛盾。", "柔软": "搭配：“柔软”形容质地或性情，不用来形容比赛中的表现。", "瘦小": "体貌：“瘦小”描述人的身材，不能用来形容表现。"}, "sentence_index": 0, "correct_answer": "杰出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个周末的天气很杰出，我们去公园散步吧。", "explanation": "这里应该用〈好〉。杰出 说人的才能、成就或作品特别出众，不用来形容天气。"}, {"text": "这碗面的味道很杰出，我吃了两碗。", "explanation": "这里应该用〈好吃〉。杰出 不形容味道，说味道好要用“好吃”。"}, {"text": "她长得很杰出，大家都喜欢她。", "explanation": "这里应该用〈好看〉。杰出 说才能或成就，不用来形容长相。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94761, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杰出", "is_correct": true, "explanation": "正确：“杰出”表示作文结构特别出色，与“是全班最好的”相符。"}, {"text": "粗心", "is_correct": false, "explanation": "搭配：“粗心”形容人的态度，不用来形容作文结构。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”描述人的身材，不能用于形容作文结构。"}, {"text": "混乱", "is_correct": false, "explanation": "语义：“混乱”指没有条理，与“是全班最好的”矛盾。"}], "explanations": {"杰出": "正确：“杰出”表示作文结构特别出色，与“是全班最好的”相符。", "粗心": "搭配：“粗心”形容人的态度，不用来形容作文结构。", "矮小": "体貌：“矮小”描述人的身材，不能用于形容作文结构。", "混乱": "语义：“混乱”指没有条理，与“是全班最好的”矛盾。"}, "sentence_index": 6, "correct_answer": "杰出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路很杰出，我们骑车很舒服。", "explanation": "这里应该用〈宽〉。杰出 形容人的才能或成就，不用来说道路的宽窄。"}, {"text": "这件衣服的颜色很杰出，我很喜欢。", "explanation": "这里应该用〈鲜艳〉。杰出 不形容颜色，说颜色好看要用“鲜艳”之类的词。"}, {"text": "我的房间很杰出，妈妈每天都夸我。", "explanation": "这里应该用〈干净〉。杰出 不形容房间的整洁，说房间干净要用“干净”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94761, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这支球队的训练成绩被十分杰出，教练很满意。", "corrected_sentence": "这支球队的训练成绩十分杰出，教练很满意。", "error_description": "错误：“十分杰出”前多加了“被”。正确：去掉“被”，直接说“成绩十分杰出”。“杰出”是形容词，不能用“被”构成被动句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94761, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个很杰出人才，学校为他感到骄傲。", "corrected_sentence": "这是一个很杰出的人才，学校为他感到骄傲。", "error_description": "错误：“很杰出”修饰名词“人才”时漏了“的”。正确：应说“很杰出的人才”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94762, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平庸", "is_correct": true, "explanation": "正确：“平庸”指没有特别出色的成就，与“杰出”相反。"}, {"text": "凶猛", "is_correct": false, "explanation": "“凶猛”形容凶狠、有力量，与“杰出”的出众程度无关。"}, {"text": "湿润", "is_correct": false, "explanation": "“湿润”形容含水分多，与“杰出”不构成反义。"}, {"text": "辽阔", "is_correct": false, "explanation": "“辽阔”形容范围广大，不是“杰出”的反义词。"}], "correct_answer": "平庸", "explanations": {"平庸": "正确：“平庸”指没有特别出色的成就，与“杰出”相反。", "凶猛": "“凶猛”形容凶狠、有力量，与“杰出”的出众程度无关。", "湿润": "“湿润”形容含水分多，与“杰出”不构成反义。", "辽阔": "“辽阔”形容范围广大，不是“杰出”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94762, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平庸", "is_correct": true, "explanation": "正确：“平庸”指没有特别出色的才能，与“杰出”相反。"}, {"text": "尖锐", "is_correct": false, "explanation": "“尖锐”形容刀、声音等的锋利，与“杰出”无关，不是反义词。"}, {"text": "稀疏", "is_correct": false, "explanation": "“稀疏”形容间隔大、数量少，与“杰出”的水平高低不构成反义。"}, {"text": "沉重", "is_correct": false, "explanation": "“沉重”形容分量大或心情压抑，与“杰出”无反义关系。"}], "correct_answer": "平庸", "explanations": {"平庸": "正确：“平庸”指没有特别出色的才能，与“杰出”相反。", "尖锐": "“尖锐”形容刀、声音等的锋利，与“杰出”无关，不是反义词。", "稀疏": "“稀疏”形容间隔大、数量少，与“杰出”的水平高低不构成反义。", "沉重": "“沉重”形容分量大或心情压抑，与“杰出”无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94762, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "才能、成就特别出众，超过一般人。", "primary_collocate": null, "pronunciation": "jié chū", "ipa": "tɕjɛ˧˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "他是一位杰出的科学家，发明了很多东西。", "target_word": "杰出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位杰出的医生救了很多病人。", "target_word": "杰出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杰出的人才对一个国家非常重要。", "target_word": "杰出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为学校做出了杰出的贡献，大家都很感谢她。", "target_word": "杰出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时是个杰出的工程师，修过大桥。", "target_word": "杰出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是公司里最杰出的领导，很有才能。", "target_word": "杰出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家很杰出，写的书卖到了很多国家。", "target_word": "杰出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杰出的运动员每天都要练习很长时间。", "target_word": "杰出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位杰出的老师教出了很多好学生。", "target_word": "杰出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的才能杰出，二十岁就成了有名的钢琴家。", "target_word": "杰出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "傑出", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "人的才能、成就特别出众，超过一般人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccaa5f06-74fd-450d-9e5c-c87f845eb06a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94762, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "杰出", "is_correct": true, "explanation": "正确：杰出（jié chū），才能、成就特别出众，超过一般人。"}, {"text": "决出", "is_correct": false, "explanation": "jué（第二声）与 jié（第二声）韵母不同（üe 与 ie），意思是“经过比较定出结果”，如“决出冠军”。"}, {"text": "解出", "is_correct": false, "explanation": "jiě（第三声）与 jié（第二声）声调不同，意思是“解答得出”，如“解出题目”。"}, {"text": "借出", "is_correct": false, "explanation": "jiè（第四声）与 jié（第二声）声调不同，意思是“把东西借给别人”，如“借出图书”。"}], "explanations": {"杰出": "正确：杰出（jié chū），才能、成就特别出众，超过一般人。", "决出": "jué（第二声）与 jié（第二声）韵母不同（üe 与 ie），意思是“经过比较定出结果”，如“决出冠军”。", "解出": "jiě（第三声）与 jié（第二声）声调不同，意思是“解答得出”，如“解出题目”。", "借出": "jiè（第四声）与 jié（第二声）声调不同，意思是“把东西借给别人”，如“借出图书”。"}, "sentence_index": null, "correct_answer": "杰出"}, "level_3": {"options": [{"text": "杰出", "is_correct": true, "explanation": "正确：“杰出”指才能特别出众，与“发明了很多东西”相符。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容环境或物体，不用来形容人的身份。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”只用于山坡、道路等，不能修饰科学家。"}, {"text": "狭窄", "is_correct": false, "explanation": "语义：“狭窄”指空间小，用来形容科学家与“发明了很多东西”不协调。"}], "explanations": {"杰出": "正确：“杰出”指才能特别出众，与“发明了很多东西”相符。", "潮湿": "搭配：“潮湿”形容环境或物体，不用来形容人的身份。", "陡峭": "搭配：“陡峭”只用于山坡、道路等，不能修饰科学家。", "狭窄": "语义：“狭窄”指空间小，用来形容科学家与“发明了很多东西”不协调。"}, "sentence_index": 0, "correct_answer": "杰出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个汤的味道很杰出，大家都想再喝一碗。", "explanation": "这里应该用〈好吃〉。杰出 说才能、成就，不用来形容味道。"}, {"text": "这个箱子很杰出，我搬不动。", "explanation": "这里应该用〈重〉。杰出 不形容物体的轻重。"}, {"text": "今天的风很杰出，我们都穿上了外套。", "explanation": "这里应该用〈冷〉。杰出 不形容风或天气的冷暖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94762, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杰出", "is_correct": true, "explanation": "正确：“杰出”形容作家的才能和成就，与“书卖到了很多国家”相符。"}, {"text": "寒冷", "is_correct": false, "explanation": "搭配：“寒冷”形容温度，不用来形容作家。"}, {"text": "空旷", "is_correct": false, "explanation": "搭配：“空旷”形容场地或空间，不能修饰人。"}, {"text": "漆黑", "is_correct": false, "explanation": "语义：“漆黑”形容颜色或光线，与作家的成就无关。"}], "explanations": {"杰出": "正确：“杰出”形容作家的才能和成就，与“书卖到了很多国家”相符。", "寒冷": "搭配：“寒冷”形容温度，不用来形容作家。", "空旷": "搭配：“空旷”形容场地或空间，不能修饰人。", "漆黑": "语义：“漆黑”形容颜色或光线，与作家的成就无关。"}, "sentence_index": 6, "correct_answer": "杰出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的个子很杰出，打篮球很厉害。", "explanation": "这里应该用〈高〉。杰出 形容才能或成就，不用来形容身高。"}, {"text": "这些书摆得很杰出，看上去很舒服。", "explanation": "这里应该用〈整齐〉。杰出 不形容物品的摆放。"}, {"text": "这块石头很杰出，砸不碎。", "explanation": "这里应该用〈硬〉。杰出 不形容物体的软硬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位工程师的能力被十分杰出，同事们都很佩服。", "corrected_sentence": "这位工程师的能力十分杰出，同事们都很佩服。", "error_description": "错误：“十分杰出”前多加了“被”。正确：去掉“被”，说“能力十分杰出”。“杰出”是形容词，不能用“被”构成被动句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一位很杰出老师，学生都很喜欢他。", "corrected_sentence": "他是一位很杰出的老师，学生都很喜欢他。", "error_description": "错误：“很杰出”修饰名词“老师”时漏了“的”。正确：应说“很杰出的老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
