INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94768, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种标点符号，用于隔开复句中并列的分句，写作“；”。", "primary_collocate": null, "pronunciation": "fēn hào", "ipa": "fən˥ xɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "分号用来隔开并列的句子。", "target_word": "分号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个分句意思并列，中间用分号。", "target_word": "分号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天教我们怎么用分号。", "target_word": "分号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这句话里的分号用得很对：哥哥喜欢唱歌；妹妹喜欢跳舞。", "target_word": "分号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "句号比分号的停顿更长。", "target_word": "分号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写长句子时，分号能让意思更清楚。", "target_word": "分号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这里的逗号改成了分号。", "target_word": "分号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中文的分号写作“；”。", "target_word": "分号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看书时，我发现作者很喜欢用分号。", "target_word": "分号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一段用分号很合适：春天很暖和；秋天很凉快。", "target_word": "分号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "分號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "隔开复句中并列分句的标点符号“；”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3101b179-ea35-4787-b575-d3c8af1182ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94768, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分号", "is_correct": true, "explanation": "分号是写作“；”的标点符号，读作 fēn hào，是本题的正确答案。"}, {"text": "分到", "is_correct": false, "explanation": "dào（第四声）与 hào（第四声）声母不同：d 与 h，意思是得到、到达。"}, {"text": "番号", "is_correct": false, "explanation": "fān（第一声）与 fēn（第一声）韵母不同：an 与 en，意思是编号。"}, {"text": "分毫", "is_correct": false, "explanation": "háo（第二声）与 hào（第四声）声调不同，意思是极少、一点点。"}, {"text": "分行", "is_correct": false, "explanation": "háng（第二声）与 hào（第四声）韵母和声调都不同，意思是银行的分支机构。"}], "explanations": {"分号": "分号是写作“；”的标点符号，读作 fēn hào，是本题的正确答案。", "分到": "dào（第四声）与 hào（第四声）声母不同：d 与 h，意思是得到、到达。", "番号": "fān（第一声）与 fēn（第一声）韵母不同：an 与 en，意思是编号。", "分毫": "háo（第二声）与 hào（第四声）声调不同，意思是极少、一点点。", "分行": "háng（第二声）与 hào（第四声）韵母和声调都不同，意思是银行的分支机构。"}, "sentence_index": null, "correct_answer": "分号"}, "level_3": {"options": [{"text": "分号", "is_correct": true, "explanation": "分号用来隔开复句中并列的分句，与词条定义一致。"}, {"text": "问号", "is_correct": false, "explanation": "语义：问号表示疑问，不用来隔开并列的句子。"}, {"text": "书名号", "is_correct": false, "explanation": "搭配：书名号标示书名或篇名，不能用来隔开并列的句子。"}, {"text": "引号", "is_correct": false, "explanation": "语义：引号标示引用的话语，不能用来隔开并列的句子。"}], "explanations": {"分号": "分号用来隔开复句中并列的分句，与词条定义一致。", "问号": "语义：问号表示疑问，不用来隔开并列的句子。", "书名号": "搭配：书名号标示书名或篇名，不能用来隔开并列的句子。", "引号": "语义：引号标示引用的话语，不能用来隔开并列的句子。"}, "sentence_index": 0, "correct_answer": "分号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了书；笔和本子。", "explanation": "这里应该用〈顿号〉。简单词语并列要用顿号，分号只用于较复杂的并列成分。"}, {"text": "老师说；大家明天来。", "explanation": "这里应该用〈冒号〉。引出说的内容时要用冒号，分号不能用来引出话语。"}, {"text": "我们已经到学校了；", "explanation": "这里应该用〈句号〉。分号只用于句中隔开并列分句，句末应使用句号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94768, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分号", "is_correct": true, "explanation": "分号是用来替代逗号、隔开并列分句的标点，符合“改成了”的语境。"}, {"text": "句子", "is_correct": false, "explanation": "语义：句子是语言单位，不是标点，不能替换逗号。"}, {"text": "数字", "is_correct": false, "explanation": "搭配：“改成了”后面不能接数字来指代标点，数字不能替代逗号。"}, {"text": "逗号", "is_correct": false, "explanation": "语义：原句中的逗号已经是逗号，改成逗号等于没有改。"}], "explanations": {"分号": "分号是用来替代逗号、隔开并列分句的标点，符合“改成了”的语境。", "句子": "语义：句子是语言单位，不是标点，不能替换逗号。", "数字": "搭配：“改成了”后面不能接数字来指代标点，数字不能替代逗号。", "逗号": "语义：原句中的逗号已经是逗号，改成逗号等于没有改。"}, "sentence_index": 6, "correct_answer": "分号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的爸爸；一位医生；每天很早起床。", "explanation": "这里应该用〈逗号〉。插入的同位说明用逗号隔开，分号只用来隔开并列的分句。"}, {"text": "在家里；我每天看书。", "explanation": "这里应该用〈逗号〉。开头的状语后面用逗号，分号只用来隔开完整的并列分句。"}, {"text": "你明天去学校吗；", "explanation": "这里应该用〈问号〉。疑问句末尾用问号，分号不能用在句末。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94768, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们老师说，这两句话之间要用一只分号。", "corrected_sentence": "我们老师说，这两句话之间要用一个分号。", "error_description": "量词错误：分号是标点符号，量词应用“个”，不能用“只”。应改为“一个分号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94768, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个分句意思并列，我在中间加了一个句号。", "corrected_sentence": "这两个分句意思并列，我在中间加了一个分号。", "error_description": "用词错误：并列分句之间应用分号隔开，句号只用于句子末尾。应改为“分号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
