INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94769, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "剧本是演戏时，写着大家要说什么话的书。", "primary_collocate": null, "pronunciation": "jù běn", "ipa": "tɕy˥˩ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个话剧的剧本写得很有意思。", "target_word": "剧本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想给学校的话剧写一个新剧本。", "target_word": "剧本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们每人一本剧本。", "target_word": "剧本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演员们正在背剧本里的话。", "target_word": "剧本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把明天要演的剧本放在桌子上了。", "target_word": "剧本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个剧本太长，两小时演不完。", "target_word": "剧本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先读一遍剧本，再开始演戏。", "target_word": "剧本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写过很多好看的剧本。", "target_word": "剧本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们看着剧本，小声地说话。", "target_word": "剧本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出以前，大家要把剧本都记住。", "target_word": "剧本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "电影剧本", "label": "复合"}, {"form": "劇本", "label": "繁体"}], "register": "中性", "sense_fingerprint": "演戏用的书，写着演员要说的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '109ed30c-9583-414f-9809-33e9e60b7ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94769, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剧本", "is_correct": true, "explanation": "正确：“剧本”指写成的文字底本，可以被“写”，与“写得很有意思”搭配通顺。"}, {"text": "舞台", "is_correct": false, "explanation": "语义：舞台是表演的场地，不是文字作品，不能“写”，与“写得很有意思”冲突。"}, {"text": "服装", "is_correct": false, "explanation": "搭配：“写”用于文字作品，服装应说“设计”，不能说“写得”。"}, {"text": "灯光", "is_correct": false, "explanation": "语义：灯光是照明设备，没有文字内容，不能“写”，与句意不合。"}], "explanations": {"剧本": "正确：“剧本”指写成的文字底本，可以被“写”，与“写得很有意思”搭配通顺。", "舞台": "语义：舞台是表演的场地，不是文字作品，不能“写”，与“写得很有意思”冲突。", "服装": "搭配：“写”用于文字作品，服装应说“设计”，不能说“写得”。", "灯光": "语义：灯光是照明设备，没有文字内容，不能“写”，与句意不合。"}, "sentence_index": 0, "correct_answer": "剧本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末学校有一场剧本。", "explanation": "这里应该用〈演出〉。“剧本”是文字底本，不能用“一场”计量；指舞台表演才用“场”。"}, {"text": "演员们一起走上了剧本。", "explanation": "这里应该用〈舞台〉。剧本是文字，不是场地，“走上”后面要接表演的场所。"}, {"text": "演员们穿上了漂亮的剧本。", "explanation": "这里应该用〈服装〉。剧本是写着台词的文字底本，不能穿；演员穿的是服装。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94769, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剧本", "is_correct": true, "explanation": "正确：“读一遍剧本”指阅读文字底本，符合句意，之后再演戏。"}, {"text": "道具", "is_correct": false, "explanation": "语义：道具是表演时使用的器具，不能“读”，与“读一遍”冲突。"}, {"text": "布景", "is_correct": false, "explanation": "语义：布景是舞台背景，不是可读的文字，不能“读一遍”。"}, {"text": "门票", "is_correct": false, "explanation": "搭配：“读”一般不搭配门票，门票应说“看”或“检”。"}], "explanations": {"剧本": "正确：“读一遍剧本”指阅读文字底本，符合句意，之后再演戏。", "道具": "语义：道具是表演时使用的器具，不能“读”，与“读一遍”冲突。", "布景": "语义：布景是舞台背景，不是可读的文字，不能“读一遍”。", "门票": "搭配：“读”一般不搭配门票，门票应说“看”或“检”。"}, "sentence_index": 6, "correct_answer": "剧本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去剧本看戏。", "explanation": "这里应该用〈剧场〉。剧本是文字，不是场所，去哪里看戏应说“剧场”。"}, {"text": "拉开剧本，演出就开始了。", "explanation": "这里应该用〈幕布〉。剧本是文字底本，不能拉开；拉开的是幕布。"}, {"text": "舞台上的剧本太暗了，看不清演员。", "explanation": "这里应该用〈灯光〉。剧本是文字底本，没有明暗；照亮舞台的是灯光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94769, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天读了一只剧本。", "corrected_sentence": "我昨天读了一本剧本。", "error_description": "量词错误：剧本的量词是“本”，不能用“只”（“只”用于动物或成对物品中的一个），应说“读了一本剧本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94769, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被剧本读完了。", "corrected_sentence": "他把剧本读完了。", "error_description": "把字句与被字句混用：“剧本”是“读完”的受事，应用“把”引出，应说“他把剧本读完了”，不能说“他被剧本读完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
