INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94771, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "功夫是练习很久才有的本事。", "primary_collocate": null, "pronunciation": "gōng fu", "ipa": "kʊŋ˥ fu", "syllable_count": 2, "sentences": [{"text": "这手好字要有很深的功夫才写得出来。", "target_word": "功夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的功夫是每天练出来的。", "target_word": "功夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅做面条的功夫真深。", "target_word": "功夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语功夫很深，说话很地道。", "target_word": "功夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她弹琴的功夫很好，因为她练了十年。", "target_word": "功夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他练太极的功夫已经很深了。", "target_word": "功夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好功夫不是一天就能练成的。", "target_word": "功夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位厨师切菜的功夫让人佩服。", "target_word": "功夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他练了二十年，功夫才这么好。", "target_word": "功夫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅说，功夫要靠自己每天练。", "target_word": "功夫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "门", "label": "量词"}, {"form": "身", "label": "量词"}], "register": "口语", "sense_fingerprint": "长期练习才有的本事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3101b179-ea35-4787-b575-d3c8af1182ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94771, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "功夫", "is_correct": true, "explanation": "功夫：长期练习才有的本事，正确答案。"}, {"text": "工服", "is_correct": false, "explanation": "gōng fú（第二声）与 gōng fu（轻声）声调不同，意思是工作服。"}, {"text": "功法", "is_correct": false, "explanation": "fǎ 与 fu 的韵母和声调都不同，意思是练功的方法。"}, {"text": "冬服", "is_correct": false, "explanation": "dōng 与 gōng 声母不同，意思是冬天穿的衣服。"}, {"text": "空服", "is_correct": false, "explanation": "kōng 与 gōng 声母不同，意思是空乘人员的制服。"}], "explanations": {"功夫": "功夫：长期练习才有的本事，正确答案。", "工服": "gōng fú（第二声）与 gōng fu（轻声）声调不同，意思是工作服。", "功法": "fǎ 与 fu 的韵母和声调都不同，意思是练功的方法。", "冬服": "dōng 与 gōng 声母不同，意思是冬天穿的衣服。", "空服": "kōng 与 gōng 声母不同，意思是空乘人员的制服。"}, "sentence_index": null, "correct_answer": "功夫"}, "level_3": {"options": [{"text": "功夫", "is_correct": true, "explanation": "功夫：长期练习得来的本领，与“写字”的语境相合，正确。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是练出来的本领，“很深的汽车”不通。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“很深的”在这里修饰能练就的本领，不说“很深的桌子才写得出来”。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包无法通过十年练成，“写得出来”的句意不通。"}], "explanations": {"功夫": "功夫：长期练习得来的本领，与“写字”的语境相合，正确。", "汽车": "语义：汽车不是练出来的本领，“很深的汽车”不通。", "桌子": "搭配：“很深的”在这里修饰能练就的本领，不说“很深的桌子才写得出来”。", "书包": "语义：书包无法通过十年练成，“写得出来”的句意不通。"}, "sentence_index": 0, "correct_answer": "功夫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他天生有很好的功夫，所以学东西很快。", "explanation": "这里应该用〈天赋〉。功夫要靠长期练习得来，天生的能力说“天赋”，不说“功夫”。"}, {"text": "他有一只很深的功夫，每天都在练。", "explanation": "这里应该用〈门〉。功夫作“本领”讲时，量词用“门”，不用“只”。"}, {"text": "工程师正在测试新功夫的安全性。", "explanation": "这里应该用〈技术〉。测试的是可以应用的技术，要说“技术”；“功夫”指练习很久才有的本事，不能用来测试安全性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94771, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "功夫", "is_correct": true, "explanation": "功夫：长期练习才有的本事，正确答案。"}, {"text": "公府", "is_correct": false, "explanation": "fǔ（第三声）与 fu（轻声）声调不同，意思是官府。"}, {"text": "共富", "is_correct": false, "explanation": "gòng（第四声）与 gōng（第一声）声调不同，意思是共同富裕。"}, {"text": "公布", "is_correct": false, "explanation": "bù 与 fu 声母和声调都不同，意思是公开发布。"}], "explanations": {"功夫": "功夫：长期练习才有的本事，正确答案。", "公府": "fǔ（第三声）与 fu（轻声）声调不同，意思是官府。", "共富": "gòng（第四声）与 gōng（第一声）声调不同，意思是共同富裕。", "公布": "bù 与 fu 声母和声调都不同，意思是公开发布。"}, "sentence_index": null, "correct_answer": "功夫"}, "level_3": {"options": [{"text": "功夫", "is_correct": true, "explanation": "功夫：长期练习得来的本领，与“练成”搭配，正确。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是靠练习得来的，“练成”的对象只能是本领。"}, {"text": "铅笔", "is_correct": false, "explanation": "搭配：“练成”的对象是本领，不说“好铅笔不是一天就能练成的”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能通过练习练成，句意不通。"}], "explanations": {"功夫": "功夫：长期练习得来的本领，与“练成”搭配，正确。", "天气": "语义：天气不是靠练习得来的，“练成”的对象只能是本领。", "铅笔": "搭配：“练成”的对象是本领，不说“好铅笔不是一天就能练成的”。", "窗户": "语义：窗户不能通过练习练成，句意不通。"}, "sentence_index": 6, "correct_answer": "功夫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师把同学们的功夫收上去批改。", "explanation": "这里应该用〈功课〉。收上去批改的是作业，要说“功课”；“功夫”指练习很久才有的本事，不能收上去批改。"}, {"text": "功夫打开了房门。", "explanation": "功夫是抽象的本领，不能做“打开”的动作，这里的用法不对。"}, {"text": "她的功夫很咸，大家都不爱吃。", "explanation": "功夫不能用“咸”来形容，味道只能用来形容食物，这里用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94771, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他练过一只功夫，所以很厉害。", "corrected_sentence": "他练过一门功夫，所以很厉害。", "error_description": "错误：“一只功夫”；正确：“一门功夫”。功夫作“本领”讲时，量词用“门”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94771, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她练出了一张好功夫。", "corrected_sentence": "她练出了一身好功夫。", "error_description": "错误：“一张好功夫”；正确：“一身好功夫”。说人具备的本领可用量词“身”，“张”用于纸、桌子等。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
