INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94774, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94774, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "受到攻击后进行回击。", "primary_collocate": null, "pronunciation": "fǎn jī", "ipa": "fan˨˩˦ tɕi˥", "syllable_count": 2, "sentences": [{"text": "对方先打了我们，我们开始反击。", "target_word": "反击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受到批评以后，他马上写文章反击。", "target_word": "反击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家先发起攻击，我们只能反击。", "target_word": "反击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对他的攻击，她没有反击，只是笑了笑。", "target_word": "反击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队被围住后，决定向敌人反击。", "target_word": "反击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司被骂了很久，终于出来反击了。", "target_word": "反击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们等着机会，准备反击。", "target_word": "反击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对手连进两球，我们必须反击。", "target_word": "反击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用事实反击了那些谣言。", "target_word": "反击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被人欺负的时候，你要学会反击。", "target_word": "反击", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反击了", "label": "体标"}, {"form": "反击过", "label": "体标"}, {"form": "反击战", "label": "复合"}], "register": "中性", "sense_fingerprint": "反击|动词|受到攻击后进行回击", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60b8685b-8c93-4781-a5d8-5d5358d689c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反击", "is_correct": true, "explanation": "正确。“反击”指受到攻击后进行回击，与“对方先打了我们”的语境相符。"}, {"text": "道歉", "is_correct": false, "explanation": "语义：对方先动手，我们却“道歉”，与“对方先打了我们”的语境相悖。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”表示欢庆，与受到攻击后的处境相反，句意不通。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”需要带宾语（感谢谁或什么），此处没有宾语，句子不完整。"}], "explanations": {"反击": "正确。“反击”指受到攻击后进行回击，与“对方先打了我们”的语境相符。", "道歉": "语义：对方先动手，我们却“道歉”，与“对方先打了我们”的语境相悖。", "庆祝": "语义：“庆祝”表示欢庆，与受到攻击后的处境相反，句意不通。", "感谢": "配价：“感谢”需要带宾语（感谢谁或什么），此处没有宾语，句子不完整。"}, "sentence_index": 0, "correct_answer": "反击"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们先反击，夺下了对方的阵地。", "explanation": "这里应该用〈进攻〉。反击只能用于回击先到来的攻击，我们先动手时不能说反击。"}, {"text": "他反击这项计划，大家都没有同意。", "explanation": "这里应该用〈反对〉。反击是受攻击后的还手，对计划表示不同意要用“反对”。"}, {"text": "我每天早上都会反击邻居。", "explanation": "这里应该用〈问候〉。反击指受攻击后的回击，早上向邻居打招呼要用“问候”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反击", "is_correct": true, "explanation": "正确。“反击”与“等着机会”的语境相符，表示伺机回击。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：一直“等着机会”的人不会放弃，与句意冲突。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：等待机会时准备睡觉，不合情理，与句意冲突。"}, {"text": "嘲笑", "is_correct": false, "explanation": "配价：“嘲笑”需要带宾语（嘲笑谁），单独作谓语时句子不完整。"}], "explanations": {"反击": "正确。“反击”与“等着机会”的语境相符，表示伺机回击。", "放弃": "语义：一直“等着机会”的人不会放弃，与句意冲突。", "睡觉": "语义：等待机会时准备睡觉，不合情理，与句意冲突。", "嘲笑": "配价：“嘲笑”需要带宾语（嘲笑谁），单独作谓语时句子不完整。"}, "sentence_index": 6, "correct_answer": "反击"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他反击了我的帮助。", "explanation": "这里应该用〈回报〉。反击是回击攻击，感谢别人的帮助要用“回报”。"}, {"text": "我们热情反击远道而来的客人。", "explanation": "这里应该用〈欢迎〉。反击只指受攻击后的还手，对客人应使用“欢迎”。"}, {"text": "老师反击了这篇作文。", "explanation": "这里应该用〈赞赏〉。反击只指受攻击后的还手，对作文的肯定要用“赞赏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "对方先打了我们，我们把反击了对方。", "corrected_sentence": "对方先打了我们，我们反击了对方。", "error_description": "错误：“我们把反击了对方”。正确：“我们反击了对方”。“把”字句需要“把＋宾语＋动词”的结构，这里“把”后没有宾语，应删去“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们等了很久，还没反击了。", "corrected_sentence": "他们等了很久，还没反击。", "error_description": "错误：“还没反击了”。正确：“还没反击”。“没”表示否定，否定句中动词后不能再带动态助词“了”，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
