INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94775, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "合约是两边人说好后写下的纸，要照着做。", "primary_collocate": null, "pronunciation": "hé yuē", "ipa": "xɤ˧˥ ɥœ˥", "syllable_count": 2, "sentences": [{"text": "我们和房东签了一份合约。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份合约写得很清楚，你可以放心。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合约上说，每月五号要交房租。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把合约放在桌子上，没有看完。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要照着合约做，不能乱改。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "签合约以前，请先读一读每一句话。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张合约我已经给老板看过了。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机公司给我寄来了新合约。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合约丢了，我得再要一份。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王对合约上的字不太明白。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "张", "label": "量词"}], "register": "中性", "sense_fingerprint": "双方说好后写下、要照做的纸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c832532e-8599-453c-a65b-bf3d6cc2a2e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94775, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合约", "is_correct": true, "explanation": "合约：双方签下的书面协议，这里指与房东签的纸质合约。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：“签”多用于合约、文件，“报纸”通常说“订”，“签了一份报纸”不说。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不是纸质文件，无法签订。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜是食物，不是可以签的文件。"}], "explanations": {"合约": "合约：双方签下的书面协议，这里指与房东签的纸质合约。", "报纸": "搭配：“签”多用于合约、文件，“报纸”通常说“订”，“签了一份报纸”不说。", "蛋糕": "语义：蛋糕不是纸质文件，无法签订。", "饭菜": "语义：饭菜是食物，不是可以签的文件。"}, "sentence_index": 0, "correct_answer": "合约"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在合约上听到了一首好听的歌。", "explanation": "这里应该用〈收音机〉。合约是写下的约定，不能听到歌。"}, {"text": "妈妈留给我一份合约，上面写着她的心愿。", "explanation": "这里应该用〈遗嘱〉。合约是双方订立的书面协议，单方面留下的心愿要说“遗嘱”。"}, {"text": "天冷了，他穿上了合约。", "explanation": "这里应该用〈大衣〉。合约是写下的约定，不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cd7f24c-5159-466b-8e24-be195f5be339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94775, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合约", "is_correct": true, "explanation": "合约：这里指已经给老板看过的那份纸质合约。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不能用“张”来数，也不是给老板看的文件。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能用“张”来数，也不能拿给老板看。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶不能用“张”来数，也不是要给老板看的文件。"}], "explanations": {"合约": "合约：这里指已经给老板看过的那份纸质合约。", "音乐": "语义：音乐不能用“张”来数，也不是给老板看的文件。", "天气": "语义：天气不能用“张”来数，也不能拿给老板看。", "牛奶": "语义：牛奶不能用“张”来数，也不是要给老板看的文件。"}, "sentence_index": 6, "correct_answer": "合约"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他今天忘带合约，刷不开宿舍的门。", "explanation": "这里应该用〈门卡〉。合约是双方订立的书面协议，开门用的卡要说“门卡”。"}, {"text": "小王用合约给妈妈打了电话。", "explanation": "这里应该用〈手机〉。合约是写下的约定，不能打电话。"}, {"text": "饿了，小王吃了一份合约。", "explanation": "这里应该用〈饭〉。合约是写下的约定，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cd7f24c-5159-466b-8e24-be195f5be339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
