INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94779, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "吸是用嘴或鼻子把空气或水拉进来。", "primary_collocate": null, "pronunciation": "xī", "ipa": "ɕi˥", "syllable_count": 1, "sentences": [{"text": "他闭上眼睛，深深吸了一口气。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用嘴吸了一口果汁。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的空气很新鲜，我用力吸了几口。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说：“用鼻子吸，用嘴呼。”", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在水里憋了很久，终于冒出水面吸了一口气。", "target_word": "吸", "complexity_tier": "T3", "furigana": "tā zài shuǐ lǐ biē le hěn jiǔ, zhōng yú mào chū shuǐ miàn xī le yì kǒu qì.", "sentence_source": "generated"}, {"text": "她用鼻子吸了吸，闻到了花香。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳前，先吸一大口气再下水。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子感冒了，鼻子堵住了，用力也吸不进空气。", "target_word": "吸", "complexity_tier": "T3", "furigana": "hái zi gǎn mào le, bí zi dǔ zhù le, yòng lì yě xī bu jìn kōng qì.", "sentence_source": "generated"}, {"text": "他用嘴把杯底的果汁吸干净了。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她吸了一口水，又吐了出来。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吸了", "label": "体标"}, {"form": "吸过", "label": "体标"}, {"form": "吸吸", "label": "重叠"}], "register": "中性", "sense_fingerprint": "吸|动词|用嘴或鼻子把空气或水拉进来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60b8685b-8c93-4781-a5d8-5d5358d689c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94779, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吸", "is_correct": true, "explanation": "正确。“吸”（第一声）指用嘴或鼻子把空气或水拉进来。"}, {"text": "洗", "is_correct": false, "explanation": "xǐ（第三声）与 xī（第一声）声调不同，意思是洗。"}, {"text": "习", "is_correct": false, "explanation": "xí（第二声）与 xī（第一声）声调不同，意思是练习、学习。"}, {"text": "戏", "is_correct": false, "explanation": "xì（第四声）与 xī（第一声）声调不同，意思是戏剧、游戏。"}, {"text": "星", "is_correct": false, "explanation": "xīng 比 xī 多一个鼻音韵尾 -ng，意思是星星。"}], "explanations": {"吸": "正确。“吸”（第一声）指用嘴或鼻子把空气或水拉进来。", "洗": "xǐ（第三声）与 xī（第一声）声调不同，意思是洗。", "习": "xí（第二声）与 xī（第一声）声调不同，意思是练习、学习。", "戏": "xì（第四声）与 xī（第一声）声调不同，意思是戏剧、游戏。", "星": "xīng 比 xī 多一个鼻音韵尾 -ng，意思是星星。"}, "sentence_index": null, "correct_answer": "吸"}, "level_3": {"options": [{"text": "吸", "is_correct": true, "explanation": "正确。“吸”与“深深……了一口气”搭配，指用鼻子把空气吸进来。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，不能说“喝一口气”。"}, {"text": "尝", "is_correct": false, "explanation": "搭配：“尝”指用舌头辨别滋味，不能与“一口气”搭配。"}, {"text": "咽", "is_correct": false, "explanation": "语义：“咽”指吞咽，“咽气”又表示断气，与深呼吸的句意不合。"}], "explanations": {"吸": "正确。“吸”与“深深……了一口气”搭配，指用鼻子把空气吸进来。", "喝": "搭配：“喝”的对象是液体，不能说“喝一口气”。", "尝": "搭配：“尝”指用舌头辨别滋味，不能与“一口气”搭配。", "咽": "语义：“咽”指吞咽，“咽气”又表示断气，与深呼吸的句意不合。"}, "sentence_index": 0, "correct_answer": "吸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一口气把蜡烛吸灭了。", "explanation": "这里应该用〈吹〉。吸是把气体或液体拉进来，吹灭蜡烛要把气吹出去，应说“吹”。"}, {"text": "他一口吸掉了一个馒头。", "explanation": "这里应该用〈吃〉。吸是用嘴或鼻子把空气或水拉进来，吃馒头要用“吃”，不能用“吸”。"}, {"text": "他用嘴把气球吸得鼓鼓的。", "explanation": "这里应该用〈吹〉。吸是把空气拉进来，把气球弄鼓要把气送出去，应说“吹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94779, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "吸", "is_correct": true, "explanation": "正确。“吸”（第一声）指用嘴或鼻子把空气或水拉进来。"}, {"text": "喜", "is_correct": false, "explanation": "xǐ（第三声）与 xī（第一声）声调不同，意思是喜欢。"}, {"text": "席", "is_correct": false, "explanation": "xí（第二声）与 xī（第一声）声调不同，意思是席位、席子。"}, {"text": "细", "is_correct": false, "explanation": "xì（第四声）与 xī（第一声）声调不同，意思是细小。"}, {"text": "心", "is_correct": false, "explanation": "xīn 比 xī 多一个韵尾 -n，意思是心脏、心思。"}, {"text": "丝", "is_correct": false, "explanation": "sī（第一声）与 xī（第一声）声母不同，意思是丝线。"}], "explanations": {"吸": "正确。“吸”（第一声）指用嘴或鼻子把空气或水拉进来。", "喜": "xǐ（第三声）与 xī（第一声）声调不同，意思是喜欢。", "席": "xí（第二声）与 xī（第一声）声调不同，意思是席位、席子。", "细": "xì（第四声）与 xī（第一声）声调不同，意思是细小。", "心": "xīn 比 xī 多一个韵尾 -n，意思是心脏、心思。", "丝": "sī（第一声）与 xī（第一声）声母不同，意思是丝线。"}, "sentence_index": null, "correct_answer": "吸"}, "level_3": {"options": [{"text": "吸", "is_correct": true, "explanation": "正确。“吸”与“先……一大口气再下水”相符，指用嘴或鼻子吸入空气。"}, {"text": "咳", "is_correct": false, "explanation": "搭配：“咳”指用力排出呼吸道内的东西，不能与“一大口气”的吸入义搭配。"}, {"text": "嚼", "is_correct": false, "explanation": "语义：“嚼”是咀嚼食物，不能用来指吸入一口气。"}, {"text": "捏", "is_correct": false, "explanation": "配价：“捏”需要具体的物体作宾语，不能带“一大口气”作宾语。"}], "explanations": {"吸": "正确。“吸”与“先……一大口气再下水”相符，指用嘴或鼻子吸入空气。", "咳": "搭配：“咳”指用力排出呼吸道内的东西，不能与“一大口气”的吸入义搭配。", "嚼": "语义：“嚼”是咀嚼食物，不能用来指吸入一口气。", "捏": "配价：“捏”需要具体的物体作宾语，不能带“一大口气”作宾语。"}, "sentence_index": 6, "correct_answer": "吸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他慢慢吸出一口气。", "explanation": "这里应该用〈呼〉。吸是把空气吸进来，把气送出去要用“呼”，“吸出”与呼气方向相反。"}, {"text": "他用力吸了一封信。", "explanation": "这里应该用〈写〉。吸是用嘴或鼻子把空气或水拉进来，写信要用“写”，不能用“吸”。"}, {"text": "他把牙膏吸进了牙刷里。", "explanation": "这里应该用〈挤〉。吸是把气体或液体拉进来，挤牙膏要用“挤”，不能用“吸”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94779, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她站在窗前，深深吸了一个清晨的空气。", "corrected_sentence": "她站在窗前，深深吸了一口清晨的空气。", "error_description": "错误：“吸了一个清晨的空气”。正确：“吸了一口清晨的空气”。吸气的量词应用“口”，不用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94779, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她感冒了，鼻子堵住了，用力也吸不出一点儿空气。", "corrected_sentence": "她感冒了，鼻子堵住了，用力也吸不进一点儿空气。", "error_description": "错误：“吸不出”。正确：“吸不进”。吸入空气是向体内进入，应用“进”；“吸出”方向相反，与“鼻子堵住”的语境不符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef72aa20-fe36-47c5-8a6c-d1cb07ec2aab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
