INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94780, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把气体或液体经口鼻引入体内；也指物体把别的东西引过来。", "primary_collocate": null, "pronunciation": "xī", "ipa": "ɕi˥", "syllable_count": 1, "sentences": [{"text": "这块磁铁能把铁钉吸起来。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海绵吸水很快。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条毛巾吸了很多水。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她闭上眼睛，吸了一口新鲜空气。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光把很多小虫吸过来了。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑色的衣服吸热，夏天穿着很热。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗帘吸了烟味，很难洗干净。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器可以把地上的灰吸走。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他蹲在河边，用管子吸水。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干土吸雨水，很快就不湿了。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吸了", "label": "体标"}, {"form": "吸过", "label": "体标"}, {"form": "吸吸", "label": "重叠"}], "register": "中性", "sense_fingerprint": "吸|动词|吸入体内或把别的东西引过来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60b8685b-8c93-4781-a5d8-5d5358d689c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = 