INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94783, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "abstract", "definition": "在先是比别的事更早。", "primary_collocate": null, "pronunciation": "zài xiān", "ipa": "tsai˥˩ ɕiɛn˥", "syllable_count": 2, "sentences": [{"text": "我把话说在先，迟到的人要自己付钱。", "target_word": "在先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们约定在先，你现在不能反悔。", "target_word": "在先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些事要说在先，免得以后大家吵架。", "target_word": "在先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他声明在先，这件事和他没有关系。", "target_word": "在先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做事情要把规矩讲在先。", "target_word": "在先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价钱谈在先，后面的事就好办了。", "target_word": "在先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把要求讲在先，学生做起来就容易。", "target_word": "在先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把丑话说在先，谁做错了都要改。", "target_word": "在先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁报名在先，谁就坐前排。", "target_word": "在先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合同里约定在先的事，双方都要遵守。", "target_word": "在先", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "时间上排在别的事前面，常说“说在先、约定在先”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd4c21aa-a6d3-4972-9722-723031958938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94783, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "在先", "is_correct": true, "explanation": "正确：在先，指时间上排在别的事前面，常说“说在先”“约定在先”。"}, {"text": "在线", "is_correct": false, "explanation": "xiàn（第四声）与 xiān（第一声）只有第二音节声调不同，意思是在网络上连接。"}, {"text": "再现", "is_correct": false, "explanation": "zàixiàn 与 zài xiān 第二音节声调不同，意思是再次出现。"}, {"text": "在乡", "is_correct": false, "explanation": "在乡（zài xiāng）与 zài xiān 只差韵尾 -ng 和 -n，意思是住在乡下、在家乡。"}], "explanations": {"在先": "正确：在先，指时间上排在别的事前面，常说“说在先”“约定在先”。", "在线": "xiàn（第四声）与 xiān（第一声）只有第二音节声调不同，意思是在网络上连接。", "再现": "zàixiàn 与 zài xiān 第二音节声调不同，意思是再次出现。", "在乡": "在乡（zài xiāng）与 zài xiān 只差韵尾 -ng 和 -n，意思是住在乡下、在家乡。"}, "sentence_index": null, "correct_answer": "在先"}, "level_3": {"options": [{"text": "在先", "is_correct": true, "explanation": "正确：“说在先”表示事先讲明，与句中“迟到的人要自己付钱”的规定相符。"}, {"text": "在后", "is_correct": false, "explanation": "语义：“在后”表示时间上靠后，与“事先讲明”的意思相反。"}, {"text": "在外", "is_correct": false, "explanation": "搭配：“在外”是方位词，“说在外”不成立。"}, {"text": "在里", "is_correct": false, "explanation": "搭配：“在里”是方位词，不能接在“说”后面表示讲明的时间。"}], "explanations": {"在先": "正确：“说在先”表示事先讲明，与句中“迟到的人要自己付钱”的规定相符。", "在后": "语义：“在后”表示时间上靠后，与“事先讲明”的意思相反。", "在外": "搭配：“在外”是方位词，“说在外”不成立。", "在里": "搭配：“在里”是方位词，不能接在“说”后面表示讲明的时间。"}, "sentence_index": 0, "correct_answer": "在先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议结束以后，我们在先讨论具体的细节。", "explanation": "这里应该用〈之后〉。“在先”指比别的事更早，会议结束后再讨论，时间顺序不对，应说“之后”。"}, {"text": "他先说了几句，在先又补充了一些内容。", "explanation": "这里应该用〈随后〉。“在先”指比别的事更早，这里说的是接着补充，时间顺序应用“随后”。"}, {"text": "我们在先吃饭，然后再说。", "explanation": "这里应该用〈先〉。“在先”不能放在动词前面直接修饰动词，“在先吃饭”不通顺，应说“先吃饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '607e29e9-b1d6-4274-a4c2-ecaae7dee8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94783, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在先", "is_correct": true, "explanation": "正确：“讲在先”表示事先讲明要求，与“学生做起来就容易”的意思相符。"}, {"text": "在后面", "is_correct": false, "explanation": "语义：“在后面”表示位置或时间靠后，与事先讲明要求的意思不符。"}, {"text": "在中间", "is_correct": false, "explanation": "语义：“在中间”指位置，不表示讲明的先后顺序。"}, {"text": "在下面", "is_correct": false, "explanation": "搭配：“在下面”是方位词，不能接在“讲”后面作时间上的说明。"}], "explanations": {"在先": "正确：“讲在先”表示事先讲明要求，与“学生做起来就容易”的意思相符。", "在后面": "语义：“在后面”表示位置或时间靠后，与事先讲明要求的意思不符。", "在中间": "语义：“在中间”指位置，不表示讲明的先后顺序。", "在下面": "搭配：“在下面”是方位词，不能接在“讲”后面作时间上的说明。"}, "sentence_index": 6, "correct_answer": "在先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明天的合同在先签，今天就不用急。", "explanation": "这里应该用〈提前〉。“在先”强调比别的事更早，说明天的合同签署时用“在先”与“明天”的时间关系说不通，应说“提前”。"}, {"text": "我们在先签了合同，然后才开始干活。", "explanation": "“在先”不能像“先”一样直接修饰动词，这里应该用“先”。"}, {"text": "我们签完合同，才把条款讲在先。", "explanation": "这里应该用〈讲明〉。“在先”指事先讲明，签完合同以后才讲，时间顺序相反，应说“讲明”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '607e29e9-b1d6-4274-a4c2-ecaae7dee8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94783, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在先约定，大家就不会误会。", "corrected_sentence": "他们先约定，大家就不会误会。", "error_description": "“在先”不能像“先”一样直接修饰动词，“在先约定”不通顺。这里多了“在”，应去掉“在”，改用“先”，说“他们先约定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '607e29e9-b1d6-4274-a4c2-ecaae7dee8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94783, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "合同里约定在先事，我们都要遵守。", "corrected_sentence": "合同里约定在先的事，我们都要遵守。", "error_description": "漏了“的”。“在先”修饰名词“事”时要用“在先的事”，漏掉“的”就不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '607e29e9-b1d6-4274-a4c2-ecaae7dee8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94784, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '607e29e9-b1d6-4274-a4c2-ecaae7dee8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
