INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94784, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指过去、从前，与“现在”相对。", "primary_collocate": null, "pronunciation": "zài xiān", "ipa": "tsai˥˩ ɕiɛn˥", "syllable_count": 2, "sentences": [{"text": "在先的计划太急了，后来我们放慢了速度。", "target_word": "在先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在先的工作在北京，后来才回到老家。", "target_word": "在先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在先的看法不对，现在改过来了。", "target_word": "在先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在先的交通很不方便，坐火车要两天。", "target_word": "在先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人常说，在先的生活很苦。", "target_word": "在先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在先的这条路很窄，现在宽多了。", "target_word": "在先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在先的身份是老师，现在做生意了。", "target_word": "在先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在先的通讯方式很简单，大家写信联系。", "target_word": "在先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她现在比在先的时候瘦了很多。", "target_word": "在先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在先的村子里没有电，大家晚上点油灯。", "target_word": "在先", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "指过去、从前，常与“现在”相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd4c21aa-a6d3-4972-9722-723031958938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94784, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "在先", "is_correct": true, "explanation": "正确：在先，指过去、从前，与“现在”相对。"}, {"text": "在线", "is_correct": false, "explanation": "xiàn（第四声）与 xiān（第一声）只有第二音节声调不同，意思是在网络上连接。"}, {"text": "再现", "is_correct": false, "explanation": "zàixiàn 与 zài xiān 第二音节声调不同，意思是再次出现。"}, {"text": "在乡", "is_correct": false, "explanation": "在乡（zài xiāng）与 zài xiān 只差韵尾 -ng 和 -n，意思是住在乡下、在家乡。"}], "explanations": {"在先": "正确：在先，指过去、从前，与“现在”相对。", "在线": "xiàn（第四声）与 xiān（第一声）只有第二音节声调不同，意思是在网络上连接。", "再现": "zàixiàn 与 zài xiān 第二音节声调不同，意思是再次出现。", "在乡": "在乡（zài xiāng）与 zài xiān 只差韵尾 -ng 和 -n，意思是住在乡下、在家乡。"}, "sentence_index": null, "correct_answer": "在先"}, "level_3": {"options": [{"text": "在先", "is_correct": true, "explanation": "正确：“在先的计划”指以前的计划，与后面“后来放慢了速度”的时间顺序相符。"}, {"text": "红色", "is_correct": false, "explanation": "搭配：“红色”是颜色，不能用来修饰“计划”表示时间先后，句意不通。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容天气或物体，不能修饰“计划”，句意不通。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：“便宜”说价钱低，不能修饰“计划”，与“太急了”的意思不通。"}], "explanations": {"在先": "正确：“在先的计划”指以前的计划，与后面“后来放慢了速度”的时间顺序相符。", "红色": "搭配：“红色”是颜色，不能用来修饰“计划”表示时间先后，句意不通。", "潮湿": "语义：“潮湿”形容天气或物体，不能修饰“计划”，句意不通。", "便宜": "语义：“便宜”说价钱低，不能修饰“计划”，与“太急了”的意思不通。"}, "sentence_index": 0, "correct_answer": "在先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天的交通在先很方便，大家都会坐车。", "explanation": "这里应该用〈将来〉。“在先”指过去的时间，不能用来说明明天的情况，表示将来应说“将来”或“以后”。"}, {"text": "明天我们在先出发，别迟到。", "explanation": "这里应该用〈将来〉。“在先”指过去的时间，不能用来说明明天才发生的事，应说“将来”或“以后”。"}, {"text": "下个月的天气在先会很热，我们要多带水。", "explanation": "这里应该用〈将来〉。“在先”指过去，不能说下个月的事，应说“将来”或“以后”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '607e29e9-b1d6-4274-a4c2-ecaae7dee8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94784, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在先", "is_correct": true, "explanation": "正确：“在先的身份”指过去的身份，与后面“现在做生意了”的对比相符。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容天气或物体，不能用来说一个人的身份。"}, {"text": "眼前", "is_correct": false, "explanation": "语义：“眼前”指当下，与“现在做生意了”重复且不构成对比。"}, {"text": "下午", "is_correct": false, "explanation": "搭配：“下午”是一天中的时段，不能用来表示身份的时间先后。"}], "explanations": {"在先": "正确：“在先的身份”指过去的身份，与后面“现在做生意了”的对比相符。", "潮湿": "语义：“潮湿”形容天气或物体，不能用来说一个人的身份。", "眼前": "语义：“眼前”指当下，与“现在做生意了”重复且不构成对比。", "下午": "搭配：“下午”是一天中的时段，不能用来表示身份的时间先后。"}, "sentence_index": 6, "correct_answer": "在先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "以后的学校在先会建得更大。", "explanation": "这里应该用〈将来〉。“在先”指过去，与“以后”“会”说的未来时间矛盾。"}, {"text": "明天的村子在先会通电，大家不用点油灯。", "explanation": "这里应该用〈将来〉。“在先”指过去的时间，不能用来说明明天才会通电的事，应说“将来”或“以后”。"}, {"text": "他很在先地看了我一眼，然后转过身去。", "explanation": "这里应该用〈仔细〉或〈认真〉。“在先”是表示时间的词，不能修饰“看”的方式，这里用“很在先地”不通顺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '607e29e9-b1d6-4274-a4c2-ecaae7dee8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她现在比在先时候胖了很多。", "corrected_sentence": "她现在比在先的时候胖了很多。", "error_description": "漏了“的”。“在先”修饰“时候”时要用“在先的时候”，漏掉“的”就不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '607e29e9-b1d6-4274-a4c2-ecaae7dee8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在先房子很小，现在大多了。", "corrected_sentence": "在先的房子很小，现在大多了。", "error_description": "漏了“的”。“在先”修饰名词“房子”时要说“在先的房子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '607e29e9-b1d6-4274-a4c2-ecaae7dee8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
