INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94787, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "姿势是身体摆出来的样子。", "primary_collocate": null, "pronunciation": "zī shì", "ipa": "tsɹ̩˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他睡觉的姿势很奇怪。", "target_word": "姿势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个姿势让我的腰很疼。", "target_word": "姿势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们正确的写字姿势。", "target_word": "姿势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照相时，她摆了一个好看的姿势。", "target_word": "姿势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你站的姿势不对，要把背挺直。", "target_word": "姿势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他保持着同一个姿势看书。", "target_word": "姿势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫用很可爱的姿势趴在窗边。", "target_word": "姿势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在泳池边的姿势很放松。", "target_word": "姿势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请换一个舒服的姿势坐着。", "target_word": "姿势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子坐在地上的姿势很可爱。", "target_word": "姿势", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "姿勢", "label": "繁体"}, {"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "身体摆出来的样子，如坐、站、睡的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4d8750f-33e3-4d0a-afc2-fdce50ccbd55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94787, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "姿势", "is_correct": true, "explanation": "姿势（zī shì）指身体摆出的样子，是本题的正确答案。"}, {"text": "私事", "is_correct": false, "explanation": "sī（第一声）与 zī（第一声）声母不同，意思是个人的事情，与身体的样子无关。"}, {"text": "只是", "is_correct": false, "explanation": "zhǐ（第三声）与 zī（第一声）声母和声调都不同，意思是仅仅。"}, {"text": "此事", "is_correct": false, "explanation": "cǐ（第三声）与 zī（第一声）声母和声调都不同，意思是这件事。"}], "explanations": {"姿势": "姿势（zī shì）指身体摆出的样子，是本题的正确答案。", "私事": "sī（第一声）与 zī（第一声）声母不同，意思是个人的事情，与身体的样子无关。", "只是": "zhǐ（第三声）与 zī（第一声）声母和声调都不同，意思是仅仅。", "此事": "cǐ（第三声）与 zī（第一声）声母和声调都不同，意思是这件事。"}, "sentence_index": null, "correct_answer": "姿势"}, "level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：价格指买卖时的钱数，睡觉没有价格，句子说不通。"}, {"text": "姿势", "is_correct": true, "explanation": "姿势：身体摆出的样子，与“睡觉的”搭配，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是身体的尺寸，不是睡觉时的样子，说“睡觉的身高”不通。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“睡觉的名字”不成立，睡觉的方式才能说奇怪。"}], "explanations": {"价格": "语义：价格指买卖时的钱数，睡觉没有价格，句子说不通。", "姿势": "姿势：身体摆出的样子，与“睡觉的”搭配，符合句意。", "身高": "体貌：身高是身体的尺寸，不是睡觉时的样子，说“睡觉的身高”不通。", "名字": "搭配：“睡觉的名字”不成立，睡觉的方式才能说奇怪。"}, "sentence_index": 0, "correct_answer": "姿势"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到好消息，他脸上露出了开心的姿势。", "explanation": "这里应该用〈表情〉。姿势指身体摆出的样子，脸上的神情要用表情。"}, {"text": "他跳高时的姿势很快，一下子就越过了横杆。", "explanation": "这里应该用〈动作〉。姿势指身体的样子，不能说“很快”，形容快慢要用动作。"}, {"text": "这首歌的姿势很快，大家跟着打起了拍子。", "explanation": "这里应该用〈节拍〉。姿势不能用来形容音乐的快慢，要用节拍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94787, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "姿势", "is_correct": true, "explanation": "姿势（zī shì）指身体摆出的样子，是本题的正确答案。"}, {"text": "制式", "is_correct": false, "explanation": "zhì（第四声）与 zī（第一声）声母不同，声调也不同，意思是统一的规格或样式。"}, {"text": "私室", "is_correct": false, "explanation": "sī（第一声）与 zī（第一声）声母不同，意思是个人使用的房间。"}, {"text": "记事", "is_correct": false, "explanation": "jì（第四声）与 zī（第一声）声母不同，声调也不同，意思是记录事情。"}], "explanations": {"姿势": "姿势（zī shì）指身体摆出的样子，是本题的正确答案。", "制式": "zhì（第四声）与 zī（第一声）声母不同，声调也不同，意思是统一的规格或样式。", "私室": "sī（第一声）与 zī（第一声）声母不同，意思是个人使用的房间。", "记事": "jì（第四声）与 zī（第一声）声母不同，声调也不同，意思是记录事情。"}, "sentence_index": null, "correct_answer": "姿势"}, "level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：年龄是人活了多少岁，小猫趴着的样子不能用年龄来形容，句子说不通。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“很可爱的考试”不成立，考试是一种活动，不能描述小猫趴着的样子。"}, {"text": "姿势", "is_correct": true, "explanation": "姿势：身体摆出的样子，“很可爱的姿势”描述小猫趴在窗边的样子，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是闻到或尝到的感觉，“很可爱的味道”不能描述小猫趴着的样子。"}], "explanations": {"年龄": "语义：年龄是人活了多少岁，小猫趴着的样子不能用年龄来形容，句子说不通。", "考试": "搭配：“很可爱的考试”不成立，考试是一种活动，不能描述小猫趴着的样子。", "姿势": "姿势：身体摆出的样子，“很可爱的姿势”描述小猫趴在窗边的样子，符合句意。", "味道": "语义：味道是闻到或尝到的感觉，“很可爱的味道”不能描述小猫趴着的样子。"}, "sentence_index": 6, "correct_answer": "姿势"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们应该从不同的姿势看问题。", "explanation": "这里应该用〈角度〉。姿势指身体摆出的样子，看问题的立场和方面要用角度，不能说“从不同的姿势看问题”。"}, {"text": "这幅画的姿势很鲜艳。", "explanation": "这里应该用〈颜色〉。姿势指身体摆出的样子，画作的色彩鲜艳要用颜色，不能说“姿势很鲜艳”。"}, {"text": "这道菜的姿势很鲜。", "explanation": "这里应该用〈味道〉。姿势指身体的样子，菜的滋味鲜美要用味道，不能说“菜的姿势很鲜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94787, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一直保持这块姿势，一动不动。", "corrected_sentence": "她一直保持这种姿势，一动不动。", "error_description": "量词错误：“姿势”前应用“种”或“个”，“块”用于块状物，不能说“这块姿势”，应改为“这种姿势”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94787, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她摆姿势得很自然。", "corrected_sentence": "她摆姿势摆得很自然。", "error_description": "补语错误：带“得”补语时，动词要重复，应说“摆姿势摆得很自然”，漏掉动词“摆”就是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
