INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94788, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体呈现出的样子或动作的形态。", "primary_collocate": null, "pronunciation": "zī shì", "ipa": "tsɹ̩˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "运动员起跑的姿势非常标准。", "target_word": "姿势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瑜伽老师在纠正大家的姿势。", "target_word": "姿势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用跪着的姿势给老人倒茶。", "target_word": "姿势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打太极拳时，姿势要慢而稳。", "target_word": "姿势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间坐着，姿势不好会伤脖子。", "target_word": "姿势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们练习跳水的第一个姿势。", "target_word": "姿势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家请模特保持这个姿势不要动。", "target_word": "姿势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用优美的姿势跳进了水里。", "target_word": "姿势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拍照时，他总是摆同样的姿势。", "target_word": "姿势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，抱孩子的姿势要正确。", "target_word": "姿势", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "姿勢", "label": "繁体"}, {"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "身体呈现的样子或动作的形态，如运动、做事时的动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4d8750f-33e3-4d0a-afc2-fdce50ccbd55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94788, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "姿势", "is_correct": true, "explanation": "姿势（zī shì）指身体呈现的样子或动作的形态，是本题的正确答案。"}, {"text": "制式", "is_correct": false, "explanation": "zhì（第四声）与 zī（第一声）声母不同，声调也不同，意思是统一的规格或样式。"}, {"text": "此事", "is_correct": false, "explanation": "cǐ（第三声）与 zī（第一声）声母和声调都不同，意思是这件事。"}, {"text": "私室", "is_correct": false, "explanation": "sī（第一声）与 zī（第一声）声母不同，意思是个人使用的房间。"}], "explanations": {"姿势": "姿势（zī shì）指身体呈现的样子或动作的形态，是本题的正确答案。", "制式": "zhì（第四声）与 zī（第一声）声母不同，声调也不同，意思是统一的规格或样式。", "此事": "cǐ（第三声）与 zī（第一声）声母和声调都不同，意思是这件事。", "私室": "sī（第一声）与 zī（第一声）声母不同，意思是个人使用的房间。"}, "sentence_index": null, "correct_answer": "姿势"}, "level_3": {"options": [{"text": "口音", "is_correct": false, "explanation": "语义：口音是说话的腔调，起跑的动作不会有口音，句子说不通。"}, {"text": "姿势", "is_correct": true, "explanation": "姿势：身体呈现的动作形态，与“起跑的”搭配，符合句意。"}, {"text": "字迹", "is_correct": false, "explanation": "搭配：“起跑”不能与“字迹”搭配，字迹与跑步无关。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是通讯工具，起跑的动作不能说“手机非常标准”。"}], "explanations": {"口音": "语义：口音是说话的腔调，起跑的动作不会有口音，句子说不通。", "姿势": "姿势：身体呈现的动作形态，与“起跑的”搭配，符合句意。", "字迹": "搭配：“起跑”不能与“字迹”搭配，字迹与跑步无关。", "手机": "语义：手机是通讯工具，起跑的动作不能说“手机非常标准”。"}, "sentence_index": 0, "correct_answer": "姿势"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑步的姿势很便宜，只要五块钱。", "explanation": "这里应该用〈价格〉。姿势指身体呈现的样子，钱的多少要用价格，不能说“姿势很便宜”。"}, {"text": "他唱歌的姿势很洪亮。", "explanation": "这里应该用〈声音〉。姿势不能形容洪亮，洪亮的是声音。"}, {"text": "这篇文章的姿势很长，足足有十页。", "explanation": "这里应该用〈篇幅〉。姿势指身体呈现的样子，文章的长短和页数要用篇幅，不能说“姿势很长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94788, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "姿势", "is_correct": true, "explanation": "姿势（zī shì）指身体呈现的样子或动作的形态，是本题的正确答案。"}, {"text": "私事", "is_correct": false, "explanation": "sī（第一声）与 zī（第一声）声母不同，意思是个人的事情，与身体的样子无关。"}, {"text": "只是", "is_correct": false, "explanation": "zhǐ（第三声）与 zī（第一声）声母和声调都不同，意思是仅仅。"}, {"text": "记事", "is_correct": false, "explanation": "jì（第四声）与 zī（第一声）声母不同，声调也不同，意思是记录事情。"}], "explanations": {"姿势": "姿势（zī shì）指身体呈现的样子或动作的形态，是本题的正确答案。", "私事": "sī（第一声）与 zī（第一声）声母不同，意思是个人的事情，与身体的样子无关。", "只是": "zhǐ（第三声）与 zī（第一声）声母和声调都不同，意思是仅仅。", "记事": "jì（第四声）与 zī（第一声）声母不同，声调也不同，意思是记录事情。"}, "sentence_index": null, "correct_answer": "姿势"}, "level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：味道是闻到或尝到的感觉，不能“保持这个味道不要动”。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“保持”不接“考试”，画家与模特的场景里没有考试。"}, {"text": "姿势", "is_correct": true, "explanation": "姿势：模特要保持的身体样子，与“保持…不要动”相符。"}, {"text": "字数", "is_correct": false, "explanation": "语义：字数是文字的多少，模特不能“保持这个字数不要动”。"}], "explanations": {"味道": "语义：味道是闻到或尝到的感觉，不能“保持这个味道不要动”。", "考试": "搭配：“保持”不接“考试”，画家与模特的场景里没有考试。", "姿势": "姿势：模特要保持的身体样子，与“保持…不要动”相符。", "字数": "语义：字数是文字的多少，模特不能“保持这个字数不要动”。"}, "sentence_index": 6, "correct_answer": "姿势"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生说，他的姿势增加了五公斤。", "explanation": "这里应该用〈体重〉。姿势指身体的样子，不能增加斤两，表示重量的增加要用体重。"}, {"text": "医生说，这个孩子的姿势是三岁。", "explanation": "这里应该用〈年龄〉。姿势指身体的样子，不能表示岁数，表示几岁要用年龄。"}, {"text": "医生说，他的姿势已经愈合。", "explanation": "这里应该用〈伤口〉。姿势指身体的样子，不会愈合，伤口愈合要用伤口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教练要求他保持这件姿势。", "corrected_sentence": "教练要求他保持这种姿势。", "error_description": "量词错误：“姿势”应用“种”或“个”，“件”用于衣物、事情等，不能说“这件姿势”，应改为“这种姿势”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她跑步的姿势得很标准。", "corrected_sentence": "她跑步的姿势很标准。", "error_description": "结构助词误用：“得”不能直接接在名词“姿势”之后作补语，应删去“得”，说“她跑步的姿势很标准”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
