INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94790, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人在学校接受教育的经历，通常指最高的学习阶段。", "primary_collocate": null, "pronunciation": "xué lì", "ipa": "ɕɥɛ˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "他的学历是大学本科。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作要求硕士学历。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有博士学历，工作很好。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司看重学历，也看重经验。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的最高学历是什么？", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学历越高，工资不一定越高。", "target_word": "学历", "complexity_tier": "T3", "furigana": "xué lì", "sentence_source": "generated"}, {"text": "他想提高学历，所以回学校读书。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面试时，老板先问我的学历。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的学历不高，但是很努力。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "简历上要写清楚学历。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高学历", "label": "复合"}, {"form": "低学历", "label": "复合"}], "register": "中性", "sense_fingerprint": "接受教育的最高阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21944ec0-25a1-4e3d-9f77-8f4f59681f20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94790, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学历", "is_correct": true, "explanation": "学历：受教育的最高阶段，与“大学本科”相合。"}, {"text": "学费", "is_correct": false, "explanation": "语义：“学费”是交的钱，不能说“学费是大学本科”。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”用数字表示，不能说“年龄是大学本科”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，和“大学本科”毫不相关。"}], "explanations": {"学历": "学历：受教育的最高阶段，与“大学本科”相合。", "学费": "语义：“学费”是交的钱，不能说“学费是大学本科”。", "年龄": "搭配：“年龄”用数字表示，不能说“年龄是大学本科”。", "体重": "语义：“体重”指身体的重量，和“大学本科”毫不相关。"}, "sentence_index": 0, "correct_answer": "学历"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的学历很快，一个上午就做完了。", "explanation": "这里应该用〈效率〉。学历指受教育的阶段，说做事快慢要用效率。"}, {"text": "他学历很广，去过很多国家。", "explanation": "这里应该用〈见识〉。学历指受教育的阶段，说见闻广要用见识。"}, {"text": "他的学历足足有三页纸，每份工作都写在上面。", "explanation": "这里应该用〈履历〉。履历指个人的工作经过，写下做过的工作要用履历；学历只指受教育的阶段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学历", "is_correct": true, "explanation": "学历：可以提高的受教育水平，与“回学校读书”相合。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：“外貌”指外形，与“回学校读书”无关，不能为提高外貌而读书。"}, {"text": "脸色", "is_correct": false, "explanation": "配价：“提高”要求可以提升的水平或能力，“脸色”不能说提高。"}, {"text": "嗓子", "is_correct": false, "explanation": "配价：“嗓子”不是可以提高的对象，“提高嗓子”不成立。"}], "explanations": {"学历": "学历：可以提高的受教育水平，与“回学校读书”相合。", "外貌": "体貌：“外貌”指外形，与“回学校读书”无关，不能为提高外貌而读书。", "脸色": "配价：“提高”要求可以提升的水平或能力，“脸色”不能说提高。", "嗓子": "配价：“嗓子”不是可以提高的对象，“提高嗓子”不成立。"}, "sentence_index": 6, "correct_answer": "学历"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的学历很老，在公司干了十年。", "explanation": "这里应该用〈资历〉。学历指受教育的阶段，说工作年限和地位要用资历。"}, {"text": "他学历很深，什么都懂。", "explanation": "这里应该用〈学问〉。学历指受教育的阶段，说知识深要用学问。"}, {"text": "这座老桥的学历很长，有几百年了。", "explanation": "这里应该用〈历史〉。学历指受教育的阶段，说桥梁的年代要用历史。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他拿到了一颗硕士学历。", "corrected_sentence": "他拿到了硕士学历。", "error_description": "“颗”用于粒状的小东西，学历不能用“颗”计量，去掉量词即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的一位学历高得很，同事都很佩服。", "corrected_sentence": "她的学历高得很，同事都很佩服。", "error_description": "“位”用于指人，学历是抽象名词，不能用“位”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
