INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94791, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "官网是一家店或学校自己做的网页。", "primary_collocate": null, "pronunciation": "guān wǎng", "ipa": "kwan˥ wɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家小店有自己的官网，可以在线点菜。", "target_word": "官网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校官网上有老师的电话。", "target_word": "官网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先看了面包店的官网，再去买东西。", "target_word": "官网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官网上说，今天下午书店不开门。", "target_word": "官网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的官网有菜单和照片。", "target_word": "官网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买衣服以前，我常常先上官网看看。", "target_word": "官网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在官网给我报了画画班。", "target_word": "官网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个官网没有英文，我看不懂。", "target_word": "官网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道那家花店的官网是什么吗？", "target_word": "官网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的官网很漂亮，信息也很多。", "target_word": "官网", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "官网首页", "label": "复合"}, {"form": "官網", "label": "繁体"}], "register": "中性", "sense_fingerprint": "店铺或学校自己做的、代表自己的网页", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73c1303b-ce7a-48fa-ac4b-097cecf36469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94791, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "官网", "is_correct": true, "explanation": "官网 guānwǎng 指店铺或学校自己做的网页，是正确答案。"}, {"text": "观望", "is_correct": false, "explanation": "观望 guānwàng 与 guānwǎng 第二音节声调不同（第四声），意思是观察等待、不表态。"}, {"text": "管网", "is_correct": false, "explanation": "管网 guǎnwǎng 与 guānwǎng 第一音节声调不同（第三声），意思是管道网络。"}, {"text": "光网", "is_correct": false, "explanation": "光网 guāngwǎng 与 guānwǎng 第一音节韵母不同（-ang 与 -an），意思是光纤网络。"}], "explanations": {"官网": "官网 guānwǎng 指店铺或学校自己做的网页，是正确答案。", "观望": "观望 guānwàng 与 guānwǎng 第二音节声调不同（第四声），意思是观察等待、不表态。", "管网": "管网 guǎnwǎng 与 guānwǎng 第一音节声调不同（第三声），意思是管道网络。", "光网": "光网 guāngwǎng 与 guānwǎng 第一音节韵母不同（-ang 与 -an），意思是光纤网络。"}, "sentence_index": null, "correct_answer": "官网"}, "level_3": {"options": [{"text": "官网", "is_correct": true, "explanation": "官网指店铺或学校自己做的网页，“有自己的官网”可以在线点菜，符合语境。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话只能打电话点菜，不能在线点菜。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是电器，不能用来在线点菜，句子不通。"}, {"text": "招牌", "is_correct": false, "explanation": "搭配：“在线点菜”需要网络平台作载体，招牌是实体店的标牌，不能在线点菜。"}], "explanations": {"官网": "官网指店铺或学校自己做的网页，“有自己的官网”可以在线点菜，符合语境。", "电话": "语义：电话只能打电话点菜，不能在线点菜。", "冰箱": "语义：冰箱是电器，不能用来在线点菜，句子不通。", "招牌": "搭配：“在线点菜”需要网络平台作载体，招牌是实体店的标牌，不能在线点菜。"}, "sentence_index": 0, "correct_answer": "官网"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在官网上写了自己的兴趣爱好。", "explanation": "这里应该用〈主页〉。官网指店铺或学校自己做的网页，个人的兴趣爱好应放在个人主页上。"}, {"text": "我在官网上给女朋友写了一封情书。", "explanation": "这里应该用〈信纸〉。官网是店铺或学校自己做的网页，不是写情书的地方，写情书要用信纸。"}, {"text": "我每天晚上都进官网和朋友说话。", "explanation": "这里应该用〈聊天室〉。官网是店铺或学校发布信息的网页，不是和朋友聊天的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94791, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "官网", "is_correct": true, "explanation": "官网指店铺或学校自己做的网页，报名可以在官网上完成，符合语境。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市是卖东西的地方，不能报名画画班。"}, {"text": "理发店", "is_correct": false, "explanation": "语义：理发店是理发的地方，不办理画画班，句子不通。"}, {"text": "菜场", "is_correct": false, "explanation": "配价：“报”要求报名的对象是班级或机构，菜场不是可以报名的机构。"}], "explanations": {"官网": "官网指店铺或学校自己做的网页，报名可以在官网上完成，符合语境。", "超市": "语义：超市是卖东西的地方，不能报名画画班。", "理发店": "语义：理发店是理发的地方，不办理画画班，句子不通。", "菜场": "配价：“报”要求报名的对象是班级或机构，菜场不是可以报名的机构。"}, "sentence_index": 6, "correct_answer": "官网"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每周在官网上写一篇游记。", "explanation": "这里应该用〈博客〉。官网指店铺或学校自己做的网页，个人写游记要用博客。"}, {"text": "我在官网上找到了失散多年的朋友。", "explanation": "这里应该用〈社交软件〉。官网是店铺或学校自己做的网页，不是用来交朋友的地方。"}, {"text": "我把今天的事写进官网里。", "explanation": "这里应该用〈日记本〉。官网是店铺或学校的网页，不是记录个人心事的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94791, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家书店有一台官网，可以在线买书。", "corrected_sentence": "这家书店有一个官网，可以在线买书。", "error_description": "量词错误：书店的官网应用“个”，不能说“台”（“台”用于机器、电器）。应说“一个官网”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94791, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家面包店的官网的有新品介绍。", "corrected_sentence": "这家面包店的官网有新品介绍。", "error_description": "“的”多余：“官网”后面不应再加“的”。应说“这家面包店的官网有新品介绍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
