INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94792, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机构、企业或产品的官方网站。", "primary_collocate": null, "pronunciation": "guān wǎng", "ipa": "kwan˥ wɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "你可以在学校官网上查看招生信息。", "target_word": "官网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的官网刚刚更新了新产品。", "target_word": "官网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的价格请看官网，别听别人说。", "target_word": "官网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在官网下载了这个软件。", "target_word": "官网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个博物馆的官网可以提前买票。", "target_word": "官网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想知道比赛时间，就去球队官网看看。", "target_word": "官网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官网上写着，这家银行周末不营业。", "target_word": "官网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕买到假货，所以只在品牌官网下单。", "target_word": "官网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请登录医院官网预约挂号。", "target_word": "官网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把这款游戏的官网发给你了。", "target_word": "官网", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "官方网站", "label": "全称"}, {"form": "官網", "label": "繁体"}], "register": "中性", "sense_fingerprint": "机构、企业或产品的官方网站", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73c1303b-ce7a-48fa-ac4b-097cecf36469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94792, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "官网", "is_correct": true, "explanation": "官网 guānwǎng 指机构、企业或产品的官方网站，是正确答案。"}, {"text": "观望", "is_correct": false, "explanation": "观望 guānwàng 与 guānwǎng 第二音节声调不同（第四声），意思是观察等待、不表态。"}, {"text": "管网", "is_correct": false, "explanation": "管网 guǎnwǎng 与 guānwǎng 第一音节声调不同（第三声），意思是管道网络。"}, {"text": "光网", "is_correct": false, "explanation": "光网 guāngwǎng 与 guānwǎng 第一音节韵母不同（-ang 与 -an），意思是光纤网络。"}], "explanations": {"官网": "官网 guānwǎng 指机构、企业或产品的官方网站，是正确答案。", "观望": "观望 guānwàng 与 guānwǎng 第二音节声调不同（第四声），意思是观察等待、不表态。", "管网": "管网 guǎnwǎng 与 guānwǎng 第一音节声调不同（第三声），意思是管道网络。", "光网": "光网 guāngwǎng 与 guānwǎng 第一音节韵母不同（-ang 与 -an），意思是光纤网络。"}, "sentence_index": null, "correct_answer": "官网"}, "level_3": {"options": [{"text": "官网", "is_correct": true, "explanation": "官网指官方网站，“学校官网上”可以查看招生信息，符合语境。"}, {"text": "网店", "is_correct": false, "explanation": "语义：网店是卖东西的网上店铺，不发布学校的招生信息。"}, {"text": "食堂", "is_correct": false, "explanation": "搭配：“查看招生信息”的载体一般是网站、公告，食堂不能作为发布信息的地方。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是教学用书，不会在上面查看招生信息。"}], "explanations": {"官网": "官网指官方网站，“学校官网上”可以查看招生信息，符合语境。", "网店": "语义：网店是卖东西的网上店铺，不发布学校的招生信息。", "食堂": "搭配：“查看招生信息”的载体一般是网站、公告，食堂不能作为发布信息的地方。", "课本": "语义：课本是教学用书，不会在上面查看招生信息。"}, "sentence_index": 0, "correct_answer": "官网"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在官网上写作业，写到很晚。", "explanation": "这里应该用〈练习本〉。官网是机构、企业或产品的官方网站，不是用来写作业的地方。"}, {"text": "我在官网上拍了一张自拍。", "explanation": "这里应该用〈相机〉。官网是机构、企业或产品的官方网站，不能用来拍照，拍照要用相机。"}, {"text": "我每天晚上都进官网和朋友聊天。", "explanation": "这里应该用〈聊天室〉。官网是发布信息和服务的官方网站，不是朋友聊天的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "官网", "is_correct": true, "explanation": "官网是官方网站，银行在官网上公布营业时间，符合语境。"}, {"text": "存折", "is_correct": false, "explanation": "语义：存折是记录存取款的本子，不会写银行的营业时间。"}, {"text": "发票", "is_correct": false, "explanation": "语义：发票是购买凭证，不会写银行是否营业。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：月亮上不会写字，不能作为“写着”的载体。"}], "explanations": {"官网": "官网是官方网站，银行在官网上公布营业时间，符合语境。", "存折": "语义：存折是记录存取款的本子，不会写银行的营业时间。", "发票": "语义：发票是购买凭证，不会写银行是否营业。", "月亮": "搭配：月亮上不会写字，不能作为“写着”的载体。"}, "sentence_index": 6, "correct_answer": "官网"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天在官网上刷短视频，停不下来。", "explanation": "这里应该用〈手机应用〉。官网是机构、企业或产品的官方网站，刷短视频要用手机应用。"}, {"text": "我在官网上找到了失散多年的朋友。", "explanation": "这里应该用〈社交软件〉。官网是机构、企业或产品的官方网站，不是用来交朋友的地方。"}, {"text": "我把全家的照片都传到官网里。", "explanation": "这里应该用〈相册〉。官网是官方网站，不用来存放家人的照片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司有一台官网，上面有新产品。", "corrected_sentence": "这家公司有一个官网，上面有新产品。", "error_description": "量词错误：官网是网站，应用“个”，不能说“台”（“台”用于机器、电器）。应说“一个官网”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学校的官网的很漂亮。", "corrected_sentence": "我们学校的官网很漂亮。", "error_description": "“的”多余：“官网”后面不应再加“的”，“官网很漂亮”才对。应说“我们学校的官网很漂亮”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f15f862-54ec-4f7c-b9bf-4afd8bb7ebdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94793, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94793, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94793, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "家伙是不太客气地叫一个人。", "primary_collocate": null, "pronunciation": "jiā huo", "ipa": "tɕja˥ xwo˩", "syllable_count": 2, "sentences": [{"text": "那个家伙一直站在门口，不知道想做什么。", "target_word": "家伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这家伙，怎么又把我的书弄丢了？", "target_word": "家伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不认识这个家伙，让他走开。", "target_word": "家伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家伙说话太难听，我不想理他。", "target_word": "家伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天来的那个家伙又来了，找老板要钱。", "target_word": "家伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家伙老是借钱不还，真让人生气。", "target_word": "家伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个家伙一点也不客气，坐下就吃。", "target_word": "家伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别跟那种家伙说话，他只会骗人。", "target_word": "家伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口有个陌生的家伙，一直看着我们。", "target_word": "家伙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们这些家伙，吵了一晚上，让人怎么睡？", "target_word": "家伙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "傢伙", "label": "繁体"}], "register": "口语", "sense_fingerprint": "不太客气地称呼某个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccaa5f06-74fd-450d-9e5c-c87f845eb06a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94793, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家伙", "is_correct": true, "explanation": "正确：指人，带有不太客气的口气，符合“一直站在门口”的描述。"}, {"text": "雕像", "is_correct": false, "explanation": "语义：雕像不会“想做什么”，与后半句矛盾。"}, {"text": "柜子", "is_correct": false, "explanation": "语义：柜子没有想法，不能“不知道想做什么”，与后半句矛盾。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子没有想法，不能“不知道想做什么”。"}], "explanations": {"家伙": "正确：指人，带有不太客气的口气，符合“一直站在门口”的描述。", "雕像": "语义：雕像不会“想做什么”，与后半句矛盾。", "柜子": "语义：柜子没有想法，不能“不知道想做什么”，与后半句矛盾。", "影子": "语义：影子没有想法，不能“不知道想做什么”。"}, "sentence_index": 0, "correct_answer": "家伙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "欢迎您来我家，这家伙请坐。", "explanation": "这里把“家伙”当作对客人的礼貌称呼，但它是不太客气地叫人，不能对客人这样说，应该用〈先生〉。"}, {"text": "王校长是一位受人尊敬的家伙。", "explanation": "“家伙”是不太客气地叫人，不能和“受人尊敬的”“一位”这样郑重的说法一起用，这里应该用〈人〉。"}, {"text": "请各位家伙在这里签名，谢谢合作。", "explanation": "这是礼貌的正式请求，“家伙”不太客气，不能这样称呼大家，这里应该用〈来宾〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94793, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家伙", "is_correct": true, "explanation": "正确：指人，带有不太客气的口气，符合“一点也不客气”的语气。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能坐下吃饭，与句意不符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不会坐下，也不会吃东西。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会坐下吃东西，与句意不符。"}], "explanations": {"家伙": "正确：指人，带有不太客气的口气，符合“一点也不客气”的语气。", "窗户": "语义：窗户不能坐下吃饭，与句意不符。", "空气": "语义：空气不会坐下，也不会吃东西。", "石头": "语义：石头不会坐下吃东西，与句意不符。"}, "sentence_index": 6, "correct_answer": "家伙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个家伙是一盏灯，夜里很亮。", "explanation": "这里把“家伙”用来指灯，但它只指人，不能指物件，应该用〈灯〉这类名词。"}, {"text": "尊敬的各位家伙，欢迎大家参加今天的会议。", "explanation": "这里把“家伙”当作郑重的称呼来用，但它表示不太客气地叫人，与“尊敬的”冲突，应该用〈先生〉。"}, {"text": "你们这些家伙是一片云，很白很轻。", "explanation": "这里把“家伙”用来指云，但它只指人，不能指天上的云，应该用〈云朵〉这类名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94793, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋里坐着三家伙，一直不说话。", "corrected_sentence": "屋里坐着三个家伙，一直不说话。", "error_description": "错误：数词“三”与名词“家伙”之间漏掉了量词“个”。正确：应说“三个家伙”，数词后面要加量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94793, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天有一张家伙来店里偷东西。", "corrected_sentence": "昨天有一个家伙来店里偷东西。", "error_description": "量词错误：指人的“家伙”应用“个”，“张”用于平面的物件，不能用于人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
