INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94796, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "佛教僧人居住和供奉佛像的场所。", "primary_collocate": null, "pronunciation": "sì", "ipa": "sɨ˥˩", "syllable_count": 1, "sentences": [{"text": "他在山上的寺里住了三年。", "target_word": "寺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "寺里的和尚每天早上很早起床。", "target_word": "寺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座寺里有一尊很大的佛像。", "target_word": "寺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位和尚住在山后面的寺里。", "target_word": "寺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "寺里有一间房子放着很多佛像。", "target_word": "寺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候在这座寺里长大。", "target_word": "寺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座寺不大，只住着五个和尚。", "target_word": "寺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "寺里的师父教他读书。", "target_word": "寺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边有一座寺，里面有三个和尚。", "target_word": "寺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和尚们在寺里吃饭、睡觉、念经。", "target_word": "寺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "寺院", "label": "复合词"}], "register": "中性", "sense_fingerprint": "和尚居住、供奉佛像的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c88eb55d-87b9-4467-ab1d-de538215c096') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94796, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "寺", "is_correct": true, "explanation": "寺（sì）指僧人居住和供奉佛像的场所，是正确答案。"}, {"text": "是", "is_correct": false, "explanation": "sh 与 s 声母不同，声调相同，意思是“是”。"}, {"text": "死", "is_correct": false, "explanation": "sǐ（第三声）与 sì（第四声）声调不同，意思是“死亡”。"}, {"text": "室", "is_correct": false, "explanation": "shì 与 sì 声母不同（sh 与 s），意思是“房间”。"}, {"text": "世", "is_correct": false, "explanation": "shì 与 sì 声母不同（sh 与 s），意思是“世界”。"}, {"text": "丝", "is_correct": false, "explanation": "sī（第一声）与 sì（第四声）声调不同，意思是“丝线”。"}], "explanations": {"寺": "寺（sì）指僧人居住和供奉佛像的场所，是正确答案。", "是": "sh 与 s 声母不同，声调相同，意思是“是”。", "死": "sǐ（第三声）与 sì（第四声）声调不同，意思是“死亡”。", "室": "shì 与 sì 声母不同（sh 与 s），意思是“房间”。", "世": "shì 与 sì 声母不同（sh 与 s），意思是“世界”。", "丝": "sī（第一声）与 sì（第四声）声调不同，意思是“丝线”。"}, "sentence_index": null, "correct_answer": "寺"}, "level_3": {"options": [{"text": "寺", "is_correct": true, "explanation": "“寺”是僧人居住的场所，可以说“住在寺里”，与“住了三年”相合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是放食物的电器，人不能住在里面。"}, {"text": "抽屉", "is_correct": false, "explanation": "语义：抽屉是放东西的小空间，人不能住在里面，与“住了三年”冲突。"}, {"text": "信封", "is_correct": false, "explanation": "搭配：“住”要求能居住的空间，不说“住在信封里”。"}], "explanations": {"寺": "“寺”是僧人居住的场所，可以说“住在寺里”，与“住了三年”相合。", "冰箱": "语义：冰箱是放食物的电器，人不能住在里面。", "抽屉": "语义：抽屉是放东西的小空间，人不能住在里面，与“住了三年”冲突。", "信封": "搭配：“住”要求能居住的空间，不说“住在信封里”。"}, "sentence_index": 0, "correct_answer": "寺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那位修女住在山后面的寺里。", "explanation": "这里应该用〈修道院〉。寺是佛教僧人的住所，修女住的地方叫修道院。"}, {"text": "囚犯每天在寺里服刑。", "explanation": "这里应该用〈监狱〉。寺是佛教僧人居住的场所，囚犯服刑要在监狱。"}, {"text": "那位道士住在山后面的寺里。", "explanation": "这里应该用〈道观〉。寺是佛教的场所，道士修行的地方叫道观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94796, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "寺", "is_correct": true, "explanation": "寺（sì）指僧人居住和供奉佛像的场所，是正确答案。"}, {"text": "思", "is_correct": false, "explanation": "sī（第一声）与 sì（第四声）声调不同，意思是“思考”。"}, {"text": "市", "is_correct": false, "explanation": "sh 与 s 声母不同，声调相同，意思是“城市”。"}, {"text": "试", "is_correct": false, "explanation": "sh 与 s 声母不同，声调相同，意思是“尝试”。"}, {"text": "私", "is_correct": false, "explanation": "sī（第一声）与 sì（第四声）声调不同，意思是“私人”。"}, {"text": "事", "is_correct": false, "explanation": "shì 与 sì 声母不同（sh 与 s），意思是“事情”。"}], "explanations": {"寺": "寺（sì）指僧人居住和供奉佛像的场所，是正确答案。", "思": "sī（第一声）与 sì（第四声）声调不同，意思是“思考”。", "市": "sh 与 s 声母不同，声调相同，意思是“城市”。", "试": "sh 与 s 声母不同，声调相同，意思是“尝试”。", "私": "sī（第一声）与 sì（第四声）声调不同，意思是“私人”。", "事": "shì 与 sì 声母不同（sh 与 s），意思是“事情”。"}, "sentence_index": null, "correct_answer": "寺"}, "level_3": {"options": [{"text": "寺", "is_correct": true, "explanation": "“寺”是僧人居住的建筑，与“只住着五个和尚”相合。"}, {"text": "桥", "is_correct": false, "explanation": "语义：桥是通行的通道，不能住人，与“只住着五个和尚”冲突。"}, {"text": "石碑", "is_correct": false, "explanation": "配价：“住着”要求能容纳人的处所，石碑是刻字的石板，无法住人。"}, {"text": "雕像", "is_correct": false, "explanation": "语义：雕像是雕刻的人像或物像，不能住着五个和尚。"}], "explanations": {"寺": "“寺”是僧人居住的建筑，与“只住着五个和尚”相合。", "桥": "语义：桥是通行的通道，不能住人，与“只住着五个和尚”冲突。", "石碑": "配价：“住着”要求能容纳人的处所，石碑是刻字的石板，无法住人。", "雕像": "语义：雕像是雕刻的人像或物像，不能住着五个和尚。"}, "sentence_index": 6, "correct_answer": "寺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人每天在寺里干活。", "explanation": "这里应该用〈工厂〉。寺是佛教场所，工人干活要去工厂。"}, {"text": "职员每天在寺里办公。", "explanation": "这里应该用〈公司〉。寺是佛教场所，职员上班办公要去公司或办公室，不在寺里。"}, {"text": "县官每天在寺里处理公务。", "explanation": "这里应该用〈衙门〉。寺是宗教场所，官员办公要去衙门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条寺里住着一位老和尚。", "corrected_sentence": "这座寺里住着一位老和尚。", "error_description": "量词错误：“寺”是建筑，量词应用“座”，说“这座寺”，不说“这条寺”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94796, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他寺里学会了念经。", "corrected_sentence": "他在寺里学会了念经。", "error_description": "介词缺失：表示处所的“寺里”前要加介词“在”，应说“在寺里”，不说“寺里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94798, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大生产", "is_correct": true, "explanation": "反义：小生产规模小，大生产规模大，两者在此义上相对。"}, {"text": "农业", "is_correct": false, "explanation": "无关：农业是行业名称，与小生产不构成反义。"}, {"text": "商品", "is_correct": false, "explanation": "无关：商品是产品，不是生产方式，没有反义关系。"}, {"text": "学校", "is_correct": false, "explanation": "无关：学校是机构，与小生产的生产方式没有反义关系。"}], "correct_answer": "大生产", "explanations": {"大生产": "反义：小生产规模小，大生产规模大，两者在此义上相对。", "农业": "无关：农业是行业名称，与小生产不构成反义。", "商品": "无关：商品是产品，不是生产方式，没有反义关系。", "学校": "无关：学校是机构，与小生产的生产方式没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cd7f24c-5159-466b-8e24-be195f5be339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
