INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94798, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以个人或家庭为单位、规模较小的生产方式。", "primary_collocate": null, "pronunciation": "xiǎo shēng chǎn", "ipa": "ɕiɑʊ̯˨˩ ʂɤŋ˥ ʈʂʰan˨˩", "syllable_count": 3, "sentences": [{"text": "小生产以个人或家庭为单位。", "target_word": "小生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去农村的主要方式是小生产。", "target_word": "小生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小生产的规模小，很难赚大钱。", "target_word": "小生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大工厂出现以后，小生产慢慢减少了。", "target_word": "小生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小生产常常靠家里人一起干活。", "target_word": "小生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，小生产是一种古老的生产方式。", "target_word": "小生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师在课上讲了小生产与大生产的区别。", "target_word": "小生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与大生产相比，小生产的成本更高。", "target_word": "小生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小生产的工具比较简单。", "target_word": "小生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家早期都有过小生产的阶段。", "target_word": "小生产", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小生產", "label": "繁体"}, {"form": "小生产者", "label": "复合"}], "register": "书面", "sense_fingerprint": "以个人或家庭为单位、规模小的生产方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c832532e-8599-453c-a65b-bf3d6cc2a2e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小生产", "is_correct": true, "explanation": "正确：小生产以个人或家庭为单位，与句中定义一致。"}, {"text": "大工业", "is_correct": false, "explanation": "语义：大工业以大规模生产为特点，与“以个人或家庭为单位”矛盾。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂通常以企业为单位，不以个人或家庭为单位，与句子矛盾。"}, {"text": "生产线", "is_correct": false, "explanation": "搭配：“以……为单位”指组织方式，“生产线”是设备，不能作为单位。"}], "explanations": {"小生产": "正确：小生产以个人或家庭为单位，与句中定义一致。", "大工业": "语义：大工业以大规模生产为特点，与“以个人或家庭为单位”矛盾。", "工厂": "语义：工厂通常以企业为单位，不以个人或家庭为单位，与句子矛盾。", "生产线": "搭配：“以……为单位”指组织方式，“生产线”是设备，不能作为单位。"}, "sentence_index": 0, "correct_answer": "小生产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家小生产有很多员工，每天都很忙。", "explanation": "这里应该用〈小企业〉。小生产指生产方式，不指企业或公司，不能说“这家小生产”。"}, {"text": "农民是一个小生产，在家里做鞋。", "explanation": "这里应该用〈小生产者〉。小生产指生产方式，指人时要说“小生产者”。"}, {"text": "他在街上做小生产，每天卖水果。", "explanation": "这里应该用〈小生意〉。卖水果是买卖经营，小生产指生产制造，不能用来指做买卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cd7f24c-5159-466b-8e24-be195f5be339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小生产", "is_correct": true, "explanation": "正确：小生产是一种生产方式，可以与大生产比较区别，句意通顺。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭不是生产方式，不能与“大生产”比较区别。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不是生产方式，不能与“大生产”作区别对比。"}, {"text": "天地", "is_correct": false, "explanation": "语义：“天地”不是生产方式，不能与“大生产”作区别对比。"}], "explanations": {"小生产": "正确：小生产是一种生产方式，可以与大生产比较区别，句意通顺。", "饭": "语义：饭不是生产方式，不能与“大生产”比较区别。", "名字": "语义：“名字”不是生产方式，不能与“大生产”作区别对比。", "天地": "语义：“天地”不是生产方式，不能与“大生产”作区别对比。"}, "sentence_index": 6, "correct_answer": "小生产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台小生产每天能磨很多豆腐。", "explanation": "这里应该用〈机器〉。小生产指一种生产方式，不是可以用“台”计数的机器。"}, {"text": "他用小生产修好了自行车。", "explanation": "这里应该用〈工具〉。小生产指生产方式，不能拿在手里使用。"}, {"text": "她的小生产很精致，绣的花很漂亮。", "explanation": "这里应该用〈手艺〉。小生产指生产方式，不指个人的绣花技艺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cd7f24c-5159-466b-8e24-be195f5be339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村子以前主要小生产生活。", "corrected_sentence": "这个村子以前主要靠小生产生活。", "error_description": "漏用介词“靠”：“靠”引出生活所依赖的方式，应说“靠小生产生活”，不能省去“靠”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cd7f24c-5159-466b-8e24-be195f5be339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小生产的规模比大生产更大。", "corrected_sentence": "小生产的规模比大生产更小。", "error_description": "语义错误：小生产以个人或家庭为单位，规模小，应说“比大生产更小”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cd7f24c-5159-466b-8e24-be195f5be339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
