INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94799, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从不是一次都没有做过。", "primary_collocate": null, "pronunciation": "cóng bù", "ipa": "tsʰʊŋ˧˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "我从不迟到，老师都知道。", "target_word": "从不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不喝酒，聚会上只喝茶。", "target_word": "从不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李从不吃辣的菜，一吃就难受。", "target_word": "从不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从不坐地铁上班，因为太挤。", "target_word": "从不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷从不抽烟，身体很好。", "target_word": "从不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从不说别人的坏话。", "target_word": "从不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟从不看电视，只爱看书。", "target_word": "从不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从不骗朋友。", "target_word": "从不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店从不打折，价钱一直很高。", "target_word": "从不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不乱花钱，每个月都存钱。", "target_word": "从不", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，一次都没有做过某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccaa5f06-74fd-450d-9e5c-c87f845eb06a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94799, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从不", "is_correct": true, "explanation": "正确：表示一次都没有迟到过，与“老师都知道”的习惯相符。"}, {"text": "非常", "is_correct": false, "explanation": "语法：程度副词“非常”不能直接修饰动词“迟到”。"}, {"text": "十分", "is_correct": false, "explanation": "语法：“十分”是程度副词，不能直接修饰“迟到”。"}, {"text": "太", "is_correct": false, "explanation": "语法：“太迟到”不成立，“太”不能直接修饰动作动词。"}], "explanations": {"从不": "正确：表示一次都没有迟到过，与“老师都知道”的习惯相符。", "非常": "语法：程度副词“非常”不能直接修饰动词“迟到”。", "十分": "语法：“十分”是程度副词，不能直接修饰“迟到”。", "太": "语法：“太迟到”不成立，“太”不能直接修饰动作动词。"}, "sentence_index": 0, "correct_answer": "从不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有时从不坐地铁上班，因为太挤。", "explanation": "“从不”表示从来一次都没有，不能和表示偶尔的“有时”一起用，这里应该用〈不〉。"}, {"text": "我常常从不坐地铁上班，因为太挤。", "explanation": "“从不”表示从来一次都没有，与“常常”冲突，这里应该用〈不〉。"}, {"text": "我明天从不坐地铁上班，因为太挤。", "explanation": "“从不”说过去到现在一贯如此，不能用于“明天”这样的将来某一次，这里应该用〈不〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94799, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从不", "is_correct": true, "explanation": "正确：表示一次都没有看过电视，与后半句“只爱看书”相符。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是看电视”与“只爱看书”的排他语气矛盾。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直看电视”与“只爱看书”矛盾。"}, {"text": "还", "is_correct": false, "explanation": "搭配：“还”后多接递进或并列，与“只爱看书”的排他语气不搭配。"}], "explanations": {"从不": "正确：表示一次都没有看过电视，与后半句“只爱看书”相符。", "总是": "语义：“总是看电视”与“只爱看书”的排他语气矛盾。", "一直": "语义：“一直看电视”与“只爱看书”矛盾。", "还": "搭配：“还”后多接递进或并列，与“只爱看书”的排他语气不搭配。"}, "sentence_index": 6, "correct_answer": "从不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他明年从不乱花钱，现在就开始存钱。", "explanation": "“从不”说过去到现在一贯如此，不能用于将来的打算，这里应该用〈不再〉。"}, {"text": "他时常从不乱花钱，每个月都存钱。", "explanation": "“从不”表示一次都没有，与“时常”冲突，这里应该用〈不〉。"}, {"text": "他一次从不乱花钱，每个月都存钱。", "explanation": "“从不”不和“一次”这样连用，要强调一次都没有，这里应该用〈也不〉，说成“一次也不”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94799, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她很从不说谎，朋友都信任她。", "corrected_sentence": "她从不说谎，朋友都信任她。", "error_description": "错误：副词“从不”前面不能再加程度副词“很”。正确：应说“她从不说谎”，“从不”直接放在动词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94799, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我弟弟从不不乱扔垃圾，很爱干净。", "corrected_sentence": "我弟弟从不乱扔垃圾，很爱干净。", "error_description": "双重否定：“从不”本身已表示否定，后面不能再加“不”，应说“从不乱扔垃圾”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
