INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94800, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从来不，表示一直都没有。", "primary_collocate": null, "pronunciation": "cóng bù", "ipa": "tsʰʊŋ˧˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈从不生气，对孩子总是很温和。", "target_word": "从不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不让别人帮忙，什么都自己做。", "target_word": "从不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家从不吃早饭，都睡到很晚。", "target_word": "从不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师从不迟到，每天最早到学校。", "target_word": "从不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从不化妆，也不爱买衣服。", "target_word": "从不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥从不害怕考试，总是很放松。", "target_word": "从不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河从不结冰，冬天也一样。", "target_word": "从不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不看天气预报，出门就走。", "target_word": "从不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸从不在家里大声说话。", "target_word": "从不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子从不哭，大家都觉得奇怪。", "target_word": "从不", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，一向不这样，一直都没有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccaa5f06-74fd-450d-9e5c-c87f845eb06a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94800, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从不", "is_correct": true, "explanation": "正确：表示一向没有生气过，与后半句“总是很温和”相符。"}, {"text": "老是", "is_correct": false, "explanation": "语义：“老是生气”与后半句“总是很温和”矛盾。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然生气”表示出乎意料，与一贯温和的情况不符。"}, {"text": "还", "is_correct": false, "explanation": "搭配：“还”表示仍然持续，与“总是很温和”的一贯性不搭配。"}], "explanations": {"从不": "正确：表示一向没有生气过，与后半句“总是很温和”相符。", "老是": "语义：“老是生气”与后半句“总是很温和”矛盾。", "竟然": "语义：“竟然生气”表示出乎意料，与一贯温和的情况不符。", "还": "搭配：“还”表示仍然持续，与“总是很温和”的一贯性不搭配。"}, "sentence_index": 0, "correct_answer": "从不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "王老师明年从不迟到，今年却常常迟到。", "explanation": "“从不”只说过去到现在一贯如此，不能用于将来“明年”，这里应该用〈不会〉。"}, {"text": "王老师常常从不迟到，每天最早到学校。", "explanation": "“从不”表示一次都没有，不能再受表示经常的“常常”修饰，应去掉“常常”。"}, {"text": "王老师有时从不迟到，每天最早到学校。", "explanation": "“从不”表示一次都没有，与表示偶尔的“有时”矛盾，应去掉“有时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94800, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从不", "is_correct": true, "explanation": "正确：表示这条河一向不结冰，与“冬天也一样”相符。"}, {"text": "早就", "is_correct": false, "explanation": "语义：“早就”表示已经发生，与一贯不结冰的情况不符。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”只指刚发生的一次，与整个冬天的情况不符。"}, {"text": "竟", "is_correct": false, "explanation": "语义：“竟”表示出乎意料，与“冬天也一样”的平常描述不符。"}], "explanations": {"从不": "正确：表示这条河一向不结冰，与“冬天也一样”相符。", "早就": "语义：“早就”表示已经发生，与一贯不结冰的情况不符。", "刚刚": "语义：“刚刚”只指刚发生的一次，与整个冬天的情况不符。", "竟": "语义：“竟”表示出乎意料，与“冬天也一样”的平常描述不符。"}, "sentence_index": 6, "correct_answer": "从不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个孩子每次跌倒都哭，从不哭。", "explanation": "“每次跌倒都哭”与“从不哭”自相矛盾，两者不能同时成立。"}, {"text": "那个孩子从不哭，但昨天哭了。", "explanation": "“从不”表示一直都没有，不能与过去发生过的事情并存，这里应该用〈很少〉。"}, {"text": "那个孩子总是从不哭，大家都觉得奇怪。", "explanation": "“从不”已表示一贯没有，不能再用表示经常发生的“总是”修饰，应去掉“总是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94800, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很从不占别人便宜，做事很公平。", "corrected_sentence": "他从不占别人便宜，做事很公平。", "error_description": "错误：副词“从不”前面不能再加程度副词“很”。正确：应说“他从不占别人便宜”，“从不”直接放在动词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94800, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只小猫从不不乱跑，一直待在家里。", "corrected_sentence": "那只小猫从不乱跑，一直待在家里。", "error_description": "双重否定：“从不”本身已表示否定，后面不能再加“不”，应说“从不乱跑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
