INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94801, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94801, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "成事是把一件事做好了。", "primary_collocate": null, "pronunciation": "chéng shì", "ipa": "ʈʂʰɤŋ³⁵ ʂɻ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "谋事在人，成事在天。", "target_word": "成事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他只会说大话，成事不足，败事有余。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做事认真的人，往往能成事。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光有想法不行，行动起来才能成事。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做事太马虎，很难成事。", "target_word": "成事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "想要成事，先要把准备做好。", "target_word": "成事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人别着急，慢慢来才能成事。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，细心的孩子长大后更容易成事。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "成事靠的是坚持，不是运气。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在公司里，他是个能成事的人。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "把一件事做好、做成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59c51a76-670c-44fa-8b2f-c5c9944b2429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94801, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成事", "is_correct": true, "explanation": "正确：与前句“谋事”相对，“成事在天”指事情能否办成由天决定。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：前句说谋划事情，后句应说事情的成败，“吃饭在天”与成败无关，句子不通。"}, {"text": "干活", "is_correct": false, "explanation": "语域：“干活”是口语，与这句谚语的书面语体不合。语义上也与前句的“谋事”不相称。"}, {"text": "管理", "is_correct": false, "explanation": "语义：“管理”指统筹安排，与“天”决定成败的意思不合，“管理在天”说不通。"}], "explanations": {"成事": "正确：与前句“谋事”相对，“成事在天”指事情能否办成由天决定。", "吃饭": "语义：前句说谋划事情，后句应说事情的成败，“吃饭在天”与成败无关，句子不通。", "干活": "语域：“干活”是口语，与这句谚语的书面语体不合。语义上也与前句的“谋事”不相称。", "管理": "语义：“管理”指统筹安排，与“天”决定成败的意思不合，“管理在天”说不通。"}, "sentence_index": 0, "correct_answer": "成事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他成事很稳，大家都信任他。", "explanation": "这里应该用〈办事〉。办事指处理事务的过程，“成事”强调事情办成的结果，不能用来形容做事的过程。"}, {"text": "这座桥三年内就能成事。", "explanation": "这里应该用〈建成〉。成事指人把事情办成，桥梁、建筑完工要说“建成”。"}, {"text": "这件衣服下周就能成事。", "explanation": "这里应该用〈做好〉。成事的对象是事务，衣服做好要说“做好”，“成事”不用于物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94801, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成事", "is_correct": true, "explanation": "正确：“才能”后接“成事”，表示办成事情这一正面结果。"}, {"text": "失败", "is_correct": false, "explanation": "语义：前句鼓励慢慢来，“慢慢来才能失败”与句意相反。"}, {"text": "着急", "is_correct": false, "explanation": "搭配：“才能”后接结果动词，“着急”是心理状态，且与前句“别着急”重复，不能作结果。"}, {"text": "吃亏", "is_correct": false, "explanation": "语义：慢慢来不会导致吃亏，此处“才能”要接正面结果，“吃亏”与句意不合。"}], "explanations": {"成事": "正确：“才能”后接“成事”，表示办成事情这一正面结果。", "失败": "语义：前句鼓励慢慢来，“慢慢来才能失败”与句意相反。", "着急": "搭配：“才能”后接结果动词，“着急”是心理状态，且与前句“别着急”重复，不能作结果。", "吃亏": "语义：慢慢来不会导致吃亏，此处“才能”要接正面结果，“吃亏”与句意不合。"}, "sentence_index": 6, "correct_answer": "成事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的理想终于成事了。", "explanation": "这里应该用〈实现〉。成事指人把具体事情办成，理想要说“实现”，不说“成事”。"}, {"text": "这锅汤她一小时就成事了。", "explanation": "这里应该用〈煮好〉。成事用于办理事务，煮汤这类具体的家务要说“煮好”。"}, {"text": "这台电脑他下午就成事了。", "explanation": "这里应该用〈修好〉。成事指把事情办成，电器等具体物件修好要说“修好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94801, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于把这件事成事了。", "corrected_sentence": "他终于把这件事办成了。", "error_description": "错误：“成事”本身已含宾语“事”，不能再用“把”字句带宾语“这件事”。应说“把这件事办成了”或“他终于成事了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94801, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没成事过。", "corrected_sentence": "他从来没成过事。", "error_description": "错误：“过”应放在离合词“成”和“事”之间，说“成过事”；“成事过”的位置不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94802, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94802, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94802, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "办成事情，把事情做成功。", "primary_collocate": null, "pronunciation": "chéng shì", "ipa": "ʈʂʰɤŋ³⁵ ʂɻ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "一个人再有本事，没有朋友也难成事。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想要成事，朋友的帮助很重要。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想了很多办法，最后还是没能成事。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想成事的人，都得先学会吃苦。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有钱有人脉，可是做事总是半途而废，难以成事。", "target_word": "成事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办事要讲方法，方法对了才容易成事。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他性子太急，成事的机会不大。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做生意既要有胆量，也要有耐心才能成事。", "target_word": "成事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩一个出钱，一个出力，终于成事。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古人说，天时地利人和，三者齐了才能成事。", "target_word": "成事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "办成事情、做成功", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59c51a76-670c-44fa-8b2f-c5c9944b2429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94802, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成事", "is_correct": true, "explanation": "正确：“也难”后接“成事”，指没有朋友就难以把事情办成。"}, {"text": "洗碗", "is_correct": false, "explanation": "搭配：“难洗碗”不是常见搭配，且与“没有朋友”的语境无关。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“没有朋友”与“发烧”无关，“也难发烧”说不通。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修好坏了的东西，与前句说的本事和朋友无关。"}], "explanations": {"成事": "正确：“也难”后接“成事”，指没有朋友就难以把事情办成。", "洗碗": "搭配：“难洗碗”不是常见搭配，且与“没有朋友”的语境无关。", "发烧": "语义：“没有朋友”与“发烧”无关，“也难发烧”说不通。", "修理": "语义：“修理”指修好坏了的东西，与前句说的本事和朋友无关。"}, "sentence_index": 0, "correct_answer": "成事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新校舍明年就能成事。", "explanation": "这里应该用〈落成〉。成事指人把事情办成，建筑物完工要说“落成”。"}, {"text": "他的梦想终于成事了。", "explanation": "这里应该用〈实现〉。梦想要说“实现”，“成事”强调人把事情办成，不用于梦想。"}, {"text": "这锅饭已经成事了。", "explanation": "这里应该用〈煮熟〉。饭菜做好要说“煮熟”，“成事”只用于办事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94802, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成事", "is_correct": true, "explanation": "正确：“成事的机会”指办成事情的可能性，与“性子太急”的语境相连。"}, {"text": "失败", "is_correct": false, "explanation": "语义：前句“性子太急”暗示容易出问题，“失败的机会不大”与之矛盾。"}, {"text": "出错", "is_correct": false, "explanation": "语义：“性子太急”通常容易出错，“出错的机会不大”与前半句矛盾。"}, {"text": "翻车", "is_correct": false, "explanation": "语域：“翻车”是口语，与句子的书面语体不协调，且语义上也与“性子太急”矛盾。"}], "explanations": {"成事": "正确：“成事的机会”指办成事情的可能性，与“性子太急”的语境相连。", "失败": "语义：前句“性子太急”暗示容易出问题，“失败的机会不大”与之矛盾。", "出错": "语义：“性子太急”通常容易出错，“出错的机会不大”与前半句矛盾。", "翻车": "语域：“翻车”是口语，与句子的书面语体不协调，且语义上也与“性子太急”矛盾。"}, "sentence_index": 6, "correct_answer": "成事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画终于成事了。", "explanation": "这里应该用〈画好〉。成事指把事情办成，画作完成要说“画好”，不能用“成事”。"}, {"text": "这些衣服终于成事了。", "explanation": "这里应该用〈洗好〉。成事用于办事情，衣物洗干净要说“洗好”。"}, {"text": "这个谜团终于成事了。", "explanation": "这里应该用〈破解〉。谜团要说“破解”，“成事”指办成事务，不能用于谜团。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是个很会成事人。", "corrected_sentence": "她是个很会成事的人。", "error_description": "错误：“成事”作定语修饰“人”时要加“的”，应说“成事的人”，不能直接说“成事人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这辈子都没成事过。", "corrected_sentence": "他这辈子都没成过事。", "error_description": "错误：“过”应放在离合词“成”和“事”之间，说“成过事”，不能说“成事过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
