INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94805, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "教材是老师教课、学生读书用的书。", "primary_collocate": null, "pronunciation": "jiào cái", "ipa": "tɕjɑʊ˥˩ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "开学第一天，我们领到了新教材。", "target_word": "教材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本教材是中文版的。", "target_word": "教材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把教材忘在家里了。", "target_word": "教材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教材上的字很大，容易读。", "target_word": "教材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们打开教材，翻到第五页。", "target_word": "教材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门课的教材很贵。", "target_word": "教材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天晚上都复习教材。", "target_word": "教材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把教材放在桌子上。", "target_word": "教材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，下节课要带教材。", "target_word": "教材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的教材上画满了小猫。", "target_word": "教材", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "套", "label": "量词"}, {"form": "本", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词，老师上课、学生学习用的书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccaa5f06-74fd-450d-9e5c-c87f845eb06a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94805, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教材", "is_correct": true, "explanation": "正确答案。开学时领到的是供学习用的新教材，符合句意。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：学校不会发给学生垃圾，“领到了新垃圾”与句意不符。"}, {"text": "河水", "is_correct": false, "explanation": "搭配：“领到”不能与“河水”搭配，河水不能被领取。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶不是学校发给学生的东西，句意不通。"}], "explanations": {"教材": "正确答案。开学时领到的是供学习用的新教材，符合句意。", "垃圾": "语义：学校不会发给学生垃圾，“领到了新垃圾”与句意不符。", "河水": "搭配：“领到”不能与“河水”搭配，河水不能被领取。", "树叶": "语义：树叶不是学校发给学生的东西，句意不通。"}, "sentence_index": 0, "correct_answer": "教材"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们在考场上认真答教材。", "explanation": "这里应该用〈试卷〉。答题的对象是试卷，教材是供学习用的书，不能用“答”。"}, {"text": "我买了一只教材。", "explanation": "这里应该用〈本〉或〈套〉。〈只〉多用于动物和成对的物品，教材不用〈只〉来计量。"}, {"text": "老师把一本教材挂在黑板上，方便大家看。", "explanation": "这里应该用〈挂图〉。挂在黑板上的是挂图等教具；“教材”是供学生读的书，不能挂在墙上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94805, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教材", "is_correct": true, "explanation": "正确答案。“复习”的对象是学习用的书，与“教材”搭配，符合句意。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“复习”不与“饭菜”搭配，复习的对象应是课文或知识。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不是学习内容，“复习雨伞”与句意不合。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能作为复习的内容，句意不通。"}], "explanations": {"教材": "正确答案。“复习”的对象是学习用的书，与“教材”搭配，符合句意。", "饭菜": "搭配：“复习”不与“饭菜”搭配，复习的对象应是课文或知识。", "雨伞": "语义：雨伞不是学习内容，“复习雨伞”与句意不合。", "窗户": "语义：窗户不能作为复习的内容，句意不通。"}, "sentence_index": 6, "correct_answer": "教材"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弟弟饿了，把教材拿去煮汤了。", "explanation": "这里应该用〈食材〉。教材是供读书用的书，不能拿去煮来吃；能煮汤的是食材。"}, {"text": "我刚买了一片教材。", "explanation": "这里应该用〈本〉。〈片〉多用于叶子、云等薄而平的东西，教材应用〈本〉或〈套〉。"}, {"text": "这些木板是做书架的好教材。", "explanation": "这里应该用〈材料〉。做书架的木板是材料；“教材”是供学习用的书，不能指家具用料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94805, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师上周就从教材发下去了。", "corrected_sentence": "老师上周就把教材发下去了。", "error_description": "介词错误：引出被处置的“教材”应用“把”，“从”表示起点，不能引出“教材”作宾语，应说“把教材发下去了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94805, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校刚买了一只新教材。", "corrected_sentence": "学校刚买了一套新教材。", "error_description": "量词错误：“教材”应用量词〈套〉或〈本〉，不能用〈只〉。正确的说法是“一套新教材”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
