INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94806, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供教学使用的材料，如课本、讲义等。", "primary_collocate": null, "pronunciation": "jiào cái", "ipa": "tɕjɑʊ˥˩ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "老师自己编了一套新教材。", "target_word": "教材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本教材里有很多图片。", "target_word": "教材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给我们发了新教材。", "target_word": "教材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套教材适合小学生用。", "target_word": "教材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师正在准备明天的教材。", "target_word": "教材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教材的内容太难，学生看不懂。", "target_word": "教材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的汉语教材有音频。", "target_word": "教材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里有很多外语教材。", "target_word": "教材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份教材是老师自己写的。", "target_word": "教材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用网上的视频当教材。", "target_word": "教材", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "套", "label": "量词"}, {"form": "本", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词，教学用的各种材料，如课本、讲义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccaa5f06-74fd-450d-9e5c-c87f845eb06a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94806, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教材", "is_correct": true, "explanation": "正确答案。“编了一套新”可以指编写的书籍、材料，“教材”符合句意。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“编”不能与“面包”搭配，面包不是编写出来的，句子不通。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑，不是供教学使用、可以编写的材料，与“老师自己编了一套新”的句意冲突。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：教室是场所，不能“编”，“老师自己编了一套新教室”说不通。"}], "explanations": {"教材": "正确答案。“编了一套新”可以指编写的书籍、材料，“教材”符合句意。", "面包": "搭配：“编”不能与“面包”搭配，面包不是编写出来的，句子不通。", "房子": "语义：房子是建筑，不是供教学使用、可以编写的材料，与“老师自己编了一套新”的句意冲突。", "教室": "搭配：教室是场所，不能“编”，“老师自己编了一套新教室”说不通。"}, "sentence_index": 0, "correct_answer": "教材"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们在考场上认真答教材。", "explanation": "这里应该用〈试卷〉。答题的对象是试卷，教材是供学习用的书，不能用“答”。"}, {"text": "我买了一只教材。", "explanation": "这里应该用〈本〉或〈套〉。〈只〉多用于动物和成对的物品，教材不用〈只〉来计量。"}, {"text": "妈妈用这块布给我做了一件新教材。", "explanation": "这里应该用〈衣服〉。布料做成的是衣服，不是供教学使用的材料，不能称为“教材”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94806, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教材", "is_correct": true, "explanation": "正确答案。汉语教材可以配有音频，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有音频，“有音频”与“石头”的意义不合。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘不是可以配音频的学习材料，句意不通。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：“汉语”不修饰“树叶”，树叶也不带音频，搭配不当。"}], "explanations": {"教材": "正确答案。汉语教材可以配有音频，符合句意。", "石头": "语义：石头没有音频，“有音频”与“石头”的意义不合。", "窗帘": "语义：窗帘不是可以配音频的学习材料，句意不通。", "树叶": "搭配：“汉语”不修饰“树叶”，树叶也不带音频，搭配不当。"}, "sentence_index": 6, "correct_answer": "教材"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他饿了，把教材放进锅里煮成了汤。", "explanation": "这里应该用〈食材〉。教材是供教学使用的材料，不能煮来吃；能煮成汤的是食材。"}, {"text": "我刚买了一片教材。", "explanation": "这里应该用〈本〉。〈片〉多用于叶子、云等薄而平的东西，教材应用〈本〉或〈套〉。"}, {"text": "这些木板是做书架的好教材。", "explanation": "这里应该用〈材料〉。做书架的木板是材料；“教材”专指供教学用的材料，不能指家具用料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师们正在编写教材们，下个月就能用。", "corrected_sentence": "老师们正在编写教材，下个月就能用。", "error_description": "错误：“们”只用于指人，不能加在“教材”后面表示复数。正确：应说“编写教材”，去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些教材们很厚，我拿不动。", "corrected_sentence": "这些教材很厚，我拿不动。", "error_description": "错误：“们”只用于指人，不能加在“教材”后面表示复数。正确：应说“这些教材很厚”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '361b4064-7510-494b-a7a4-32497d9274e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
