INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94809, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "新兴是刚刚出现，正在长大的。", "primary_collocate": null, "pronunciation": "xīn xīng", "ipa": "ɕin˥ ɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "滑板是一项年轻人喜欢的新兴运动。", "target_word": "新兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新兴事物常常需要时间让大家接受。", "target_word": "新兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个新兴品牌最近很受年轻人欢迎。", "target_word": "新兴", "complexity_tier": "T3", "furigana": "zhè gè xīn xīng pǐn pái zuì jìn hěn shòu nián qīng rén huān yíng", "sentence_source": "generated"}, {"text": "他们是球队里的新兴力量。", "target_word": "新兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个新兴城区里住着很多年轻家庭。", "target_word": "新兴", "complexity_tier": "T3", "furigana": "zhè gè xīn xīng chéng qū lǐ zhù zhe hěn duō nián qīng jiā tíng", "sentence_source": "generated"}, {"text": "电动车是近年来的新兴产品。", "target_word": "新兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新兴城市的街道很干净，也很新。", "target_word": "新兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家新兴小店刚开了半年，生意就不错。", "target_word": "新兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说新兴艺术需要大家多关心。", "target_word": "新兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们小区附近有几个新兴的小公司。", "target_word": "新兴", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "新兴力量", "label": "复合"}, {"form": "新兴事物", "label": "复合"}], "register": "中性", "sense_fingerprint": "新兴|刚出现、正在长大的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '702d0700-d623-41b2-b926-c6455e91f03f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94809, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "新兴", "is_correct": true, "explanation": "新兴：刚出现、正在长大，为正确答案。"}, {"text": "心形", "is_correct": false, "explanation": "xīnxíng（第二声）与 xīnxīng 第二个音节声调不同，意思是心的形状。"}, {"text": "新型", "is_correct": false, "explanation": "xīnxíng（第二声）与 xīnxīng 第二个音节声调不同，意思是新的类型。"}, {"text": "欣幸", "is_correct": false, "explanation": "xīnxìng（第四声）与 xīnxīng 第二个音节声调不同，意思是欢喜庆幸。"}], "explanations": {"新兴": "新兴：刚出现、正在长大，为正确答案。", "心形": "xīnxíng（第二声）与 xīnxīng 第二个音节声调不同，意思是心的形状。", "新型": "xīnxíng（第二声）与 xīnxīng 第二个音节声调不同，意思是新的类型。", "欣幸": "xīnxìng（第四声）与 xīnxīng 第二个音节声调不同，意思是欢喜庆幸。"}, "sentence_index": null, "correct_answer": "新兴"}, "level_3": {"options": [{"text": "文静", "is_correct": false, "explanation": "语义：“文静”形容人的性情，不能修饰“运动”。"}, {"text": "肥胖", "is_correct": false, "explanation": "搭配：“肥胖”形容人或动物的体形，不说“肥胖的运动”。"}, {"text": "新兴", "is_correct": true, "explanation": "新兴：刚出现、正在长大，修饰“运动”，与“年轻人喜欢的”相符。"}, {"text": "愚笨", "is_correct": false, "explanation": "语义：“愚笨”形容人的智力，不能用于形容运动。"}], "explanations": {"文静": "语义：“文静”形容人的性情，不能修饰“运动”。", "肥胖": "搭配：“肥胖”形容人或动物的体形，不说“肥胖的运动”。", "新兴": "新兴：刚出现、正在长大，修饰“运动”，与“年轻人喜欢的”相符。", "愚笨": "语义：“愚笨”形容人的智力，不能用于形容运动。"}, "sentence_index": 0, "correct_answer": "新兴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈给我买了一双新兴的鞋。", "explanation": "这里应该用〈崭新〉。新兴指刚兴起、正在发展的事物，形容鞋子等物品全新要用“崭新”。"}, {"text": "院子里出生了一只新兴的小猫。", "explanation": "这里应该用〈新生〉。新生指刚出生或刚出现，形容刚出生的小动物要用“新生”。"}, {"text": "他手指上有一道新兴的伤口。", "explanation": "这里应该用〈新〉。新兴指刚出现、正在发展的事物，不用来形容伤口，刚受的伤口要用“新”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94809, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "新兴", "is_correct": true, "explanation": "新兴：刚出现、正在长大，为正确答案。"}, {"text": "星星", "is_correct": false, "explanation": "xīngxīng：第一个音节是 xīng 不是 xīn，听起来很像，意思是天上的星星。"}, {"text": "心性", "is_correct": false, "explanation": "xīnxìng（第四声）与 xīnxīng 第二个音节声调不同，意思是人的性情。"}, {"text": "欣欣", "is_correct": false, "explanation": "xīnxīn：第二个音节是 xīn 不是 xīng，听起来很像，意思是高兴、茂盛的样子。"}], "explanations": {"新兴": "新兴：刚出现、正在长大，为正确答案。", "星星": "xīngxīng：第一个音节是 xīng 不是 xīn，听起来很像，意思是天上的星星。", "心性": "xīnxìng（第四声）与 xīnxīng 第二个音节声调不同，意思是人的性情。", "欣欣": "xīnxīn：第二个音节是 xīn 不是 xīng，听起来很像，意思是高兴、茂盛的样子。"}, "sentence_index": null, "correct_answer": "新兴"}, "level_3": {"options": [{"text": "古老", "is_correct": false, "explanation": "语义：“古老”指年代久远，与后文“也很新”矛盾。"}, {"text": "新兴", "is_correct": true, "explanation": "新兴：刚出现、正在长大，修饰“城市”，与“也很新”相符。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”指过时、老旧，与后文“也很新”矛盾。"}, {"text": "破旧", "is_correct": false, "explanation": "搭配：“破旧”形容东西损坏、老旧，不能用来形容街道“很干净，也很新”。"}], "explanations": {"古老": "语义：“古老”指年代久远，与后文“也很新”矛盾。", "新兴": "新兴：刚出现、正在长大，修饰“城市”，与“也很新”相符。", "陈旧": "语义：“陈旧”指过时、老旧，与后文“也很新”矛盾。", "破旧": "搭配：“破旧”形容东西损坏、老旧，不能用来形容街道“很干净，也很新”。"}, "sentence_index": 6, "correct_answer": "新兴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他穿着一件很新兴的外套。", "explanation": "这里应该用〈新潮〉。新兴指事物刚刚兴起，形容外套的样式时尚要用“新潮”。"}, {"text": "这个方案的想法很新兴。", "explanation": "这里应该用〈新颖〉。新兴不用来形容想法的别致、有新意，要用“新颖”。"}, {"text": "我今天买了一本新兴的书。", "explanation": "这里应该用〈新〉。新兴强调刚刚兴起、正在发展，只说刚买的新书要用“新”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94809, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新兴地力量正在改变这个行业。", "corrected_sentence": "新兴的力量正在改变这个行业。", "error_description": "错误：“新兴”修饰名词“力量”时要用“的”，不用“地”。正确形式为“新兴的力量”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94809, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片新兴了的城区这几年发展很快。", "corrected_sentence": "这片新兴的城区这几年发展很快。", "error_description": "错误：“新兴”修饰名词“城区”时，后面直接接“的”，不能加“了”。正确形式为“新兴的城区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94810, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清澈", "is_correct": false, "explanation": "无反义关系：“清澈”形容水或眼睛干净透明，与“新兴”不构成反义。"}, {"text": "没落", "is_correct": true, "explanation": "没落：与“新兴”构成反义，指事物逐渐衰落，符合这里的语境。"}, {"text": "柔软", "is_correct": false, "explanation": "无反义关系：“柔软”形容质地不硬，与“新兴”不构成反义。"}, {"text": "狭窄", "is_correct": false, "explanation": "无反义关系：“狭窄”形容空间小，与“新兴”不构成反义。"}], "correct_answer": "没落", "explanations": {"清澈": "无反义关系：“清澈”形容水或眼睛干净透明，与“新兴”不构成反义。", "没落": "没落：与“新兴”构成反义，指事物逐渐衰落，符合这里的语境。", "柔软": "无反义关系：“柔软”形容质地不硬，与“新兴”不构成反义。", "狭窄": "无反义关系：“狭窄”形容空间小，与“新兴”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94810, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗糙", "is_correct": false, "explanation": "无反义关系：“粗糙”形容表面不光滑，与“新兴”不构成反义。"}, {"text": "没落", "is_correct": true, "explanation": "没落：与“新兴”构成反义，指事物逐渐衰落，符合这里的语境。"}, {"text": "漆黑", "is_correct": false, "explanation": "无反义关系：“漆黑”形容颜色或光线很暗，与“新兴”不构成反义。"}, {"text": "圆润", "is_correct": false, "explanation": "无反义关系：“圆润”形容形状或声音饱满柔和，与“新兴”不构成反义。"}], "correct_answer": "没落", "explanations": {"粗糙": "无反义关系：“粗糙”形容表面不光滑，与“新兴”不构成反义。", "没落": "没落：与“新兴”构成反义，指事物逐渐衰落，符合这里的语境。", "漆黑": "无反义关系：“漆黑”形容颜色或光线很暗，与“新兴”不构成反义。", "圆润": "无反义关系：“圆润”形容形状或声音饱满柔和，与“新兴”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94810, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "刚刚兴起、正在迅速发展的。", "primary_collocate": null, "pronunciation": "xīn xīng", "ipa": "ɕin˥ ɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "这个城市是一个新兴的旅游城市。", "target_word": "新兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新兴产业给年轻人带来了很多机会。", "target_word": "新兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想去一家新兴公司工作。", "target_word": "新兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新兴市场的发展速度比我们想的快。", "target_word": "新兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多新兴国家的经济发展得很快。", "target_word": "新兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络购物是近几年的新兴行业。", "target_word": "新兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些新兴企业大多是年轻人办的。", "target_word": "新兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新兴行业的工资常常比较高。", "target_word": "新兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥在一家新兴科技公司上班。", "target_word": "新兴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座新兴的小城正在吸引越来越多的人。", "target_word": "新兴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "新兴产业", "label": "复合"}, {"form": "新兴市场", "label": "复合"}], "register": "中性", "sense_fingerprint": "新兴|刚兴起、迅速发展的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '702d0700-d623-41b2-b926-c6455e91f03f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94810, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "新兴", "is_correct": true, "explanation": "新兴：刚刚兴起、正在迅速发展，为正确答案。"}, {"text": "新型", "is_correct": false, "explanation": "xīnxíng（第二声）与 xīnxīng 第二个音节声调不同，意思是新的类型，不是刚刚兴起。"}, {"text": "心形", "is_correct": false, "explanation": "xīnxíng（第二声）与 xīnxīng 第二个音节声调不同，意思是心的形状。"}, {"text": "欣幸", "is_correct": false, "explanation": "xīnxìng（第四声）与 xīnxīng 第二个音节声调不同，意思是欢喜庆幸。"}], "explanations": {"新兴": "新兴：刚刚兴起、正在迅速发展，为正确答案。", "新型": "xīnxíng（第二声）与 xīnxīng 第二个音节声调不同，意思是新的类型，不是刚刚兴起。", "心形": "xīnxíng（第二声）与 xīnxīng 第二个音节声调不同，意思是心的形状。", "欣幸": "xīnxìng（第四声）与 xīnxīng 第二个音节声调不同，意思是欢喜庆幸。"}, "sentence_index": null, "correct_answer": "新兴"}, "level_3": {"options": [{"text": "瘦小", "is_correct": false, "explanation": "语义：“瘦小”形容人或动物的体形，不能用来形容城市。"}, {"text": "新兴", "is_correct": true, "explanation": "新兴：刚刚兴起、正在迅速发展，修饰“旅游城市”，符合语境。"}, {"text": "年迈", "is_correct": false, "explanation": "语义：“年迈”指人的年纪很大，不用来形容城市。"}, {"text": "饱满", "is_correct": false, "explanation": "搭配：“饱满”多用于果实、情绪、精神，不说“饱满的旅游城市”。"}], "explanations": {"瘦小": "语义：“瘦小”形容人或动物的体形，不能用来形容城市。", "新兴": "新兴：刚刚兴起、正在迅速发展，修饰“旅游城市”，符合语境。", "年迈": "语义：“年迈”指人的年纪很大，不用来形容城市。", "饱满": "搭配：“饱满”多用于果实、情绪、精神，不说“饱满的旅游城市”。"}, "sentence_index": 0, "correct_answer": "新兴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块电池的电量很新兴，续航很长。", "explanation": "这里应该用〈充足〉。新兴形容事物刚兴起、正在发展，不用来形容电量，电量多要用“充足”。"}, {"text": "这块面包很新兴，我们一起吃吧。", "explanation": "这里应该用〈新鲜〉。新兴不用来描述食物的新鲜程度，形容食物要用“新鲜”。"}, {"text": "我今天买了一件新兴的衣服，很漂亮。", "explanation": "这里应该用〈新〉。新兴强调刚刚兴起、正在发展，只说刚买的、全新的衣服要用“新”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94810, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "新兴", "is_correct": true, "explanation": "新兴：刚刚兴起、正在迅速发展，为正确答案。"}, {"text": "星星", "is_correct": false, "explanation": "xīngxīng：第一个音节是 xīng 不是 xīn，听起来很像，意思是天上的星星。"}, {"text": "心性", "is_correct": false, "explanation": "xīnxìng（第四声）与 xīnxīng 第二个音节声调不同，意思是人的性情。"}, {"text": "欣欣", "is_correct": false, "explanation": "xīnxīn：第二个音节是 xīn 不是 xīng，听起来很像，意思是高兴、茂盛的样子。"}], "explanations": {"新兴": "新兴：刚刚兴起、正在迅速发展，为正确答案。", "星星": "xīngxīng：第一个音节是 xīng 不是 xīn，听起来很像，意思是天上的星星。", "心性": "xīnxìng（第四声）与 xīnxīng 第二个音节声调不同，意思是人的性情。", "欣欣": "xīnxīn：第二个音节是 xīn 不是 xīng，听起来很像，意思是高兴、茂盛的样子。"}, "sentence_index": null, "correct_answer": "新兴"}, "level_3": {"options": [{"text": "瘦弱", "is_correct": false, "explanation": "语义：“瘦弱”形容人的身体，不能用来形容企业。"}, {"text": "冰冷", "is_correct": false, "explanation": "搭配：“冰冷”形容温度或态度，不说“冰冷的企业”。"}, {"text": "新兴", "is_correct": true, "explanation": "新兴：刚刚兴起、正在迅速发展，修饰“企业”，与“年轻人办的”相符。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”指过时、老旧，与刚由年轻人创办的企业不相符。"}], "explanations": {"瘦弱": "语义：“瘦弱”形容人的身体，不能用来形容企业。", "冰冷": "搭配：“冰冷”形容温度或态度，不说“冰冷的企业”。", "新兴": "新兴：刚刚兴起、正在迅速发展，修饰“企业”，与“年轻人办的”相符。", "陈旧": "语义：“陈旧”指过时、老旧，与刚由年轻人创办的企业不相符。"}, "sentence_index": 6, "correct_answer": "新兴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章的观点很新兴，大家都很喜欢。", "explanation": "这里应该用〈新颖〉。新兴指刚刚兴起的事物，不用来形容观点别致、有新意。"}, {"text": "这个玩具的设计很新兴，孩子们都很爱玩。", "explanation": "这里应该用〈新奇〉。形容东西奇特、让人感到新鲜，要用“新奇”，不用“新兴”。"}, {"text": "这件衣服的颜色今年很新兴，很多人都在穿。", "explanation": "这里应该用〈流行〉。新兴指产业、市场等刚兴起，形容衣服颜色受欢迎要用“流行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新兴地行业发展得很快。", "corrected_sentence": "新兴的行业发展得很快。", "error_description": "错误：“新兴”修饰名词“行业”时要用“的”，写成“地”是把它当作修饰动词的状语。正确形式为“新兴的行业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个新兴了的行业发展很快。", "corrected_sentence": "这个新兴的行业发展很快。", "error_description": "错误：“新兴”修饰名词“行业”时，后面直接接“的”，不能加“了”。“新兴了的”多出了体标“了”，正确形式为“新兴的行业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
