INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94811, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "有帮助是对别人有好处，能帮上忙。", "primary_collocate": null, "pronunciation": "yǒu bāng zhù", "ipa": "jou˨˩˦ paŋ˥ ʈʂu˥˩", "syllable_count": 3, "sentences": [{"text": "你的建议对我很有帮助。", "target_word": "有帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本词典对学汉语的人有帮助。", "target_word": "有帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话对他有帮助。", "target_word": "有帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张地图对游客很有帮助。", "target_word": "有帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法对解决问题有帮助。", "target_word": "有帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友给我的资料真的有帮助。", "target_word": "有帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些笔记对考试有帮助吗？", "target_word": "有帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多听录音对练习口语有帮助。", "target_word": "有帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看图片对小孩学词有帮助。", "target_word": "有帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机软件对出门旅行有帮助。", "target_word": "有帮助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有帮助", "label": "否定"}, {"form": "有很大帮助", "label": "程度"}], "register": "中性", "sense_fingerprint": "对别人有用，能帮上忙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c88eb55d-87b9-4467-ab1d-de538215c096') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94811, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有帮助", "is_correct": true, "explanation": "正确。“你的建议对我很有帮助”表示对我有好处，符合句意。"}, {"text": "有名", "is_correct": false, "explanation": "语义：有名表示很多人知道，不能说“建议对我很有名”。"}, {"text": "有意思", "is_correct": false, "explanation": "语义：有意思只表示有趣，不表示对人有用，与“建议”的作用不符。"}, {"text": "有难度", "is_correct": false, "explanation": "搭配：“难度”说的是事情的难易，不用来描述建议对人的作用。"}], "explanations": {"有帮助": "正确。“你的建议对我很有帮助”表示对我有好处，符合句意。", "有名": "语义：有名表示很多人知道，不能说“建议对我很有名”。", "有意思": "语义：有意思只表示有趣，不表示对人有用，与“建议”的作用不符。", "有难度": "搭配：“难度”说的是事情的难易，不用来描述建议对人的作用。"}, "sentence_index": 0, "correct_answer": "有帮助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张地图对游客很有帮助，因为它把路都画错了。", "explanation": "这里应该用〈误导〉。有帮助表示对人有好处，把路画错会让游客迷路，两者意思相反。"}, {"text": "这张地图对游客很有帮助，所以他们都迷路了。", "explanation": "这里应该用〈误导〉。有帮助表示有好处，让游客迷路是坏的结果，两者矛盾。"}, {"text": "这张地图对游客很有帮助，但它一用就出错。", "explanation": "语义冲突：有帮助表示有好处，一用就出错会妨碍游客，这里应该用〈妨碍〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94811, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有帮助", "is_correct": true, "explanation": "正确。“这些笔记对考试有帮助吗”问笔记对考试是否有用，符合句意。"}, {"text": "有危险", "is_correct": false, "explanation": "语义：有危险表示可能造成危害，与问笔记是否有用的语境不符。"}, {"text": "有兴趣", "is_correct": false, "explanation": "语义：有兴趣表示对某事感兴趣，不表示对考试产生作用。"}, {"text": "有声音", "is_correct": false, "explanation": "搭配：“声音”不能用来描述对考试产生的作用，这样搭配不成立。"}], "explanations": {"有帮助": "正确。“这些笔记对考试有帮助吗”问笔记对考试是否有用，符合句意。", "有危险": "语义：有危险表示可能造成危害，与问笔记是否有用的语境不符。", "有兴趣": "语义：有兴趣表示对某事感兴趣，不表示对考试产生作用。", "有声音": "搭配：“声音”不能用来描述对考试产生的作用，这样搭配不成立。"}, "sentence_index": 6, "correct_answer": "有帮助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个手机软件对出门旅行很有帮助，但它一开机就耗光电量。", "explanation": "这里应该用〈妨碍〉。有帮助表示有好处，耗光电量会妨碍出行，两者意思相反。"}, {"text": "这个手机软件对出门旅行很有帮助，却一点用处也没有。", "explanation": "语义冲突：有帮助表示有好处，一点用处也没有与之矛盾，这里应该用〈没用〉。"}, {"text": "这个手机软件对出门旅行很有帮助，但它给出的路线常常是错的。", "explanation": "这里应该用〈误导〉。有帮助表示有好处，给出错误路线会让人走错路，两者意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94811, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方法给学习很有帮助。", "corrected_sentence": "这个方法对学习很有帮助。", "error_description": "介词错误：“有帮助”的对象要用“对”引出，应说“对学习很有帮助”，不能用“给”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94811, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些练习对发音不有帮助。", "corrected_sentence": "这些练习对发音没有帮助。", "error_description": "否定词错误：“有帮助”的否定要用“没有”，不能用“不有”，应说“没有帮助”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5b5e7af-0dbd-4dff-b509-1d0c08d0bf16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
