INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94813, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张表用了一只格式，一看就懂。", "corrected_sentence": "这张表用了一种格式，一看就懂。", "error_description": "“格式”前的量词应用“种”。“只”多用于动物或成对物件中的一件，不能用于“格式”。“一只格式”是错的，应改为“一种格式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '607e29e9-b1d6-4274-a4c2-ecaae7dee8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94813, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个网页的格式制造得很整齐。", "corrected_sentence": "这个网页的格式设置得很整齐。", "error_description": "“格式”应与“设置、设计、制定”搭配，“制造”不能用于“格式”。应改为“设置”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '607e29e9-b1d6-4274-a4c2-ecaae7dee8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
