INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94816, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "建立、确立，使某种形象、风气等成立并被认可。", "primary_collocate": null, "pronunciation": "shù lì", "ipa": "ʂu⁵¹ li⁵¹", "syllable_count": 2, "sentences": [{"text": "他想在公司里树立好形象。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校要树立良好的学习风气。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人要树立正确的人生目标。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店靠好服务树立了自己的名声。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要帮孩子树立学好数学的信心。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位新校长很快就树立了威信。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直想树立一个爱学习的好形象。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有树立正确的观念，才能做出好选择。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司把诚信当作原则，树立了好品牌。", "target_word": "树立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就树立了当医生的理想。", "target_word": "树立", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "树立了", "label": "体标"}, {"form": "树立过", "label": "体标"}, {"form": "樹立", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "建立、确立形象、风气、观念等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59c51a76-670c-44fa-8b2f-c5c9944b2429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94816, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "树立", "is_correct": true, "explanation": "正确：听到的是“树立”，指建立、确立某种形象、风气等。"}, {"text": "书吏", "is_correct": false, "explanation": "声调不同：shū 为第一声，shù 为第四声。书吏意思是旧时官府中抄写文书的小吏。"}, {"text": "树篱", "is_correct": false, "explanation": "声调不同：lí 为第二声，lì 为第四声，意思是密植成墙的树木。"}, {"text": "数理", "is_correct": false, "explanation": "声调不同：lǐ 为第三声，lì 为第四声，意思是数学的道理。"}], "explanations": {"树立": "正确：听到的是“树立”，指建立、确立某种形象、风气等。", "书吏": "声调不同：shū 为第一声，shù 为第四声。书吏意思是旧时官府中抄写文书的小吏。", "树篱": "声调不同：lí 为第二声，lì 为第四声，意思是密植成墙的树木。", "数理": "声调不同：lǐ 为第三声，lì 为第四声，意思是数学的道理。"}, "sentence_index": null, "correct_answer": "树立"}, "level_3": {"options": [{"text": "树立", "is_correct": true, "explanation": "正确：“树立好形象”指在公司里确立良好的形象。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“想破坏好形象”与前半句“想”所表达的正面愿望相矛盾。"}, {"text": "吃", "is_correct": false, "explanation": "语义：形象不能被吃，“想吃好形象”不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”与“形象”不相配，“洗好形象”不是常见说法。"}], "explanations": {"树立": "正确：“树立好形象”指在公司里确立良好的形象。", "破坏": "语义：“想破坏好形象”与前半句“想”所表达的正面愿望相矛盾。", "吃": "语义：形象不能被吃，“想吃好形象”不通。", "洗": "搭配：“洗”与“形象”不相配，“洗好形象”不是常见说法。"}, "sentence_index": 0, "correct_answer": "树立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他多年树立了丰富的经验。", "explanation": "这里应该用〈积累〉。树立用于形象、风气、榜样，经验要说“积累”。"}, {"text": "这位选手树立了观众的喜爱。", "explanation": "这里应该用〈赢得〉。喜爱是别人给予的，要说“赢得”，“树立”不能用于此。"}, {"text": "他树立了很多真诚的朋友。", "explanation": "这里应该用〈拥有〉。朋友要说“拥有”，“树立”不能用于人际关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94816, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "树立", "is_correct": true, "explanation": "正确：听到的是“树立”，指建立、确立某种形象、风气等。"}, {"text": "树篱", "is_correct": false, "explanation": "声调不同：lí 为第二声，lì 为第四声。树篱意思是密植成墙的树木。"}, {"text": "属吏", "is_correct": false, "explanation": "声调不同：shǔ 为第三声，shù 为第四声。属吏意思是隶属于官府的下级官吏。"}, {"text": "书立", "is_correct": false, "explanation": "第一音节声调不同：shū 为第一声，shù 为第四声，意思是书挡。"}], "explanations": {"树立": "正确：听到的是“树立”，指建立、确立某种形象、风气等。", "树篱": "声调不同：lí 为第二声，lì 为第四声。树篱意思是密植成墙的树木。", "属吏": "声调不同：shǔ 为第三声，shù 为第四声。属吏意思是隶属于官府的下级官吏。", "书立": "第一音节声调不同：shū 为第一声，shù 为第四声，意思是书挡。"}, "sentence_index": null, "correct_answer": "树立"}, "level_3": {"options": [{"text": "树立", "is_correct": true, "explanation": "正确：“树立一个好形象”指确立良好的形象，与“爱学习”相合。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“想打碎好形象”与句意相反，与“爱学习”的正面形象矛盾。"}, {"text": "投诉", "is_correct": false, "explanation": "搭配：“投诉”的对象是事件或服务，“投诉一个形象”搭配不当。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”多与希望、热情连用，不能与“形象”搭配。"}], "explanations": {"树立": "正确：“树立一个好形象”指确立良好的形象，与“爱学习”相合。", "打碎": "语义：“想打碎好形象”与句意相反，与“爱学习”的正面形象矛盾。", "投诉": "搭配：“投诉”的对象是事件或服务，“投诉一个形象”搭配不当。", "点燃": "搭配：“点燃”多与希望、热情连用，不能与“形象”搭配。"}, "sentence_index": 6, "correct_answer": "树立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用两年时间树立了一门外语。", "explanation": "这里应该用〈学会〉。外语属于技能，要说“学会”；“树立”用于形象、风气、观念，不能用于技能。"}, {"text": "他上个月树立了一篇论文。", "explanation": "这里应该用〈撰写〉。论文要说“撰写”；“树立”用于形象、风气、观念，不能用于文章。"}, {"text": "公司今年树立了新市场。", "explanation": "这里应该用〈开拓〉。市场要说“开拓”；“树立”用于形象、风气、观念，不能用于市场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直想树立了良好的形象。", "corrected_sentence": "他一直想树立良好的形象。", "error_description": "错误：“想”表示意愿，后面的“树立”不能带“了”，应说“想树立”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他树立得良好的形象，大家都很信任他。", "corrected_sentence": "他树立了良好的形象，大家都很信任他。", "error_description": "错误：动词“树立”后带宾语表示完成时要用“了”，不能用补语标记“得”，应说“树立了良好的形象”，不能说“树立得良好的形象”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34687fa6-00cd-48ee-851a-715f6055399c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94817, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "唱", "is_correct": false, "explanation": "无反义关系：“唱”指发声演唱，与“涨”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "无反义关系：“写”指记录文字，与“涨”没有反义关系。"}, {"text": "跌", "is_correct": true, "explanation": "跌：与“涨”构成反义，指价钱下降，符合“菜价涨得太快”的语境。"}, {"text": "走", "is_correct": false, "explanation": "无反义关系：“走”指移动，与“涨”没有反义关系。"}], "correct_answer": "跌", "explanations": {"唱": "无反义关系：“唱”指发声演唱，与“涨”没有反义关系。", "写": "无反义关系：“写”指记录文字，与“涨”没有反义关系。", "跌": "跌：与“涨”构成反义，指价钱下降，符合“菜价涨得太快”的语境。", "走": "无反义关系：“走”指移动，与“涨”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94817, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "站", "is_correct": false, "explanation": "无反义关系：“站”指站立，与“涨”没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "无反义关系：“吃”指进食，与“涨”没有反义关系。"}, {"text": "跌", "is_correct": true, "explanation": "跌：与“涨”构成反义，指价格下降，符合“房价一直在涨”的语境。"}, {"text": "跑", "is_correct": false, "explanation": "无反义关系：“跑”指快速移动，与“涨”没有反义关系。"}], "correct_answer": "跌", "explanations": {"站": "无反义关系：“站”指站立，与“涨”没有反义关系。", "吃": "无反义关系：“吃”指进食，与“涨”没有反义关系。", "跌": "跌：与“涨”构成反义，指价格下降，符合“房价一直在涨”的语境。", "跑": "无反义关系：“跑”指快速移动，与“涨”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94817, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "涨是水或价钱变高了。", "primary_collocate": null, "pronunciation": "zhǎng", "ipa": "ʈʂaŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "下了三天雨，河水涨了。", "target_word": "涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年猪肉的价钱涨了不少。", "target_word": "涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说下个月房租要涨。", "target_word": "涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菜价涨得太快，妈妈不想买。", "target_word": "涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨一直下，湖里的水涨高了。", "target_word": "涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们公司今年工资涨了一点。", "target_word": "涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天牛奶的价格涨了两块钱。", "target_word": "涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水涨到了桥下，大家都很担心。", "target_word": "涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "什么都涨了，只有工资没涨。", "target_word": "涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几年，这里的房价一直在涨。", "target_word": "涨", "complexity_tier": "T3", "furigana": "zhè jǐ nián zhè lǐ de fáng jià yì zhí zài zhǎng", "sentence_source": "generated"}], "morphological_forms": [{"form": "涨了", "label": "体标"}, {"form": "涨过", "label": "体标"}], "register": "中性", "sense_fingerprint": "涨|水或价钱变高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '702d0700-d623-41b2-b926-c6455e91f03f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94817, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "涨", "is_correct": true, "explanation": "涨（zhǎng）：指水位、价钱等升高，为正确答案。"}, {"text": "仗", "is_correct": false, "explanation": "zhàng（第四声）与 zhǎng（第三声）声调不同，意思是战争、打仗。"}, {"text": "张", "is_correct": false, "explanation": "zhāng（第一声）与 zhǎng（第三声）声调不同，意思是张开。"}, {"text": "站", "is_correct": false, "explanation": "zhàn（第四声）与 zhǎng 韵母 ang 变为 an，声调也不同，意思是站立。"}], "explanations": {"涨": "涨（zhǎng）：指水位、价钱等升高，为正确答案。", "仗": "zhàng（第四声）与 zhǎng（第三声）声调不同，意思是战争、打仗。", "张": "zhāng（第一声）与 zhǎng（第三声）声调不同，意思是张开。", "站": "zhàn（第四声）与 zhǎng 韵母 ang 变为 an，声调也不同，意思是站立。"}, "sentence_index": null, "correct_answer": "涨"}, "level_3": {"options": [{"text": "笑", "is_correct": false, "explanation": "语义：“笑”是人的动作，河水不会笑。"}, {"text": "涨", "is_correct": true, "explanation": "涨：水位升高，与“下了三天雨”的语境相符，正确。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能说“河水写了”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是人或动物的动作，河水不会唱歌。"}], "explanations": {"笑": "语义：“笑”是人的动作，河水不会笑。", "涨": "涨：水位升高，与“下了三天雨”的语境相符，正确。", "写": "搭配：“写”的对象是文字，不能说“河水写了”。", "唱": "语义：“唱”是人或动物的动作，河水不会唱歌。"}, "sentence_index": 0, "correct_answer": "涨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子这一年涨高了十厘米。", "explanation": "这里应该用〈长高〉。涨用于水位、价钱、工资等升高，人的个子长高要用“长高”。"}, {"text": "院子里的树今年又涨高了一米。", "explanation": "这里应该用〈长高〉。涨用于水位、价钱等升高，植物生长变高要用“长高”。"}, {"text": "这个孩子正在慢慢涨。", "explanation": "这里应该用〈成长〉。涨不表示人的身体或能力成长，说孩子成长要用“成长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94817, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "涨", "is_correct": true, "explanation": "涨（zhǎng）：指水位、价钱等升高，为正确答案。"}, {"text": "账", "is_correct": false, "explanation": "zhàng（第四声）与 zhǎng 声调不同，意思是账目。"}, {"text": "展", "is_correct": false, "explanation": "zhǎn 与 zhǎng 韵母 ang 变为 an，意思是展开。"}, {"text": "战", "is_correct": false, "explanation": "zhàn 与 zhǎng 韵母 ang 变为 an，声调也不同，意思是战斗。"}], "explanations": {"涨": "涨（zhǎng）：指水位、价钱等升高，为正确答案。", "账": "zhàng（第四声）与 zhǎng 声调不同，意思是账目。", "展": "zhǎn 与 zhǎng 韵母 ang 变为 an，意思是展开。", "战": "zhàn 与 zhǎng 韵母 ang 变为 an，声调也不同，意思是战斗。"}, "sentence_index": null, "correct_answer": "涨"}, "level_3": {"options": [{"text": "花", "is_correct": false, "explanation": "搭配：“花”的对象是钱，价格不能说“花了两块钱”。"}, {"text": "赚", "is_correct": false, "explanation": "语义：价格不会赚钱，“赚了两块钱”与语境不符。"}, {"text": "涨", "is_correct": true, "explanation": "涨：价钱升高，与“牛奶的价格”和“两块钱”的语境相符，正确。"}, {"text": "亏", "is_correct": false, "explanation": "语义：“亏”指经营受损，价格不能说亏。"}], "explanations": {"花": "搭配：“花”的对象是钱，价格不能说“花了两块钱”。", "赚": "语义：价格不会赚钱，“赚了两块钱”与语境不符。", "涨": "涨：价钱升高，与“牛奶的价格”和“两块钱”的语境相符，正确。", "亏": "语义：“亏”指经营受损，价格不能说亏。"}, "sentence_index": 6, "correct_answer": "涨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的规模涨了很多。", "explanation": "这里应该用〈扩大〉。涨用于价钱、水位等升高，公司的规模、范围增大要用“扩大”。"}, {"text": "假期涨了两天。", "explanation": "这里应该用〈延长〉。涨不用于时间的增加，假期时间变长要用“延长”。"}, {"text": "他的体质涨了很多。", "explanation": "这里应该用〈增强〉。涨不表示身体素质的提高，体质变好要用“增强”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94817, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "河水慢慢涨下来了。", "corrected_sentence": "河水慢慢涨上来了。", "error_description": "补语方向错误：水位升高应接“上来”，“下来”表示向下，与“涨”的意思矛盾。正确形式为“涨上来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94817, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里的房租去年涨了过一次。", "corrected_sentence": "这里的房租去年涨过一次。", "error_description": "体标错误：“涨过”已表示经历过，“过”前不能再加“了”。正确形式为“涨过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94818, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "唱", "is_correct": false, "explanation": "无反义关系：“唱”指发声演唱，与“涨”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "无反义关系：“写”指记录文字，与“涨”没有反义关系。"}, {"text": "落", "is_correct": true, "explanation": "落：与“涨”构成反义（涨落），指水位下降，符合“江水一天天涨高”的语境。"}, {"text": "站", "is_correct": false, "explanation": "无反义关系：“站”指站立，与“涨”没有反义关系。"}], "correct_answer": "落", "explanations": {"唱": "无反义关系：“唱”指发声演唱，与“涨”没有反义关系。", "写": "无反义关系：“写”指记录文字，与“涨”没有反义关系。", "落": "落：与“涨”构成反义（涨落），指水位下降，符合“江水一天天涨高”的语境。", "站": "无反义关系：“站”指站立，与“涨”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94818, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吃", "is_correct": false, "explanation": "无反义关系：“吃”指进食，与“涨”没有反义关系。"}, {"text": "降", "is_correct": true, "explanation": "降：与“涨”构成反义，指价格下降，符合“票价也要涨”的语境。"}, {"text": "咬", "is_correct": false, "explanation": "无反义关系：“咬”指用牙齿夹住或切断，与“涨”没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "无反义关系：“跑”指快速移动，与“涨”没有反义关系。"}], "correct_answer": "降", "explanations": {"吃": "无反义关系：“吃”指进食，与“涨”没有反义关系。", "降": "降：与“涨”构成反义，指价格下降，符合“票价也要涨”的语境。", "咬": "无反义关系：“咬”指用牙齿夹住或切断，与“涨”没有反义关系。", "跑": "无反义关系：“跑”指快速移动，与“涨”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94818, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "水位或物价升高。", "primary_collocate": null, "pronunciation": "zhǎng", "ipa": "ʈʂaŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "河里的水位涨了三米。", "target_word": "涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雨过后，海边的水涨起来了。", "target_word": "涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月物价涨得特别快。", "target_word": "涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天到了，江水一天天涨高。", "target_word": "涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "油价涨了以后，坐车也贵了。", "target_word": "涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看，水已经涨到门口了。", "target_word": "涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽油的价格最近涨了很多。", "target_word": "涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水涨得太高，船开不过去了。", "target_word": "涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "东西都在涨，我们得省着点花。", "target_word": "涨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说明年地铁票价也要涨。", "target_word": "涨", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "涨了", "label": "体标"}, {"form": "涨过", "label": "体标"}], "register": "中性", "sense_fingerprint": "涨|水位、物价升高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '702d0700-d623-41b2-b926-c6455e91f03f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
