on_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94818, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "涨", "is_correct": true, "explanation": "涨（zhǎng）：指水位、物价升高，为正确答案。"}, {"text": "张", "is_correct": false, "explanation": "zhāng（第一声）与 zhǎng 声调不同，意思是张开。"}, {"text": "展", "is_correct": false, "explanation": "zhǎn 与 zhǎng 韵母 ang 变为 an，意思是展开。"}, {"text": "战", "is_correct": false, "explanation": "zhàn 与 zhǎng 韵母 ang 变为 an，声调也不同，意思是战斗。"}], "explanations": {"涨": "涨（zhǎng）：指水位、物价升高，为正确答案。", "张": "zhāng（第一声）与 zhǎng 声调不同，意思是张开。", "展": "zhǎn 与 zhǎng 韵母 ang 变为 an，意思是展开。", "战": "zhàn 与 zhǎng 韵母 ang 变为 an，声调也不同，意思是战斗。"}, "sentence_index": null, "correct_answer": "涨"}, "level_3": {"options": [{"text": "胖", "is_correct": false, "explanation": "语义：“胖”形容人或动物的体形，不能说“价格胖了”。"}, {"text": "瘦", "is_correct": false, "explanation": "语义：“瘦”形容人或动物的体形，价格不能说瘦。"}, {"text": "涨", "is_correct": true, "explanation": "涨：价格升高，与“汽油的价格最近”和“很多”的语境相符，正确。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”指燃烧或耗费钱财，价格不说“烧了很多”。"}], "explanations": {"胖": "语义：“胖”形容人或动物的体形，不能说“价格胖了”。", "瘦": "语义：“瘦”形容人或动物的体形，价格不能说瘦。", "涨": "涨：价格升高，与“汽油的价格最近”和“很多”的语境相符，正确。", "烧": "搭配：“烧”指燃烧或耗费钱财，价格不说“烧了很多”。"}, "sentence_index": 6, "correct_answer": "涨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的面积涨大了。", "explanation": "这里应该用〈扩大〉。涨用于价钱、水位等升高，面积、范围增大要用“扩大”。"}, {"text": "班里的同学涨多了。", "explanation": "这里应该用〈增多〉。涨不用于人数的增加，同学变多要用“增多”。"}, {"text": "两国的误会涨了。", "explanation": "这里应该用〈加深〉。涨不用于抽象的误会，误会程度加深要用“加深”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94818, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖水一夜之间涨低了。", "corrected_sentence": "湖水一夜之间涨高了。", "error_description": "补语错误：“涨”后面的结果补语应为“高”（表示升高），“低”与“涨”搭配不通。正确形式为“涨高了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94818, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "汽油的价格涨在了每升八块。", "corrected_sentence": "汽油的价格涨到了每升八块。", "error_description": "介词错误：价格升到某个数值，应用“到”，不能用“在”。正确形式为“涨到了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '285ed9d0-33bc-43e9-8b33-d3745b24d339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
