INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94819, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "激励是说好话让人更想努力。", "primary_collocate": null, "pronunciation": "jī lì", "ipa": "tɕi˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "老师的话激励我继续努力。", "target_word": "激励", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈常常用好话激励弟弟学习。", "target_word": "激励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练在比赛前激励大家，队员们都很有信心。", "target_word": "激励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话激励了很多年轻人。", "target_word": "激励", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他总是说好话激励同事好好工作。", "target_word": "激励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的故事一直激励着我向前走。", "target_word": "激励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板开会时激励大家，说公司会越来越好。", "target_word": "激励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的一封信激励了我，我又开始跑步了。", "target_word": "激励", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要互相激励，一起进步。", "target_word": "激励", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把这些话写在本子上，天天激励自己。", "target_word": "激励", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "激励了", "label": "体标"}, {"form": "激励着", "label": "体标"}, {"form": "激励机制", "label": "复合"}], "register": "中性", "sense_fingerprint": "用好话让别人更有干劲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3101b179-ea35-4787-b575-d3c8af1182ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94819, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "激励", "is_correct": true, "explanation": "激励：用好话或行动让人更想努力，正确答案。"}, {"text": "精力", "is_correct": false, "explanation": "jīng 比 jī 多了 ng 韵尾，意思是体力和精神。"}, {"text": "积累", "is_correct": false, "explanation": "lěi（第三声）与 lì（第四声）的韵母和声调都不同，意思是逐渐增加。"}, {"text": "机理", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，意思是事物的内在道理。"}], "explanations": {"激励": "激励：用好话或行动让人更想努力，正确答案。", "精力": "jīng 比 jī 多了 ng 韵尾，意思是体力和精神。", "积累": "lěi（第三声）与 lì（第四声）的韵母和声调都不同，意思是逐渐增加。", "机理": "lǐ（第三声）与 lì（第四声）声调不同，意思是事物的内在道理。"}, "sentence_index": null, "correct_answer": "激励"}, "level_3": {"options": [{"text": "激励", "is_correct": true, "explanation": "激励：用言语使人振作，与“老师的话”和“继续努力”相合，正确。"}, {"text": "诅咒", "is_correct": false, "explanation": "语义：“诅咒”是咒人不好，与“老师的话”的鼓励语境相反。"}, {"text": "嘲笑", "is_correct": false, "explanation": "搭配：“嘲笑”带讽刺意味，不能与“继续努力”的积极语境搭配。"}, {"text": "抚摸", "is_correct": false, "explanation": "配价：“抚摸”需要有形的接触对象，“老师的话”不能抚摸人，句意不通。"}], "explanations": {"激励": "激励：用言语使人振作，与“老师的话”和“继续努力”相合，正确。", "诅咒": "语义：“诅咒”是咒人不好，与“老师的话”的鼓励语境相反。", "嘲笑": "搭配：“嘲笑”带讽刺意味，不能与“继续努力”的积极语境搭配。", "抚摸": "配价：“抚摸”需要有形的接触对象，“老师的话”不能抚摸人，句意不通。"}, "sentence_index": 0, "correct_answer": "激励"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他激励了那张桌子，桌子却一动不动。", "explanation": "激励的对象应是能被鼓舞的人，桌子不能被激励，这里的用法不对。"}, {"text": "这节课的实验激励了学生的兴趣，大家都想动手做。", "explanation": "这里应该用〈激发〉。激发的对象是兴趣、积极性等抽象事物；“激励”的对象必须是人，不说“激励兴趣”。"}, {"text": "他激励了那盘饺子，饺子很快吃完了。", "explanation": "激励的对象应是能被鼓舞的人，饺子不能被激励，这里的用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
